    def _prebuilt_tooltip(self, paper: str) -> str:
        """Tooltip text for a prebuilt-files built-in preset."""
        return (
            "Built-in chart — cannot be deleted.\n"
            f"A complete, ready-made target laid out for {paper}.\n"
            "Picking it asks for a name, then copies the bundled patch set\n"
            "(.ti1 / .ti2 / TIFF pages) into a new folder under that name —\n"
            "no targen or printtarg is run, so those panels are greyed out.\n"
            "The copied TIFFs are loaded straight into the preview."
        )

    def _populate_preset_combo(self, presets: dict, select_name: str | None = None) -> None:
        self._preset_combo.blockSignals(True)
        self._preset_combo.clear()
        self._preset_combo.addItem(tr("none"), userData=None)
        # User presets first, then the built-ins below them. A preset saved with
        # "generate on select" gets a ▶ prefix so the user knows picking it
        # starts the chart, not just loads values. userData stays the bare name.
        for name in presets:
            if name in BUILTIN_PRESET_LABELS or name in BUILTIN_PRESET_KEYS:
                continue  # never let a user file shadow a built-in entry
            label = f"▶  {name}" if (isinstance(presets[name], dict)
                                     and presets[name].get("auto_run")) else name
            self._preset_combo.addItem(label, userData=name)
        # Built-in presets, pinned below the user's own and grouped by the
        # instrument they target. Groups (and the order within each) follow the
        # shared BUILTIN_PRESET_GROUPS registry verbatim — no re-sorting — so the
        # dropdown and the Built-in presets overlay show the instruments in the
        # exact same order. A separator line is drawn before the whole built-in
        # block (dividing it from the user presets) and again before each new
        # instrument group.
        # (instrument, label, key, tooltip)
        builtins = [
            (instr, combo_label, key, self._builtin_tooltip(key))
            for instr, entries in BUILTIN_PRESET_GROUPS
            for (combo_label, _overlay_label, key) in entries
        ]
        prev_instr: str | None = None
        for instr, label, key, tip in builtins:
            if instr != prev_instr:
                self._preset_combo.insertSeparator(self._preset_combo.count())
                # A real heading, in the Instrument field's own words (Knut,
                # 2026-08-18): the overlay has always shown one, the dropdown
                # only had a separator, so "i1Pro" had to be inferred from the
                # rows — and it never said that those charts suit an i1Pro 2 or 3.
                self._add_builtin_group_heading(instr)
                prev_instr = instr
            self._add_builtin_preset_item(
                label, key, tip, disabled=key in DISABLED_BUILTIN_PRESET_KEYS
            )
        if select_name is not None:
            # Match by userData (the bare name), not the shown text, which may
            # carry a ▶ prefix for auto-run presets.
            idx = self._preset_combo.findData(select_name)
            if idx >= 0:
                self._preset_combo.setCurrentIndex(idx)
        self._preset_combo.blockSignals(False)
        self._last_preset_index = self._preset_combo.currentIndex()
        self._preset_del_btn.setEnabled(
            self._is_deletable_preset(self._preset_combo.currentIndex())
        )

    @staticmethod
    def _builtin_default_name(key: str) -> str:
        """Default target name suggested in the prompt for a built-in preset."""
        if key == TC918_PRESET_KEY:
            return TC918_TARGET_NAME
        if key in KNUT_PRESET_KEYS:
            return KNUT_PRESETS_BY_KEY[key].default_target_name
        if key in MUNKI_TARGEN:
            return f"ColorMunki-{MUNKI_TARGEN[key][0]}"
        if key in PREBUILT_PRESETS:
            return PREBUILT_PRESETS[key][1]
        return "chart"

    def _builtin_tooltip(self, key: str) -> str:
        """Combo/overlay tooltip for any built-in preset (per its kind)."""
        if key in KNUT_PRESET_KEYS:
            return self._knut_tooltip(key)
        return self._prebuilt_tooltip(_prebuilt_paper(key))

    @staticmethod
    def _knut_tooltip(key: str) -> str:
        """Tooltip for a ti1 → printtarg built-in preset (TC9.18 or Full layout setup)."""
        p = KNUT_PRESETS_BY_KEY[key]
        if p.group == "Scanner":
            # Scanner family (#100) — a flatbed scanner reads these, not a
            # spectrophotometer, so the tooltip explains the whole detour.
            rec = p.layout_recipe or {}
            return (
                "Built-in chart — cannot be deleted.\n"
                f"Loads the bundled {p.patches}-patch set and lays it out with "
                f"the ChromIQ layout engine\n"
                f"({rec.get('paper', p.paper)}, {p.pages}-page, "
                f"{rec.get('area_min_patch_mm', 4):g} mm patches).\n"
                "Print it WITHOUT colour management, scan it on a flatbed "
                "scanner, then use\n"
                "Tools → “Build profile with scanner or camera” with “Profile my "
                "printer from this scan”.\n"
                "Creates the target right away; the patch set stays fixed but "
                "you can adjust\nany layout setting and regenerate."
            )
        if p.layout_recipe is not None:
            # Any other engine-built preset (ColorMunki family, Red River).
            # Describe what the user gets on paper: sheet, pages, and the grid
            # that decides how big each patch is.
            rec = p.layout_recipe
            # An explicit family group already names the device the way the rest
            # of the UI does ("i1Pro 3 Plus"); fall back to the margin-table
            # label, whose keys are stored settings and must not be renamed.
            instr = (p.group
                     or _MARGIN_INSTR_LABEL.get(p.instrument, p.instrument))
            grid = ""
            if rec.get("area_cols") and rec.get("area_rows"):
                grid = (f"\n{rec['area_cols']} patches across × "
                        f"{rec['area_rows']} strips down per sheet.")
            width = _WIDTH_TOKEN_RE.search(p.name)
            ruler = ""
            if rec.get("helper_markers"):
                ruler = ("\nThe small helper marks along the edges let you line "
                         "a ruler up with the strip\nyou are reading.")
            # This family prints a wide empty band down one side — the run-up the
            # instrument needs before it reaches the first patch. Say so, or it
            # reads as wasted paper.
            if rec.get("clip_border") and rec.get("clip_content_mode") == "notes":
                ruler += ("\nThe wide white band down the side is the run-up your "
                          "instrument needs before\nthe first patch; the chart's "
                          "details are printed in it.")
            return (
                "Built-in chart — cannot be deleted.\n"
                f"A ready-made {p.patches}-patch target for the {instr} on "
                f"{rec.get('paper', p.paper)}, {p.pages} "
                f"{'page' if p.pages == 1 else 'pages'}"
                + (f", {width.group(0)[2:]} patches" if width else "") + "."
                + grid + ruler +
                "\nPicking it asks for a name and builds the chart right away. "
                "The colours stay\nfixed, but every layout setting can be "
                "changed and the chart regenerated."
            )
        instr = "i1Pro" if p.instrument == _KNUT_I1 else "ColorMunki (double density)"
        family = ("TC9.18 + Spyderprint-greys" if p.suffix == KNUT_SUFFIX
                  else "Full layout setup")
        bits = [f"-p{p.paper}", f"-a{p.patch_scale:g}", f"-M{p.margin}"]
        if p.spacer_scale is not None:
            bits.append(f"-A{p.spacer_scale:g}")
        if p.seed is not None:
            bits.append(f"-R{p.seed}")
        return (
            "Built-in chart — cannot be deleted.\n"
            f"Loads the bundled {p.patches}-patch {family} set and\n"
            f"lays it out for the {instr} ({p.pages}-page):\n"
            f"printtarg -i{p.instrument} -T200 {' '.join(bits)}\n"
            "Creates the target right away; the patch set stays fixed but you\n"
            "can adjust any printtarg setting and regenerate."
        )

    def _revert_preset_combo(self, *, to_none: bool = False) -> None:
        """Restore the dropdown after a selection that did not take.

        Also records that this selection was abandoned, so
        `_on_preset_selected` does not commit it as the new "last" one.

        *to_none* IS THE HONEST ANSWER ONCE A DISPATCH HAS STARTED. By then
        `_on_preset_selected` has already torn the previous preset down — it
        clears the TC9.18 and Spyderprint overrides and resets the panels before
        it dispatches — so putting the dropdown back on that preset shows a
        selection whose settings no longer exist, and, because the index then
        matches, picking it again emits no signal and does nothing at all. The
        first version of this fix moved exactly that trap from the new preset
        onto the previous one. "None" is what is actually applied at that point.

        The separator guard is the other caller and passes nothing: a divider
        was clicked, no dispatch ran, and the previous selection is still real.
        """
        index = 0 if to_none else self._last_preset_index
        self._preset_selection_reverted = True
        self._preset_combo.blockSignals(True)
        self._preset_combo.setCurrentIndex(index)
        self._preset_combo.blockSignals(False)
        self._preset_del_btn.setEnabled(self._is_deletable_preset(index))
        if to_none:
            self._last_preset_index = 0

    def _update_header_buttons_for_mode(self) -> None:
        """Park "Load patch set" and the presets button while FROM PROFILE
        GAMUT is active (Basti, 2026-08-10): this module asks the run's
        profile which colours to test, so both shortcuts fight its purpose —
        a loaded patch set would be silently ignored by Generate, and a
        preset would switch the module away and replace the chart. The
        buttons grey out and their tooltips say why and where to go instead.
        """
        if getattr(self, "_load_ti1_btn", None) is None \
                or getattr(self, "_builtin_preset_btn", None) is None:
            return                       # reached during UI build
        gamut = self._mode_name() == "gamut"
        cursor = (Qt.CursorShape.ArrowCursor if gamut
                  else Qt.CursorShape.PointingHandCursor)
        self._load_ti1_btn.setEnabled(not gamut)
        self._load_ti1_btn.setCursor(cursor)
        self._load_ti1_btn.setToolTip(tr(
            "Not available in FROM PROFILE GAMUT.\n"
            "This module asks the run's profile which colours to test, so a "
            "patch set of your own can't be used here. To lay out a loaded "
            "patch set, switch to GUIDED or MANUAL first.")
            if gamut else self._load_ti1_tip)
        self._builtin_preset_btn.setEnabled(not gamut)
        self._builtin_preset_btn.setCursor(cursor)
        self._builtin_preset_btn.setToolTip(tr(
            "Not available in FROM PROFILE GAMUT.\n"
            "A preset brings its own ready-made patch set, but this module "
            "asks the run's profile which colours to test. To use a built-in "
            "preset, switch to GUIDED or MANUAL first.")
            if gamut else self._builtin_preset_tip)

    def _open_builtin_preset_overlay(self) -> None:
        """Show the speech-bubble overlay of built-in presets under the star button."""
        from ui.theme import resolve_mode
        # The marker rides on the overlay ROW, but NOT on `overlay_label`
        # itself: `comparable_presets` (#66 "Compare with profile") reads the
        # same tuple slot, and that dialog is about a PATCH SET, where "Full
        # layout setup" would be 115 rows of noise about something it does not
        # show.
        groups = [
            (instr, [(_marked_overlay_label(key, overlay_label), key)
                     for (_combo, overlay_label, key) in entries])
            for instr, entries in BUILTIN_PRESET_GROUPS
        ]
        popup = BuiltinPresetPopup(groups, self)
        popup.set_appearance(resolve_mode(self._settings.get("appearance", "auto")))
        popup.selected.connect(self._activate_builtin_preset)
        # Keep a reference so the popup isn't garbage-collected while shown.
        self._builtin_preset_popup = popup
        popup.show_under(self._builtin_preset_btn)

    def _activate_builtin_preset(self, key: str) -> None:
        """Pick a built-in from the overlay — identical to choosing it in the dropdown.

        The built-ins live in the Manual presets dropdown, so route through it:
        switch to Manual (so the dropdown and greyed panels are visible), move
        the dropdown to the matching entry, then run the handler — the name
        prompt + generate flow.

        THE HANDLER IS CALLED HERE, NOT LEFT TO A SIGNAL. The combo is wired to
        `activated`, which Qt emits only for a real interaction, so moving it
        from code is silent by design (#175). That is what lets a refused preset
        be put back on the dropdown without arming it; the price is that this
        caller does the dispatch itself, in both directions."""
        idx = self._preset_combo.findData(key)
        if idx < 0:
            log.warning("Built-in preset overlay: key %r not in dropdown", key)
            return
        # THE MODE IS PUT BACK HERE, NOT IN THE HANDLER (#175). The switch to
        # Manual happens before `_on_preset_selected` is even called, so the
        # snapshot it takes has already lost the mode the person was in.
        _mode_before = self._mode_name()
        if self._current_mode() != "manual":
            self._switch_mode("manual")
        if idx != self._preset_combo.currentIndex():
            self._preset_combo.blockSignals(True)
            self._preset_combo.setCurrentIndex(idx)
            self._preset_combo.blockSignals(False)
        self._preset_selection_reverted = False
        self._on_preset_selected(idx)
        if self._preset_selection_reverted and self._mode_name() != _mode_before:
            self._switch_mode(_mode_before)

    # ------------------------------------------------------------------
    # #175 — a built-in preset that is refused must leave NOTHING behind
    # ------------------------------------------------------------------
    #: Settings a built-in preset writes that OUTLIVE THE APP RUN, and which
    #: Basti ruled go back with everything else (2026-08-28). Before this,
    #: answering Cancel to a Spyderprint preset changed the layout-engine switch
    #: and the four ruler-marker values for good — measured, with a negative
    #: control proving it was the preset seeding and not the window.
    _PRESET_PERSISTED_SETTINGS = (
        "use_chromiq_layout_engine",
        "i1pro_chromiq_clip_style",
        "helper_markers_show",
        "helper_marker_edge_mm",
        "helper_marker_len_mm",
        "helper_marker_per_patch",
        "helper_markers_top_bottom",
        "helper_markers_sides",
    )

    #: Every attribute that records "which kind of chart is on screen".
    #: `_leave_prebuilt` and its two siblings are nothing but these plus a lock
    #: refresh, so putting the values back and re-running `_update_preset_locks`
    #: undoes them exactly.
    _PRESET_FAMILY_ATTRS = (
        "_tc918_active", "_tc918_targen_sig",
        "_knut_active", "_knut_active_key", "_knut_targen_sig",
        "_prebuilt_active", "_prebuilt_key",
        "_prebuilt_targen_sig", "_prebuilt_printtarg_sig",
        "_applied_active", "_applied_src_dir", "_applied_stem",
        "_applied_targen_sig", "_applied_printtarg_sig",
        "_reflected_active", "_reflected_ti2",
        "_preset_ti1_path", "_preset_ti1_targen_sig",
        "_pending_editor_recipe", "_builtin_ti1_path",
        "_vendor_debranded", "_layout_owned_by_build",
        "_engine_clip_saved", "_engine_leftclip_saved",
        "_engine_was_active", "_stamp_engine_state",
        # THE LAYOUT TRIPLE DENSITY IS HIDING. `_on_manual_td_toggled` stashes
        # the pre-TD `-a/-m/-P/-L` here when the box goes on and clears it when
        # the box goes off, and a preset switches the box off on its way in. The
        # box is put back with signals blocked — it has to be, its handler is not
        # idempotent — so without this the box came back ticked with no stash
        # behind it: unticking Triple Density afterwards reverted nothing and the
        # chart silently stayed at the triple-density spacing. Found on screen.
        "_td_saved_layout",
        # Written by `_convert_engine_to_printtarg` on the way in and read to
        # decide whether a LATER printtarg→engine switch keeps the panel's
        # margins or re-derives them from `-m`. Measured absent before a refused
        # preset and 10 after, which quietly changes that later decision.
        "_pt_margin_at_switch",
        # Restored LAST of the group and deliberately: if the preset was what
        # first seeded the layout panel, putting this back to False means the
        # next time the engine is switched on the panel is seeded again from
        # "Save as Defaults" — which is exactly what would have happened had the
        # preset never been chosen. `_init_manual_layout_panel` only sets the
        # flag and applies a recipe, so re-running it connects nothing twice.
        "_manual_panel_inited",
    )

    #: Tick boxes a preset can move. Restored with signals blocked: their
    #: handlers rewrite the very rows being restored, and one of them
    #: (`_on_manual_engine_toggled`) runs the whole engine↔printtarg conversion.
    _PRESET_CHECKS = (
        "_manual_engine_check", "_manual_td_check",
        "_manual_auto_patches_check", "_manual_left_clip_check",
        "_manual_auto_grey_check", "_manual_auto_white_check",
        "_manual_auto_black_check", "_manual_stamp_cmd_check",
        "_override_targen_check", "_override_printtarg_check",
    )

    def _snapshot_preset_state(self) -> dict | None:
        """Everything a built-in preset can move, exactly as it stands now.

        NOTHING HERE MAY RAISE. This runs inside a Qt slot, and PyQt hands an
        escaping exception to `sys.excepthook`, which ends in `qFatal()` — the
        app aborts (measured: SIGABRT). Every part is taken independently, so
        one unreadable row costs that row. If even the spine cannot be read the
        answer is None, which the caller reads as "there is no undo" and leaves
        the preset applied rather than half-undoing it.
        """
        snap: dict = {"checks": {}, "names": {}, "widgets": {},
                      "recipe": None, "pages": None, "pages_spin": None}
        try:
            snap["mode"] = self._mode_name()
            # THE VALUE *AND* WHETHER IT WAS EVER WRITTEN. `get` answers with
            # the default for a key nobody has touched, so value alone cannot
            # tell "absent" from "set to today's default" — and putting the
            # value back would pin a key that had never been in the file, which
            # then stops following a changed default.
            snap["settings"] = {k: (self._settings.get(k), self._is_stored(k))
                                for k in self._PRESET_PERSISTED_SETTINGS}
            snap["attrs"] = {a: getattr(self, a, None)
                             for a in self._PRESET_FAMILY_ATTRS}
            # NOT `currentIndex()` — by the time this runs the dropdown has
            # already moved to the new preset, so its own position is the thing
            # being undone. `_last_preset_index` is the selection that was
            # actually committed, which is what Basti's ruling means by "what
            # they were before the dropdown was touched".
            snap["combo_index"] = self._last_preset_index
            snap["last_preset_index"] = self._last_preset_index
            snap["del_enabled"] = self._is_deletable_preset(self._last_preset_index)
            snap["name_typed"] = bool(getattr(self, "_name_typed_by_user", False))
            snap["bit16"] = bool(self._bit16_radio is not None
                                 and self._bit16_radio.isChecked())
        except Exception:              # noqa: BLE001 — see the docstring
            log.warning("preset undo: the state could not be read, so this "
                        "preset cannot be undone", exc_info=True)
            return None
        for tool, widgets in self._manual_widgets.items():
            rows = []
            for pw in widgets:
                try:
                    rows.append((pw.flag, pw.get_raw_value(),
                                 bool(pw.is_enabled_by_user)))
                except Exception:      # noqa: BLE001 — one bad row, not the undo
                    # `getattr(pw, "flag", "?")` would RE-RAISE here: a default
                    # only covers a missing attribute, and a deleted C++ object
                    # raises `RuntimeError` from the property itself. Naming the
                    # tool is enough, and cannot fail.
                    log.debug("preset undo: could not read a %s row", tool,
                              exc_info=True)
            snap["widgets"][tool] = rows
        for attr in self._PRESET_CHECKS:
            try:
                w = getattr(self, attr, None)
                if w is not None:
                    snap["checks"][attr] = w.isChecked()
            except Exception:          # noqa: BLE001
                log.debug("preset undo: could not read %s", attr, exc_info=True)
        for attr in ("_target_name_edit", "_manual_target_name_edit"):
            try:
                w = getattr(self, attr, None)
                if w is not None:
                    snap["names"][attr] = w.text()
            except Exception:          # noqa: BLE001
                log.debug("preset undo: could not read %s", attr, exc_info=True)
        try:
            spin = getattr(self, "_manual_pages_spin", None)
            if spin is not None:
                snap["pages_spin"] = spin.value()
        except Exception:              # noqa: BLE001
            log.debug("preset undo: could not read the pages spin", exc_info=True)
        # WHETHER THE SECTIONS WERE OPEN. A preset locks the patch recipe and
        # `_update_preset_locks` collapses the targen frame while the lock is
        # on — but on the way back that same method does nothing, because it
        # only touches the frame while a preset is active. So a section the
        # person had deliberately opened was shut and stayed shut.
        for attr in ("_manual_targen_grp", "_manual_printtarg_grp"):
            try:
                grp = getattr(self, attr, None)
                if grp is not None and hasattr(grp, "is_collapsed"):
                    snap.setdefault("collapsed", {})[attr] = grp.is_collapsed()
            except Exception:          # noqa: BLE001
                log.debug("preset undo: could not read %s", attr, exc_info=True)
        # NOT GUARDED ON `_manual_panel_inited` — that is the bug this had.
        # Driven on screen: with the engine off, the panel exists but is not yet
        # seeded, so a guarded snapshot took no recipe; the refused A3 preset
        # then inited it and its layout (CM / 420x297 / 200 dpi / its four
        # margins) stayed behind, invisible until the person next switched the
        # engine on. `get_recipe()` answers before the panel is seeded, and
        # whatever it answers IS what was on screen.
        panel = getattr(self, "_manual_layout_panel", None)
        if panel is not None:
            try:
                snap["recipe"] = panel.get_recipe()
                snap["pages"] = panel.get_pages()
            except Exception:          # noqa: BLE001
                log.debug("preset undo: could not read the layout recipe",
                          exc_info=True)
        return snap

    def _is_stored(self, key: str) -> bool:
        """Has this settings key ever been WRITTEN, rather than answered by a
        default? Degrades to "yes" for a settings object that cannot say.

        Not every settings object in this codebase is an `AppSettings` — the
        test suite has a dozen small doubles with only `get`/`set`. Asking one
        of those directly raised `AttributeError` out of the snapshot, which
        skipped the whole undo and failed a test for a reason that had nothing
        to do with what it was testing. "Yes" is the safe answer: the value is
        written back, which is what happened before the key-pinning fix.
        """
        ask = getattr(self._settings, "is_stored", None)
        if ask is None:
            return True
        try:
            return bool(ask(key))
        except Exception:              # noqa: BLE001
            log.debug("could not ask whether %s is stored", key, exc_info=True)
            return True

    def _guarded(self, what: str, fn, *args) -> None:
        """Run one step of the preset undo and never let it out.

        The steps guard themselves internally, but a step that cannot even be
        ENTERED must still cost only itself — an exception escaping here reaches
        a Qt slot, where PyQt hands it to `sys.excepthook` and ChromIQ aborts
        (measured: SIGABRT), and it would leave the tab half-undone, which is
        worse than not undoing it at all.
        """
        try:
            fn(*args)
        except Exception:              # noqa: BLE001 — see the docstring
            log.warning("preset undo: %s could not be put back", what,
                        exc_info=True)

    def _write_back_settings(self, snap: dict) -> None:
        """Put the persisted settings back WITHOUT materialising keys.

        `AppSettings.get` answers with the DEFAULT for a key nobody has ever
        written, so a value alone cannot tell "absent" from "set to today's
        default" — and writing every key back turned the first into the second.
        A pinned key stops following a changed default and needs a migration to
        move it, so the snapshot records whether each key was STORED, and a key
        that was not is removed rather than written. Measured: one refused
        preset used to pin `use_chromiq_layout_engine` and
        `i1pro_chromiq_clip_style` in the person's file for good, and the
        preset's own seeding is what put the first one there.
        """
        for key, (value, was_stored) in snap["settings"].items():
            try:
                if not was_stored:
                    # It was not in the file before the preset, so it does not
                    # go in the file after one the person refused. Measured: a
                    # refused preset pinned `use_chromiq_layout_engine` and
                    # `i1pro_chromiq_clip_style` for good.
                    if self._is_stored(key) and hasattr(self._settings, "unset"):
                        self._settings.unset(key)
                elif self._settings.get(key) != value:
                    self._settings.set(key, value)
            except Exception:          # noqa: BLE001 — one key, not the undo
                log.warning("preset undo: could not restore the setting %s",
                            key, exc_info=True)

    def _assert_preset_checks(self, snap: dict) -> None:
        """Force every tick box back to the snapshot, silently.

        Called more than once on purpose. Three separate slots reached during
        the restore move a box on their own — the command stamp when the engine
        state it remembers disagrees with the engine, Triple Density when the
        instrument is momentarily not a ColorMunki, the Auto-neutral greying —
        and every one of them fired AFTER the boxes had been correctly put back.
        Rather than order those slots and hope, the boxes are simply asserted
        again after anything that could move them.
        """
        for attr, was in snap["checks"].items():
            try:
                w = getattr(self, attr, None)
                if w is None or w.isChecked() == was:
                    continue
                log.debug("preset undo: %s was moved to %s during the restore; "
                          "putting it back to %s", attr, not was, was)
                w.blockSignals(True)
                w.setChecked(was)
                w.blockSignals(False)
            except Exception:          # noqa: BLE001 — one box, not the undo
                log.warning("preset undo: could not restore %s", attr,
                            exc_info=True)

    def _restore_preset_state(self, snap: dict) -> None:
        """Put back everything :meth:`_snapshot_preset_state` took.

        EVERY STEP IS INDEPENDENT AND NONE OF THEM MAY RAISE. This is reached
        from a Qt slot, where an escaping exception aborts the whole app
        (measured: SIGABRT), and a raise part-way leaves the tab in a state
        worse than no undo at all — the parameter rows back, but the dropdown,
        the name field and the family flags still on the preset that was
        refused. One step failing must therefore cost that step and nothing
        else.

        THE ORDER IS LOAD-BEARING, AND IT WAS MEASURED BOTH WAYS.

        * `-i` goes back before `-m`, because setting the instrument re-applies
          that instrument's default margin. Restoring the rows in reverse panel
          order rewrote a margin of 10 that the user had typed to 6.
        * The layout recipe goes back BEFORE the rows it writes into.
          `panel.set_recipe` applies the recipe one control at a time, and the
          instrument combo's slot reads the panel's paper — still the refused
          preset's — and pushes it into `-p`.
        * The tick boxes are asserted LAST, and again after the greying, because
          three different slots move them behind the restore's back.
        """
        # 0. AN AGREED "REPLACE IT" IS NOT AGREED TO ANY MORE. The person said
        #    yes to the archive and then no to what followed, so the answer must
        #    not outlive the window that asked for it. `_generate_from_ti1`'s
        #    refusals do not clear it themselves, and it is not an attribute
        #    this method could put back — it never had a "before" value. Every
        #    known consumer re-asks first, so nothing acts on it today; the same
        #    leak four times over is what once archived a whole project with no
        #    window on screen, and `_forget_gate_answer` says so by name.
        try:
            self._forget_gate_answer()
        except Exception:              # noqa: BLE001
            log.warning("preset undo: could not clear the gate answer",
                        exc_info=True)
        # 1. The mode. BELT AND BRACES, and honestly so: the snapshot is taken
        #    inside `_on_preset_selected`, by which time `_activate_builtin_preset`
        #    has already switched to Manual — so this line does nothing on the
        #    routes that exist today, and the mode is really put back by that
        #    method. It stays for a future caller that snapshots earlier.
        try:
            if snap["mode"] != self._mode_name():
                self._switch_mode(snap["mode"])
        except Exception:              # noqa: BLE001
            log.warning("preset undo: could not restore the mode", exc_info=True)
        # 2. The settings that outlive the run. Written HERE so that everything
        #    below reads the right value while it works — `panel.set_recipe`
        #    emits `changed`, and one of that signal's slots reloads the whole
        #    layout frame from `use_chromiq_layout_engine`.
        self._guarded("the stored settings", self._write_back_settings, snap)
        # 3. Tick boxes, silenced. Asserted again at step 12; see that step.
        self._guarded("the tick boxes", self._assert_preset_checks, snap)
        # 3b. …but "Auto patch count" also greys the -f and Pages controls, and
        #     that is visible. Run its handler HERE, before the rows: it writes
        #     -f, so afterwards the row restore below would have to fight it.
        try:
            if getattr(self, "_manual_auto_patches_check", None) is not None:
                self._on_auto_patches_toggled(
                    snap["checks"].get("_manual_auto_patches_check", False))
        except Exception:              # noqa: BLE001
            log.debug("preset undo: auto-patch refresh failed", exc_info=True)
        # 4. The bit-depth radios. `setChecked(False)` on an auto-exclusive
        #    radio does nothing, so check the one that WAS on.
        try:
            radio = self._bit16_radio if snap["bit16"] else self._bit8_radio
            if radio is not None and not radio.isChecked():
                radio.setChecked(True)
        except Exception:              # noqa: BLE001
            log.warning("preset undo: could not restore the bit depth",
                        exc_info=True)
        # 5. THE LAYOUT PANEL GOES BACK BEFORE THE ROWS IT WRITES INTO — see
        #    the docstring. Measured: restoring the rows first left `-p` on the
        #    A3 preset's 420x297 while every other row was correctly back.
        panel = getattr(self, "_manual_layout_panel", None)
        if panel is not None and snap["recipe"] is not None:
            try:
                panel.set_recipe(snap["recipe"])
                if snap["pages"] is not None:
                    panel.set_pages(snap["pages"])
            except Exception:          # noqa: BLE001
                log.warning("preset undo: could not restore the layout recipe",
                            exc_info=True)
        # 6. Every parameter row, in panel order (see the docstring) — the last
        #    word on the rows, after anything the panel pushed into them.
        # THE WHOLE STEP IS INSIDE THE GUARD, LOOP HEADER INCLUDED. Two lines
        # here used to sit outside every `try`: the iteration itself, and
        # `pw.flag`, which raises `RuntimeError` on a ParameterWidget whose C++
        # object has been deleted — the snapshot's identical access was already
        # guarded, and this one was not. Either raise skipped steps 7 to 12 and
        # left the dropdown, the family flags and `-i` on the preset that had
        # just been refused: precisely the "worse than no undo" state this
        # method says it has removed.
        try:
            for tool, rows in snap["widgets"].items():
                try:
                    by_flag = {pw.flag: pw
                               for pw in self._manual_widgets.get(tool, [])}
                except Exception:      # noqa: BLE001 — one tool, not the undo
                    log.warning("preset undo: could not index the %s rows",
                                tool, exc_info=True)
                    continue
                for flag, value, enabled in rows:
                    pw = by_flag.get(flag)
                    if pw is None:
                        continue
                    try:
                        pw.set_value(value)
                        pw.set_user_enabled(enabled)
                    except Exception:  # noqa: BLE001 — one row, not the undo
                        log.debug("preset undo: could not restore %s %s", tool,
                                  flag, exc_info=True)
        except Exception:              # noqa: BLE001 — the step, not the undo
            log.warning("preset undo: the parameter rows could not be put back",
                        exc_info=True)
        try:
            spin = getattr(self, "_manual_pages_spin", None)
            if spin is not None and snap["pages_spin"] is not None:
                spin.setValue(snap["pages_spin"])
        except Exception:              # noqa: BLE001
            log.warning("preset undo: could not restore the page count",
                        exc_info=True)
        # 7. AND THE SETTINGS AGAIN, because steps 5 and 6 both emit `changed`
        #    and one of its slots re-persists the ruler markers from the panel.
        #
        #    HONESTLY: with the ordering above, either this write or step 2
        #    alone passes the suite — the recipe being restored is the person's
        #    own, so what gets re-persisted in between is what we want anyway.
        #    Mutation-tested both ways; only removing BOTH fails. Both are kept
        #    because they guard different moments (step 2 what the intermediate
        #    refreshes read, step 7 what survives them), and because the cost of
        #    being wrong here is a preference silently changed for good.
        self._guarded("the stored settings", self._write_back_settings, snap)
        # 8. The name the person had, and whether THEY typed it. That flag is
        #    what §S4.7 keys off, so a seeded name must not be left looking typed.
        try:
            for attr, text in snap["names"].items():
                w = getattr(self, attr, None)
                if w is not None and w.text() != text:
                    w.blockSignals(True)
                    w.setText(text)
                    w.blockSignals(False)
            self._name_typed_by_user = snap["name_typed"]
        except Exception:              # noqa: BLE001
            log.warning("preset undo: could not restore the name", exc_info=True)
        # 9. Which family of chart is on screen. GUARDED SEPARATELY: this and
        #    step 10 are what make a partial restore incoherent rather than
        #    merely incomplete, so neither may be skipped by an earlier raise.
        try:
            for attr, value in snap["attrs"].items():
                setattr(self, attr, value)
        except Exception:              # noqa: BLE001
            log.warning("preset undo: could not restore the family flags",
                        exc_info=True)
        # 10. The dropdown, silently — `activated` is a user's signal.
        try:
            self._preset_combo.blockSignals(True)
            self._preset_combo.setCurrentIndex(snap["combo_index"])
            self._preset_combo.blockSignals(False)
            self._last_preset_index = snap["last_preset_index"]
            self._preset_del_btn.setEnabled(snap["del_enabled"])
        except Exception:              # noqa: BLE001
            log.warning("preset undo: could not restore the dropdown",
                        exc_info=True)
        self._preset_selection_reverted = True
        # 11. Everything that only READS the state above, so the screen agrees
        #     with it: locks, row visibility, the engine frame and the preview.
        try:
            self._update_preset_locks()
            self._update_manual_lb_visibility()
            self._refresh_helper_marker_support()
            self._refresh_manual_command_preview()
            # The name went back at step 8 with the field's signals BLOCKED, so
            # the "you already have a project with this name" line — which is
            # wired to `textChanged` — never heard about it. It sat over an
            # emptied box, describing a name that was no longer there.
            self._refresh_project_exists_line()
        except Exception:              # noqa: BLE001 — never leave the tab dead
            log.warning("preset undo: could not refresh the panel", exc_info=True)
        # 12. THE TICK BOXES GET THE LAST WORD, then the greying they own, then
        #     the last word again. Three slots reached above move a box on their
        #     own and all three did: the command stamp was unticked by the
        #     preview refresh, Triple Density by the instrument-visibility pass
        #     while `-i` was momentarily not a ColorMunki, and the three Auto
        #     neutrals were left ticked beside boxes that read 0 instead of
        #     "Auto" because only the box, not its greying, had been restored.
        self._guarded("the tick boxes", self._assert_preset_checks, snap)
        for which, (_pw_attr, chk_attr) in self._AUTO_NEUTRAL_MAP.items():
            try:
                if getattr(self, chk_attr, None) is not None:
                    self._on_auto_neutral_toggled(
                        which, bool(snap["checks"].get(chk_attr, False)))
            except Exception:          # noqa: BLE001
                log.debug("preset undo: auto-%s refresh failed", which,
                          exc_info=True)
        try:
            self._update_manual_lb_visibility()
        except Exception:              # noqa: BLE001
            log.debug("preset undo: row visibility refresh failed", exc_info=True)
        # …and the sections the person had open. This must come AFTER
        # `_update_preset_locks` in step 11, because that is what shut them:
        # it collapses the targen frame while a preset locks the recipe, and on
        # the way back it leaves the frame exactly as the preset left it. Worst
        # under Run type = Calibration, where ChromIQ opens that section on
        # purpose so "Single Channel Steps" — the row that decides the
        # calibration — is in view; a person who tried a preset and backed out
        # was left with it shut and nothing saying why. Found on screen.
        for attr, was_collapsed in (snap.get("collapsed") or {}).items():
            try:
                grp = getattr(self, attr, None)
                if grp is not None and grp.is_collapsed() != was_collapsed:
                    grp.set_collapsed(was_collapsed)
            except Exception:          # noqa: BLE001
                log.debug("preset undo: could not restore %s", attr,
                          exc_info=True)
        # …and once more, which is INSURANCE AND NOT PROVEN LOAD-BEARING: the
        # visibility pass just above is the one thing left that can move a box
        # (it force-unticks Triple Density when the instrument is not a
        # ColorMunki), and by now `-i` has been restored so it does not. Removing
        # this line alone still passes the suite; removing it AND the assertion
        # before the greying does not. Kept because it costs six comparisons and
        # the fault it guards against was on screen twice this week.
        self._guarded("the tick boxes", self._assert_preset_checks, snap)
        # LAST OF ALL, and deliberately after that final assert: the one piece
        # of greying a forced box owns which nothing above re-derives. Triple
        # Density disables "Double density", because the two are mutually
        # exclusive. Its handler cannot simply be re-run — called again with
        # True it would stash the TRIPLE-density values as the "pre-TD" ones,
        # which is #89's round-trip bug — so the box's own rule is applied
        # directly. It has to run after the last assert, not before: an assert
        # that re-ticks Triple Density would otherwise leave "Double density"
        # enabled beside it, which is the very fault this line exists to fix.
        try:
            _td = getattr(self, "_manual_td_check", None)
            if _td is not None and self._manual_dd_pw is not None:
                self._manual_dd_pw.setEnabled(not _td.isChecked())
        except Exception:              # noqa: BLE001
            log.debug("preset undo: could not re-grey Double density",
                      exc_info=True)
        log.info("Create Chart: the preset was refused, the tab was put back")

    def _on_preset_activated(self, index: int) -> None:
        """A real click (or keyboard choice) in the presets dropdown.

        RE-CHOOSING WHAT IS ALREADY SHOWING IS A BUILT-IN'S PRIVILEGE, and this
        slot is where that is decided — not in `_on_preset_selected`, which is
        also the entry point for the ★ overlay and for callers that mean
        "apply this entry now" regardless of what the dropdown shows.

        The dropdown moved from `currentIndexChanged` to `activated` so that a
        built-in put back after a refusal can be chosen again; with the
        change-only signal it could not (#175). But `activated` also fires when
        a person opens the list and clicks the entry that is already ticked,
        which is an easy gesture to make by accident — and until #175 that click
        did nothing at all. Measured on "none": it re-ran the Default branch and
        rewrote every manual row from the stored defaults, so a typed margin of
        17 and a patch count of 999 went back to 6 and 0 with nothing said; a
        user preset with "generate on select" would have started a build.
        Basti's ruling is about the built-ins, so only they re-dispatch.
        """
        if index == self._last_preset_index \
                and self._preset_combo.itemData(index) not in BUILTIN_PRESET_KEYS:
            log.debug("Create Chart: %r was already the selection; a re-pick "
                      "of a non-built-in entry changes nothing", index)
            return
        self._on_preset_selected(index)

    def _on_preset_selected(self, index: int) -> None:
        # Group-divider separators aren't real choices. The combo skips them on
        # mouse/keyboard interaction, but guard anyway so one can never be
        # treated as a selection — restore the prior pick instead.
        if index > 0 and self._preset_combo.itemData(index) is None \
                and not self._preset_combo.itemText(index):
            self._revert_preset_combo()
            return
        data = self._preset_combo.itemData(index)

        # Applying a preset writes the whole layout panel. That is the app
        # filling the widgets, not the user turning knobs, so the live preview
        # must be left where it was found — on EVERY exit, including the
        # mid-way returns below (a preset with `auto_run` while a process is
        # already running leaves through one of them). Measured on current
        # master: selecting a user preset re-laid out the chart and rewrote it
        # to disk, 450 ms after the click, with nothing else touched.
        try:

            # Temporarily-disabled built-ins are greyed out and unselectable in the
            # UI, but guard anyway so a programmatic selection can never apply one.
            if data in DISABLED_BUILTIN_PRESET_KEYS:
                self._revert_preset_combo()
                return

            # Built-in presets generate immediately under the current Printer-profile
            # name — selecting a preset is a *chart-layout* choice and never changes
            # the profile name the user typed (#70, Knut's model). The preset's own
            # default name is only a fallback used when the name field is still empty.
            if data in BUILTIN_PRESET_KEYS:
                if self._runner.is_running:
                    log.warning("Built-in preset: a process is already running")
                    self._revert_preset_combo()
                    return
                name = None
                # EVERYTHING BELOW IS UNDOABLE FROM HERE (#175). Taken before the
                # first tear-down, because those run whether or not the build is
                # ever agreed to, and Basti's ruling is that a preset the person
                # backs out of leaves nothing behind at all.
                # NOTHING HERE MAY ESCAPE THIS SLOT. `_snapshot_preset_state`
                # guards every part of itself and answers None when it cannot
                # read the spine, but this is a Qt slot: an exception getting
                # out does not merely lose the undo, PyQt hands it to
                # `sys.excepthook`, which ends in `qFatal()` and takes ChromIQ
                # down. Measured as SIGABRT. None simply means "no undo", and
                # then the preset stays applied — what happened before #175.
                try:
                    _undo = self._snapshot_preset_state()
                except Exception:      # noqa: BLE001 — see above
                    log.error("Create Chart: the state could not be read, so "
                              "this preset cannot be undone", exc_info=True)
                    _undo = None
                # Switching from the TC9.18 chart to another built-in clears the
                # expert printtarg overrides it forced on (margins, spacers, etc.).
                if self._tc918_active and data != TC918_PRESET_KEY:
                    self._reset_tc918_overrides()
                    self._tc918_active = False
                    self._tc918_targen_sig = None
                # Switching away from a TC9.18+Spyderprint preset clears its printtarg
                # overrides; picking another one of them re-seeds cleanly, so only
                # reset when the new pick isn't itself one of them.
                if self._knut_active and data not in KNUT_PRESET_KEYS:
                    self._reset_knut_overrides()
                    self._knut_active = False
                    self._knut_targen_sig = None
                # Leaving a prebuilt-files preset for a params-based built-in
                # (TC9.18 / ColorMunki) must re-enable the greyed param panels.
                if self._prebuilt_active and data not in PREBUILT_PRESETS:
                    self._leave_prebuilt()
                # Picking any preset drops an applied editor chart's binding.
                if self._applied_active:
                    self._leave_applied()
                if self._reflected_active:
                    self._leave_reflected()
                self._preset_ti1_path = None  # built-ins are not ti1-user-presets
                self._preset_ti1_targen_sig = None
                # A built-in that ships a creation recipe (Set B) seeds the New-chart
                # window just like a user preset — so loading it carries its colour
                # sets / layout into New chart, not the app-wide last-used state
                # (Knut).
                #
                # A BUILT-IN WITH NO DESIGN CLEARS THE RECORD, IT DOES NOT LEAVE IT.
                # 15 of the built-ins are fixed .ti1 charts with no recipe — the
                # nine "by Pharmacist" ones and the six Red River ones. `None` here
                # means "don't touch", so building one of those into a run that had
                # previously held a preset left the PREVIOUS preset's design on the
                # run, describing a chart it did not build. From there it was copied
                # into any preset saved from that run, and offered as the basis for
                # the next design in "Load setup from preset" (#164, Knut: *"a
                # previously created patch set setting is there instead"*).
                from workflow.ti2_relayout import NO_RECIPE
                self._pending_editor_recipe = builtin_preset_recipe(data) or NO_RECIPE
                # …but a built-in's own bundled .ti1 still feeds Suggest-name (#62).
                asset = self._builtin_ti1_asset(data)
                self._builtin_ti1_path = resource_path(asset) if asset else None
                # Start the freshly-picked built-in with its panels locked again.
                self._reset_override_checks()
                self._preset_del_btn.setEnabled(False)
                # THE SELECTION IS COMMITTED AFTER THE PRESET IS APPLIED, NOT
                # BEFORE. This line used to sit here, above the dispatch — so
                # by the time anything called `_revert_preset_combo` it was
                # restoring the combo to the index the combo was already on, and
                # EVERY built-in preset's revert was a no-op. Driven through the
                # real dropdown: answer "Cancel" to the project window, whose
                # own button says it changes nothing, and the dropdown went on
                # showing a preset that had not been applied — with the panels
                # still on their old values. Worse, `_last_preset_index` then
                # matched the combo, so picking the same preset again emitted no
                # signal at all and nothing happened until the user chose
                # something else first.
                self._preset_selection_reverted = False
                # Load each built-in with the engine it was made with: most are
                # printtarg-based (they predate the engine), but the Scanner family
                # carries a layout_recipe and needs the ChromIQ engine ON so the
                # recipe drives the layout (#100). Set BEFORE the dispatch so the
                # engine↔printtarg conversion runs first and the preset's values
                # then win — otherwise the layout panel would show leftovers
                # instead of the preset's real instrument/paper (Knut).
                _kp = KNUT_PRESETS_BY_KEY.get(data)
                engine_builtin = _kp is not None and (
                    _kp.layout_recipe is not None or _kp.engine)
                if getattr(self, "_manual_engine_check", None) is not None \
                        and self._manual_engine_check.isChecked() != engine_builtin:
                    self._set_engine_checked(engine_builtin)
                if data == TC918_PRESET_KEY:
                    applied = self._apply_tc918_preset(name)
                elif data in KNUT_PRESET_KEYS:
                    applied = self._apply_knut_preset(data, name)
                elif data in PREBUILT_PRESETS:
                    applied = self._apply_prebuilt_preset(data, name)
                else:
                    applied = self._apply_colormunki_td_preset(
                        *MUNKI_TARGEN[data], target_name=name)
                if not applied:
                    # THE PERSON SAID NO. Put the tab back exactly as it was —
                    # the mode, the panel, the flags and the settings that
                    # outlive the app run (#175, Basti 2026-08-27/28).
                    #
                    # BELT AND BRACES ROUND A SLOT. `_restore_preset_state`
                    # already guards every step of itself; this catches anything
                    # outside them, because an exception escaping a Qt slot does
                    # not merely abort the undo — PyQt hands it to
                    # `sys.excepthook`, which ends in `qFatal()` and takes
                    # ChromIQ down. Measured: SIGABRT. A snapshot that could not
                    # be read is None, and then the preset simply stays applied,
                    # which is what happened before this feature existed.
                    if _undo is None:
                        log.warning("Create Chart: the preset was refused but "
                                    "there is no undo to apply")
                    else:
                        try:
                            self._restore_preset_state(_undo)
                        except Exception:      # noqa: BLE001 — see above
                            log.error("Create Chart: putting the tab back after "
                                      "a refused preset failed", exc_info=True)
                    return
                # Final lock pass: covers the params-based ColorMunki presets (which
                # set no ti1/prebuilt flag, so their panels stay fully editable) and
                # re-asserts state after leaving a previous tc918/knut preset.
                self._update_preset_locks()
                if not self._preset_selection_reverted:
                    self._last_preset_index = index
                return

            # Leaving the TC9.18 built-in chart for Default or a user preset clears
            # the expert printtarg overrides it forced on (margins -m/-M, black &
            # white spacers -b, …). The restores below only *set* flags the target
            # preset stores, so without this they would bleed through.
            if self._tc918_active:
                self._reset_tc918_overrides()
                self._tc918_active = False
                self._tc918_targen_sig = None
            # Same for a TC9.18+Spyderprint preset → Default / a user preset.
            if self._knut_active:
                self._reset_knut_overrides()
                self._knut_active = False
                self._knut_targen_sig = None
            # Leaving a prebuilt-files preset re-enables the greyed param panels.
            if self._prebuilt_active:
                self._leave_prebuilt()
            # Likewise an applied editor chart is dropped for Default / a user preset.
            if self._applied_active:
                self._leave_applied()
            if self._reflected_active:
                self._leave_reflected()

            self._last_preset_index = index
            self._preset_del_btn.setEnabled(self._is_deletable_preset(index))
            s = self._settings
            if index == 0:
                # Returning to Default builds a fresh chart via targen. The
                # Printer-profile name is the user's own and is left untouched (#70).
                for tool, widgets in self._manual_widgets.items():
                    for pw in widgets:
                        if pw in self._d_cascade_widgets:
                            continue
                        # Use the same case-disambiguated key that _on_save_defaults
                        # writes, so single-char flags (-l, -g, …) round-trip here too.
                        key = _pw_settings_key(tool, pw.flag)
                        v = s.get(key)
                        if v is None:
                            # No saved default for this row → revert to its factory
                            # default (and clear any expert enable-checkbox). Without
                            # this, picking "Default" would leave a row the user
                            # changed but never saved untouched — the reported bug.
                            pw.reset_to_default()
                            continue
                        pw.set_value(v)
                        if pw.has_separate_enable:
                            pw.set_user_enabled(bool(s.get(f"{key}_enabled", False)))
                for idx, pw in enumerate(self._d_cascade_widgets):
                    v = s.get(f"manual_targen_-D_{idx}")
                    if v is not None:
                        pw.set_value(v)
                    pw.set_user_enabled(bool(s.get(f"manual_targen_-D_{idx}_enabled", False)))
                self._rebuild_d_cascade_visibility()
                self._builtin_ti1_path = None     # Default builds via targen
                # "Default" BUILDS A FRESH targen CHART, SO IT HAS NO DESIGN —
                # and `None` here meant "leave whatever the run already says",
                # which left the previously selected preset's design standing as a
                # description of a chart it did not build. One click on Default was
                # enough to reproduce Knut's *"a previously created patch set
                # setting is there instead"* (#164).
                from workflow.ti2_relayout import NO_RECIPE
                self._pending_editor_recipe = NO_RECIPE
                if self._bit8_radio is not None and self._bit16_radio is not None:
                    is_16bit = bool(s.get("manual_printtarg_tiff_16bit", False))
                    self._bit16_radio.setChecked(is_16bit)
                    self._bit8_radio.setChecked(not is_16bit)
                if self._manual_pages_spin is not None:
                    self._manual_pages_spin.setValue(int(s.get("manual_pages", 1)))
                if self._manual_auto_patches_check is not None:
                    auto_on = bool(s.get("manual_auto_patches", True))
                    self._manual_auto_patches_check.setChecked(auto_on)
                    self._on_auto_patches_toggled(auto_on)
                self._load_auto_neutral_states(
                    grey  = bool(s.get("manual_auto_grey",  True)),
                    white = bool(s.get("manual_auto_white", True)),
                    black = bool(s.get("manual_auto_black", True)),
                )
                self._manual_left_clip_check.setChecked(
                    bool(s.get("chart_left_clip_info", False))
                )
                if self._manual_td_check is not None:
                    self._manual_td_check.setChecked(
                        bool(s.get("manual_printtarg__triple_density", False))
                    )
                self._preset_ti1_path = None      # Default builds via targen
            else:
                name = self._preset_combo.currentData()
                presets = self._load_presets_from_settings()
                pdata = presets.get(name, {})
                self._restore_user_preset(pdata)
                # Load the preset with the engine it was made with (Knut #93): a
                # Manual preset stores printtarg widget values (no layout_recipe), so
                # select the printtarg engine — otherwise the ChromIQ engine would try
                # to render it and the preview is wrong. The restored -i/-p widgets
                # then drive the (correct) instrument & paper. An engine preset (future
                # layout_recipe) would instead switch the engine on.
                if getattr(self, "_manual_engine_check", None) is not None:
                    has_recipe = isinstance(pdata, dict) and bool(pdata.get("layout_recipe"))
                    self._set_engine_checked(has_recipe)
                # Carry the preset's stored New-chart recipe (Set B), if any, so a
                # chart generated from it reopens in the editor with this design
                # pre-loaded into New chart / Add (#70, Knut follow-up).
                rec = pdata.get("editor_recipe") if isinstance(pdata, dict) else None
                self._pending_editor_recipe = rec if isinstance(rec, dict) and rec else None
                self._builtin_ti1_path = None     # a user preset, not a built-in
                # A user preset that bundled a .ti1 builds from it (skip targen). Point
                # Generate at the sidecar file if it's present; otherwise fall back to
                # the normal targen path.
                self._preset_ti1_path = None
                self._preset_ti1_targen_sig = None
                if isinstance(pdata, dict) and pdata.get("attached_ti1"):
                    p = _preset_sidecar_path("create_chart", str(name), ".ti1")
                    if p.is_file():
                        self._preset_ti1_path = p
                        # Snapshot targen so the override box can opt into a fresh
                        # targen run (changed → different patches), like the built-ins.
                        self._preset_ti1_targen_sig = self._targen_signature()
                    else:
                        log.warning("preset '%s' marked attached_ti1 but %s is missing",
                                    name, p)
            # Every Default / user-preset selection re-establishes the lock state:
            # untick any leftover override and grey the panels a ti1 preset needs.
            self._reset_override_checks()
            self._update_preset_locks()
            self._update_manual_lb_visibility()
            # Re-establish the descriptive prefix: cleared while a preset name is
            # loaded, re-applied to the editable tail back on Default (#68).
            self._refresh_name_prefix()

            # A user preset flagged "generate on select" (▶) generates straight away
            # under the current Printer-profile name (#70) — the values are already
            # loaded above. The preset name is never written into the profile field.
            if data is not None and data not in BUILTIN_PRESET_KEYS:
                presets = self._load_presets_from_settings()
                pdata = presets.get(data, {})
                if isinstance(pdata, dict) and pdata.get("auto_run"):
                    if self._runner.is_running:
                        return
                    self._on_generate()
        finally:
            self._settle_live_preview()

    def _restore_user_preset(self, data: dict) -> None:
        """Apply a saved user preset's stored values to the manual widgets."""
        for tool, widgets in self._manual_widgets.items():
            for pw in widgets:
                if pw in self._d_cascade_widgets:
                    continue
                v = data.get(f"{tool}_{pw.flag}")
                if v is not None:
                    pw.set_value(v)
                # Re-arm expert non-boolean rows from the stored enable state.
                # Only act when the key was persisted, so presets saved before
                # this fix (which stored a value regardless of the checkbox)
                # don't suddenly turn their flag on.
                if pw.has_separate_enable:
                    en = data.get(f"{tool}_{pw.flag}_enabled")
                    if en is not None:
                        pw.set_user_enabled(bool(en))
        for idx, pw in enumerate(self._d_cascade_widgets):
            v = data.get(f"targen_-D_{idx}")
            if v is not None:
                pw.set_value(v)
            pw.set_user_enabled(bool(data.get(f"targen_-D_{idx}_enabled", False)))
        self._rebuild_d_cascade_visibility()
        if self._bit8_radio is not None and self._bit16_radio is not None:
            is_16bit = bool(data.get("tiff_16bit", False))
            self._bit16_radio.setChecked(is_16bit)
            self._bit8_radio.setChecked(not is_16bit)
        if self._manual_pages_spin is not None:
            self._manual_pages_spin.setValue(int(data.get("pages", 1)))
        if self._manual_auto_patches_check is not None:
            auto_on = bool(data.get("auto_patches", False))
            self._manual_auto_patches_check.setChecked(auto_on)
            self._on_auto_patches_toggled(auto_on)
        self._load_auto_neutral_states(
            grey  = bool(data.get("auto_grey",  False)),
            white = bool(data.get("auto_white", False)),
            black = bool(data.get("auto_black", False)),
        )
        self._manual_left_clip_check.setChecked(bool(data.get("left_clip_info", False)))
        # Apply triple-density last. The saved values already ARE the effective
        # TD layout, so suppress the override so re-enabling the checkbox keeps
        # the restored -a / -m / -P / -L instead of snapping them to 1.3 / 5 (#89).
        if self._manual_td_check is not None:
            td_on = bool(data.get("triple_density", False))
            self._suppress_td_override = td_on
            try:
                self._manual_td_check.setChecked(td_on)
            finally:
                self._suppress_td_override = False
        # Auto-match the engine toggle to what the preset actually contains, so
        # the shown controls reflect the preset (engine panel vs printtarg). A
        # preset carries "layout_recipe" iff it was saved with the engine on;
        # old/printtarg presets lack it → engine off. Shareable + back-compat
        # (the flag lives in the preset file, not local state) (#93). Toggle and
        # refresh FIRST so the engine panel is built before we seed it (the
        # build reseeds from the store, which would clobber the preset recipe).
        lr = data.get("layout_recipe")
        engine_on = isinstance(lr, dict) and bool(lr)
        if bool(self._settings.get("use_chromiq_layout_engine", False)) != engine_on:
            self._settings.set("use_chromiq_layout_engine", engine_on)
        if engine_on:
            self._refresh_manual_command_preview()   # swap groups + init panel
            if getattr(self, "_manual_layout_panel", None) is not None:
                from dataclasses import replace as _replace
                from workflow.layout_engine.presets import LayoutRecipe
                # A preset the person picked BY NAME owns its layout: the
                # instrument defaults may not write over it afterwards. Forced
                # rather than read, because presets saved before the flag
                # existed do not carry it.
                self._set_engine_recipe(
                    _replace(LayoutRecipe.from_dict(lr), layout_explicit=True))
                # The recipe carries its own instrument/paper — mirror them onto
                # the printtarg -i/-p so Preferences preselect + naming follow the
                # loaded engine preset (set_recipe suppresses the live mirror) (#93).
                self._sync_manual_selection_from_panel()
        else:
            self._refresh_manual_command_preview()   # show printtarg controls
        # Chart notes + stamp choice, gated on key presence so presets saved
        # without them keep the fields untouched. AFTER the engine block: an
        # engine flip resets the stamp checkbox to its mode default via
        # _refresh_manual_command_preview, which would overwrite these.
        if "chart_notes" in data and self._manual_chart_notes_edit is not None:
            self._manual_chart_notes_edit.setText(
                str(data.get("chart_notes") or ""))
        if ("stamp_commands" in data
                and self._manual_stamp_cmd_check is not None):
            self._manual_stamp_cmd_check.setChecked(
                bool(data.get("stamp_commands")))

    def _preset_save_prefill(self) -> tuple[str, bool, bool, bool]:
        """Initial (name, auto_run, attach, from_generator) for the Save Preset
        dialog.

        A preset names a **chart layout**, so the default is the descriptive
        generator name (instrument-paper-patches-pages-orientation) — *not* the
        printer-profile name in the Output frame, which describes the job, not
        the layout (#70, Knut). A non-built-in preset selected in the combo is
        the fallback when there's no generator name yet.

        Options follow the *name*: if it matches an existing user preset (i.e.
        you're about to overwrite it) its stored auto_run / attach are reused;
        otherwise it's a new preset and both default on — the common case."""
        generated = self._suggest_target_name().strip()
        cur_key = self._preset_combo.currentData()
        selected_preset = (str(cur_key)
                           if cur_key is not None and cur_key not in BUILTIN_PRESET_KEYS
                           else "")
        name = generated or selected_preset
        existing = self._load_presets_from_settings().get(name)
        if isinstance(existing, dict):
            return (name, bool(existing.get("auto_run")),
                    bool(existing.get("attached_ti1")), bool(generated))
        return (name, True, True, bool(generated))

    @staticmethod
    def _paper_name_and_orientation(paper: str) -> tuple[str, str]:
        """(base paper name, orientation) for a printtarg -p value, read from the
        paper labels (which carry "… Portrait" / "… Landscape"), e.g.
        ``"A4R"`` → ``("A4", "Landscape")``. Custom ``WxH`` sizes derive the
        orientation from their dimensions."""
        label = PAPER_LABELS.get(paper, "")
        if label:
            # Filesystem-safe readable token (A3+ → A3Plus, 8×10" → 8x10in) (#68).
            base = paper_name_token(paper)
            orient = ("Landscape" if "Landscape" in label
                      else "Portrait" if "Portrait" in label else "")
            return base, orient
        if "x" in str(paper):
            try:
                w, h = (float(v) for v in str(paper).split("x", 1))
                return str(paper), ("Landscape" if w > h else "Portrait")
            except ValueError:
                pass
        return str(paper), ""

    def comparable_presets(self) -> list[tuple[str, list[tuple[str, "Path"]]]]:
        """See the module-level :func:`comparable_presets` (#66)."""
        return comparable_presets(self._settings)

    @staticmethod
    def _builtin_ti1_asset(data: str) -> str | None:
        """Asset path of a built-in preset's bundled .ti1, or None for the
        targen-based built-ins (ColorMunki Triple-density) that have no .ti1."""
        if data == TC918_PRESET_KEY:
            return TC918_TI1_ASSET
        if data in KNUT_PRESETS_BY_KEY:
            return KNUT_PRESETS_BY_KEY[data].ti1_asset
        if data in PREBUILT_PRESETS:
            return PREBUILT_PRESETS[data][0] + ".ti1"
        return None

    def _loaded_ti1_patch_count(self) -> int | None:
        """Patch count of the .ti1 backing the current selection, if any —
        a user preset's sidecar (_preset_ti1_path), a built-in's bundled .ti1
        (_builtin_ti1_path, #62), or the chart just generated (_current_ti1_path)."""
        for p in (getattr(self, "_preset_ti1_path", None),
                  getattr(self, "_builtin_ti1_path", None),
                  getattr(self, "_current_ti1_path", None)):
            if p and Path(p).is_file():
                try:
                    txt = Path(p).read_text(encoding="latin-1", errors="ignore")
                    m = re.search(r"NUMBER_OF_SETS\s+(\d+)", txt)
                    if m:
                        return int(m.group(1))
                except OSError:
                    pass
        return None

    def _generated_page_count(self) -> int:
        """Actual number of pages the currently-previewed chart spans, or 0 when
        nothing is loaded. Mirrors what the user sees in the preview, so a fixed
        layout that printtarg split across extra sheets is counted correctly
        (#73)."""
        try:
            return self._preview.page_count()
        except Exception:  # noqa: BLE001 — name suggestion must never crash
            return 0

    def _suggest_target_name(self) -> str:
        """A descriptive default name from the current settings (#62):
        ``<instrument>-<paper>[-<N>p]-<pages>pages-<orientation>``. The patch
        count comes from the predicted count (guided) or the loaded preset's
        .ti1 (manual); the orientation comes from the paper selection."""
        instr_lbl = {"i1": "i1Pro", "CM": "ColorMunki", "3p": "i1Pro3Plus",
                     "p3": "i1Pro3", "SS": "SpectroScan", "CR30": "CR30"}
        manual = self._manual_btn is not None and self._manual_btn.isChecked()
        if manual:
            engine_on = (self._manual_engine_check is not None
                         and self._manual_engine_check.isChecked())
            panel = self._manual_layout_panel
            if engine_on and panel is not None and panel.paper is not None:
                # The layout ENGINE replaces printtarg — instrument and paper
                # live in its own panel; the printtarg widgets can hold stale
                # values (Knut: A4 Landscape suggested "A4…Portrait", Letter
                # Landscape even suggested "A4…Portrait", #108).
                instr = (panel.instr.currentData()
                         if panel.instr is not None else "") or "i1"
                paper = panel.paper.currentData() or "A4"
            else:
                instr = (self._manual_instr_pw.get_raw_value()
                         if self._manual_instr_pw is not None else "") or "i1"
                paper = (self._manual_paper_pw.get_raw_value()
                         if self._manual_paper_pw is not None else "") or "A4"
            spin = self._manual_pages_spin
            patches = self._loaded_ti1_patch_count()
        else:
            instr = (self._instr_combo.currentData()
                     if self._instr_combo is not None else "") or "i1"
            paper = (self._paper_combo.currentData()
                     if self._paper_combo is not None else "") or "A4"
            spin = self._pages_spin
            patches = getattr(self, "_predicted_patch_count", None)
        pages = int(spin.value()) if spin is not None else 1
        # When the Pages control is locked (a preset / .ti1 drives the layout),
        # its value can't be trusted — printtarg may split the fixed chart across
        # more sheets than it shows (e.g. a "1page" preset that lays out on 2).
        # Use the real page count of the generated chart instead (#73, Knut).
        if spin is not None and not spin.isEnabled():
            actual = self._generated_page_count()
            if actual:
                pages = actual
        base_paper, orient = self._paper_name_and_orientation(str(paper))
        parts = [instr_lbl.get(str(instr), str(instr)), base_paper]
        if patches:
            parts.append(f"{patches}p")
        parts.append("1page" if pages == 1 else f"{pages}pages")
        if orient:
            parts.append(orient)
        return "-".join(parts)

    # ------------------------------------------------------------------
    # Auto descriptive prefix (#68): keep a live, locked
    # "<instrument>-<paper>-<patches>p-<pages>-<orientation>-" head on the
    # target-name field, toggled by the "Add a descriptive prefix" option.
    # ------------------------------------------------------------------
    @staticmethod
    def _auto_suffix_tooltip() -> str:
        return tr(
            "Names this preset after its chart layout, so layout presets sort and read "
            "clearly together. With this on, ChromIQ leads the name with the layout's "
            "key details — instrument, paper size, patch count, pages and orientation — "
            "as a locked prefix, then you add your own detail after. So the name begins "
            "“i1Pro-A4-484p-1page-Portrait-” and you just add what tells this layout "
            "apart from your others.\n\n"
            "Add a detail about the layout itself — for example a variant or revision "
            "(“v2”), how it was built (“denser”, “no-greys”), or a date. There's no need "
            "to repeat printer or paper here: those name the finished profile, not the "
            "chart layout.\n\n"
            "The prefix updates on its own as you change the settings and can't be "
            "edited directly — click the field and your cursor lands right after it, "
            "ready to type. Turn the option off to name the preset entirely yourself.")

    @staticmethod
    def _profile_name_tooltip() -> str:
        """Guidance for the Printer-profile name field (#70, Knut's model).

        Speaks only to the *profile's* identity — the working folder, the files
        and the embedded ICC description (colprof -D) all share this name, so it
        deliberately says nothing about chart-layout naming (that lives in Save
        Preset and the editor's Save As)."""
        return tr(
            "The name of this whole profiling project — think of it as the job's "
            "title. It becomes the project folder on disk, the base name of every "
            "file ChromIQ makes along the way (chart, measurements, the finished "
            "ICC profile) and the profile's own embedded description — so what "
            "you see later in, for example, macOS ColorSync Utility matches the "
            "folder and files exactly.\n\n"
            "(The “printer profile” itself is the .icc / .icm file this project "
            "produces at the end. Naming the project after the printer and paper "
            "keeps that file easy to recognise.)\n\n"
            "Choose a name that identifies this printer and paper at a glance. "
            "A good name describes the printer (name or abbreviation), the paper "
            "(type/id and substrate such as glossy or matte), the colour space, "
            "the measurement instrument and the profile quality — e.g. "
            "Canon_Pro1000_PhotoRagBaryta_RGB_i1Pro3_High. Use underscores or "
            "dashes instead of spaces.\n\n"
            "You can rename it later: change the name here and ChromIQ offers to "
            "rename the folder and files to match — until the profile has been "
            "built, after which you copy it to a new name instead.")

    def _active_name_field(self):
        manual = self._manual_btn is not None and self._manual_btn.isChecked()
        return (self._manual_target_name_edit if manual
                else getattr(self, "_target_name_edit", None))

    # ------------------------------------------------------------------
    # §S4.7 — the typed name already names a project (Knut, 2026-08-27)
    # ------------------------------------------------------------------
    def _typed_project_peek(self):
        """What the name box points at, when that is a DIFFERENT project that
        already exists on disk. None when there is nothing to say.

        Read-only, and deliberately so: this runs while the user is merely
        considering a name, and `Project.load` would migrate the folder in
        place — rearranging somebody's project before they have answered the
        question about it. `peek_project` reads the manifest as plain JSON.
        """
        # A NAME THE APP FILLED IN IS NOT A NAME THE USER TYPED.
        # `_update_name_fields` writes the open project's name into this field,
        # and a restored run's name is seeded into it by `_seed_preset_name`. Reading either back as "the user asked for this project" is the
        # trap the memory note calls *the app answered its own question* — and
        # the gate would then interrupt somebody who had merely picked a preset
        # whose default name happens to exist. `textEdited` fires only for a
        # real keystroke or paste, so this flag is the difference.
        if not getattr(self, "_name_typed_by_user", False):
            return None
        field = self._active_name_field()
        typed = field.text().strip() if field is not None else ""
        if not typed:
            return None
        # RESOLVE IT THE WAY THE BUILD WILL. `preview_project_root` always
        # answers <ChromIQ>/<name>, and `set_target_name` deliberately keeps a
        # NESTED project where it is — so for the name of a nested project the
        # two disagree, and the window described <ChromIQ>/test while the build
        # wrote to <ChromIQ>/Group-A/test. One click on "Replace it" then
        # emptied a project the build never touched.
        root = self._file_mgr.resolved_root_for_name(typed)
        if root is None:
            return None
        # THE PROJECT ALREADY OPEN IS NOT A COLLISION — it is this project.
        # `same_dir`, not `==`: a Path comparison is a string comparison, so
        # "REAL" typed against an open "real" (one folder on macOS), a project
        # opened through a symlink, and NFC-vs-NFD forms of one name all slipped
        # past this and offered to replace the project on screen. `is_named()`
        # first, because `working_dir()` goes through the mutating
        # `get_target_name()`, which invents a name when there is none.
        from core.file_manager import peek_project, same_dir
        try:
            if self._file_mgr.is_named() and same_dir(self._file_mgr.working_dir(),
                                                      root):
                return None
        except OSError:      # an unreachable custom output path
            return None
        peek = peek_project(root)
        return peek if peek.exists else None

    @staticmethod
    def _run_label(number: str) -> str:
        """"Run 1" — TRANSLATED. `peek` hands back only the number, so the
        twelve catalogues are never handed an English label."""
        return tr("Run {n}").format(n=number)

    def _name_points_elsewhere(self, name: str) -> bool:
        """Whether *name* resolves to a project other than the one open.

        Deliberately NOT `_typed_project_peek`, which answers None unless the
        user typed the name themselves. That flag is right for the WINDOW — a
        preset seeding the field must not interrupt anybody — and wrong for the
        live preview, which must not adopt another project whoever put the name
        there. Measured: a preset whose default name matched an existing
        project, plus one nudge of a layout knob, moved the preview into that
        project and reset its run, with no window because §4 forbids one.
        """
        from core.file_manager import same_dir

        root = self._file_mgr.resolved_root_for_name(name)
        if root is None or not (root / "project.json").is_file():
            return False
        try:
            if self._file_mgr.is_named() and same_dir(self._file_mgr.working_dir(),
                                                      root):
                return False
        except OSError:
            return False
        return True

    def _project_exists_message(self, peek, chosen_run_id: str = "") -> "tuple[str, str]":
        """M-PROJECT-EXISTS — §S4.7, rendered from the catalogue.

        *chosen_run_id* is the run the picker is on ("" = a new run); the body
        describes THAT run, and is re-rendered when the picker moves.
        """
        from workflow import measurement_messages as M

        chosen = next((r for r in peek.runs if r.id == chosen_run_id), None)
        label = self._run_label(chosen.number) if chosen is not None else ""
        return M.M_PROJECT_EXISTS.render(
            name=peek.root.name,
            folder=str(peek.root),
            runs=M.runs_phrase(len(peek.runs) or 1, peek.finished_runs),
            # The calibration is a fact about the PROJECT, so it is stated with
            # the project — not listed under "A new run holds:", which is what
            # it used to say, and which was simply untrue.
            cal=M.calibration_phrase(peek.calibration),
            chosen=M.chosen_phrase(label),
            holds=M.holds_phrase(
                label,
                chart=chosen.chart if chosen else False,
                measurement=chosen.measurement if chosen else False,
                profile=chosen.profile if chosen else False,
                verifications=chosen.verifications if chosen else 0))

    def _gate_typed_project_name(self) -> "tuple[bool, bool]":
        """§S4.7. Returns ``(proceed, the §4 question is already answered)``.

        Until 4.1.3 typing the name of a project you already had adopted it in
        SILENCE and built into its current run — Knut, 2026-08-27: *"there is no
        warning message that this project already exists … Nothing shall ever be
        lost and user shall always be notified if there is a risk of overwriting
        a project."*

        Two things were wrong at once and only one of them was this. The other
        is that §4's own question (M-CHART-PROFILING) was asked BEFORE the typed
        name was applied, so when a name adopted a different project §4 was
        answered about the run the app happened to be on. This window is asked
        first, about the project the build will really touch, and it carries
        §4's answer for that run — which is why it returns a second flag saying
        so, and why §S4.7 replaces S4.1–S4.5 rather than preceding them. One
        action, one window.

        An existing project that holds NOTHING raises nothing: there is nothing
        to lose, and a window there is a nag. The line under the name box still
        appears, because it appears whenever the name matches at all.
        """
        self._pending_replace = None
        self._adopted_via_gate = False
        if hasattr(self, "_adopt_run_choice"):
            del self._adopt_run_choice
        peek = self._typed_project_peek()
        if peek is None or not peek.holds_anything:
            return True, False
        from PyQt6.QtWidgets import QMessageBox
        from ui.widgets import (fit_message_box_buttons,
                                spread_message_box_buttons)

        # A NEW RUN IS THE DEFAULT, deliberately. It is the one answer that
        # cannot cost anything: a fresh, empty run beside the work already
        # there. Continuing INTO an existing run is one click away in the
        # picker, and the window then says what that run holds — which is the
        # decision the user is actually being asked to make.
        picker, chosen = self._build_run_picker(peek)
        if picker is None:
            chosen = [peek.run_id]
        title, _ = self._project_exists_message(peek, chosen[0])
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.NoIcon)
        box.setWindowTitle(title)
        box.setText(title)
        box.setInformativeText(self._project_exists_message(peek, chosen[0])[1])
        go = box.addButton(tr("Continue this project"),
                           QMessageBox.ButtonRole.AcceptRole)
        replace = box.addButton(tr("Replace it"),
                                QMessageBox.ButtonRole.DestructiveRole)
        rename = box.addButton(tr("Use a different name"),
                               QMessageBox.ButtonRole.ActionRole)
        cancel = box.addButton(tr("Cancel"), QMessageBox.ButtonRole.RejectRole)
        # THE DEFAULT IS CANCEL. A Return keypress must never be an overwrite.
        box.setDefaultButton(cancel)
        if picker is not None:
            self._attach_run_picker(box, picker)

            def _on_pick(_i: int) -> None:
                chosen[0] = picker.currentData() or ""
                box.setInformativeText(
                    self._project_exists_message(peek, chosen[0])[1])

            picker.currentIndexChanged.connect(_on_pick)
        fit_message_box_buttons(box)
        # FOUR choices, not one and three afterthoughts — and Cancel on the far
        # right, not wedged between the safe answers and the destructive one
        # (Basti, 2026-08-27).
        spread_message_box_buttons(box, order=[go, replace, rename, cancel])
        box.exec()
        clicked = box.clickedButton()
        if clicked is go:
            log.info("continuing the existing project at %s, in %s",
                     peek.root, chosen[0] or "a new run")
            self._adopted_via_gate = True
            self._adopt_run_choice = chosen[0]
            return True, self._s4_is_answered_by_this_window()
        if clicked is replace:
            if not self._confirm_replace_whole_project(peek):
                return False, False
            # ARM IT, DO NOT DO IT. Several steps between this answer and the
            # point of no return still abort — a missing .ti1 used to archive
            # the whole project and then say "Patch set not found", having built
            # nothing. `_perform_pending_replace` runs it where the build
            # commits, and drops it if the name has changed since.
            field = self._active_name_field()
            self._pending_replace = (
                peek.root, field.text().strip() if field is not None else "")
            log.info("replace armed for %s", peek.root)
            return True, self._s4_is_answered_by_this_window()
        if clicked is rename:
            self._focus_project_name_field()
        return False, False

    def _build_run_picker(self, peek):
        """The run chooser for M-PROJECT-EXISTS, and the mutable choice it sets.

        Basti, 2026-08-27, on being shown that ChromIQ recognises the project
        and then still refuses to let him say which run to work in: *"allowing
        me to either work in run 1 (or whatever runs exist for this name) or
        create a new run under this name"*. This is that, put where he is
        asking it — inside the window, with the folder named beside it — rather
        than by unlocking a bar that would have to resolve a project on every
        keystroke.
        """
        from PyQt6.QtWidgets import QComboBox

        # NOT FOR A CALIBRATION. A calibration lives in `cal/`, one per project,
        # shared by every run — `_align_current_run_to_target` is skipped for it
        # entirely, so the picker could not affect where the chart goes. It was
        # not inert either: answering it moved the Profile-run bar to a run
        # nobody had chosen and fired a target-change write in the middle of a
        # build, which is the "build in flight vs the run's stored state" family
        # of fault all over again.
        ctl = getattr(self, "_target_ctl", None)
        if ctl is not None and getattr(ctl.target, "is_calibration", bool)():
            return None, [peek.run_id]

        # These two live HERE as literals, not in the catalogue module: the
        # extractor resolves `tr(NAME)` only for a constant in the same file,
        # so `tr(M.PICK_NEW_RUN)` would have shipped untranslated in all twelve
        # languages while looking perfectly correct in the source.
        picker = QComboBox()
        # THE SAME WHITE BODY AS EVERY OTHER COMBOBOX (Basti, 2026-08-27). A
        # QMessageBox paints on the window background, so a combo inside one
        # inherits beige in light mode and reads as disabled chrome. App-wide
        # QSS is silently ignored by Qt for compound widgets; per-widget is the
        # way, which is what `_input_bg_qss` exists for.
        from ui.widgets import _input_bg_qss
        picker.setStyleSheet(_input_bg_qss())
        picker.addItem(tr("A new run (nothing already there is touched)"), "")
        for r in peek.runs:
            picker.addItem(self._run_label(r.number), r.id)
        # A NEW RUN IS THE DEFAULT — except for a verification, where it is
        # nonsense: a brand-new run has no profile, so the chart would verify
        # nothing. There the project's own current run is the sane starting
        # point, and §S4.5's question still follows this window.
        default = ""
        try:
            if self._is_verification_target():
                default = peek.run_id
        except Exception:      # noqa: BLE001 — a duck-typed target double
            pass
        idx = max(0, picker.findData(default))
        picker.setCurrentIndex(idx)
        return picker, [picker.currentData() or ""]

    @staticmethod
    def _attach_run_picker(box, picker, label: str = "") -> None:
        """Put the picker into the message box, above its buttons.

        A QMessageBox lays itself out in a grid with the button box on the last
        row, so a widget simply added lands UNDER the buttons. Lifting the
        button box out and putting it back after is the only ordering Qt
        guarantees.
        """
        from PyQt6.QtWidgets import (QDialogButtonBox, QHBoxLayout, QLabel,
                                     QWidget)

        lay = box.layout()
        bb = box.findChild(QDialogButtonBox)
        if lay is None or bb is None:
            return
        row = QWidget(box)
        h = QHBoxLayout(row)
        h.setContentsMargins(0, 8, 0, 4)
        # THE CALLER SAYS WHAT THE RUN IS FOR. §S4.7 is choosing where a
        # CHART goes; the measurement import reuses this same picker to
        # choose where a MEASUREMENT goes, and it read "Make the new
        # chart in:" over a list of runs for a file that is not a chart.
        h.addWidget(QLabel(label or tr("Make the new chart in:"), row))
        h.addWidget(picker, 1)
        lay.removeWidget(bb)
        lay.addWidget(row, lay.rowCount(), 0, 1, lay.columnCount())
        lay.addWidget(bb, lay.rowCount(), 0, 1, lay.columnCount())

    def _apply_gate_run_choice(self) -> None:
        """Point the Profile-run bar at the run chosen in the §S4.7 window.

        Called immediately AFTER the project is adopted — before that the bar
        would be naming runs of the project the user is leaving. From here
        `_align_current_run_to_target` does the rest, exactly as it does for an
        ordinary in-project build: "Overwrite run N" points at that folder, and
        the empty choice makes a fresh run and advances the bar to it.
        """
        if not hasattr(self, "_adopt_run_choice"):
            return
        choice = self._adopt_run_choice
        del self._adopt_run_choice
        ctl = getattr(self, "_target_ctl", None)
        if ctl is None:
            return
        try:
            ctl.set_profile_run(choice or "")
            log.info("§S4.7: the bar now says %s", choice or "New run")
        except Exception:      # noqa: BLE001 — never block a build over the bar
            log.warning("could not point the bar at %r", choice, exc_info=True)

    def _s4_is_answered_by_this_window(self) -> bool:
        """Whether M-PROJECT-EXISTS may stand in for §4's own question.

        For a PROFILING build, yes: it names the run and lists what is in it,
        which is what M-CHART-PROFILING would have said, so §S4.7 replaces
        S4.1–S4.4 and one action still opens one window.

        For the other two run types, NO — and this is the correction. A
        calibration build writes `cal/`, a verification build writes
        `verifications/`, and each has its own question with its own message
        (`_confirm_replacing_calibration`, and M-CHART-VERIFY at §S4.5). This
        window describes the run's PROFILING artefacts and knows nothing about
        either, so standing in for them meant a verification chart could replace
        a measured, dated verification with nothing said about it. The specific
        question follows this one for those run types — two windows, which §S4
        must record.
        """
        ctl = getattr(self, "_target_ctl", None)
        if ctl is not None and getattr(ctl.target, "is_calibration", bool)():
            return False
        try:
            if self._is_verification_target():
                return False
        except Exception:      # noqa: BLE001 — a duck-typed target double
            return False
        return True

    def _gate_route_and_replace(self, already_asked: bool = False, *,
                                perform_replace: bool = True) -> "tuple[bool, bool]":
        """Ask §S4.7 for a route that adopts the typed name itself, and carry
        out a Replace straight away.

        For the two routes that do not go through `_generate_from_ti1`'s or
        `_on_generate`'s own sequence there is nothing between the question and
        the adoption, so ask-now/act-later collapses into one step. Returns
        False when the build must not go ahead.

        ASKING TWICE WAS NOT ONLY POSSIBLE, IT WAS THE NORMAL CASE. Both of
        these routes are reached from `_on_generate`, which has already asked —
        and the typed name is still not adopted at that point, so the second
        call put the same window up again. Worse: the second gate resets
        `_pending_replace`, so answering "Replace it" in the first window and
        "Continue this project" in the second dropped a confirmed, destructive
        answer without a word.

        *already_asked* IS AN ARGUMENT, NOT A FLAG ON self. The first attempt at
        this read `_adopted_via_gate` — which only the gate clears, and which the
        guard then skipped, so a stale flag suppressed the window AND the code
        that would have cleared it. Five early returns in `_on_generate` and
        `_create_prebuilt_target` leave it set, and the next preset chosen from
        the dropdown was then adopted in silence, into the run chosen for a
        different project. Measured. A caller knows whether it has asked; state
        that outlives one call cannot.

        Returns ``(proceed, the §4 question is already answered)`` — the second
        half used to be thrown away here, so the prebuilt route asked §4 a
        second time, about the project the user was leaving.
        """
        s4_answered = False
        if not already_asked:
            proceed, s4_answered = self._gate_typed_project_name()
            if not proceed:
                return False, False
        # *perform_replace* False leaves an agreed Replace ARMED. The prebuilt
        # route needs that: it may still have to ask §4 (Calibration and
        # Verification are not answered by §S4.7), and answering "no" there
        # after the archive had already run left the project emptied and
        # nothing built.
        if not perform_replace:
            return True, s4_answered
        return self._perform_pending_replace(), s4_answered

    def _forget_gate_answer(self) -> None:
        """Drop a §S4.7 answer that no build consumed.

        AN ANSWER BELONGS TO ONE ACTION. Four returns between the question and
        the point of no return — a reflected chart, a vanished patch set, the
        name prompt, and the rename chooser being cancelled — left the answer
        armed on `self`, and the next thing to reach a consumer acted on it: one
        live-preview render archived a whole project, and a run choice made for
        one project moved another project's bar. Called from a `finally`, so it
        cannot be forgotten at a new early return.

        Safe after a real build too: everything it clears has been consumed by
        then.
        """
        self._pending_replace = None
        self._adopted_via_gate = False
        if hasattr(self, "_adopt_run_choice"):
            del self._adopt_run_choice

    def _perform_pending_replace(self) -> bool:
        """Carry out a "Replace it" the user agreed to — at the point of no
        return, not at the moment they clicked.

        Returns True when there was nothing to do or the replace succeeded, and
        False when it failed, in which case the build must not go ahead either:
        the user asked for a clean project and would otherwise get a build on
        top of the old one.
        """
        pending = getattr(self, "_pending_replace", None)
        self._pending_replace = None
        if pending is None:
            return True
        root, name_then = pending
        from core.file_manager import same_dir
        # Resolve the name that is in the box NOW, not the one that was there
        # when the question was answered — the whole point is to notice that it
        # has moved on.
        field = self._active_name_field()
        typed = field.text().strip() if field is not None else ""
        now = self._file_mgr.resolved_root_for_name(typed) if typed else None
        if now is None or not same_dir(now, root):
            # The name moved between the answer and here. Replacing what they
            # were asked about would now destroy a project they never saw named.
            log.warning("the armed replace was for %r at %s and the box now "
                        "says %r (%s) — dropped", name_then, root, typed, now)
            return True
        return self._replace_whole_project(root)

    def _confirm_replace_whole_project(self, peek) -> bool:
        """M-PROJECT-REPLACE-CONFIRM — the second look before a whole project is
        cleared (Basti, 2026-08-27).

        The default is "Go back". This is the only control in the app that
        empties a whole project from the Create Chart tab, and it must never be
        one click away from a window somebody opened by accident.
        """
        from PyQt6.QtWidgets import QMessageBox
        from ui.widgets import fit_message_box_buttons
        from workflow import measurement_messages as M

        title, body = M.M_PROJECT_REPLACE_CONFIRM.render(
            name=peek.root.name, folder=str(peek.root))
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.NoIcon)
        box.setWindowTitle(title)
        box.setText(title)
        box.setInformativeText(body)
        yes = box.addButton(tr("Replace it"),
                            QMessageBox.ButtonRole.DestructiveRole)
        back = box.addButton(tr("Go back"), QMessageBox.ButtonRole.RejectRole)
        box.setDefaultButton(back)
        fit_message_box_buttons(box)
        box.exec()
        return box.clickedButton() is yes

    def _replace_whole_project(self, root) -> bool:
        """Move everything the project at *root* holds into its own
        ``old/<date>/``.

        Not a delete: the same operation "Copy the whole project in ▸ Replace"
        already performs (`workflow/chart_import._archive_project_contents`), so
        one word means one thing in both places. The folder itself stays, with
        `old/` inside it, and the build then creates a fresh project there.

        A failure is a WINDOW, not a log line. The old code wrote one sentence
        into the tab's log and returned False, so a user who had just been
        promised "everything is moved into its own old folder, nothing is
        deleted" was told nothing at all when it had not happened.
        """
        from workflow.chart_import import _archive_project_contents
        try:
            dest = _archive_project_contents(root)
        except OSError as exc:
            log.warning("could not archive %s: %s", root, exc)
            self._replace_failed_message(root, exc)
            return False
        log.info("replaced the project at %s — its contents are in %s",
                 root, dest)
        # The FileManager may be holding a Project object for a folder that has
        # just been emptied; the next `project()` must read the new state.
        self._file_mgr.forget_cached_project()
        return True

    def _replace_failed_message(self, root, exc) -> None:
        """M-PROJECT-REPLACE-FAILED — §S4.7, rendered from the catalogue."""
        from workflow import measurement_messages as M

        title, body = M.M_PROJECT_REPLACE_FAILED.render(
            folder=str(root), reason=str(exc))
        InfoDialog(title, body, self, min_width=560).exec()

    def _mark_name_typed_by_user(self, *_a) -> None:
        """Remember that the name in the box came from a person.

        Wired to `textEdited`, which Qt emits for a keystroke or a paste and
        NOT for `setText` — so a preset seeding the field, or the open
        project's name being reflected into it, leaves this False.
        """
        self._name_typed_by_user = True

    def _focus_project_name_field(self) -> None:
        """"Use a different name" — put the cursor back where the answer goes."""
        from PyQt6.QtCore import Qt as _Qt
        f = self._active_name_field()
        if f is not None:
            f.setFocus(_Qt.FocusReason.OtherFocusReason)
            f.selectAll()

    def _project_already_exists(self, typed: str) -> bool:
        """Whether *typed* names a project that is already there — and is not
        the one already open, which is not news.

        Extracted so the name dialog and the line under the name box answer
        from the SAME code. Two copies of this question would drift, and the
        dialog must not read the disk itself: it is handed this as a callback.

        Deliberately the cheapest possible check — one `is_file()` on the
        manifest — because it runs on every keystroke. Never `Project.load`,
        which MIGRATES IN PLACE: rearranging somebody's project while they are
        still typing its name would be the worst possible moment.
        """
        typed = (typed or "").strip()
        if not typed:
            return False
        root = self._file_mgr.resolved_root_for_name(typed)
        if root is None:
            return False
        try:
            if not (root / "project.json").is_file():
                return False
        except OSError:
            return False
        if self._file_mgr.is_named():
            try:
                from core.file_manager import same_dir
                return not same_dir(self._file_mgr.working_dir(), root)
            except OSError:
                pass
        return True

    def _refresh_project_exists_line(self) -> None:
        """Show, under the name box, that this name points at a project that is
        already there — and show it ONLY then.

        Basti's ruling (2026-08-27): the line must not sit there empty, because
        then the user has nothing to notice; its APPEARING is the signal. So
        both labels are hidden unless the typed name matches, and no space is
        reserved for them.

        Deliberately the cheapest possible check — one `is_file()` on the
        manifest — because this runs on every keystroke. The full read
        (`peek_project`) happens once, at build time.
        """
        for field, lbl in ((getattr(self, "_target_name_edit", None),
                            getattr(self, "_project_exists_lbl", None)),
                           (getattr(self, "_manual_target_name_edit", None),
                            getattr(self, "_manual_project_exists_lbl", None))):
            if lbl is None:
                continue
            typed = field.text().strip() if field is not None else ""
            shown = self._project_already_exists(typed)
            if shown:
                # NO NAME IN IT, AND NO DASH. The name is in the field 20 px
                # above, live in the Profile-run bar's location line while you
                # type, and in full in the window that follows — and this label
                # is a fixed 524 px, so a real project name (the app's own
                # `default_target_name` makes an 81-character one) takes two
                # rows in German and Dutch and three in Japanese, pushing the
                # Run Description and Chart Notes rows down. Measured. The dash
                # went because Basti reads one as a tell that a machine wrote
                # the sentence.
                #
                # AND IT STATES THE FACT, NOT WHAT WILL HAPPEN NEXT (Basti,
                # 2026-08-31). It used to end "Your new chart goes into it",
                # which is a prediction — and one that is only true for an
                # EMPTY project. Where the project holds measurements, §S4.7
                # opens four buttons and a run picker and defaults to a NEW
                # run, so the sentence was most confident exactly where the
                # risk was highest. A notice before a fork may say what is
                # there; it may not say what will happen.
                lbl.setText(tr("You already have a project with this name."))
            lbl.setVisible(shown)

    def _name_prefix(self) -> str:
        """The locked descriptive head, e.g. ``i1Pro-A4-484p-1page-Portrait``;
        the user's free text follows it. The separator is supplied by
        PrefixLockedLineEdit and only appears once a tail is typed (#68)."""
        return self._suggest_target_name() or ""

    def _refresh_name_prefix(self) -> None:
        """Keep the Create Chart name fields plain (#70, Knut's model).

        The descriptive prefix now lives only in Save Preset and the editor's
        Save As; the Create Chart name is a plain, manual *printer-profile* name.
        This just clears any stale locked prefix left on the active field."""
        field = self._active_name_field()
        if isinstance(field, PrefixLockedLineEdit):
            field.set_prefix("")

    def _set_manual_name_plain(self, name: str) -> None:
        """Set the manual profile-name field verbatim (no locked prefix)."""
        f = self._manual_target_name_edit
        if f is None:
            return
        if isinstance(f, PrefixLockedLineEdit):
            f.set_prefix("")
        f.setText(name)
        # ChromIQ put this there, not the user — see `_name_typed_by_user`.
        self._name_typed_by_user = False

    def _seed_preset_name(self, target_name: str | None) -> None:
        """Put a name in the Printer-profile field for a BUILT-IN preset — and
        ONLY when the caller supplied one.

        #70 (Knut's model) said a preset must never overwrite a name the user
        chose, and `_ensure_profile_name` honoured that by seeding only into an
        empty field. But the fallback it was handed was the preset's OWN name,
        so an empty field silently became e.g.
        ``i1Pro-A4-162p-1page-Portrait-w7.5mm`` — and that string is not a
        suggestion, it is the project folder, the ICC stem and the name printed
        on the sheet. Knut reported it as a fault (2026-08-30); Basti agreed he
        had wanted it the other way all along, so both asked for the field to
        stay EMPTY, letting the build-time guard ask for a real name the way
        the user-preset path already does.

        A *restored* name is still applied. `target_name` comes from a saved
        run or a reopened project — that name IS the user's, merely not typed
        this minute — and #70's rule about not overwriting a chosen name is
        exactly what keeps it.
        """
        if target_name:
            self._ensure_profile_name(target_name)

    def _ensure_profile_name(self, default: str) -> str:
        """Return the current Printer-profile name, seeding the field with
        ``default`` only when the user hasn't typed one (#70, Knut's model:
        presets / loaded charts never overwrite a name the user already chose).
        """
        f = self._manual_target_name_edit
        cur = (f.text().strip() if f is not None else "")
        if cur:
            return cur
        self._set_manual_name_plain(default)
        return default

    @staticmethod
    def _toggle_name_prefix(edit: "PrefixLockedLineEdit", on: bool, prefix: str) -> None:
        """Flip a name field between the locked-prefix and free modes (#68,
        Knut's model). ON: the descriptive head is locked + greyed with a
        trailing '-' and an empty editable tail (ready to type). OFF: the
        descriptive name is shown as a plain, fully editable field (no dash, no
        lock) — keep it, edit it, or replace it."""
        if on:
            edit.set_prefix("")        # drop any prior lock
            edit.setText("")
            edit.set_prefix(prefix)    # → "prefix-" with an empty tail
        else:
            edit.set_prefix("")        # remove the lock
            edit.setText(prefix)       # the generated name, fully editable

    def _on_preset_save(self) -> None:
        capture: dict = {}
        # Store the EFFECTIVE widget values, including the triple-density layout
        # (-a / -m / -P / -L) when TD is on — so the preset round-trips with the
        # right scale/margin (#89). On restore the TD checkbox is re-enabled in
        # suppressed mode so it won't clobber these back to the TD defaults.
        for tool, widgets in self._manual_widgets.items():
            for pw in widgets:
                if pw in self._d_cascade_widgets:
                    continue
                v = pw.get_raw_value()
                if v is not None:
                    capture[f"{tool}_{pw.flag}"] = v
                # Persist the enable-checkbox state for expert non-boolean rows
                # so the flag is re-armed when the preset is recalled.
                if pw.has_separate_enable:
                    capture[f"{tool}_{pw.flag}_enabled"] = pw.is_enabled_by_user
        for idx, pw in enumerate(self._d_cascade_widgets):
            capture[f"targen_-D_{idx}"] = pw.get_raw_value()
            capture[f"targen_-D_{idx}_enabled"] = pw.is_enabled_by_user
        capture["tiff_16bit"] = (
            self._bit16_radio.isChecked() if self._bit16_radio is not None else False
        )
        capture["auto_patches"] = (
            self._manual_auto_patches_check.isChecked()
            if self._manual_auto_patches_check is not None else False
        )
        capture["auto_grey"] = (
            self._manual_auto_grey_check.isChecked()
            if self._manual_auto_grey_check is not None else False
        )
        capture["auto_white"] = (
            self._manual_auto_white_check.isChecked()
            if self._manual_auto_white_check is not None else False
        )
        capture["auto_black"] = (
            self._manual_auto_black_check.isChecked()
            if self._manual_auto_black_check is not None else False
        )
        capture["pages"] = (
            int(self._manual_pages_spin.value())
            if self._manual_pages_spin is not None else 1
        )
        capture["left_clip_info"] = bool(self._manual_left_clip_check.isChecked())
        capture["triple_density"] = bool(
            self._manual_td_check is not None and self._manual_td_check.isChecked()
        )
        # ChromIQ layout engine: store the full layout recipe (minus the per-chart
        # seed) so a named preset carries the engine options too, exactly like it
        # carries the printtarg ones (#93). Only when the engine is active.
        if (getattr(self, "_manual_layout_panel", None) is not None
                and bool(self._settings.get("use_chromiq_layout_engine", False))):
            from dataclasses import replace
            # PINNED: a saved preset carries its own label style, so a later
            # Preferences change can't resize the labels on it (Knut, beta-6).
            capture["layout_recipe"] = replace(
                self._pinned_layout_recipe(), seed=None).to_dict()
        # Chart notes + stamp choice round-trip with the preset (mavtop,
        # forum). Presets saved before these keys existed simply lack them,
        # and loading such a preset leaves both fields untouched.
        capture["chart_notes"] = (
            self._manual_chart_notes_edit.text().strip()
            if self._manual_chart_notes_edit is not None else "")
        capture["stamp_commands"] = bool(
            self._manual_stamp_cmd_check is not None
            and self._manual_stamp_cmd_check.isChecked())
        (_prefill_name, prefill_run, prefill_attach,
         prefilled_from_target) = self._preset_save_prefill()
        # A patch set can only be attached if one is currently loaded.
        have_ti1 = (self._current_ti1_path is not None
                    and self._current_ti1_path.is_file())

        dlg = QDialog(self)
        dlg.setWindowTitle(tr("Save Preset"))
        dlg.setMinimumWidth(500)
        lay = QVBoxLayout(dlg)
        lay.setContentsMargins(22, 20, 22, 16)
        lay.setSpacing(10)

        heading = QLabel(tr("Save preset"), dlg)
        heading.setStyleSheet("font-weight: bold;")
        lay.addWidget(heading)
        info = QLabel(
            tr("Give this preset a name. All current Manual-mode parameter values are "
            "saved under it and can be recalled any time from the preset list. "
            "Re-saving with an existing name overwrites it."),
            dlg,
        )
        info.setWordWrap(True)
        lay.addWidget(info)

        lay.addSpacing(6)
        # An explicit label above the field — the placeholder is hidden once the
        # field is pre-filled, so a visible "Preset name:" keeps it clear (#50).
        name_lbl = QLabel(tr("Preset name:"), dlg)
        lay.addWidget(name_lbl)
        edit = PrefixLockedLineEdit(dlg)
        edit.setMinimumHeight(28)
        edit.setPlaceholderText(tr("Preset name"))
        lay.addWidget(edit)
        # "Add a descriptive prefix": a preset names a CHART LAYOUT, so the
        # default comes from the layout generator (instrument · paper · patch ·
        # pages · orientation), never the printer-profile name. ON locks that as
        # a greyed prefix with a trailing '-' for a distinguishing detail; OFF
        # shows it as a plain editable name. (#70, Knut)
        preset_suffix_cb = QCheckBox(tr("Add a descriptive prefix"), dlg)
        preset_suffix_cb.setChecked(bool(self._settings.get("create_chart_auto_suffix", True)))
        preset_suffix_cb.toggled.connect(
            lambda on: self._toggle_name_prefix(edit, on, self._name_prefix()))
        suffix_row = QHBoxLayout()
        suffix_row.setContentsMargins(0, 0, 0, 0)
        suffix_row.addWidget(preset_suffix_cb)
        suffix_row.addStretch()
        suffix_row.addWidget(TooltipButton(tr("Add a descriptive prefix"),
                                           self._auto_suffix_tooltip(), dlg, min_width=520))
        lay.addLayout(suffix_row)
        # Seed the field from the chart-layout generator (not the profile name):
        # ON → "<generated>-", OFF → "<generated>" editable.
        self._toggle_name_prefix(edit, preset_suffix_cb.isChecked(), self._name_prefix())
        if prefilled_from_target:
            name_hint = QLabel(
                tr("Suggested from this chart's layout — add a detail to tell it "
                "apart from your other layout presets."),
                dlg)
            name_hint.setWordWrap(True)
            name_hint.setObjectName("info")
            lay.addWidget(name_hint)

        run_chk = QCheckBox(
            tr("Generate the chart immediately when this preset is selected"), dlg)
        run_chk.setChecked(prefill_run)
        lay.addWidget(run_chk)
        run_note = QLabel(
            tr("When on, picking this preset asks for a printer profile project name and then creates "
            "the chart straight away (it's shown with a ▶ in the list), instead of "
            "only loading the values. This is saved inside the preset file, so it "
            "travels with a shared preset."),
            dlg,
        )
        run_note.setWordWrap(True)
        run_note.setObjectName("info")
        lay.addWidget(run_note)

        lay.addSpacing(6)
        attach_chk = QCheckBox(
            tr("Build from the currently loaded patch set (attach its .ti1)"), dlg)
        attach_chk.setChecked(prefill_attach and have_ti1)
        attach_chk.setEnabled(have_ti1)
        lay.addWidget(attach_chk)
        if have_ti1:
            attach_text = (
                "When on, the patch set currently loaded (its .ti1) is saved next to "
                "this preset. Selecting the preset then builds the chart straight from "
                "that .ti1 — targen is skipped and printtarg just lays it out, exactly "
                "like the built-in presets. The .ti1 is stored inside the preset folder "
                "under the preset's name, so it travels with a shared preset."
            )
        else:
            attach_text = (
                "Generate or load a chart first to enable this — there's no patch set "
                "(.ti1) loaded right now to attach. When a set is loaded, you can save "
                "it with the preset so selecting it skips targen and builds from that "
                "exact .ti1."
            )
        attach_note = QLabel(attach_text, dlg)
        attach_note.setWordWrap(True)
        attach_note.setObjectName("info")
        lay.addWidget(attach_note)

        lay.addSpacing(4)
        bb = QDialogButtonBox(dlg)
        bb.addButton(tr("Cancel"), QDialogButtonBox.ButtonRole.RejectRole)
        bb.addButton(tr("Save"), QDialogButtonBox.ButtonRole.AcceptRole)
        bb.rejected.connect(dlg.reject)
        bb.accepted.connect(dlg.accept)
        lay.addWidget(bb)
        edit.returnPressed.connect(dlg.accept)
        edit.setFocus()
        dlg.adjustSize()

        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        # Normalise away invisible characters before saving / comparing: a name
        # pasted from elsewhere can carry a zero-width space (U+200B), a
        # non-breaking space, or other format/control characters that .strip()
        # leaves in place — so "MyChart" and "MyChart​" looked identical but
        # didn't match, the overwrite prompt never fired, and a duplicate was
        # created (#59). NFC-normalise and drop control/format chars on both
        # the typed name and the stored keys before comparing.
        name = _clean_preset_name(edit.text())
        if not name:
            return
        # Don't silently overwrite (or duplicate) an existing preset — ask first
        # (#59). Match on a separator-insensitive, case-insensitive key so
        # case-variants AND punctuation-variants (e.g. a dot vs the underscore
        # the name cleaning produces, "w11.5mm" vs "w11_5mm") are caught; reuse
        # the existing key so the match replaces it cleanly.
        existing = self._load_presets_from_settings()
        nkey = _preset_match_key(name)
        match = next((k for k in existing if _preset_match_key(k) == nkey), None)
        if match is not None:
            if not self._confirm_overwrite_preset(match):
                return
            name = match
        capture["auto_run"] = bool(run_chk.isChecked())
        attach = bool(attach_chk.isChecked() and have_ti1)
        capture["attached_ti1"] = attach
        # Manage the .ti1 sidecar next to the preset .json. Copy the loaded set in
        # when attaching; remove any stale one when the option is turned off.
        sidecar = _preset_sidecar_path("create_chart", name, ".ti1")
        try:
            if attach:
                import shutil
                sidecar.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy(self._current_ti1_path, sidecar)
            elif sidecar.is_file():
                sidecar.unlink()
        except OSError as exc:
            log.warning("preset .ti1 sidecar update failed for '%s': %s", name, exc)
            if attach:
                capture["attached_ti1"] = False
        # Carry the chart's creation recipe (Set B) into the preset when the
        # current chart has one (e.g. applied from the editor), so it can later
        # be reloaded into the New chart window via "Load setup from preset"
        # (#55). Presets without it simply won't appear in that dropdown.
        recipe = self._current_chart_recipe()
        if recipe:
            capture["editor_recipe"] = self._recipe_synced_to_manual(recipe)
        presets = self._load_presets_from_settings()
        presets[name] = capture
        self._save_presets_to_settings(presets)
        self._populate_preset_combo(presets, select_name=name)

    def _recipe_synced_to_manual(self, recipe: dict) -> dict:
        """A copy of the chart's creation recipe (Set B) with its ``layout``
        block refreshed from the current Manual-tab printtarg settings (Set A),
        so a saved preset's two records can never disagree on scale / margin /
        density / etc. (#92).

        Only the layout (and the instrument / paper identity) sync — the
        generators, colour-set params, source mode and patch count stay frozen as
        "what was used at creation". Falls back to the recipe unchanged if the
        manual params can't be read."""
        # Engine charts: the printtarg widgets didn't produce the chart (the
        # engine recipe did, and the preset carries it as layout_recipe), so
        # syncing from them would stamp unrelated instrument/paper/layout values
        # into the recipe (#100). Keep it exactly as created.
        if bool(self._settings.get("use_chromiq_layout_engine", False)):
            return recipe
        try:
            from workflow.ti2_relayout import recipe_layout_from_options
            opts = _layout_options_from_params(self._collect_params())
        except Exception:  # noqa: BLE001 — sync is best-effort, never block save
            return recipe
        synced = dict(recipe)
        synced["layout"] = recipe_layout_from_options(opts)
        return synced

    def _current_chart_recipe(self) -> dict | None:
        """The current run's stored New-chart creation recipe (Set B), or None.

        Read from the run's ``meta.json`` (``editor_recipe``) — present for charts
        applied from the layout editor; absent for plain targen charts."""
        try:
            if not self._file_mgr.has_project():
                return None
            meta = self._file_mgr.project().current_run().load_meta()
        except Exception:  # noqa: BLE001 — recipe capture is best-effort
            return None
        return meta.editor_recipe if isinstance(meta.editor_recipe, dict) else None

    def _confirm_overwrite_preset(self, name: str) -> bool:
        """Ask whether to overwrite an existing same-named preset (#59).

        Returns True to overwrite, False to cancel (the user can retry with a
        different name)."""
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.Question)
        box.setWindowTitle(tr("Preset already exists"))
        box.setText(tr("A preset named “{name}” already exists. Overwrite it, "
                       "or cancel and choose a different name.").format(name=name))
        overwrite = box.addButton(tr("Overwrite"),
                                  QMessageBox.ButtonRole.AcceptRole)
        box.addButton(tr("Cancel"), QMessageBox.ButtonRole.RejectRole)
        box.exec()
        return box.clickedButton() is overwrite

    def _on_preset_delete(self) -> None:
        if not self._is_deletable_preset(self._preset_combo.currentIndex()):
            return  # Default and the built-in presets are protected
        # Use userData (bare name), not the shown text which may carry a ▶ prefix.
        name = self._preset_combo.currentData()
        dlg = QDialog(self)
        dlg.setWindowTitle(tr("Delete Preset"))
        dlg.setMinimumWidth(460)
        dlg_layout = QVBoxLayout(dlg)
        dlg_layout.setSpacing(10)
        dlg_layout.setContentsMargins(20, 20, 20, 16)
        heading = QLabel(tr("Delete the preset \"{name}\"?").format(name=name), dlg)
        heading.setStyleSheet("font-weight: bold;")
        heading.setWordWrap(True)
        dlg_layout.addWidget(heading)
        info = QLabel(
            tr("All parameter values saved in this preset will be permanently removed. "
            "This cannot be undone."),
            dlg,
        )
        info.setWordWrap(True)
        dlg_layout.addWidget(info)
        bb = QDialogButtonBox(dlg)
        bb.addButton(tr("Cancel"), QDialogButtonBox.ButtonRole.RejectRole)
        bb.addButton(tr("Delete"), QDialogButtonBox.ButtonRole.AcceptRole)
        bb.rejected.connect(dlg.reject)
        bb.accepted.connect(dlg.accept)
        dlg_layout.addWidget(bb)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        presets = self._load_presets_from_settings()
        presets.pop(name, None)
        self._save_presets_to_settings(presets)
        # Remove the attached .ti1 sidecar, if any, so it doesn't orphan.
        sidecar = _preset_sidecar_path("create_chart", str(name), ".ti1")
        if sidecar.is_file():
            try:
                sidecar.unlink()
            except OSError as exc:
                log.warning("could not remove preset .ti1 sidecar %s: %s", sidecar, exc)
        self._populate_preset_combo(presets)

    # ------------------------------------------------------------------
    # TC9.18 built-in preset
    # ------------------------------------------------------------------

    @staticmethod
    def _tc918_ti1_path() -> Path:
        """Absolute path to the bundled TC9.18 patch set (dev + frozen)."""
        return resource_path(TC918_TI1_ASSET)

    def _reset_tc918_overrides(self) -> None:
        """Revert the printtarg flags the TC9.18 preset forces to YAML defaults.

        Run when the user switches away from the built-in chart so its expert
        overrides (notably -m margins and -b black-and-white spacers) don't
        carry into Default or another preset.

        The recipe pins -a to 1.0; resetting it to the YAML default (also 1.0)
        would leave it at 1.0 even on i1, where the instrument default is 0.95.
        So after reverting, re-apply the per-instrument margin/scale defaults —
        the last word, since the -i reset earlier in the loop would otherwise be
        undone by -a's own reset."""
        for flag in TC918_PRINTTARG:
            for pw in self._manual_widgets.get("printtarg", []):
                if pw.flag == flag:
                    pw.reset_to_default()
        self._apply_instrument_default_margin()

    def _set_manual_value(self, tool: str, flag: str, value: Any) -> None:
        """Set the value of a single manual ParameterWidget, if present."""
        for pw in self._manual_widgets.get(tool, []):
            if pw.flag == flag:
                pw.set_value(value)
                # Expert non-boolean rows (e.g. -m, -A) only emit their flag
                # when their enable-checkbox is ticked; turn it on for any
                # value we deliberately set so it reaches the command.
                if value not in (None, False):
                    pw.set_user_enabled(True)
                return

    def _reset_manual_value(self, tool: str, flag: str) -> None:
        """Revert a single manual widget to its YAML default and disable it.

        For expert non-boolean rows (-A, -R, …) this also unticks the enable
        checkbox, so a flag a previously-selected preset turned on can't leak
        into the next one."""
        for pw in self._manual_widgets.get(tool, []):
            if pw.flag == flag:
                pw.reset_to_default()
                return

    def _seed_manual_printtarg_from_layout(self, opts) -> None:
        """Reflect an editor ``LayoutOptions`` bundle onto the manual printtarg
        panel so a chart handed over from the layout editor shows the exact
        knobs it was laid out with — patch scale (-a), spacer scale (-A),
        margin (-m), spacers (-b/-n), double/triple density, DPI and bit depth,
        -L/-P — not just instrument + paper.

        The panel is locked right after this, so the seeding is display-faithful
        (the override boxes let the user unlock and edit). Scalar expert rows
        mirror :meth:`LayoutOptions.to_printtarg_args`' default-suppression: a
        row at its default value is reset (disabled) rather than spuriously
        enabled, so the panel reads exactly like the flags printtarg received.
        """
        # Spacers: at most one of -b / -n; "colored" leaves both off.
        self._set_manual_value("printtarg", "-b", opts.spacer_mode == "bw")
        self._set_manual_value("printtarg", "-n", opts.spacer_mode == "none")
        # DPI + bit depth.
        self._set_manual_value("printtarg", "-t", opts.dpi)
        if self._bit16_radio is not None and self._bit8_radio is not None:
            (self._bit16_radio if opts.tiff_16bit
             else self._bit8_radio).setChecked(True)
        # Triple density FIRST: its toggle handler re-applies the canonical
        # i1Pro-layout preset (-a1.3 / -m5 / -P / -L), so it must run *before* the
        # margin / patch-scale / spacer / -L / -P rows below — otherwise it would
        # clobber the editor's real values with the TD defaults. Knut's #45: a
        # triple-density chart laid out at margin 6 / patch-scale 1.06 came back
        # as margin 5 / 1.30 because TD ran last and overwrote them.
        if self._manual_td_check is not None:
            self._manual_td_check.setChecked(bool(opts.triple_density))
        # Strip-reader / density booleans (override any TD preset above).
        self._set_manual_value("printtarg", "-L", opts.suppress_left_clip)
        self._set_manual_value("printtarg", "-P", opts.no_strip_limit)
        self._set_manual_value("printtarg", "-h", opts.double_density)
        # The layout editor always lays its charts out in fixed order
        # (printtarg -r — see workflow/ti2_relayout.py), so the applied chart is
        # "preserve patch order". Reflect that on the panel and in the baseline:
        # otherwise -r sits at its factory default and unchecking Preserve Patch
        # Order to get randomisation reads as "no change", so Generate copies the
        # fixed-order files verbatim and the chart is never randomised (the
        # randomisation only appeared as a side effect of toggling another knob).
        self._set_manual_value("printtarg", "-r", True)
        # Scalar expert rows: set+enable only when non-default, else reset. These
        # run last so the chart's actual patch/spacer scale and margin win over
        # the triple-density preset applied above.
        if abs(opts.patch_scale - 1.0) > 0.01:
            self._set_manual_value("printtarg", "-a", opts.patch_scale)
        else:
            self._reset_manual_value("printtarg", "-a")
        if abs(opts.spacer_scale - 1.0) > 0.01:
            self._set_manual_value("printtarg", "-A", opts.spacer_scale)
        else:
            self._reset_manual_value("printtarg", "-A")
        # Margin is always a deliberate layout choice in the editor, so show it
        # enabled even at the default 6 mm. Suppressing it left the Create Chart
        # margin row unticked after Save & apply, reading as "no margin set" (#61).
        self._set_manual_value("printtarg", "-m", opts.margin_mm)

    def _targen_signature(self) -> list:
        """Snapshot of every targen-affecting control.

        printtarg controls are excluded on purpose: changing the *layout*
        (patch size, margins, spacers…) should still re-lay-out the same
        bundled patches, while changing anything that would alter the patch
        *set* means the user wants a fresh targen-generated chart.
        """
        sig: list = []
        for pw in self._manual_widgets.get("targen", []):
            sig.append((pw.flag, pw.get_raw_value(), pw.is_enabled_by_user))
        for label, chk in (
            ("auto_patches", self._manual_auto_patches_check),
            ("auto_grey",    self._manual_auto_grey_check),
            ("auto_white",   self._manual_auto_white_check),
            ("auto_black",   self._manual_auto_black_check),
        ):
            if chk is not None:
                sig.append((label, chk.isChecked()))
        if self._manual_pages_spin is not None:
            sig.append(("pages", int(self._manual_pages_spin.value())))
        return sig

    def _printtarg_signature(self) -> list:
        """Snapshot of every printtarg (layout) control.

        Used by the prebuilt-files presets to tell a pure layout change (re-run
        printtarg on the bundled .ti1, keeping the patches) from no change at all
        (copy the bundled files verbatim)."""
        sig: list = []
        for pw in self._manual_widgets.get("printtarg", []):
            sig.append((pw.flag, pw.get_raw_value(), pw.is_enabled_by_user))
        if self._bit16_radio is not None:
            sig.append(("bit16", self._bit16_radio.isChecked()))
        if self._manual_td_check is not None:
            sig.append(("triple", self._manual_td_check.isChecked()))
        # THE ENGINE'S RECIPE IS PART OF THE LAYOUT TOO.
        #
        # When the ChromIQ layout engine is driving, printtarg's own controls
        # are not what decides the sheet — the recipe is. Leaving it out of the
        # signature meant a preset saw "nothing changed" however much of the
        # layout the user had altered, and Generate Chart copied the bundled
        # files back verbatim. Knut, beta.150, after loading "by pharmacist"
        # and changing Calculation method: *"it was not possible to press
        # Generate Chart. It was locked … I should be able to override the
        # loaded preset chart."*
        panel = getattr(self, "_manual_layout_panel", None)
        check = getattr(self, "_manual_engine_check", None)
        if panel is not None and check is not None and check.isChecked():
            try:
                sig.append(("engine", repr(panel.get_recipe().to_dict())))
            except Exception:      # noqa: BLE001 — a signature is never fatal
                pass
        return sig

    # ------------------------------------------------------------------
    # Preset panel locks (greying targen / printtarg while a preset is active)
    # ------------------------------------------------------------------

    def _ti1_preset_active(self) -> bool:
        """True while a preset that supplies a fixed patch set (.ti1) is active.

        Covers the TC9.18 built-in, Knut's TC9.18+Spyderprint presets, and any
        user preset that bundled a .ti1 — for all of these targen is skipped, so
        its panel is greyed unless the user opts in."""
        return bool(
            self._tc918_active
            or self._knut_active
            or self._preset_ti1_path is not None
        )

    def _update_preset_locks(self) -> None:
        """Show/hide the override rows and grey the panels they guard.

        • A ti1 preset greys only targen (printtarg stays editable).
        • A prebuilt-files preset greys both targen and printtarg.
        • No preset → both override rows hidden, both panels editable.
        Each panel is enabled when no lock applies, or when its override box is
        ticked."""
        ti1 = self._ti1_preset_active()
        # An applied editor chart — or a chart reflected from the Print/Measure
        # tab — locks both panels exactly like a prebuilt-files preset (the
        # patches AND the layout are fixed until the user opts in).
        prebuilt = self._prebuilt_active or self._applied_active or self._reflected_active
        show_targen_cb = ti1 or prebuilt
        show_printtarg_cb = prebuilt

        if self._override_targen_row is not None:
            self._override_targen_row.setVisible(show_targen_cb)
        if self._override_printtarg_row is not None:
            self._override_printtarg_row.setVisible(show_printtarg_cb)

        targen_unlocked = (
            not show_targen_cb
            or (self._override_targen_check is not None
                and self._override_targen_check.isChecked())
        )
        printtarg_unlocked = (
            not show_printtarg_cb
            or (self._override_printtarg_check is not None
                and self._override_printtarg_check.isChecked())
        )
        for w in self._manual_targen_content:
            w.setEnabled(targen_unlocked)
        for w in self._manual_printtarg_content:
            w.setEnabled(printtarg_unlocked)
        # When a preset locks the recipe, collapse the targen frame while it's
        # locked and expand it the moment the user ticks "Edit patch recipe", so
        # the now-editable controls come into view (Knut). Outside a lock the
        # frame keeps its own collapsed-by-default / user-clicked state.
        tgrp = getattr(self, "_manual_targen_grp", None)
        if tgrp is not None and show_targen_cb:
            tgrp.set_collapsed(not targen_unlocked)

    def _reset_override_checks(self) -> None:
        """Untick both override boxes without firing their pop-up.

        Called on every preset selection so a freshly chosen preset always starts
        locked. blockSignals keeps the toggle from thrashing _update_preset_locks
        mid-selection (the caller re-applies the lock state afterwards)."""
        for cb in (self._override_targen_check, self._override_printtarg_check):
            if cb is not None and cb.isChecked():
                cb.blockSignals(True)
                cb.setChecked(False)
                cb.blockSignals(False)
        # A newly selected preset starts fully branded again.
        self._vendor_debranded = False

    def _on_override_clicked(self, tool: str, checked: bool) -> None:
        """User ticked/unticked an override box — warn (once) when unlocking.

        Fires only on real clicks (not programmatic setChecked), so the warning
        pop-up appears exactly when the user themselves unlocks a panel."""
        if not checked:
            return
        if tool == "targen":
            InfoDialog(tr(_OVERRIDE_TARGEN_POPUP_TITLE), tr(_OVERRIDE_TARGEN_POPUP_BODY),
                       self, min_width=560).exec()
            # Editing the patch recipe drops the vendor identity: once the locked
            # patch set can be changed, the chart is no longer that vendor's
            # certified set, so its branding must not stay on it. Revert a
            # branded clip band (a bundled vendor logo) to ChromIQ's own notes
            # record — no vendor logo / text remains on the chart.
            self._debrand_on_override()
        else:
            InfoDialog(tr(_OVERRIDE_PRINTTARG_POPUP_TITLE), tr(_OVERRIDE_PRINTTARG_POPUP_BODY),
                       self, min_width=560).exec()

    def _debrand_on_override(self) -> None:
        """Strip a vendor preset's branding from the layout when the user unlocks
        the patch recipe: a bundled-logo clip band (clip_content_mode "image")
        reverts to ChromIQ's regular chart-notes clip border, so nothing on the
        chart still names the vendor."""
        key = getattr(self, "_knut_active_key", None)
        p = KNUT_PRESETS_BY_KEY.get(key or "")
        branded = bool(
            p is not None and p.layout_recipe
            and p.layout_recipe.get("clip_content_mode") == "image")
        if not branded:
            return
        # Drop the vendor identity from the layout-name stamp too (the "Chart
        # layout <name>" text on the sheet edge), not just the clip logo.
        self._vendor_debranded = True
        panel = getattr(self, "_manual_layout_panel", None)
        if panel is None:
            return
        rec = self._current_layout_recipe()
        if rec is None:
            return
        from dataclasses import replace
        panel.set_recipe(replace(
            rec,
            clip_content_mode="notes",   # ChromIQ's own record, not a vendor logo
            clip_image_path="",
            clip_image_rotation=0,
            clip_border_width_mm=26.0,    # the regular clip-border width
        ))

    def _apply_tc918_preset(self, target_name: str | None = None) -> bool:
        """Seed the fixed TC9.18 layout and create the target from the bundled .ti1.

        Returns whether the preset was actually applied. False means the person
        (or a missing file) refused it, and the caller puts the tab back (#175).
        """
        if self._runner.is_running:
            log.warning("TC9.18 preset: a process is already running")
            return False
        ti1 = self._tc918_ti1_path()
        if not ti1.is_file():
            InfoDialog(
                "TC9.18 chart not found",
                "The built-in TC9.18 patch set could not be located:\n\n"
                f"{ti1}\n\nThe app bundle may be incomplete.",
                self, min_width=520,
            ).exec()
            return False

        # Triple density / Auto patch count must be off before seeding values,
        # otherwise they hijack the -a / -m / -e / -B widgets we set below.
        if self._manual_td_check is not None:
            self._manual_td_check.setChecked(False)
        if self._manual_auto_patches_check is not None:
            self._manual_auto_patches_check.setChecked(False)
            self._on_auto_patches_toggled(False)
        self._load_auto_neutral_states(grey=False, white=False, black=False)

        # Fixed printtarg layout (the Pharmacist recipe).
        for flag, value in TC918_PRINTTARG.items():
            self._set_manual_value("printtarg", flag, value)

        # Best-effort targen description of the bundled chart (white/black
        # patches and total set size read straight from the .ti1 header). The
        # chart is built from the .ti1 itself, so these are descriptive only —
        # but they make the panel reflect what was loaded, and changing any of
        # them is what tells "Generate Chart" to switch to a fresh targen run.
        self._set_manual_value("targen", "-f", 918)
        self._set_manual_value("targen", "-e", 4)
        self._set_manual_value("targen", "-B", 4)

        # 8-bit output (the recipe doesn't ask for 16-bit).
        if self._bit8_radio is not None:
            self._bit8_radio.setChecked(True)

        # Built under the current Printer-profile name; the preset never
        # overwrites it (#70) and no longer NAMES the project after itself.
        self._seed_preset_name(target_name)

        self._tc918_active = True
        self._tc918_targen_sig = self._targen_signature()
        self._update_preset_locks()      # grey targen (printtarg stays editable)
        self._refresh_manual_command_preview()
        return self._generate_from_ti1(ti1)

    def _apply_colormunki_td_preset(
        self, patches: int, white: int, black: int, grey: int,
        target_name: str | None = None,
    ) -> bool:
        """Load a ColorMunki + Triple-density recipe and generate it immediately.

        Produces (example for 324 / 2 / 2 / 16):
            targen   -d2 -f324 -e2 -B2 -G -g16
            printtarg -ii1 -pA4R -T300 -L -a1.30 -m5 -M5 -b -P
        Triple density makes printtarg use the denser i1Pro geometry (-ii1) while
        chart_creator rewrites the .ti2 TARGET_INSTRUMENT back to ColorMunki.
        Like TC9.18, selecting the preset creates the target right away; all
        settings stay editable for a regenerate afterwards.

        THIS FAMILY CANNOT REPORT A REFUSAL, AND CANNOT BE REACHED EITHER.
        It builds through `_on_generate`, which has no return channel, so the
        best it can say is "the dispatch ran". That is harmless only because no
        `MUNKI_TARGEN` key is in `BUILTIN_PRESET_KEYS`, so the dropdown branch
        that calls this is unreachable —
        `tests/test_backing_out_of_a_preset_changes_nothing.py` fails the moment
        that stops being true, because then #175's undo would need a real answer
        here.
        """
        if self._runner.is_running:
            log.warning("ColorMunki preset: a process is already running")
            return False
        # Clear modes that would otherwise hijack the seeded -f / -e / -B / -g.
        if self._manual_auto_patches_check is not None:
            self._manual_auto_patches_check.setChecked(False)
            self._on_auto_patches_toggled(False)
        self._load_auto_neutral_states(grey=False, white=False, black=False)

        # Instrument must be ColorMunki *before* Triple density is enabled — TD
        # is gated to CM and the TD row is hidden (and force-unchecked) otherwise.
        self._set_manual_value("printtarg", "-i", "CM")
        self._set_manual_value("printtarg", "-p", "A4R")
        if self._bit16_radio is not None:
            self._bit16_radio.setChecked(True)          # 16-bit TIFF (→ -T300)
        self._set_manual_value("printtarg", "-b", True)  # B&W spacers

        # targen recipe.
        self._set_manual_value("targen", "-d", "2")
        self._set_manual_value("targen", "-f", patches)
        self._set_manual_value("targen", "-e", white)
        self._set_manual_value("targen", "-B", black)
        self._set_manual_value("targen", "-G", True)
        self._set_manual_value("targen", "-g", grey)

        if self._manual_pages_spin is not None:
            self._manual_pages_spin.setValue(1)

        # Enable Triple density LAST: its toggle handler seeds -a1.3 / -m5 / -P /
        # -L and arms the .ti2 ColorMunki rewrite. Seeding it after the values
        # above means those four are deliberately TD-driven (matching the recipe).
        if self._manual_td_check is not None:
            self._manual_td_check.setChecked(True)

        # Built under the current Printer-profile name; the preset never
        # overwrites it (#70) and no longer NAMES the project after itself.
        self._seed_preset_name(target_name)

        self._refresh_manual_command_preview()
        # Auto-generate immediately, like the TC9.18 preset.
        self._on_generate()

        self._refresh_manual_command_preview()
        return True

    # ------------------------------------------------------------------
    # TC9.18 + Spyderprint-greys presets (shared .ti1 → printtarg)
    # ------------------------------------------------------------------

    @staticmethod
    def _knut_ti1_path() -> Path:
        """Absolute path to the bundled 1168-patch TC9.18+Spyderprint .ti1."""
        return resource_path(KNUT_TI1_ASSET)

    def _fls_engine_recipe(self, p: "_Ti1Preset"):
        """The layout-engine recipe for a Full-layout-setup ENGINE preset,
        derived from the preset's own printtarg fields.

        Built from the exact same mapping the engine build uses
        (`ChartCreator._engine_build_kwargs`), so the engine reproduces
        printtarg byte-for-byte (verified for all 11 engine presets). We add the
        explicit per-edge ``margins`` (the mapping only emits ``border``) so the
        recipe round-trip keeps the preset's margin instead of defaulting to
        6 mm."""
        from workflow.chart_creator import ChartParams
        from workflow.layout_engine.presets import LayoutRecipe
        params = ChartParams(
            instrument=p.instrument, paper=p.paper, is_manual=True,
            tiff_dpi=KNUT_DPI, tiff_16bit=p.tiff_16bit,
            patch_scale=p.patch_scale, margin_mm=p.margin,
            triple_density=p.triple_density, double_density=p.double_density,
            disable_left_border=p.suppress_left_clip,
            no_strip_limit=p.no_strip_limit)
        kw = self._creator._engine_build_kwargs(params)
        kw["margins"] = (float(p.margin),) * 4
        kw["dpi"] = KNUT_DPI
        r = LayoutRecipe.from_build_kwargs(kw)
        r.instrument, r.paper = p.instrument, p.paper
        return r

    def _seed_knut_preset(self, key: str, target_name: str | None = None) -> None:
        """Load a TC9.18+Spyderprint preset's fixed printtarg layout into the panel.

        Sets every printtarg control the recipe touches (and resets the optional
        -A / -R rows when it doesn't), so the layout is fully determined no matter
        which preset was selected before. Split from _apply_knut_preset so it can
        be unit-tested without running printtarg."""
        p = KNUT_PRESETS_BY_KEY[key]
        triple = p.triple_density and p.instrument == "CM"

        # Clear modes that would otherwise hijack the seeded printtarg values.
        if self._manual_td_check is not None:
            self._manual_td_check.setChecked(False)
        if self._manual_auto_patches_check is not None:
            self._manual_auto_patches_check.setChecked(False)
            self._on_auto_patches_toggled(False)
        self._load_auto_neutral_states(grey=False, white=False, black=False)

        if p.layout_recipe is not None or p.engine:
            # Engine preset — the ChromIQ layout engine lays the bundled patch
            # set out, so seed the layout panel with the recipe instead of the
            # (hidden) printtarg widgets. The engine toggle is already on
            # (_on_preset_selected sets it before dispatching here). Scanner
            # presets carry an explicit recipe; the Full-layout-setup engine
            # presets derive theirs from their printtarg fields, reproducing
            # printtarg exactly (verified) but on the native engine path (#63).
            if getattr(self, "_manual_layout_panel", None) is not None:
                from dataclasses import replace as _replace
                from workflow.layout_engine.presets import LayoutRecipe
                # A BUILT-IN PRESET OWNS ITS LABEL STYLE. These recipes were
                # authored against a printed sheet — Knut's Scanner charts, the
                # ColorMunki / i1Pro / i1Pro3 families, the Red River sets — so
                # Preferences must not resize their labels. This is exactly the
                # beta-6 report: loading "Scanner-A4-3430p-1page-Landscape-
                # w4.0mm" printed 12 pt row numbers because a size set once for
                # another instrument was overlaid onto it. The values pinned are
                # the ones the dict carries (the Scanner recipe names no size,
                # so it pins "auto" — which is the size Knut had to set by hand).
                # The Full-layout-setup presets derive their recipe from their
                # printtarg fields rather than authoring one, so they are left
                # unpinned and keep following Preferences as before.
                # A BUILT-IN PRESET OWNS ITS LAYOUT TOO. `layout_explicit`
                # tells the panel that the layout mode, the area method, the
                # spacers and the clip content are this preset's answer — so
                # changing the instrument afterwards no longer applies the
                # instrument default over them (Knut, beta.5: a ColorMunki 84p
                # preset lost its 25.8 mm patches the moment a CR30 was picked).
                # Forced here rather than read from the file because none of the
                # bundled dicts carries the key.
                recipe = (_replace(LayoutRecipe.from_dict(p.layout_recipe),
                                   label_style_explicit=True,
                                   layout_explicit=True)
                          if p.layout_recipe is not None
                          else _replace(self._fls_engine_recipe(p),
                                        layout_explicit=True))
                self._set_engine_recipe(recipe)
                self._manual_layout_panel.set_pages(p.pages)
            if self._bit16_radio is not None and self._bit8_radio is not None:
                (self._bit16_radio if p.tiff_16bit
                 else self._bit8_radio).setChecked(True)
            # Descriptive targen values (the bundled .ti1 is the real source).
            self._set_manual_value("targen", "-f", p.patches)
            self._set_manual_value("targen", "-e", p.white)
            self._set_manual_value("targen", "-B", p.black)
            if self._manual_pages_spin is not None:
                self._manual_pages_spin.setValue(p.pages)
            self._seed_preset_name(target_name)
            return

        # Instrument first — it drives -h visibility and the per-instrument
        # default margin; we set the margin explicitly afterwards so ours wins.
        self._set_manual_value("printtarg", "-i", p.instrument)
        self._set_manual_value("printtarg", "-p", p.paper)
        self._set_manual_value("printtarg", "-t", KNUT_DPI)        # dpi (with -T)
        if self._bit16_radio is not None and self._bit8_radio is not None:
            (self._bit16_radio if p.tiff_16bit
             else self._bit8_radio).setChecked(True)               # -T (16-bit) / 8-bit
        # Triple density BEFORE the scalar rows: its toggle handler seeds
        # -a1.3/-m5/-P/-L, so it must run first or it would clobber the recipe's
        # own -a/-m below (the #45 ordering). Instrument is already CM, so the
        # TD row is visible/settable here.
        if triple and self._manual_td_check is not None:
            self._manual_td_check.setChecked(True)
        self._set_manual_value("printtarg", "-a", p.patch_scale)
        self._set_manual_value("printtarg", "-P", p.no_strip_limit)  # don't limit strips
        self._set_manual_value("printtarg", "-m", p.margin)        # → -m/-M
        self._set_manual_value("printtarg", "-L", p.suppress_left_clip)  # left clip border
        self._set_manual_value("printtarg", "-r", p.no_randomise)  # preserve order? (default: randomise)
        self._set_manual_value("printtarg", "-b", False)           # coloured spacers
        self._set_manual_value("printtarg", "-h", p.double_density)  # CM double density
        if p.spacer_scale is not None:
            self._set_manual_value("printtarg", "-A", p.spacer_scale)
        else:
            self._reset_manual_value("printtarg", "-A")
        if p.seed is not None:
            self._set_manual_value("printtarg", "-R", p.seed)
        else:
            self._reset_manual_value("printtarg", "-R")

        # Descriptive targen values (the bundled patch set; .ti1 is the real
        # source, so these only make the panel reflect what was loaded).
        self._set_manual_value("targen", "-f", p.patches)
        self._set_manual_value("targen", "-e", p.white)
        self._set_manual_value("targen", "-B", p.black)

        if self._manual_pages_spin is not None:
            self._manual_pages_spin.setValue(p.pages)
        self._seed_preset_name(target_name)

    def _apply_knut_preset(self, key: str, target_name: str | None = None) -> bool:
        """Seed a TC9.18+Spyderprint preset and build it from the bundled .ti1.

        Returns whether it was applied; False means the caller puts the tab back
        (#175).
        """
        if self._runner.is_running:
            log.warning("Knut preset: a process is already running")
            return False
        ti1 = resource_path(KNUT_PRESETS_BY_KEY[key].ti1_asset)
        if not ti1.is_file():
            InfoDialog(
                "Patch set not found",
                "The bundled patch set for this preset could not be "
                f"located:\n\n{ti1}\n\nThe app bundle may be incomplete.",
                self, min_width=520,
            ).exec()
            return False
        self._seed_knut_preset(key, target_name)
        self._knut_active = True
        self._knut_active_key = key
        # Snapshot the targen controls so later "Generate" clicks know whether to
        # re-lay-out the bundled .ti1 (printtarg only, targen untouched) or build a
        # fresh targen chart (the user changed a targen setting) — mirrors the
        # TC9.18 mechanism in _on_generate. The .ti1 is the fixed OFPS patch set,
        # so it can't be recreated by re-running targen.
        self._knut_targen_sig = self._targen_signature()
        self._update_preset_locks()      # grey targen (printtarg stays editable)
        self._refresh_manual_command_preview()
        return self._generate_from_ti1(ti1)

    def _reset_knut_overrides(self) -> None:
        """Revert the printtarg flags a TC9.18+Spyderprint preset forced on.

        Run when the user switches away from one (to Default / a user preset / a
        different built-in) so its layout overrides don't carry over. Mirrors
        _reset_tc918_overrides: revert to YAML defaults, then re-apply the
        per-instrument margin (the last word, after -i resets to its default)."""
        for flag in ("-i", "-p", "-t", "-a", "-P", "-m", "-L", "-r", "-b",
                     "-h", "-A", "-R"):
            self._reset_manual_value("printtarg", flag)
        self._apply_instrument_default_margin()

    # ------------------------------------------------------------------
    # Prebuilt-files built-in presets (TC9.24 A4 / Letter)
    # ------------------------------------------------------------------

    @staticmethod
    def _prebuilt_instrument(key: str) -> str:
        """printtarg -i code a prebuilt preset is laid out for, from its asset path.

        The asset stem is ``.../<instrument>/<paper>/<target>/<target>``; the
        instrument folder is the fourth component from the end. Used to seed the
        printtarg panel so an override re-layout starts from the right device."""
        stem = PREBUILT_PRESETS.get(key, ("",))[0]
        parts = stem.split("/")
        instr = parts[-4] if len(parts) >= 4 else ""
        return {"i1pro": "i1", "colormunki": "CM"}.get(instr, "i1")

    @staticmethod
    def _prebuilt_paper_code(key: str) -> str:
        """printtarg -p code a prebuilt preset is laid out for, from its asset path."""
        stem = PREBUILT_PRESETS.get(key, ("",))[0]
        parts = stem.split("/")
        paper = parts[-3] if len(parts) >= 3 else ""
        # Map the asset folder name to a valid printtarg -p code (see PAPER_SIZES).
        return {"a4": "A4", "a3": "A3", "a3plus": "329x483",
                "letter": "Letter"}.get(paper, "A4")

    def _leave_prebuilt(self) -> None:
        """Clear prebuilt-files state and re-enable the param panels."""
        self._prebuilt_active = False
        self._prebuilt_key = None
        self._prebuilt_targen_sig = None
        self._prebuilt_printtarg_sig = None
        self._reset_override_checks()
        self._update_preset_locks()

    def _leave_applied(self) -> None:
        """Clear applied-editor-chart state and re-enable the param panels."""
        self._applied_active = False
        self._applied_src_dir = None
        self._applied_stem = None
        self._applied_targen_sig = None
        self._applied_printtarg_sig = None
        self._reset_override_checks()
        self._update_preset_locks()

    def _leave_reflected(self) -> None:
        """Clear the reflected-chart state and re-enable the param panels."""
        if self._reflected_active:
            # Logged because the state is invisible until it blocks something:
            # Knut's beta.132 report of "This chart is loaded from elsewhere" on
            # a run's own verification chart had no trace in the log at all.
            log.info("Create Chart: leaving the loaded-from-elsewhere state")
        self._reflected_active = False
        self._reflected_ti2 = None
        self._reset_override_checks()
        self._update_preset_locks()

    def _apply_loaded_chart_settings(self, sidecar: Path) -> bool:
        """Take a loaded patch set's chart-settings file and put those settings
        on screen, so the sheet is rebuilt as it was laid out (#130, Knut).

        :meth:`_restore_chart_settings` is written around a chart's ``.ti2``
        because that is where a patch count can also be read; here only the
        sidecar exists, so it is addressed by the stem the two share.
        """
        try:
            out = self._restore_chart_settings(
                Path(sidecar).with_suffix("").with_suffix(".ti2"))
            self._forget_what_the_chart_imposed()
            return out
        except Exception:      # noqa: BLE001 — a bad sidecar must not block a load
            log.warning("Could not apply the loaded chart's settings from %s",
                        sidecar, exc_info=True)
            return False

    def _show_loaded_page_count(self, tiffs: "list[Path]",
                                ti2_path: Path) -> None:
        """Put the loaded chart's real number of pages in the pages field.

        Counted from what is actually there — the page images first, and the
        chart's own patch geometry as a fallback when a chart is shown before
        its pages have been rendered. Best-effort: a field that cannot be set
        is never worth failing a chart load over.
        """
        try:
            pages = len([t for t in tiffs if t.exists()])
            if not pages:
                import json as _json
                sidecar = ti2_path.with_suffix("").with_suffix(".channels.json")
                if not sidecar.exists():
                    sidecar = ti2_path.parent / f"{ti2_path.stem}.channels.json"
                if sidecar.exists():
                    layout = _json.loads(read_text(sidecar)).get("layout", {})
                    pages = 1 + max((int(p.get("page", 0))
                                     for p in layout.get("patches") or []),
                                    default=-1)
            # Read for the log only — and defensively, because a diagnostic
            # must never be able to stop the thing it is describing.
            try:
                before = self._manual_pages_spin.value()
            except Exception:      # noqa: BLE001
                before = None
            if pages > 0 and self._manual_pages_spin is not None:
                self._manual_pages_spin.setValue(int(pages))
            if pages > 0 and getattr(self, "_pages_spin", None) is not None:
                self._pages_spin.setValue(int(pages))
            # Knut asked me to find the stuck "pages = 20" in his log and it was
            # not there to find: ChromIQ never recorded the page count, so no
            # log could show what it held or who set it (#130, 2026-07-29).
            # It does now.
            log.info("chart loaded: %s page(s) counted from %s "
                     "(field was %s, now %s)", pages,
                     "the page images" if tiffs else "the patch geometry",
                     before, pages if pages > 0 else before)
        except Exception:      # noqa: BLE001 — never block a chart load
            log.warning("could not show the loaded chart's page count",
                        exc_info=True)

    def _forget_what_the_chart_imposed(self) -> None:
        """After an EXPLICIT restore, the chart's values are the answer.

        §10: *"When a chart is restored, the chart sidecar will overrule the
        settings for the chart for that specific run type."* The K3/K4 shield
        exists for the OTHER case -- merely selecting a run, where the sidecar
        gets a word in that nobody asked for. Leaving the shield standing here
        meant that pressing "Restore Used Chart" put the chart's settings on
        screen and then filed the pre-restore ones to disk, so the store and
        the screen disagreed the moment the tab was left.
        """
        if getattr(self, "_chart_imposed", None):
            log.debug("chart restored explicitly: the shield is dropped")
        self._chart_imposed = {}
        self._own_values_before_chart = None
        self._release_imposed_connections()

    def _restore_chart_settings(self, ti2_path: Path) -> bool:
        """Fill the Create-Chart options with the settings the loaded chart
        was actually made with, so what's on screen matches the chart —
        instead of whatever the panels happened to hold (mavtop, forum: a
        reloaded chart showed default patch counts, empty notes, seed 0…).

        Engine charts carry their complete layout recipe in the chart's own
        ``channels.json`` (patch size, spacers, margins, seed, notes,
        alignment — everything), so those restore fully: the engine toggle
        comes on, the layout panel takes the recipe, the pages/notes fields
        follow, and the patch count is pinned to the chart's real total.
        printtarg charts store no recipe — only instrument/paper (seeded by
        the callers) and the patch count can be recovered. Returns True when
        a full recipe was restored.

        Newer sidecars additionally carry ``chart_notes`` and
        ``stamp_commands`` (both chart kinds — the TIFF stamp itself can't be
        read back), restored gated on key presence so older charts keep the
        fields untouched; ``self._restored_notes_stamp`` tells the caller
        whether they were, for an accurate log line (mavtop, forum)."""
        import json as _json
        import re as _re
        # Forget the previous chart's recipe first: a chart that carries none
        # must not inherit the last one's layout (it would be rebuilt as some
        # other sheet entirely).
        self._restored_exact_recipe = None
        self._restored_chart_date = ""
        # Patch count from the .ti2 itself — works for every chart kind.
        try:
            txt = read_text(Path(ti2_path), lenient=True)
            m = _re.search(r"NUMBER_OF_SETS\s+(\d+)", txt)
            if m:
                self._set_manual_value("targen", "-f", int(m.group(1)))
                if self._manual_auto_patches_check is not None:
                    # Pin the count: with Auto on it would be recomputed from
                    # the layout and drift away from the loaded chart's total.
                    self._manual_auto_patches_check.setChecked(False)
        except Exception:  # noqa: BLE001 — count seeding is best-effort
            log.warning("could not seed patch count from %s", ti2_path,
                        exc_info=True)
        sidecar = Path(ti2_path).with_suffix(".channels.json")
        self._restored_notes_stamp = False
        if not sidecar.is_file():
            return False
        try:
            doc = _json.loads(read_text(sidecar))
        except Exception:  # noqa: BLE001 — never block a load on a bad sidecar
            log.warning("could not restore chart settings from %s", sidecar,
                        exc_info=True)
            return False
        restored_full = False
        try:
            layout = doc.get("layout") or {}
            rec_dict = layout.get("recipe") or {}
            if rec_dict:
                from workflow.layout_engine.presets import LayoutRecipe
                recipe = LayoutRecipe.from_dict(rec_dict)
                # The seed the chart was ACTUALLY built with (Knut, #130
                # 2026-07-27: "the random seed must survive the restore and
                # regeneration of the chart image"). The recipe records what
                # the user asked for — and "draw a fresh one each time" is
                # written there as no seed at all, so rebuilding from the
                # recipe alone shuffles the patches differently and the sheet
                # that comes back is not the sheet that was measured. The
                # build writes the drawn number one level up, and that is the
                # one that reproduces this chart.
                if isinstance(layout.get("seed"), int):
                    recipe.seed = int(layout["seed"])
                # Keep the recipe EXACTLY as the chart recorded it, before any
                # widget has rounded it and before Preferences has had its say.
                # A rebuild that must reproduce this chart reads this, not the
                # panel — see _restored_exact_recipe's use in the Restore path.
                self._restored_exact_recipe = recipe
                self._restored_chart_date = (
                    str(layout.get("date") or "")
                    or _chart_date_from_ti2(Path(ti2_path)))
                # Engine on first (builds/updates the panel), then the recipe.
                if (self._manual_engine_check is not None
                        and not self._manual_engine_check.isChecked()):
                    self._set_engine_checked(True)
                if self._manual_layout_panel is not None:
                    from dataclasses import replace as _replace_rec
                    # The chart's OWN recorded layout is the answer for that
                    # chart (§10: a restored chart's sidecar overrules), so the
                    # instrument defaults must not write over it either.
                    self._set_engine_recipe(
                        _replace_rec(recipe, layout_explicit=True))
                n_pages = 1 + max((int(p.get("page", 0))
                                   for p in layout.get("patches") or []),
                                  default=0)
                if self._manual_pages_spin is not None:
                    self._manual_pages_spin.setValue(n_pages)
                if (self._manual_chart_notes_edit is not None
                        and "chart_notes" not in doc
                        and getattr(recipe, "chart_text", "")):
                    # Sidecar predates the chart_notes key: the recipe's
                    # on-sheet text is the only note-like value left to show.
                    self._manual_chart_notes_edit.setText(recipe.chart_text)
                restored_full = True
        except Exception:  # noqa: BLE001 — never block a load on a bad sidecar
            log.warning("could not restore chart settings from %s", sidecar,
                        exc_info=True)
        # Chart notes + stamp choice — recorded for BOTH chart kinds. A
        # missing key means an older chart: leave the fields untouched.
        # Applied AFTER the engine toggle above, which resets the stamp
        # checkbox to its mode default (_refresh_manual_command_preview)
        # and would overwrite anything set earlier.
        try:
            # THE CHART'S NOTES, AND ONLY WHEN IT HAS ANY.
            #
            # §4 T4.1/T4.2: a restored chart REPLACES the notes field, and one
            # with no notes LEAVES IT AS IT IS — a restore must not blank text
            # the user has written for the chart they are about to make.
            #
            # They are then written into the run's (or the verification's run's,
            # or the calibration's) own meta, so the working copy agrees with
            # the sheet now on screen. The refresh that follows a restore reads
            # that meta, so without this the restored notes could be replaced by
            # the stale ones a moment later, depending on which handler ran
            # last. Knut, beta.148, asked for the restore to work for a
            # verification and a calibration exactly as it does for a run; one
            # rule in one place is how that is true for all three.
            _notes = str(doc.get("chart_notes") or "")
            if _notes and self._manual_chart_notes_edit is not None:
                self._manual_chart_notes_edit.setText(_notes)
                self._persist_restored_chart_notes(_notes)
                self._restored_notes_stamp = True
            if ("stamp_commands" in doc
                    and self._manual_stamp_cmd_check is not None):
                self._manual_stamp_cmd_check.setChecked(
                    bool(doc.get("stamp_commands")))
                self._restored_notes_stamp = True
        except Exception:  # noqa: BLE001
            log.warning("could not restore notes/stamp from %s", sidecar,
                        exc_info=True)
        # printtarg charts carry no layout recipe, but they DO save their
        # printtarg parameter fields (margins, patch scale, spacers, …). Restore
        # them so toggling between two charts shows EACH chart's own printtarg
        # settings, not whichever preset was loaded last (#130 Bug 1, Knut).
        if not restored_full:
            # This chart was drawn by printtarg: an engine chart always embeds
            # its recipe, and a sidecar with no recipe therefore describes a
            # printtarg layout. So the engine toggle has to come OFF, exactly as
            # it comes ON for an engine chart a few lines above.
            #
            # Knut, #130 2026-07-29, naming the case he had suspected all along:
            # *"if the stored chart in chart/ folder was made with printtarg
            # layout engine, and I change the Create Chart manual mode parameters
            # for ChromIQ layout engine, then settings from both layout engines
            # should be restored when clicking Restore Used Chart."* With the
            # engine left on, the printtarg fields restored on the next line were
            # simply ignored — `_collect_params` reads whichever engine is
            # selected — so the options on screen did not describe the stored
            # chart at all. That is the asymmetry: restoring an engine chart
            # switched the engine on, restoring a printtarg chart left it on too.
            if (self._manual_engine_check is not None
                    and self._manual_engine_check.isChecked()):
                self._set_engine_checked(False)
        # BOTH chart kinds get their printtarg fields back, not just printtarg
        # charts. On an engine chart these values are inert — the engine lays
        # the sheet out and the printtarg panel is hidden — but they are still
        # *recorded* in the sidecar, and leaving them alone meant a rebuild
        # wrote whatever the panel happened to hold. The sidecar then differed
        # from the stored one, the rebuild guard reported that the chart had
        # been altered, and the warning was about nothing: the layout was
        # identical and only this dormant history had moved (#130, seen while
        # reproducing Knut's Second-Project-R restore).
        self._restore_printtarg_fields(doc.get("printtarg_fields"))
        # K2 (Knut, beta.4: "Targen parameters are not loaded with charts
        # json file"): newer sidecars record the FULL registry at Generate —
        # targen rows included — and loading the chart applies it, so the
        # options on screen are the ones that made this sheet, whichever
        # target it belongs to. Older sidecars simply lack the key and keep
        # the printtarg-only restore above. Applied last, then the patch
        # count is re-pinned from the sheet itself: NUMBER_OF_SETS is the
        # chart's truth, and with Auto fill the generating -f can differ.
        reg = doc.get("create_chart_settings")
        if isinstance(reg, dict) and reg:
            was_loading = getattr(self, "_loading_target_settings", False)
            self._loading_target_settings = True
            try:
                from workflow.per_target_settings import apply as _apply_reg
                _apply_reg(self, reg)
            except Exception:  # noqa: BLE001 — never block a load
                log.warning("could not apply the chart's recorded registry",
                            exc_info=True)
            finally:
                self._loading_target_settings = was_loading
            try:
                m = _re.search(r"NUMBER_OF_SETS\s+(\d+)",
                               read_text(Path(ti2_path), lenient=True))
                if m:
                    self._set_manual_value("targen", "-f", int(m.group(1)))
            except Exception:  # noqa: BLE001
                pass
        return restored_full

    def _snapshot_printtarg_fields(self) -> list:
        """The current manual printtarg fields as ``[{flag, value, enabled}]`` —
        saved with each chart so it can be shown exactly when reloaded (#130)."""
        out = []
        for pw in self._manual_widgets.get("printtarg", []):
            try:
                out.append({"flag": pw.flag, "value": pw.get_raw_value(),
                            "enabled": bool(pw.is_enabled_by_user)})
            except Exception:  # noqa: BLE001
                pass
        return out

    def _restore_printtarg_fields(self, fields) -> None:
        """Apply saved printtarg field values (from :meth:`_snapshot_printtarg_
        fields`) to the manual printtarg panel (#130 Bug 1)."""
        if not fields:
            return
        by_flag = {pw.flag: pw for pw in self._manual_widgets.get("printtarg", [])}
        for f in fields:
            pw = by_flag.get(f.get("flag"))
            if pw is None:
                continue
            try:
                pw.set_value(f.get("value"))
                pw.set_user_enabled(bool(f.get("enabled")))
            except Exception:  # noqa: BLE001 — one bad field must not abort
                pass

    def _store_printtarg_fields_in_sidecar(self, ti2: "Path | None") -> None:
        """Merge the current printtarg fields into a chart's channels.json so a
        later load restores them (#130 Bug 1). Best-effort; never raises."""
        if not ti2:
            return
        sidecar = Path(ti2).with_suffix(".channels.json")
        try:
            doc = json.loads(read_text(sidecar)) if sidecar.is_file() else {}
        except Exception:  # noqa: BLE001
            doc = {}
        doc["printtarg_fields"] = self._snapshot_printtarg_fields()
        try:
            sidecar.write_text(json.dumps(doc), encoding="utf-8")
        except Exception:  # noqa: BLE001
            log.warning("could not store printtarg fields in %s", sidecar)

    def _chart_is_in_this_project(self, ti2_path: Path) -> bool:
        """Is this ``.ti2`` inside the project that is currently open?

        That is the whole question behind "loaded from elsewhere". A chart in
        the open project's own folder — any run, any verification, the
        calibration — is this tab's chart to edit and regenerate. Only a file
        outside it is somebody else's.
        """
        ctl = getattr(self, "_target_ctl", None)
        if ctl is None:
            return False
        try:
            project = ctl.project_or_none()
            if project is None:
                return False
            root = Path(project.root).resolve()
            return Path(ti2_path).resolve().is_relative_to(root)
        except (OSError, ValueError):      # unresolvable path → treat as outside
            return False

    def reflect_loaded_chart(self, ti2_path: Path, tiffs: list[Path]) -> None:
        """Mirror a chart loaded in the Print/Measure tab, read-only.

        Called by the main window when the user clicks "Load .ti2" in Print or
        Measure. Shows the chart's pages here with both panels greyed (so it's
        clear the loaded layout is what's active), WITHOUT copying anything or
        creating a project — the chart already lives in its own folder. A
        one-time note explains that the previously-shown layout is preserved.
        """
        # Mirroring someone else's chart fills this tab's widgets from that
        # chart's recipe. The user asked to LOOK at a chart, not to re-lay it
        # out — and a live re-render would rewrite a file that lives in a
        # folder this tab does not own. Settle on both exits.
        try:
            ti2_path = Path(ti2_path)
            # A CHART THE SELECTION ALREADY OWNS IS NOT "FROM ELSEWHERE".
            #
            # This state exists to say "the chart on screen lives in someone else's
            # folder, so there is nothing here to generate". When the file IS the
            # selected target's own chart, that sentence is false — and it does not
            # merely mislead, it BLOCKS: `_on_generate` stops on it. Knut, beta.147,
            # after using Duplicate (which shows the copy through this method):
            # *"Now I get a window 'This chart is loaded from elsewhere' … This is
            # obviously wrong … I am not allowed to finish the Generate Chart."*
            # He met the same wall on a run's own verification chart in beta.132.
            if self._chart_is_in_this_project(ti2_path):
                log.info("Create Chart: %s belongs to the open project — showing "
                         "it as this tab's own chart, not as a loaded one",
                         ti2_path.name)
                self._leave_reflected()
                self._shown_chart_ti2 = ti2_path
                self._shown_chart_stamp = self._chart_stamp(ti2_path)
                self._display_run_chart(ti2_path, list(tiffs),
                                        ti2_path.with_suffix(".ti1"))
                return
            self._switch_mode("manual")
            # Drop any other fixed-layout binding for a consistent lock state.
            self._tc918_active = False
            self._tc918_targen_sig = None
            self._knut_active = False
            self._knut_targen_sig = None
            self._preset_ti1_path = None
            self._preset_ti1_targen_sig = None
            # A reflected chart replaces whatever was loaded; drop the built-in's
            # bundled .ti1 too, or its patch count would shadow the live chart in
            # the Save-Preset name suggestion (_loaded_ti1_patch_count, Knut).
            self._builtin_ti1_path = None
            self._pending_editor_recipe = None   # reflected chart carries its own meta
            if self._prebuilt_active:
                self._leave_prebuilt()
            if self._applied_active:
                self._leave_applied()
            self._reflected_active = True
            log.info("Create Chart: showing a chart loaded from elsewhere: %s",
                     ti2_path)
            self._reflected_ti2 = ti2_path
            self._reset_override_checks()
            # Seed the instrument + page the chart was laid out for, so an
            # unlock-and-edit starts from the right device/paper.
            try:
                from workflow.ti2_relayout import ChartSpec
                spec = ChartSpec.from_ti2(ti2_path)
                self._set_manual_value("printtarg", "-i", spec.instrument_flag)
                self._set_manual_value("printtarg", "-p", spec.paper_flag)
            except Exception as exc:  # noqa: BLE001 — seeding is best-effort
                log.warning("Could not seed instrument/paper from reflected chart: %s", exc)
            # Bring the option panels to the chart's own creation settings BEFORE
            # locking, so the greyed panels show the truth about this chart —
            # and an unlock-and-edit really does start "from these settings", as
            # the loaded-chart dialog promises (mavtop, forum).
            self._restore_chart_settings(ti2_path)
            self._forget_what_the_chart_imposed()
            # A reflected chart is shown for reference only and never overwrites the
            # user's Printer-profile name (#70); seed it only if the field is empty.
            self._ensure_profile_name(ti2_path.stem)
            self._update_preset_locks()      # grey both panels
            self._log.clear()
            self._log.appendPlainText(
                f"Reflecting loaded chart “{ti2_path.name}” "
                f"({count_phrase(len(tiffs), tr('1 page'), tr('{n} pages'))}). "
                + tr("Loaded for reference only — not generated.")
            )
            if Path(ti2_path).with_suffix(".channels.json").is_file():
                self._log.appendPlainText(tr(
                    "The locked panels show the settings this chart was made "
                    "with — tick “Edit patch recipe (override preset)” or “Edit "
                    "page layout (override preset)” to build a new chart starting "
                    "from them."))
            if tiffs:
                self._preview.load_tiff(list(tiffs))
                self._set_margin_chart(list(tiffs), ti2_path)
            else:
                self._preview.clear()
                self._set_margin_chart([], None)
            # Estimate column follows the restored settings (set_recipe applies
            # silently, and the margin chart — the estimate's patch-count anchor
            # — only landed just above).
            self._refresh_manual_command_preview()
            self._maybe_warn_reflected_backfill(ti2_path)
        finally:
            self._settle_live_preview()

    def announce_duplicated_run(self, ti2_path: Path, run_label: str,
                                source_label: str) -> None:
        """Say what a Duplicate just did — in the words of a duplicate.

        Knut, #130 2026-08-01, on the window that used to appear here: *"Why
        mention safe in its own project folder, or that ti2 file can be opened
        again from Print or Measure?? First, Duplicate action was performed, so
        we are still inside the same open project. No need to say it is safe."*
        He is right; that text is written for a chart loaded from elsewhere, and
        every reassurance in it answers a worry a duplicate does not raise.

        He also caught the last paragraph describing how to build a new chart
        from these settings — *"This sounds like creating a verification run
        chart, without mentioning that it is, and that run type must be set
        correctly to do so."* So the verification route is named explicitly,
        with the step that actually matters.
        """
        if bool(self._settings.get("duplicate_notice_hide", False)):
            return
        dlg = QDialog(self)
        dlg.setWindowTitle(tr("Your duplicated run is ready"))
        dlg.setMinimumWidth(560)
        lay = QVBoxLayout(dlg)
        lay.setContentsMargins(24, 20, 24, 16)
        lay.setSpacing(12)
        heading = QLabel(
            tr("{run} is a copy of {source}, and it is now the run you are "
               "working in").format(run=run_label, source=source_label), dlg)
        heading.setWordWrap(True)
        heading.setStyleSheet("font-weight: 600; font-size: 14px;")
        lay.addWidget(heading)
        body = QLabel(
            tr("Create Chart is showing the copied chart — “{name}” — and the "
               "Print and Measure tabs are on it too, so every tab is working "
               "on the new run.\n\n"
               "{source} has not changed. Its chart, its measurement and its "
               "profile are exactly as they were, and you can go back to it at "
               "any time from the “Profile run” box.\n\n"
               "WHAT YOU CAN DO NOW\n"
               "•  Measure this chart again — the copied measurement is here, "
               "so tick “Refine / resume existing measurement (-r)” to add to it, or "
               "leave it unticked to start fresh.\n"
               "•  Build a different profile from the copied measurement, on "
               "the Build Profile tab.\n"
               "•  Give this run a different verification chart: set “Run "
               "type” to “Verification” first, then create the chart — the "
               "copy deliberately starts with none, which is why duplicating "
               "is the way to change one.").format(name=ti2_path.name,
                                                  source=source_label), dlg)
        body.setWordWrap(True)
        lay.addWidget(body)
        hide_cb = QCheckBox(tr("Don't show this again"), dlg)
        lay.addWidget(hide_cb)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok, dlg)
        bb.accepted.connect(dlg.accept)
        lay.addWidget(bb)
        dlg.exec()
        if hide_cb.isChecked():
            self._settings.set("duplicate_notice_hide", True)

    def _ti2_is_inside_current_project(self, ti2_path: Path) -> bool:
        """Whether *ti2_path* already lives under the project that is open.

        Used to keep the "loaded chart is now shown here" window for the case
        it was written for — a chart brought in from somewhere else — and out
        of the case where the user simply picked a file the project already
        owned.
        """
        # A QUESTION MUST NOT CREATE A PROJECT.
        # `project()` goes through `get_target_name()`, the mutating getter that
        # invents `Printer_Paper_Type_Instr_<timestamp>` and writes the folder.
        # So merely ASKING whether a loaded chart lived inside the current
        # project conjured one up: driven with no project open, one call left
        # `Printer_Paper_Type_Instr_2026-08-25_08-09/project.json` on disk and
        # `is_named()` True — after which the app was "in" a project the user
        # never made, and the next Generate built into it. Third site of this
        # fault (#164); `has_project()` answers without creating anything.
        if not self._file_mgr.has_project():
            return False           # nothing open, so nothing can be inside it
        try:
            project = self._file_mgr.project()
            root = getattr(project, "root", None) or getattr(project, "dir", None)
            if root is None:
                return False
            return Path(root).resolve() in Path(ti2_path).resolve().parents
        except Exception:      # noqa: BLE001 — a missing project is not "inside"
            return False

    def _maybe_warn_reflected_backfill(self, ti2_path: Path) -> None:
        """One-time, friendly heads-up that a loaded chart now shows here.

        Skipped after a Duplicate: that path shows its own window, because this
        one is written for a chart loaded from somewhere else and every
        reassurance in it is wrong for a copy made inside the open project
        (Knut, #130 2026-08-01 — see :meth:`announce_duplicated_run`).
        """
        if getattr(self, "_suppress_reflect_notice", False):
            return
        if bool(self._settings.get("reflect_backfill_hide_warning", False)):
            return
        # Nothing was imported, so there is nothing to announce. Knut, #130
        # beta.120: choosing a .ti2 that already lives in the open project and
        # picking "Continue" copies no files and moves nothing — *"This is
        # strange, as no import action was performed in this case, so this
        # window could be removed"*. Same reasoning as the Duplicate skip above.
        if self._ti2_is_inside_current_project(ti2_path):
            return
        dlg = QDialog(self)
        dlg.setWindowTitle(tr("Loaded chart is now shown in Create Chart"))
        dlg.setMinimumWidth(560)
        lay = QVBoxLayout(dlg)
        lay.setContentsMargins(24, 20, 24, 16)
        lay.setSpacing(12)
        heading = QLabel(
            tr("The chart you just loaded is now also shown in “Create Chart”"),
            dlg)
        heading.setWordWrap(True)
        heading.setStyleSheet("font-weight: 600; font-size: 14px;")
        lay.addWidget(heading)
        body = QLabel(
            tr("So every tab agrees on what you're working with, the Create "
               "Chart tab now mirrors this loaded chart — “{name}”. Its patch "
               "recipe and page layout are shown locked, because the chart "
               "already exists; ChromIQ won't change it.\n\n"
               "Nothing you built before is lost: any chart you'd generated "
               "earlier is still safe in its own project folder under "
               "~/ChromIQ, and you can open it again at any time with “Open "
               "Chart File (.ti2)” at the top left of the window.\n\n"
               "If you'd like to build a NEW chart starting from these "
               "settings, tick the “Edit patch recipe (override preset)” or "
               "“Edit page layout (override preset)” checkbox in the Create "
               "Chart tab, make your changes, and click “Generate Chart” — the "
               "loaded chart stays untouched. For charts made with the ChromIQ "
               "layout engine, "
               "the panels really do show the chart's own creation settings "
               "— patch size, spacers, margins, seed, notes and patch count "
               "are all restored from the chart itself.").format(name=ti2_path.name),
            dlg)
        body.setWordWrap(True)
        lay.addWidget(body)
        hide_cb = QCheckBox(tr("Don't show this again"), dlg)
        lay.addWidget(hide_cb)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok, dlg)
        bb.accepted.connect(dlg.accept)
        lay.addWidget(bb)
        dlg.exec()
        if hide_cb.isChecked():
            self._settings.set("reflect_backfill_hide_warning", True)

    def apply_external_chart(self, src_dir: Path, name: str) -> bool:
        """Adopt a chart the TI2 layout editor just wrote into ``src_dir``.

        Called by the main window when the user clicks **Overwrite** in the
        editor's "Apply / Save" window (#70, Knut's model). ``src_dir`` is a
        staging folder holding ``<name>.ti1`` / ``.ti2`` / ``<name>_NN.tif`` /
        ``meta.json`` — ``name`` is only the chart-*layout* file stem, NOT the
        profile name. The chart is imported into the **current** Create Chart
        profile (replacing the chart loaded there); the profile name is never
        changed. Both param panels are greyed so the applied patches and layout
        can't be overwritten by accident — the override boxes let the user opt
        back in, exactly like a prebuilt preset.

        Returns True (applied).
        """
        src_dir = Path(src_dir)
        # Applied charts always land in the manual module (the override boxes and
        # locked panels only exist there).
        self._switch_mode("manual")
        # Drop any other fixed-layout binding so the locks stay consistent.
        self._tc918_active = False
        self._tc918_targen_sig = None
        self._knut_active = False
        self._knut_targen_sig = None
        self._preset_ti1_path = None
        self._preset_ti1_targen_sig = None
        # The applied editor chart becomes the live chart; clear the built-in's
        # bundled .ti1 too. Otherwise its patch count shadows the applied chart
        # in the Save-Preset name suggestion (_loaded_ti1_patch_count checks
        # _builtin_ti1_path before _current_ti1_path) — Knut's 1168-vs-1575 bug.
        self._builtin_ti1_path = None
        # Carry the applied chart's creation recipe (Set B) along: the editor
        # writes it into the staging folder's meta.json, and only this pending
        # slot gets it into the regenerated run's meta.json (_stamp_chart_meta).
        # Without it the New-patch-set design is lost on apply, so presets saved
        # from the run can't reload it into the editor (#100).
        from workflow.ti2_relayout import load_editor_recipe
        rec = load_editor_recipe(src_dir / f"{name}.ti2")
        self._pending_editor_recipe = rec if isinstance(rec, dict) and rec else None
        if self._prebuilt_active:
            self._leave_prebuilt()
        if self._reflected_active:
            self._leave_reflected()
        # Create Chart OWNS the layout (Knut #93): applying takes only the editor's
        # PATCH SET (the .ti1) and lays it out with the layout currently set here —
        # it never changes your instrument / paper / margins / patch size. So we
        # adopt the .ti1 as the patch source (the same mechanism a bundled-.ti1
        # preset uses: patch set fixed, layout fully editable) and regenerate. We
        # do NOT seed or lock the editor's layout, and the layout panels stay live.
        self._applied_active = False
        ti1 = src_dir / f"{name}.ti1"
        if not ti1.is_file():
            log.warning("Applied patch set has no .ti1: %s", ti1)
            return False
        import shutil
        # NO PROJECT MEANS NOWHERE TO STAGE IT.
        # `working_dir()` invents and stores a name when there is none, so this
        # wrote `edited_patch_set.ti1` into a folder that had no project.json —
        # an orphan ChromIQ can never see again — and the NEXT action then made
        # a second, real project beside it. Two folders from one click (#164).
        try:
            dest = self._file_mgr.working_dir() / "edited_patch_set.ti1"
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(ti1, dest)
        except Exception as exc:  # noqa: BLE001
            log.warning("Could not stage the edited patch set: %s", exc)
            return False
        self._preset_ti1_path = dest
        self._preset_ti1_targen_sig = self._targen_signature()
        # Never overwrite the user's profile name — only seed it when empty.
        self._ensure_profile_name(name)
        self._reset_override_checks()
        self._update_preset_locks()
        # Lay the patch set out NOW with the current Create Chart layout.
        self._generate_from_ti1(dest)
        return True

    def _carry_engine_recipe_from(self, channels_json) -> None:
        """Carry an adopted chart's engine recipe back into Create Chart (#93).

        If *channels_json* holds a ChromIQ-engine recipe, turn the engine on and
        seed the Manual engine panel so the options chosen in the editor come
        back here; otherwise make sure the engine is off so the printtarg seeding
        shows. Best-effort — never blocks adopting the chart.
        """
        try:
            from workflow.layout_engine.presets import LayoutRecipe
            eng = LayoutRecipe.from_channels_json(channels_json)
            self._settings.set("use_chromiq_layout_engine", eng is not None)
            self._refresh_manual_command_preview()
            if eng is not None and getattr(self, "_manual_layout_panel", None) is not None:
                from dataclasses import replace as _replace_rec
                # Laid out by hand in the editor — an answer, not a default.
                self._set_engine_recipe(_replace_rec(eng, layout_explicit=True))
        except Exception as exc:  # noqa: BLE001 — carry-back is best-effort
            log.warning("Could not carry engine recipe back from editor: %s", exc)

    def _import_applied_chart(self, add_new_run: bool = False, *,
                              gate_already_asked: bool = False) -> None:
        """Copy the applied editor chart's files into the current run and load it.

        No targen/printtarg is run: the staged ``.ti1`` / ``.ti2`` / TIFF pages
        are copied into runs/<current>/ under the fixed ``chart`` stem and the
        TIFFs are shown in the preview, then routed downstream like any chart.
        The editor's richer ``meta.json`` (full layout) is copied in afterwards
        so reopening the run restores it exactly as the editor saved it.
        """
        import shutil
        if self._runner.is_running:
            log.warning("Applied chart: a process is already running")
            return
        if self._applied_src_dir is None or self._applied_stem is None:
            return
        src_dir = self._applied_src_dir
        stem = self._applied_stem
        src_ti1 = src_dir / f"{stem}.ti1"
        src_ti2 = src_dir / f"{stem}.ti2"
        # Multi-page charts are "<stem>_01.tif…"; a single page is just
        # "<stem>.tif". Accept both so a one-page applied chart still imports.
        from core.file_manager import stem_files
        src_tiffs = stem_files(src_dir, stem, "_*.tif")
        if not src_tiffs and (src_dir / f"{stem}.tif").is_file():
            src_tiffs = [src_dir / f"{stem}.tif"]
        _ctl = getattr(self, "_target_ctl", None)
        _proj_before = _ctl.project_or_none() if _ctl is not None else None
        if not src_ti1.is_file() or not src_tiffs:
            InfoDialog(
                "Applied chart not found",
                "The chart handed over from the layout editor could not be "
                f"located:\n\n{src_dir}",
                self, min_width=520,
            ).exec()
            return

        # §S4.7 BEFORE `target_started`, and before anything else. The window
        # promises "Cancel — stops here and changes nothing", and
        # `target_started` clears the user's Build Profile and Check tabs — so
        # asking after it made that promise false on this route. Measured.
        _proceed, _s4_done = self._gate_route_and_replace(gate_already_asked)
        if not _proceed:
            return
        self.target_started.emit()
        name = (self._manual_target_name_edit.text().strip()
                if self._manual_target_name_edit is not None else "") or stem
        self._file_mgr.set_target_name(name)
        # The run the picker named — this route used to ignore it entirely and
        # write to the manifest's own current run, so someone who chose
        # "A new run (nothing already there is touched)" had run 1's
        # measurement archived under their new chart. Measured.
        self._apply_gate_run_choice()
        if self._builds_into_project(_proj_before):
            self._align_current_run_to_target()
        project = self._file_mgr.project()
        # "Add as a new run" preserves the existing project's runs (and their
        # measurements) by filing this chart in a fresh runN; otherwise it goes
        # into — and resets — the project's current run.
        run = project.new_run() if add_new_run else project.current_run()
        run.reset_chart_artefacts()
        work_dir = run.ensure_dir()

        self._log.clear()
        self._preview.clear()
        try:
            shutil.copy(src_ti1, run.chart_ti1)
            if src_ti2.is_file():
                shutil.copy(src_ti2, run.chart_ti2)
            # Engine charts carry a channels.json (engine marker + recipe + strip
            # geometry); copy it so the run reads as an engine chart (#93).
            _src_ch = src_ti1.with_suffix(".channels.json")
            if _src_ch.is_file():
                shutil.copy(_src_ch, run.chart_channels_json)
            tiffs: list[Path] = []
            for i, src_tif in enumerate(src_tiffs, start=1):
                dest = work_dir / f"{run.stem}_{i:02d}.tif"
                shutil.copy(src_tif, dest)
                tiffs.append(dest)
        except OSError as exc:
            log.error("Applied-chart copy failed: %s", exc)
            InfoDialog(
                "Could not create target",
                f"Copying the chart into\n\n{work_dir}\n\nfailed:\n{exc}",
                self, min_width=520,
            ).exec()
            return

        self._last_target_name = name
        self._log.appendPlainText(
            f"Applied chart from the layout editor into {work_dir} "
            f"({count_phrase(len(tiffs), tr('1 page'), tr('{n} pages'))}). "
            + tr("targen and printtarg skipped.")
        )
        # The laid-out .ti2 may hold more patches than the designed .ti1: a
        # partial last strip is topped up with paper-white patches (printtarg
        # behaviour, mirrored by the engine). Say so, or the total silently
        # grows from the designed count (#124 report 6: 896 → 910).
        designed = _number_of_sets(run.chart_ti1)
        total = _number_of_sets(run.chart_ti2)
        if designed and total and total > designed:
            _fill = count_phrase(total - designed,
                                 tr("1 paper-white fill-up patch"),
                                 tr("{n} paper-white fill-up patches"))
            self._log.appendPlainText(
                f"Patch count: {designed} designed + {_fill} completing the "
                f"last strip = {total} total. Instruments read whole strips; "
                f"the fill-up patches are measured like any others."
            )
        # The chart wasn't built from ChartParams; clear them so the meta stamp
        # falls back to instrument/paper only and preserves the editor layout we
        # copy in next.
        self._last_params = None
        self._on_generate_finished(tiffs)
        # Overlay the editor's full meta.json (richer editor_layout) so reopening
        # this run in the editor restores every knob, not just instrument/paper.
        src_meta = src_dir / "meta.json"
        if src_meta.is_file():
            try:
                shutil.copy(src_meta, run.meta_path)
            except OSError as exc:
                log.warning("Could not copy applied-chart meta.json: %s", exc)
        # Carry the i1Profiler hand-off pair (and the colour list) the editor
        # wrote into the run folder too, so the working folder is self-contained
        # for users who profile in i1Profiler instead of measuring here. The
        # staged files carry the editor's layout name; rename them to the run
        # stem (the profile name) so the whole run folder is self-consistent —
        # the profile name and the chart layout name now differ (#70).
        from core.file_manager import nfc, stem_files
        for extra in stem_files(src_dir, stem, "-i1profiler.*",
                                "-colours.txt"):
            # NFC on both sides: `len(stem)` is a count of code points, and a
            # decomposed page name has more of them than the composed stem the
            # slice is measured against, so the tail would be cut in the wrong
            # place.
            dest_name = run.stem + nfc(extra.name)[len(nfc(stem)):]
            try:
                shutil.copy(extra, run.dir / dest_name)
            except OSError as exc:
                log.warning("Could not copy applied-chart extra %s: %s",
                            extra.name, exc)

    def _apply_prebuilt_preset(self, key: str, target_name: str | None = None) -> bool:
        """Select a prebuilt-files preset: grey the panels and copy the bundle.

        Both panels start locked. The instrument and paper the bundle was made
        for are seeded so that, if the user unlocks the layout and changes it,
        a printtarg re-run starts from the right device/page — and so the
        "did the layout change?" check has a sensible baseline.

        §S4.7 IS ASKED BEFORE ANY OF THAT. Everything below mutates the tab —
        `_prebuilt_active`, `_prebuilt_key`, `_layout_owned_by_build`, the
        override boxes, the instrument and paper rows — and Cancel used to undo
        only the dropdown. The window says "Cancel stops here and changes
        nothing", and the dropdown then read "none" while the next Generate
        quietly copied the bundle, with `_layout_owned_by_build` left latched.
        Measured. Asking first is cheaper than unwinding.
        """
        # THE NAME BEFORE THE GATE, on this route too. `_create_prebuilt_target`
        # is handed `gate_already_asked=True` from here, so the guard inside it
        # can no longer put §S4.7 in front of the answer — the question is
        # settled here or not at all. Asked while the box was empty, §S4.7 has
        # nothing to compare and a name given later overwrote a project without
        # a single window.
        if self._name_needs_asking(
                self._manual_target_name_edit.text().strip()
                if self._manual_target_name_edit is not None else "",
                target_name):
            if not self._ask_for_a_project_name():
                self._revert_preset_combo()
                return False
        _proceed, _s4_done = self._gate_route_and_replace(perform_replace=False)
        if not _proceed:
            # TO NONE, not back to the preset that was applied before: by the
            # time this runs, `_on_preset_selected` has already torn that one
            # down. See `_revert_preset_combo`.
            self._forget_gate_answer()
            self._revert_preset_combo(to_none=True)
            return False
        self._prebuilt_active = True
        self._prebuilt_key = key
        # THESE ROWS BELONG TO THE BUNDLE NOW, NOT TO THE TARGET.
        # Copying the bundle lands the Profile-run bar on the new run, and on a
        # fresh project that is a change of run — which resets every per-target
        # row to its factory value. targen's `-e`/`-B` go 0 → 4, the bundle's
        # signature stops matching, and Generate quietly rebuilds the chart
        # through targen instead of using the bundle: TC3.00's 300 patches came
        # out as 504, with no error to show for it (#164). The .ti1-backed
        # built-ins raise the same shield at `_apply_knut_preset`; this family
        # was missed, which is the silent half of that report.
        self._layout_owned_by_build = True
        self._reset_override_checks()
        # Seed the device + page the bundle was made for. printtarg is re-run from
        # the bundled .ti1 only if the user unlocks the layout and edits it.
        self._set_manual_value("printtarg", "-i", self._prebuilt_instrument(key))
        self._set_manual_value("printtarg", "-p", self._prebuilt_paper_code(key))
        # Built under the current Printer-profile name; never overwritten (#70),
        # and no longer named after the preset — see `_seed_preset_name`.
        self._seed_preset_name(target_name)
        # Baselines for the Generate-time change detection, taken after seeding.
        self._prebuilt_targen_sig = self._targen_signature()
        self._prebuilt_printtarg_sig = self._printtarg_signature()
        self._update_preset_locks()      # grey both panels
        return self._create_prebuilt_target(key, target_name,
                                            gate_already_asked=True,
                                            s4_already_answered=_s4_done)

    def _abandon_prebuilt_attempt(self) -> None:
        """Leave nothing behind when a prebuilt build does not happen.

        Three exits used to put the dropdown back and stop there, which left an
        agreed "Replace it" armed on the tab and `_layout_owned_by_build`
        latched True — the state this file documents as the cause of a run's
        stored Create Chart settings being clobbered. Neither could be reached
        today, because every consumer sits downstream of a gate that clears
        them; both broke the invariant this code states about itself, which is
        how the last three faults here started.
        """
        self._forget_gate_answer()
        self._layout_owned_by_build = False
        self._revert_preset_combo(to_none=True)
        self._leave_prebuilt()

    def _create_prebuilt_target(self, key: str, target_name: str | None = None,
                                *, gate_already_asked: bool = False,
                                s4_already_answered: bool = False) -> bool:
        """Copy a bundled prebuilt target into the project's current run and load it.

        No targen/printtarg is run: the bundled .ti1/.ti2 and TIFF pages are
        copied into runs/<current>/ under the fixed ``chart`` stem and the TIFFs
        are loaded into the preview, then routed downstream like a normal chart.

        WHAT THE RETURN VALUE MEANS, AND WHERE IT STOPS MEANING IT (#175).
        False = nothing happened and the caller may put the whole tab back.
        Every such exit is ABOVE ``target_started.emit()``. From that emit
        onwards the project has really changed — the tabs are cleared, the run
        is chosen, the run root is cleared for the copy — so there is nothing to
        go back to, and even the copy failing returns True. An undo there would
        put the panel back to describing the project the person just left.
        """
        import shutil
        if self._runner.is_running:
            log.warning("Prebuilt preset: a process is already running")
            return False
        stem_rel, default_name = PREBUILT_PRESETS[key]
        src_ti1 = resource_path(f"{stem_rel}.ti1")
        src_ti2 = resource_path(f"{stem_rel}.ti2")
        src_dir = src_ti1.parent
        src_stem = src_ti1.stem
        from core.file_manager import stem_files
        src_tiffs = stem_files(src_dir, src_stem, "_*.tif")
        if not src_ti1.is_file() or not src_tiffs:
            InfoDialog(
                "Prebuilt chart not found",
                "The bundled patch set could not be located:\n\n"
                f"{src_dir}\n\nThe app bundle may be incomplete.",
                self, min_width=520,
            ).exec()
            # …and leave nothing behind: this exit used to keep the preset
            # marked active with no bundle to build from, the build shield
            # latched, and an agreed "Replace it" still armed.
            self._abandon_prebuilt_attempt()
            return False

        # §4: THIS REPLACES THE RUN'S CHART LIKE ANY OTHER BUILD.
        #
        # It copies a bundled chart into the run and calls
        # reset_chart_artefacts() below, which archives the measurement — so it
        # displaces exactly what Generate Chart displaces and must ask exactly
        # the same question. Knut, beta.132: *"when selecting a preset that says
        # 'by pharmacist', then the chart is loaded without any
        # M-CHART-PROFILING message, but instead runs a full replace of the
        # chart, which also moved ti3 file to old/."* Every other preset path
        # asks — the params-based ones through _on_generate, the .ti1 ones
        # through _generate_from_ti1 — and this one, which runs no Argyll tool,
        # was the single way in that did not.
        # §S4.7 FIRST, and before `target_started` — the window says Cancel
        # changes nothing, and `target_started` clears the Build Profile and
        # Check tabs. MERELY CHOOSING a prebuilt-files preset from the dropdown
        # lands here and adopts the typed name, so this was the one route where
        # Knut's report stayed reproducible after the gate went on the others.
        # THE NAME COMES FIRST, BEFORE §S4.7 IS ASKED ABOUT ANYTHING.
        # §S4.7 asks about the project this build will touch, so it has to be
        # asked about the FINAL name. Asking for the name afterwards would
        # invalidate the answer just given: the person agrees to replace project
        # X and then names the project Y. `default_name` is the preset's own
        # name, and letting it stand is what made the folder, the ICC stem and
        # the name printed on the sheet into
        # `i1Pro-A4-162p-1page-Portrait-w7.5mm` — Knut's report, 2026-08-30.
        # An open project is not asked about: the chart is being added to it and
        # its name is already the answer.
        if self._name_needs_asking(
                self._manual_target_name_edit.text().strip()
                if self._manual_target_name_edit is not None else "",
                target_name):
            if not self._ask_for_a_project_name():
                self._abandon_prebuilt_attempt()
                return False
        _proceed, _s4_done = self._gate_route_and_replace(gate_already_asked,
                                                          perform_replace=False)
        if not _proceed:
            self._abandon_prebuilt_attempt()
            return False
        _s4_done = _s4_done or s4_already_answered

        # Remember the loaded project BEFORE the name is applied, so a build into
        # the SAME project can honour the Profile-run bar (Overwrite run N / New
        # run); a build under a NEW name is its own project (#130).
        _ctl = getattr(self, "_target_ctl", None)
        _proj_before = _ctl.project_or_none() if _ctl is not None else None
        # The name was settled above, before §S4.7 was asked. Read it back.
        _typed = (self._manual_target_name_edit.text().strip()
                  if self._manual_target_name_edit is not None else "")
        _named = _is_named(self._file_mgr)
        # AN OPEN PROJECT IS THE ANSWER — DO NOT RENAME IT AFTER THE PRESET.
        # With a project open and the name box cleared, falling through to
        # `default_name` renamed the target to the preset's own name and built
        # there: the very fault this guard exists to stop, one branch over.
        # `_generate_from_ti1` gets this right by simply not calling
        # `set_target_name` when it has no name, which leaves the FileManager on
        # the project already open; do the same here.
        name = _typed or target_name or (None if _named else default_name)
        # ADOPT, ASK, AND PUT IT BACK ON A NO.
        #
        # §4 must be asked about the run this build will really touch, which
        # means after the name is applied — asked before, it described the run
        # of the project the user was LEAVING, which is the whole fault §S4.7
        # exists to remove. But "no" then has to leave the app exactly where it
        # found it: an earlier attempt at this emitted `target_started` first,
        # so a "no" had already cleared the Build Profile and Check tabs and
        # switched the project. Driven against the shipped build, which does
        # neither.
        _snapshot = self._file_mgr.target_snapshot()
        if name:
            self._file_mgr.set_target_name(name)
        if not _s4_done and not self._confirm_displacing_results():
            self._file_mgr.restore_target(_snapshot)
            self._abandon_prebuilt_attempt()
            return False
        # Only now is anything committed: the archive the user agreed to, the
        # tabs, and the run the picker named.
        if not self._perform_pending_replace():
            # PUT THE PROJECT BACK TOO. `set_target_name` above has already moved
            # the FileManager onto the new name — the branch two lines up
            # restores it and this one did not, so a failed archive left ChromIQ
            # quietly on a different project while reporting that nothing had
            # happened. `set_target_name` also drops `_project_root_override`, so
            # a project living in a sub-folder lost its location with it, which
            # is #130's fault by another door. Measured.
            self._file_mgr.restore_target(_snapshot)
            self._abandon_prebuilt_attempt()
            return False
        # ---- THE POINT OF NO RETURN. Everything below is True (see docstring).
        self.target_started.emit()
        # The run the picker named. Without this the route fell through to
        # `_align_current_run_to_target`, which reads the BAR — still pointing
        # at a run of the project the user is leaving — so choosing "Run 1" put
        # the chart in run 3 and archived run 3's measurement. Measured.
        self._apply_gate_run_choice()
        # #130 CRITICAL (Knut): a prebuilt preset must build into the run the bar
        # shows — "Overwrite run N" → run N, "New run" → a fresh run — NOT always
        # the project's current run (which jumped the chart to the last run and
        # overwrote it). The params-based presets already do this via _on_generate;
        # the prebuilt-copy path bypassed it. Skipped for a build under a new name.
        _same_project = self._builds_into_project(_proj_before)
        if _same_project:
            self._align_current_run_to_target()
        # Run type = Verification copies through the run root too — keep the
        # run's profiling chart (#130, Knut K3).
        self._arm_verification_snapshot()
        run = self._file_mgr.project().current_run()
        # Start from a clean slate so stale pages from a prior copy can't linger.
        run.reset_chart_artefacts()
        work_dir = run.ensure_dir()

        self._log.clear()
        self._preview.clear()
        try:
            shutil.copy(src_ti1, run.chart_ti1)
            if src_ti2.is_file():
                shutil.copy(src_ti2, run.chart_ti2)
            # Engine charts carry a channels.json (engine marker + recipe + strip
            # geometry); copy it so the run reads as an engine chart (#93).
            _src_ch = src_ti1.with_suffix(".channels.json")
            if _src_ch.is_file():
                shutil.copy(_src_ch, run.chart_channels_json)
            tiffs: list[Path] = []
            for i, src_tif in enumerate(src_tiffs, start=1):
                dest = work_dir / f"{run.stem}_{i:02d}.tif"
                shutil.copy(src_tif, dest)
                tiffs.append(dest)
        except OSError as exc:
            log.error("Prebuilt copy failed: %s", exc)
            # The run root was already cleared for the copy — give the run its
            # profiling chart back before bailing out (#130, Knut K3).
            self._restore_profiling_chart()
            InfoDialog(
                "Could not create target",
                f"Copying the bundled chart into\n\n{work_dir}\n\nfailed:\n{exc}",
                self, min_width=520,
            ).exec()
            return True     # past the point of no return — see the docstring

        self._last_target_name = name
        self._log.appendPlainText(
            f"Copied prebuilt patch set into {work_dir} "
            f"({count_phrase(len(tiffs), tr('1 page'), tr('{n} pages'))}). "
            "targen and printtarg skipped."
        )
        # Prebuilt sets aren't generated from ChartParams — clear any stale
        # params so _stamp_chart_meta falls back to instrument/paper only
        # (read from the bundled .ti2) rather than a previous chart's knobs.
        self._last_params = None
        self._on_generate_finished(tiffs)
        return True

    def _targen_skipped_layout_name(self) -> str | None:
        """Layout name when Generate will skip targen for a *non-built-in* ti1
        source (a user preset's .ti1, an applied editor chart, or a reflected
        chart). Built-in presets have their own preview text above; returns None
        when a fresh targen will run (#70)."""
        if getattr(self, "_reflected_active", False) and self._reflected_ti2 is not None:
            return self._reflected_ti2.stem
        if getattr(self, "_applied_active", False) and self._applied_stem:
            if (self._applied_targen_sig is None
                    or self._targen_signature() == self._applied_targen_sig):
                return self._applied_stem
        if getattr(self, "_preset_ti1_path", None) is not None:
            if (self._preset_ti1_targen_sig is None
                    or self._targen_signature() == self._preset_ti1_targen_sig):
                cur = self._preset_combo.currentData()
                if cur is not None and cur not in BUILTIN_PRESET_KEYS:
                    return str(cur)
        return None

    def _active_layout_name(self) -> str | None:
        """A human label for the chart *layout* currently driving generation —
        a built-in/user preset, a prebuilt chart, an editor-applied layout, or a
        loaded .ti1. Stamped onto the TIFF as "Chart layout <name>" in place of
        the targen command when no targen was run (#70, Knut's model)."""
        if getattr(self, "_tc918_active", False):
            return "TC9.18"
        # A de-branded vendor preset (patch recipe unlocked) must NOT stamp the
        # vendor's name onto the sheet — fall through to a neutral label.
        if getattr(self, "_knut_active", False) and not self._vendor_debranded:
            p = KNUT_PRESETS_BY_KEY.get(self._knut_active_key or "")
            return p.default_target_name if p is not None else "TC9.18+Spyderprint"
        if getattr(self, "_prebuilt_active", False) and self._prebuilt_key:
            return PREBUILT_PRESETS[self._prebuilt_key][1]
        if getattr(self, "_applied_active", False) and self._applied_stem:
            return self._applied_stem
        if getattr(self, "_reflected_active", False) and self._reflected_ti2 is not None:
            return self._reflected_ti2.stem
        if getattr(self, "_preset_ti1_path", None) is not None:
            cur = self._preset_combo.currentData()
            if cur is not None and cur not in BUILTIN_PRESET_KEYS:
                return str(cur)
        ti1 = getattr(self, "_current_ti1_path", None)
        if ti1 is not None:
            return Path(ti1).stem
        return None

    def _generate_from_ti1(self, ti1_path: Path, *, ask: bool = True,
                           preview: bool = False) -> bool:
        """Create the target by running printtarg only on an existing .ti1.

        Used by the TC9.18 preset both for its initial creation and for every
        later "Generate Chart" click while the bundled patch set is still the
        active source. Shares _on_generate_finished with the normal path.

        *ask* is False only for the live auto-update preview, which cannot open
        a window on every turn of a knob — see :meth:`_auto_regenerate_preview`,
        which does its own §4 check and simply does not re-lay-out a run that
        holds work.

        WHAT THE RETURN VALUE MEANS (#175). False = this build did not happen
        and nothing was changed, so the caller may put the whole tab back. The
        five refusals are a busy runner, either half of the project/§4 question,
        a missing patch set, and no project name — and all five sit ABOVE
        ``target_started.emit()``. From that emit onwards the project has
        already moved, so every exit returns True even when the build then
        fails: there is no earlier state left to go back to.
        """
        if self._runner.is_running:
            log.warning("A process is already running")
            return False
        self._log_chart_build("live preview" if not ask else "user", ti1_path)
        self._cancel_pending_auto_preview()
        # `preview` IS THE ONE CALLER THAT MAY NOT OPEN A WINDOW.
        # The live auto-update preview re-renders on every turn of a knob, so a
        # modal here would be thrown at somebody repeatedly while they drag a
        # slider — and it left one standing in headless runs, which the gate
        # reports as an ERROR rather than a failure and is easy to miss.
        #
        # NOT `ask`, which is the obvious-looking flag and the wrong one. Four
        # auto-run preset routes also pass `ask=False` (they are the reason
        # `_generate_from_ti1` needs its own name guard at all — Knut's G1
        # report), and they ARE person-initiated. Keying on `ask` silently
        # turned his exact route back into "nothing happens and nothing says
        # why". `preview=True` is passed by exactly one caller.
        #
        # AND IT RUNS BEFORE §S4.7, WHICH IS THE WHOLE POINT OF ITS PLACE HERE.
        # §S4.7 asks about the project this build will touch; asked while the
        # name box is still empty it has nothing to check, waves the build
        # through, and the name given afterwards is never compared with anything
        # — so a name that already belongs to a project overwrote it with no
        # window of any kind. Driven: 7 files replaced, including the .ti2 a
        # printed sheet is read against. Typing the same name into the box
        # itself asked properly. The name must exist BEFORE the gate.
        _field = self._active_name_field()
        _typed = _field.text().strip() if _field is not None else ""
        # Empty, or typed into the box and unusable as a folder — the same door.
        if self._name_needs_asking(_typed):
            if preview:
                log.debug("live preview: nothing rendered — no usable project "
                          "name yet")
                return False
            if not self._ask_for_a_project_name():
                return False      # cancelled — nothing has been touched yet
            # Answered. Fall through and build: the name is in the field now,
            # and the code below reads it from there.

        # §4: every path that lays out a new chart asks first, not just the
        # Generate Chart button — a preset, an imported chart and a bundled
        # patch set all replace the chart a measurement describes.
        if ask:
            # §S4.7 FIRST, and it may answer §4 as well — see
            # `_gate_typed_project_name`. Asked before anything is applied, so
            # Cancel is a plain early return that has changed nothing.
            _proceed, _s4_done = self._gate_typed_project_name()
            if not _proceed:
                return False
            if not _s4_done and not self._confirm_displacing_results():
                return False
        if not ti1_path.is_file():
            InfoDialog(
                "Patch set not found",
                f"The .ti1 patch set could not be located:\n\n{ti1_path}",
                self, min_width=520,
            ).exec()
            return False
        # A NAME IS REQUIRED — never invent one (Basti, #164 Q15).
        #
        # THE GUARD BELONGS HERE, NOT ONLY IN `_on_generate`. Seven of that
        # method's paths reach this one through an early return ABOVE its own
        # check — a user preset with an attached .ti1 (the route Knut hit), an
        # applied editor chart, a prebuilt re-layout, TC9.18, a Spyderprint
        # preset — and the ▶ "generate on select" branch walks straight in.
        # Down at `base_name` the mutating `get_target_name()` then makes up
        # `Printer_Paper_Type_Instr_<timestamp>`, CREATES that project and
        # builds the whole chart into a folder nobody asked for and nobody
        # would find again. Driven: selecting a saved user preset from a fresh
        # start produced exactly that, with no dialog of any kind. Placed
        # BEFORE the button is disabled below, so an early return needs no undo.
        #
        # THIS NOW COVERS THE BUILT-IN PRESETS TOO. Until 2026-08-30 every
        # built-in route had already called `_ensure_profile_name` with the
        # preset's own default name, so the field was never empty here and the
        # guard could not fire — and a preset picked on a freshly started app
        # created a project named `i1Pro-A4-162p-1page-Portrait-w7.5mm` with no
        # window at all, because §S4.7 keys off a name the USER typed. Knut
        # reported that; Basti had wanted it asked all along. `_seed_preset_name`
        # now leaves the field empty, so a built-in arrives here like any other
        # preset and is asked for a name.
        # THE BUILD STARTS HERE, not at the call to the creator further down.
        # Everything below — naming the target, re-aligning the run, arming the
        # verification snapshot — can fire the target-switch handler, which loads
        # the run's stored Create Chart state over the layout this build is about
        # to use. `_chart_build_in_flight` reads this button, so disabling it any
        # later leaves exactly that window open, and Basti's log showed the four
        # loads landing in it (2026-08-16). Every path out of this build
        # re-enables the button, including the failures.
        self._generate_btn.setEnabled(False)
        self._layout_owned_by_build = True
        # ---- THE POINT OF NO RETURN. Every exit below is True (see docstring).
        self.target_started.emit()
        # Remember the loaded project before the name is applied (#130).
        _ctl = getattr(self, "_target_ctl", None)
        _proj_before = _ctl.project_or_none() if _ctl is not None else None
        name = (self._manual_target_name_edit.text().strip()
                if self._manual_target_name_edit is not None else "")
        # A LIVE PREVIEW MAY NOT CHANGE PROJECT. This line runs whatever `ask`
        # is, so the auto-update preview used to read the name box and adopt
        # whatever was typed there: open project A, type the name of project B
        # without pressing anything, nudge a layout knob, and ChromIQ made B
        # current and rebuilt B's chart — with no window, because §4 forbids the
        # preview from opening one. It renders into the run it just assessed
        # instead; only a deliberate build may move to another project.
        if name and preview and self._name_points_elsewhere(name):
            log.info("live preview: not adopting the typed name %r — it names "
                     "another project", name)
            name = ""
        # A PREVIEW IS NOT A POINT OF NO RETURN, AND MAY NOT ACT ON AN ANSWER.
        # An armed "Replace it" survived an aborted build — cancel the rename
        # chooser and nothing is built, but the answer stayed on `self` — and
        # then ONE live-preview render archived the whole project, with no
        # window, because §4 forbids the preview from opening one. Driven. The
        # same leak applied a run choice made for one project to another
        # project's bar.
        # THE POINT OF NO RETURN. A "Replace it" the user agreed to is carried
        # out HERE, not when they clicked it — everything above can still
        # abort, and a missing .ti1 used to archive the whole project and then
        # say "Patch set not found", having built nothing.
        #
        # AND A PREVIEW IS NOT THAT POINT. It is the one route forbidden to open
        # a window, so an armed "Replace it" left over from an aborted build was
        # carried out HERE with nothing said: cancel the rename chooser, nudge a
        # layout knob, and the whole project was archived. Driven. The same leak
        # applied a run choice made for one project to another project's bar.
        if not preview and not self._perform_pending_replace():
            self._generate_btn.setEnabled(True)
            self._layout_owned_by_build = False
            return True     # past the point of no return — see the docstring
        if name:
            self._file_mgr.set_target_name(name)
        if not preview:
            self._apply_gate_run_choice()
        # #130 CRITICAL (Knut): a .ti1-based preset (TC9.18, Spyderprint) must
        # build into the run the Profile-run bar shows — Overwrite run N / New
        # run — not always the project's current run. Skipped for a build under a
        # new name (that's a different project).
        _same_project = self._builds_into_project(_proj_before)
        if _same_project:
            self._align_current_run_to_target()
        # Run type = Verification builds through the run root too — keep the
        # run's profiling chart (#130, Knut K3).
        self._arm_verification_snapshot()
        # The guard above means a name is always set by now, so this getter
        # can no longer invent one. The old `or TC918_TARGET_NAME` fallback
        # only ever hid the fault.
        base_name = self._file_mgr.get_target_name()
        params = self._collect_params()
        self._last_params = params  # for _stamp_chart_meta (see _on_generate)
        params.target_name = base_name
        # Built from an existing patch set (targen not run) → the stamp names the
        # chart layout instead of a misleading targen command (#70).
        params.chart_layout_name = self._active_layout_name()
        self._last_target_name = base_name
        self._log.clear()
        self._preview.clear()
        self._creator.load_ti1_and_generate_preview(
            ti1_path, params,
            on_line=self._on_log_line,
            on_finish=self._on_generate_finished,
        )
        return True

    # ------------------------------------------------------------------
    # Patch count display
    # ------------------------------------------------------------------

    def _combo_thresholds(self, instr: str, paper: str):
        """The user's margin-threshold minimums for an engine instrument + paper,
        or None — so the live patch count honours the same minimums the engine
        enforces at generation (#93)."""
        try:
            from core.settings import thresholds_for_combo
            from workflow.layout_engine import papers
            w_mm, h_mm = papers.dimensions_mm(paper)
            return thresholds_for_combo(
                self._settings.get_margin_thresholds(), instr, w_mm, h_mm)
        except Exception:
            return None


    def _engine_geom(self, instr: str, paper: str, *, dd: bool, td: bool,
                     eff_lb: bool, nsl: bool, pscale: float, margin: float,
                     guided: bool = True):
        """Build a layout-engine Geom from the guided/manual effective values,
        with the user's margin thresholds enforced (so the count matches what
        the engine will actually build, #93).

        Spacers are decided HERE, from *guided*, and never by a caller. They
        were hard-coded ``True``, which stayed invisible until the CR30 became
        the first instrument that lays out without them: the estimate reserved
        1.3 mm of gap the chart never used and under-counted by ~10 %. Fixing it
        at one call site then left the sibling caller wrong, so the
        Calculated-Patches figure and the Chart-layout-information panel
        disagreed with each other. One rule, one place — mirroring
        ``chart_creator._engine_build_kwargs``.
        """
        from workflow.layout_engine import instruments
        kw: dict = dict(instrument=instr, paper=paper, spacer_on=True,
                        pscale=float(pscale),
                        margins=(float(margin),) * 4, border=float(margin),
                        nolimit=bool(nsl))
        # The strip-reading instruments bracket each strip with a leading +
        # trailing spacer (chart_creator._engine_build_kwargs does the same for
        # the real build); those two reserved gaps must be counted here too, or
        # the estimate over-counts what the engine actually fits (i1 A4 read 575
        # vs the real 550).
        if instr in ("i1", "p3", "CM"):
            kw["edge_spacers"] = True
        if instr in ("i1", "p3"):
            kw["nolpcbord"] = bool(eff_lb)
        elif instr == "CM":
            kw["density"] = 3 if td else (2 if dd else 1)
            if dd and not td:
                # Double density couples the tighter rows with a half-patch row
                # stagger, whose overhang reserves ¼-patch and reduces capacity;
                # the build sets it, so the count must too (else it over-counts
                # — CM double A3 read 480 vs the real 460).
                kw["cm_stagger"] = True
            if td:
                # Same printtarg-> engine scale conversion the build applies
                # (chart_creator._engine_build_kwargs): the guided pscale is the
                # printtarg -ii1 -a value (1.3 default), and the engine's native
                # extra-high size reproduces -a1.3 at pscale 1.0. Without this
                # the count used the raw 1.3 → oversized patches → undercount.
                from workflow.chart_creator import CM_TRIPLE_PRINTTARG_SCALE
                kw["pscale"] = float(pscale) / CM_TRIPLE_PRINTTARG_SCALE
        elif instruments.hex_capable(instr):
            # For the ColorMunki the same checkbox means DENSITY; for a
            # hex-capable instrument it is the rectangular/hexagonal switch.
            # ASKED OF THE GEOMETRY (instruments.hex_capable probes whether the
            # build branch honours hflag) rather than held in yet another list:
            # this decision was already spelled out by name in eight places, and
            # a ninth hard-coded tuple here would have been the tenth thing to
            # forget when the next hex instrument arrives.
            kw["hflag"] = bool(dd)
        # A GUIDED CR30 is laid out with no spacers at all (Basti's ruling);
        # chart_creator._engine_build_kwargs does exactly this for the build, so
        # the estimate must model the same chart. Manual keeps its own control.
        if instr == "CR30" and guided:
            kw["spacer_on"] = False
            kw["spacer_mode"] = "none"
        # Guided mode has no margin boxes and no "Use instrument margins"
        # recipe toggle, so the jig-safety threshold clamp is NOT applied here.
        # It would pin the patch count regardless of the clip-border / strip-cap
        # toggles (the thresholds dominate). Mirrors chart_creator's Guided
        # generation path so the estimate matches the real render.
        return instruments.geom_from_build_kwargs(kw, thresholds=None)

    def _engine_capacity(self, instr: str, paper: str, *, dd: bool, td: bool,
                         eff_lb: bool, nsl: bool, pscale: float, margin: float,
                         guided: bool = True):
        """Patches per sheet from the ChromIQ engine (None if it can't lay out)."""
        try:
            from workflow.layout_engine import geometry, papers
            geom = self._engine_geom(instr, paper, dd=dd, td=td, eff_lb=eff_lb,
                                     nsl=nsl, pscale=pscale, margin=margin,
                                     guided=guided)
            w_mm, h_mm = papers.dimensions_mm(paper)
            return geometry.patches_per_sheet(geom, w_mm, h_mm)
        except Exception:
            return None

    def _engine_info_line(self, instr: str, paper: str, dpi: int, *, dd: bool,
                          td: bool, eff_lb: bool, nsl: bool, pscale: float,
                          margin: float) -> str:
        """One-line description of what the ChromIQ engine will build.

        Used by Guided mode, where the engine runs on fixed settings derived
        from the instrument/paper (not from an editable recipe). Manual mode
        has a live recipe panel — see :meth:`_engine_info_line_from_recipe`."""
        bits = [tr("ChromIQ layout engine"), instr, paper, f"{dpi} dpi",
                tr("margin {mm:g} mm").format(mm=margin)]
        if abs(pscale - 1.0) > 0.01:
            bits.append(tr("patch ×{s:.2f}").format(s=pscale))
        if instr in ("i1", "p3"):
            bits.append(tr("clip border off") if eff_lb else tr("clip border on"))
        if instr == "CM":
            bits.append({3: tr("extra-high density"), 2: tr("high density")}.get(
                3 if td else (2 if dd else 1), tr("hand-held")))
        from workflow.layout_engine import instruments as _inst
        if dd and _inst.hex_capable(instr):
            bits.append(tr("hexagonal"))
        if nsl:
            bits.append(tr("no strip-length cap"))
        return " · ".join(bits)

    @staticmethod
    def _engine_info_line_from_recipe(r) -> str:
        """One-line summary of what the engine will build, read straight from
        the live layout recipe (Manual mode's source of truth).

        The printtarg widgets do NOT drive the engine here, so the info box has
        to reflect the recipe's own margins / patch size / clip border / etc.,
        otherwise it shows stale printtarg values (#93)."""
        from workflow.layout_engine import papers
        bits = [tr("ChromIQ layout engine"), r.instrument,
                papers.friendly_label(r.paper), f"{r.dpi} dpi"]
        # Margins — collapse to one value when all four agree, else show them.
        m = (r.margin_top, r.margin_right, r.margin_bottom, r.margin_left)
        if len(set(m)) == 1:
            bits.append(tr("margin {mm:g} mm").format(mm=m[0]))
        else:
            bits.append(tr("margins {t:g}/{r:g}/{b:g}/{l:g} mm").format(
                t=m[0], r=m[1], b=m[2], l=m[3]))
        # Layout strategy: area-first shows the target grid (patches are derived);
        # patch-first shows the explicit size or scale.
        if getattr(r, "layout_mode", "patch_first") == "area_first":
            if getattr(r, "area_method", "by_width") == "by_grid":
                _c = r.area_cols or tr("auto")
                _rr = r.area_rows or tr("auto")
                bits.append(tr("area-fit {c}×{r}").format(c=_c, r=_rr))
            elif r.area_min_patch_mm > 0:
                bits.append(tr("area-fit ≥{mm:g} mm").format(
                    mm=r.area_min_patch_mm))
            else:
                bits.append(tr("area-fit"))
        elif r.patch_w_mm > 0 and r.patch_h_mm > 0:
            bits.append(tr("patch {w:g}×{h:g} mm").format(
                w=r.patch_w_mm, h=r.patch_h_mm))
        elif abs(r.pscale - 1.0) > 0.01:
            bits.append(tr("patch ×{s:.2f}").format(s=r.pscale))
        if r.instrument in ("i1", "p3"):
            bits.append(tr("clip border on") if r.clip_border
                        else tr("clip border off"))
        if r.instrument == "CM":
            bits.append({3: tr("extra-high density"), 2: tr("high density")}.get(
                r.cm_density, tr("hand-held")))
        if r.instrument == "SS" and r.hflag:
            bits.append(tr("hexagonal"))
        if r.nolimit:
            bits.append(tr("no strip-length cap"))
        # Patch-area alignment, only when it differs from the default.
        if (r.patch_area_align or "top-left") != "top-left":
            bits.append(tr("align {a}").format(a=r.patch_area_align))
        return " · ".join(bits)

    def _update_patch_count(self) -> None:
        instr  = self._instr_combo.currentData() or "i1"
        paper  = self._paper_combo.currentData() or "A4"
        dd     = self._dd_check.isChecked()
        td     = self._td_check.isChecked() and instr == "CM"
        pages  = self._pages_spin.value()
        has_lb = self._lb_check.isChecked()  # True = -L active (left border suppressed)
        # -P only matters for strip instruments; for CM/SS the layout
        # is fixed and the checkbox is hidden anyway.
        nsl    = (self._nsl_check.isChecked()
                  and instr in {"i1", "p3"}
                  and not td)
        # ChromIQ-style forces -L, so capacity must be computed at -L-enabled
        # values even when the user left the checkbox unchecked. Triple
        # density also forces -L (and the suppress widget is hidden).
        # The ChromIQ clip style is a printtarg-era flag; on an engine chart the
        # engine draws its own clip band and the flag is ignored, so it must not
        # move the predicted capacity either (#170). `engine_on` is computed the
        # same way a dozen lines below; Guided is always the engine.
        from workflow.chart_creator import ENGINE_INSTRUMENTS as _EI
        _engine_here = (instr in _EI) and (
            not (self._manual_btn is not None and self._manual_btn.isChecked())
            or bool(self._settings.get("use_chromiq_layout_engine", False)))
        chromiq_force_l = self._chromiq_force_l(instr, paper) and not _engine_here
        eff_lb = has_lb or chromiq_force_l or td
        # Triple density forces -P; reflect that in the lookup so the
        # patch counter agrees with what printtarg will actually do.
        nsl_eff = nsl or td
        dpi    = int(self._settings.get("printtarg_dpi", 300))
        if td:
            # Triple density bypasses the per-instrument defaults and locks
            # the layout to the i1Pro emulation preset.
            eff_margin = 5
            eff_scale = 1.3
        elif instr == "i1":
            preset_key = str(self._settings.get(
                "i1pro_default_preset", I1PRO_DEFAULT_PRESET_KEY
            ))
            eff_margin, eff_scale = i1_defaults_from_preset(preset_key)
        else:
            eff_margin = INSTRUMENT_DEFAULT_MARGIN.get(instr, 6)
            eff_scale = 1.0

        # Which engine the COUNT must model has to match what will actually
        # build: Guided always lays out engine instruments with the ChromIQ
        # engine (regardless of the Manual "use engine" toggle — that governs
        # Manual only); Manual honours the toggle. Mirroring _should_use_engine
        # here fixes the Guided count/estimate reading the printtarg DB (or
        # showing nothing) when the Manual toggle happened to be off (Basti).
        from workflow.chart_creator import ENGINE_INSTRUMENTS
        guided_active = not (self._manual_btn is not None
                             and self._manual_btn.isChecked())
        engine_on = (instr in ENGINE_INSTRUMENTS) and (
            guided_active or bool(self._settings.get("use_chromiq_layout_engine", False)))
        if engine_on:
            per_sheet = self._engine_capacity(
                instr, paper, dd=dd, td=td, eff_lb=eff_lb, nsl=nsl_eff,
                pscale=eff_scale, margin=eff_margin, guided=guided_active)
        else:
            per_sheet = query_patches(instr, paper, dd, suppress_lb=eff_lb,
                                      margin_mm=eff_margin, patch_scale=eff_scale,
                                      triple_density=td, no_strip_limit=nsl_eff)
        if per_sheet is not None:
            total = per_sheet * pages
            self._predicted_patch_count = total   # for the Suggest-name button (#62)
            self._patch_count_lbl.setText(self._count_with_accent(str(total)))
            # "1 PAGES" sat on the first screen of the app, in the largest
            # type on the panel, with "Number of pages: 1" two inches above it.
            # Every other count-bearing line already uses `count_phrase`; this
            # one skipped it and thirteen translations inherited the mistake.
            _pages = count_phrase(pages, tr("1 PAGE"), tr("{n} PAGES"))
            self._patch_detail_lbl.setText(
                tr("PATCHES · {pages} · {paper}").format(
                    pages=_pages, paper=paper.upper())
            )
        else:
            self._predicted_patch_count = None
            self._patch_count_lbl.setText(self._count_with_accent("", mark="?"))
            self._patch_detail_lbl.setText(tr("CUSTOM LAYOUT"))

        # Live layout-info estimate (Guided + engine). Runs even with a chart on
        # screen, so its "estimate" column tracks the current settings while the
        # "on screen" column keeps the generated chart's real numbers (#93).
        if guided_active and getattr(self, "_layout_info_panel", None) is not None:
            if engine_on:
                # Same mirror of chart_creator._engine_build_kwargs as the
                # patch-count estimate above. This is a SECOND caller of
                # _engine_geom and it was missed when the first was fixed, so
                # the Calculated-Patches figure went right while the
                # Chart-layout-information panel next to it still described a
                # rectangular, spacered chart (Basti, 2026-08-28).
                geom = self._engine_geom(instr, paper, dd=dd, td=td, eff_lb=eff_lb,
                                         nsl=nsl_eff, pscale=eff_scale,
                                         margin=eff_margin, guided=guided_active)
                self._predict_layout_info(geom, paper, pages)
            else:
                self._layout_info_panel.clear_estimate()

        # Hidden-defaults info label (values mirror _collect_guided logic).
        # The base is fixed (no settings UI exposes it); reading it from settings
        # used to round-trip the auto-computed result back into the base via
        # "Save as defaults", which collapsed -e/-B toward the floor of 2.
        grey_steps, wp, bp = guided_neutrals(
            instr, paper, pages, GUIDED_NEUTRAL_BASE, GUIDED_NEUTRAL_BASE, eff_lb,
            double_density=dd, triple_density=td, no_strip_limit=nsl_eff,
            ref_budget=int(self._settings.get("grey_ramp_reference", REF_BUDGET)),
        )
        # -L only matters for strip instruments; -h only for CM/SS. Hide
        # both from the command preview when not applicable so the user
        # sees exactly what printtarg will run. ChromIQ-style clipping
        # border forces -L regardless of the per-chart toggle (eff_lb).
        # Triple density: emulate the i1Pro layout with -ii1, force -L,
        # and append -P (strip-limit removal); the -h flag is gated off.
        preview_instr = "i1" if td else instr
        lb_flag = "-L " if eff_lb and (preview_instr in {"i1", "p3"}) else ""
        dd_flag = "-h " if (dd and not td) and instr in {"CM", "SS"} else ""
        margin_flag = f"-m{eff_margin} -M{eff_margin} " if eff_margin != 6 else ""
        scale_flag = f"-a{eff_scale:.2f} " if abs(eff_scale - 1.0) > 0.01 else ""
        strip_flag = "-P " if nsl_eff else ""
        precond_path = (
            self._guided_precond_path.text().strip()
            if hasattr(self, "_guided_precond_path") else ""
        )
        precond_active = (
            hasattr(self, "_guided_precond_check")
            and self._guided_precond_check.isChecked()
        )
        precond_line = ""
        recommendation = ""
        if precond_active:
            if precond_path:
                # chart_creator imports the pick into the run as
                # preconditioning.icc; show that staged name in the preview.
                precond_line = " -c preconditioning.icc"
                recommendation = "\n" + tr(
                    "Tip: use at least as many pages as the original profile.")
            else:
                recommendation = "\n" + tr(
                    "Pick a profile to refine from (Browse… above).")

        # With a refinement profile (-c) the neutral ramp samples the profile-
        # defined neutral axis (-n) rather than naïve device grey (-g).
        grey_flag = "-n" if (precond_active and precond_path) else "-g"

        target_name = self._preview_target_name("guided")
        targen_line = (f"targen -d2 -G -e{wp} -B{bp} "
                       f"{grey_flag}{grey_steps}{precond_line} {target_name}")
        if engine_on:
            layout_line = self._engine_info_line(
                instr, paper, dpi, dd=dd, td=td, eff_lb=eff_lb, nsl=nsl_eff,
                pscale=eff_scale, margin=eff_margin)
            info = (tr("Guided mode applies these fixed settings:")
                    + f"\n{targen_line}\n{layout_line}{recommendation}")
        else:
            info = (
                tr("Guided mode applies these fixed settings:")
                + f"\n{targen_line}\n"
                f"printtarg -i{preview_instr} -p{paper} -t{dpi} {scale_flag}{lb_flag}{dd_flag}{margin_flag}{strip_flag}{target_name}"
                f"{recommendation}"
            )
        if hasattr(self, "_guided_info_lbl"):
            self._guided_info_lbl.setText(info)

        # Patch count / options just changed → refresh the live name prefix
        # (no-op when it's unchanged, so this can't loop with the field's own
        # textChanged → _update_patch_count).
        self._refresh_name_prefix()

    def _rebuild_paper_combo(self) -> None:
        instr    = self._instr_combo.currentData() or "i1"
        excluded = EXCLUDED_PAPERS.get(instr, set())
        current  = self._paper_combo.currentData()

        self._paper_combo.blockSignals(True)
        self._paper_combo.clear()
        for size in PAPER_SIZES:
            if size not in excluded:
                self._paper_combo.addItem(PAPER_LABELS.get(size, size), size)
        self._paper_combo.blockSignals(False)

        target = current if current not in excluded else PAPER_FALLBACK.get(current, "A4")
        idx = self._paper_combo.findData(target)
        self._paper_combo.setCurrentIndex(max(idx, 0))
        self._update_patch_count()

    def _update_dd_visibility(self) -> None:
        instr = self._instr_combo.currentData() or "i1"
        # -h is meaningful on CM (double density via rig) and SS (hexagon
        # patches), but has different semantics → relabel and retitle.
        if instr == "CM":
            self._dd_check.setVisible(True)
            self._dd_tooltip.setVisible(True)
            self._dd_check.setText(tr("Double density"))
            self._dd_tooltip._title = tr("Double Density (-h)")
            self._dd_tooltip._body = tr(
                "Doubles the number of patches that fit in each measurement strip "
                "when using a ColorMunki / i1Studio / ColorChecker Studio.\n\n"
                "REQUIRES the physical measuring rig accessory — a clear plastic "
                "guide that mounts the instrument over the chart. Without the rig "
                "the device cannot align to the tighter patch spacing and will "
                "misread.\n\n"
                "With the rig you get roughly twice as many patches per page, "
                "which means either a more detailed profile from the same number "
                "of sheets, or the same profile quality on fewer sheets. "
                "Recommended for anyone with the rig — it's a strict upgrade on "
                "patch density.\n\n"
                "Has no effect on i1Pro, i1Pro 3 Plus or SpectroScan — the option "
                "is hidden when those are selected."
            )
            self._dd_tooltip._min_width = 600
            self._dd_tooltip.setToolTip(tr("Double Density (-h)\n\nClick for details"))
        elif instr == "CR30":
            # Same option, its own numbers and its own reasons (#159, Basti
            # 2026-08-28). Measured on this branch: A4 patch-first, 532 patches
            # rectangular against 576 hexagonal.
            self._dd_check.setVisible(True)
            self._dd_tooltip.setVisible(True)
            self._dd_check.setText(
                tr("Hexagon patches (suits the round CR30, fits more per sheet)"))
            self._dd_tooltip._title = tr("Hexagon Patches (CR30)")
            self._dd_tooltip._body = tr(
                "Switches the CR30 chart from rectangular to hexagonal "
                "patches. Rectangular is the default.\n\n"
                "The CR30 is a ROUND instrument — a 33 mm barrel reading "
                "through a 4 mm circular window — and a round window can never "
                "use the corners of a square patch. Hexagons are the tightest "
                "way to pack round openings into a sheet (90.7 % of the area "
                "is within reach of a circle, against 78.5 % for squares), so "
                "you keep the same 4 mm of clearance all round the window "
                "while each patch uses less paper. Measured on A4 at the "
                "standard size and default margins: 345 patches rectangular, "
                "405 hexagonal. The gain depends on the paper — on A3 it is "
                "much smaller.\n\n"
                "It is also reasonable to expect a honeycomb to be easier to "
                "aim at, since its six sides close in on the centre of the "
                "cell where four right angles do not. That has NOT been "
                "measured, so please do not plan around it; the packing above "
                "is what has.\n\n"
                "No extra hardware, and nothing changes about how you measure. "
                "The shape only matters to an instrument that has to travel "
                "along a row of patches, and the CR30 never does.\n\n"
                "Two costs, both real. The scanner and camera tools turn a "
                "honeycomb chart away unless you switch them on for it in "
                "Preferences → Beta; and the ruler helper markers are not "
                "drawn on a honeycomb, because it has no straight rows to line "
                "a ruler against.\n\n"
                "Has no effect on i1Pro, i1Pro 3 Plus or ColorMunki — the "
                "option is hidden when those are selected."
            )
            self._dd_tooltip._min_width = 600
            self._dd_tooltip.setToolTip(tr("Hexagon Patches (CR30)\n\nClick for details"))
        elif instr == "SS":
            self._dd_check.setVisible(True)
            self._dd_tooltip.setVisible(True)
            self._dd_check.setText(tr("Hexagon patches (packs ~15% more per sheet)"))
            self._dd_tooltip._title = tr("Hexagon Patches (-h)")
            self._dd_tooltip._body = tr(
                "Switches the SpectroScan chart layout from rectangular to "
                "hexagonal patches. Hexagons tessellate more tightly than "
                "rectangles, so roughly 14% more patches fit on the same sheet — "
                "useful for squeezing extra colour samples out of large papers.\n\n"
                "No extra hardware is required. The SpectroScan's XY scanner "
                "reads each patch individually under a motorised arm, so it "
                "doesn't care whether the patch is square or hexagonal.\n\n"
                "Has no effect on i1Pro, i1Pro 3 Plus or ColorMunki — the option "
                "is hidden when those are selected."
            )
            self._dd_tooltip._min_width = 600
            self._dd_tooltip.setToolTip(tr("Hexagon Patches (-h)\n\nClick for details"))
        else:
            self._dd_check.setVisible(False)
            self._dd_tooltip.setVisible(False)
            # Force-uncheck when hidden so the state can't leak into printtarg
            # the next time the user goes back to CM/SS without re-touching it.
            if self._dd_check.isChecked():
                self._dd_check.setChecked(False)
        # Triple density: CM-only, hidden everywhere else.
        td_visible = instr == "CM"
        self._td_check.setVisible(td_visible)
        self._td_tooltip.setVisible(td_visible)
        # "For rig:" prefix is meaningful only when both density options
        # represent the ColorMunki rig accessory. For SS the dd checkbox
        # is hexagon-patches (no rig involved) so we hide the label.
        self._for_rig_label.setVisible(instr == "CM")
        if not td_visible and self._td_check.isChecked():
            self._td_check.setChecked(False)
        # -L only affects strip instruments (i1, p3). CM reads patches
        # individually and SS is an XY flatbed — both ignore -L. Even with
        # the ChromIQ-style clipping border on, the toggle stays visible:
        # leaving it unchecked yields the branded strip; checking it
        # suppresses the border entirely and routes commands/notes to the
        # right margin as usual.
        # Triple density forces -L internally and the user can't influence
        # it — hide the row entirely in that mode.
        lb_visible = instr in {"i1", "p3"} and not self._td_check.isChecked()
        self._lb_check.setVisible(lb_visible)
        self._lb_tooltip.setVisible(lb_visible)
        # -P (no strip-length limit) is only meaningful on strip readers.
        # CM reads patches individually and SS is an XY flatbed — both
        # ignore -P. Triple density forces -P internally and the
        # checkbox would be confusing, so hide it in that mode too.
        nsl_visible = instr in {"i1", "p3"} and not self._td_check.isChecked()
        self._nsl_check.setVisible(nsl_visible)
        self._nsl_tooltip.setVisible(nsl_visible)
        if not nsl_visible and self._nsl_check.isChecked():
            self._nsl_check.setChecked(False)

    def _on_guided_dd_toggled(self, checked: bool) -> None:
        if checked and self._td_check.isChecked():
            self._td_check.setChecked(False)
        self._td_check.setEnabled(not checked)
        self._td_tooltip.setEnabled(not checked)

    def _on_guided_td_toggled(self, checked: bool) -> None:
        if checked and self._dd_check.isChecked():
            self._dd_check.setChecked(False)
        self._dd_check.setEnabled(not checked)
        self._dd_tooltip.setEnabled(not checked)
        # Triple density forces -L internally — stash the user's lb_check
        # value and force it on; restore on untoggle.
        if checked:
            self._td_saved_lb_check = self._lb_check.isChecked()
            self._lb_check.setChecked(True)
        else:
            saved = getattr(self, "_td_saved_lb_check", None)
            if saved is not None:
                self._lb_check.setChecked(bool(saved))
            self._td_saved_lb_check = None
        # -L visibility depends on td state now — refresh.
        self._update_dd_visibility()

    # ------------------------------------------------------------------
    # Actions
    # ------------------------------------------------------------------

    def _handle_target_rename(self, new_name: str) -> bool:
        """Reconcile a name change away from an already-created target.

        Returns True to proceed with generation, False only when the user
        cancels. When the user has previously generated a target this session
        and now asks for a different (not-yet-existing) folder, pops the
        rename/keep/delete chooser and performs the chosen file operation.
        """
        old_name = getattr(self, "_last_target_name", "")
        if not old_name or not new_name:
            return True
        # Both sides resolved the way the file manager resolves them — see
        # `_maybe_rename_on_edit`. The folder this window NAMES must be the
        # folder the rename or the delete then acts on.
        old_root = self._file_mgr.resolved_root_for_name(old_name)
        if old_root is None:
            return True
        new_root = self._new_project_root_beside(old_root, new_name)
        if new_root is None:
            return True
        # Same destination (e.g. only spacing/case-equivalent edit), or the old
        # target was never written to disk — nothing to reconcile.
        if new_root == old_root or not (old_root / "project.json").exists():
            return True
        # A project already occupying the new name is a different situation
        # (merge/overwrite) that this dialog doesn't cover — let the normal flow
        # handle it rather than offering a misleading "rename onto it".
        if new_root.exists():
            return True

        dlg = TargetChangeDialog(old_name, new_root.name, old_root, new_root, self)
        dlg.exec()
        action = dlg.result_action()
        if action == TargetChangeAction.CANCEL:
            return False
        if action == TargetChangeAction.RENAME:
            try:
                self._file_mgr.rename_existing_project(old_root, new_name)
            except (OSError, FileExistsError, FileNotFoundError) as exc:
                # Fall back to a fresh target rather than blocking the user.
                log.warning("Project rename failed (%s); creating fresh instead", exc)
            else:
                self._refresh_after_rename(new_name)
        elif action == TargetChangeAction.DELETE:
            self._file_mgr.delete_project_folder(old_root)
        # KEEP: leave the old folder; set_target_name creates the fresh one.
        return True

    def _refresh_after_rename(self, new_name: str) -> None:
        """Re-push the renamed run's files to every tab holding absolute paths.

        The rename moves the whole project folder and fixes the file stems, but
        the chart preview here and the Print tab still hold the OLD paths in
        memory — printing right after a rename failed with "no such file"
        (Basti, #108 batch). Best-effort: never blocks the rename itself."""
        try:
            self._file_mgr.set_target_name(new_name)
            run = self._file_mgr.project().current_run()
            tiffs = run.chart_tiffs()
            if tiffs:
                self._preview.load_tiff(tiffs)
                self.chart_finished.emit(tiffs, run.chart_ti2, False)
            self._last_target_name = new_name
        except Exception:  # noqa: BLE001 — refresh must never block the rename
            log.warning("post-rename path refresh failed", exc_info=True)

    def _patchset_missing_message(self, path) -> None:
        """M-PATCHSET-MISSING — the loaded patch set is no longer on disk.

        The text comes from the catalogue, never from here: a window that
        writes its own prose is how new wording reached users unreviewed in
        #155.
        """
        from workflow import measurement_messages as M

        m = M.M_PATCHSET_MISSING
        InfoDialog(tr(m.title), tr(m.body).format(path=path),
                   self, min_width=560).exec()

    def _name_needs_asking(self, typed: str, target_name: str | None = None) -> bool:
        """Whether this build must stop and ask for a project name.

        TWO CASES, ONE DOOR. Nothing typed and no project open — or something
        typed that a folder cannot be made from. The second half was added to
        only two of the four routes that reach a build, and the two it missed
        are the prebuilt-preset ones: typing `///` and picking a bundled chart
        built a COMPLETE project called "session" — the sanitiser's fallback —
        with no window of any kind. Exactly what `name_prompt.validate` says it
        exists to prevent. Keeping the rule in one method is what stops the next
        route from being missed too.
        """
        from ui.dialogs.name_prompt import validate
        if typed:
            return validate(typed) is not None
        return not target_name and not _is_named(self._file_mgr)

    def _ask_for_a_project_name(self) -> bool:
        """Ask for the project name, put it in the box, and say whether the
        action that needed it may now go on.

        IT USED TO BE A DEAD END. The old window explained that the name box
        was empty, named the box, told the person to type into it and then
        repeat the thing they had just done — so it closed, and the work
        happened somewhere else. Basti, 2026-08-30: *"can this pop up window
        offer me a field to directly enter the name in it and then a
        confirmation button as well plus a tooltip icon"*. It can, and every
        caller is placed early enough to carry straight on with the answer.

        Returns True when a name was given (and written into the field), False
        when the person cancelled — in which case the caller must leave
        everything exactly as it found it (#175).
        """
        from ui.dialogs.name_prompt import ask_for_project_name
        field = self._active_name_field()
        current = field.text().strip() if field is not None else ""
        name = ask_for_project_name(self, prefill=current,
                                    exists=self._project_already_exists)
        if not name:
            return False
        if field is not None:
            field.setText(name)
            field.setFocus()
        # A PERSON TYPED THIS, SO §S4.7 MUST SPEAK FOR IT.
        # `setText` never emits `textEdited`, which is the only thing that sets
        # this flag, and `_typed_project_peek` deliberately returns None for a
        # name the app put in the box. Without this line a name that already
        # belongs to another project would be accepted in silence — the very
        # fault the flag exists to prevent, rebuilt one layer down.
        self._name_typed_by_user = True
        self._refresh_project_exists_line()
        return True

    def _on_generate(self) -> None:
        """Generate Chart.

        THE WHOLE BODY IS INSIDE A `try`, for one reason: a §S4.7 answer
        belongs to ONE click. Four returns between the question and the
        point of no return — a reflected chart, a vanished patch set, the
        name prompt, and the rename chooser being cancelled — left an armed
        "Replace it" on the tab, and the next thing to reach a consumer
        acted on it: one live-preview render archived a whole project with
        no window at all, and a run choice made for one project moved
        another project's bar. Driven. A `finally` cannot be forgotten at a
        return somebody adds later.
        """
        try:
            if self._runner.is_running:
                log.warning("A process is already running")
                return
            self._log_chart_build("Generate Chart", "targen")
            self._cancel_pending_auto_preview()
            # #133: the FROM PROFILE GAMUT module has its own generate route — the
            # colours come from the master set through this run's profile, and the
            # layout from Manual via the ordinary from-.ti1 build (which asks the
            # §4 displacing-results question itself).
            if self._mode_name() == "gamut":
                self._on_generate_gamut()
                return
            # THE NAME BEFORE THE GATE. §S4.7 below compares the name in the
            # box with the projects on disk, so an empty box gives it nothing to
            # compare: it waved the build through, and the name supplied
            # afterwards was never checked against anything. A name that already
            # belonged to a project then overwrote it in silence — while typing
            # the very same name into the box asked properly. Ask first, and the
            # gate does its job on the real answer.
            # …AND A NAME THE FILESYSTEM CANNOT TAKE IS NO BETTER THAN NONE.
            # The dialog refuses one; the name BOX has no limit at all, so a
            # 250-character name reached `mkdir`, died with Errno 63 and left a
            # half-built project behind. Send it back through the same dialog,
            # pre-filled, rather than inventing a second way to say no.
            _cur = (self._target_name_edit.text().strip()
                    if self._current_mode() == "guided"
                    else self._manual_target_name_edit.text().strip())
            if self._name_needs_asking(_cur):
                if not self._ask_for_a_project_name():
                    return

            # §S4.7 FIRST — the typed name may point at a project that already
            # exists, in which case that window carries §4's answer too. Placed
            # AFTER the from-profile-gamut branch above, which asks for itself
            # further down its own route, so the question is put exactly once.
            _proceed, _s4_done = self._gate_typed_project_name()
            if not _proceed:
                return
            if not _s4_done and not self._confirm_displacing_results():
                return
            # The per-ink inspector describes the PREVIOUS chart — drop it the
            # moment a new build starts; load_tiff rebuilds it for the new chart's
            # ink set when the build lands (#72, Basti).
            self._preview.reset_ink_inspector()
            # Chart reflected from the Print/Measure tab — read-only. While nothing
            # is unlocked there is nothing to generate (the chart lives in its own
            # folder already); say so and stop. Unlocking a panel means the user
            # wants to build their own, so drop the reflection and fall through to
            # the normal fresh-chart path.
            if self._reflected_active and self._current_mode() == "manual":
                unlocked = (
                    (self._override_targen_check is not None
                     and self._override_targen_check.isChecked())
                    or (self._override_printtarg_check is not None
                        and self._override_printtarg_check.isChecked()))
                if not unlocked:
                    InfoDialog(
                        "This chart is loaded from elsewhere",
                        "This chart was opened with “Open Chart File (.ti2)” at the "
                        "top left of the window, so it's shown here just for "
                        "reference — it already lives in its own folder and there's "
                        "nothing to generate.\n\n"
                        "If you want to build your own chart from these settings, "
                        "tick “Edit patch recipe (override preset)” or “Edit page "
                        "layout (override preset)” above, make your changes, then "
                        "click “Generate Chart” — that creates a brand-new chart and "
                        "leaves the loaded one untouched.",
                        self, min_width=540,
                    ).exec()
                    return
                self._leave_reflected()
            # Chart applied from the TI2 layout editor. Mirrors the prebuilt-files
            # logic, but the source is the editor's staging folder rather than a
            # bundled asset:
            #   • targen changed   → fresh targen run (different patches): fall through
            #   • else printtarg changed → re-lay-out the staged .ti1 (same patches)
            #   • else                   → re-import the staged files verbatim
            if self._applied_active and self._applied_src_dir is not None \
                    and self._current_mode() == "manual":
                targen_changed = (self._applied_targen_sig is not None
                                  and self._targen_signature() != self._applied_targen_sig)
                printtarg_changed = (self._applied_printtarg_sig is not None
                                     and self._printtarg_signature() != self._applied_printtarg_sig)
                if targen_changed:
                    # User unlocked the recipe — drop the applied binding and build a
                    # fresh chart from the current settings (fall through below).
                    self._leave_applied()
                elif printtarg_changed:
                    self._generate_from_ti1(
                        self._applied_src_dir / f"{self._applied_stem}.ti1",
                        ask=False)
                    return
                else:
                    self._import_applied_chart(gate_already_asked=True)
                    return
            # Prebuilt-files preset. By default nothing is computed — the bundled
            # files are copied verbatim. But the user can unlock the panels:
            #   • targen changed   → fresh targen run (different patches): fall through
            #   • else printtarg changed → re-lay-out the bundled .ti1 (same patches)
            #   • else                   → copy the bundled files (exact original)
            if self._prebuilt_active and self._prebuilt_key is not None \
                    and self._current_mode() == "manual":
                targen_changed = (self._prebuilt_targen_sig is not None
                                  and self._targen_signature() != self._prebuilt_targen_sig)
                printtarg_changed = (self._prebuilt_printtarg_sig is not None
                                     and self._printtarg_signature() != self._prebuilt_printtarg_sig)
                if targen_changed:
                    # User unlocked the patch recipe and changed it — build a fresh
                    # chart from the current settings (fall through to the normal
                    # targen→printtarg path below). The preset stays selected.
                    pass
                elif printtarg_changed:
                    stem_rel = PREBUILT_PRESETS[self._prebuilt_key][0]
                    bundled_ti1 = resource_path(f"{stem_rel}.ti1")
                    self._generate_from_ti1(bundled_ti1, ask=False)
                    return
                else:
                    name = (self._manual_target_name_edit.text().strip()
                            if self._manual_target_name_edit is not None else "")
                    self._create_prebuilt_target(
                        self._prebuilt_key,
                        # `name or None` — NOT the preset's own name. Passing a
                        # default in as `target_name` told the callee that a
                        # name had been supplied, which suppressed the ask AND
                        # defeated the "an open project is the answer" guard
                        # inside it: with a preset active, clearing the box and
                        # pressing Generate built a whole project named after
                        # the preset, with no window at all — the exact fault
                        # that guard's own comment says it prevents.
                        name or None,
                        gate_already_asked=True,
                        # …and the §4 answer, which this caller had and dropped,
                        # so one Generate click with a prebuilt preset active
                        # raised the identical §4 window twice. Shipped 4.1.3
                        # does it too; it is the other half of a fix that only
                        # reached one of this route's two callers.
                        s4_already_answered=_s4_done)
                    return
            # User preset with a bundled .ti1: build from that patch set (skip targen,
            # lay it out with printtarg) — same path as the TC9.18 built-in. If the
            # user unlocked the targen panel and changed it, fall through to a fresh
            # targen run instead (different patches, like the built-in ti1 presets).
            # NOT GATED ON MANUAL. "Load patch set" lives in the tab HEADER, above
            # the Guided/Manual stack, so it is offered in Guided too — which is
            # where a beginner is. With the mode clause here, loading a patch set in
            # Guided and pressing Generate walked straight past this branch into a
            # fresh targen run: the user's own patches were replaced, silently, and
            # `_preset_ti1_path` was not even cleared. Driven: load in Manual →
            # from_ti1; switch to Guided, same state → fresh targen.
            if self._preset_ti1_path is not None:
                # A LOCKED PANEL CANNOT HAVE BEEN EDITED. The signature comparison
                # exists so a user who UNLOCKS the targen panel and changes a knob
                # gets the fresh chart they asked for. Without the override box
                # ticked there is no such consent, and any difference is something
                # the app did to itself — which is exactly how this fault kept
                # coming back.
                opted_in = bool(self._override_targen_check is not None
                                and self._override_targen_check.isChecked())
                targen_changed = (opted_in
                                  and self._preset_ti1_targen_sig is not None
                                  and self._targen_signature() != self._preset_ti1_targen_sig)
                if not targen_changed:
                    if self._preset_ti1_path.is_file():
                        self._generate_from_ti1(self._preset_ti1_path, ask=False)
                        return
                    # SAY SO. This wrote one line to the log and then built a
                    # completely different chart (§M M-PATCHSET-MISSING).
                    log.warning("attached preset .ti1 vanished: %s", self._preset_ti1_path)
                    self._patchset_missing_message(self._preset_ti1_path)
                    return
                else:
                    # NO SECOND WINDOW HERE, DELIBERATELY. Ticking "Edit patch
                    # recipe (override preset)" already opens a window that says
                    # exactly this — *"The moment you change a targen value, ChromIQ
                    # can no longer reuse the preset's patches … it will create a
                    # completely new set of colours from scratch"*
                    # (`_OVERRIDE_TARGEN_POPUP_BODY`, shown from
                    # `_on_override_clicked` on every real click of that box). And
                    # the box is shown for a patch set the USER loaded, not only for
                    # a built-in preset (`_ti1_preset_active` counts
                    # `_preset_ti1_path`), so there is no gap it would cover.
                    #
                    # A window here would interrupt a decision the user has already
                    # made and acknowledged. Knut, 4.1.3-beta.17: *"there is already
                    # a message when clicking the 'Edit patch recipe' warning of
                    # consequences, so it is deliberate and obvious that the chart
                    # will change … that warning should be sufficient for a user."*
                    # Checked against the existing text before removing this.
                    log.info("loaded patch set dropped: the targen recipe was "
                             "edited (the override warning was already shown)")
                    self._preset_ti1_path = None
                    self._preset_ti1_targen_sig = None
            # TC9.18 built-in preset: while it's active and the user hasn't touched
            # any targen setting, reproduce the exact bundled chart (printtarg only).
            # The OFPS patch set can't be recreated reliably by re-running targen, so
            # this is the only way to guarantee an identical target. Once a targen
            # setting changes the user has opted into a fresh chart, so fall through.
            if self._tc918_active and self._current_mode() == "manual":
                if self._targen_signature() == self._tc918_targen_sig:
                    self._generate_from_ti1(self._tc918_ti1_path(), ask=False)
                    return
                self._tc918_active = False
                self._tc918_targen_sig = None
            # Same for Knut's TC9.18+Spyderprint presets: while active and the targen
            # settings are untouched, re-lay-out the bundled 1168-patch .ti1 (printtarg
            # only). Changing a targen setting opts into a fresh targen chart.
            if self._knut_active and self._current_mode() == "manual":
                if self._targen_signature() == self._knut_targen_sig:
                    # Reuse THIS preset's own .ti1 (Full-layout-setup presets each bundle a
                    # different one); never the shared TC9.18 set (#58).
                    p = KNUT_PRESETS_BY_KEY.get(self._knut_active_key or "")
                    ti1 = (resource_path(p.ti1_asset) if p is not None
                           else self._knut_ti1_path())
                    self._generate_from_ti1(ti1, ask=False)
                    return
                self._knut_active = False
                self._knut_targen_sig = None
                self._knut_active_key = None
            name = (
                self._target_name_edit.text().strip()
                if self._current_mode() == "guided"
                else self._manual_target_name_edit.text().strip()
            )
            # A NAME IS REQUIRED — never invent one (Basti, #164 Q15).
            # `get_target_name()` below is a MUTATING getter: with nothing set it
            # makes up `Printer_Paper_Type_Instr_<timestamp>` and builds the whole
            # chart into a folder of that name, which nobody asked for and nobody
            # would find again. Only ask when no project is open — once one is,
            # emptying the field is a rename question, and `_handle_target_rename`
            # owns that.
            # Normally already answered above, before §S4.7 ran; kept as the
            # backstop for any route that reaches here another way.
            if not name and not _is_named(self._file_mgr):
                if not self._ask_for_a_project_name():
                    return
                name = (
                    self._target_name_edit.text().strip()
                    if self._current_mode() == "guided"
                    else self._manual_target_name_edit.text().strip()
                )
            # If a target was already created this session and the user has now typed
            # a different name, switching folders would orphan the old one. Ask first
            # (rename / keep both / delete old); Cancel aborts before anything clears.
            if not self._handle_target_rename(name):
                return

            # From here on this IS a build (nothing below returns without going
            # through _on_generate_finished), and everything below can fire the
            # target-switch handler — so mark it in flight before it can load the
            # run's stored layout over the one being built with. Same reasoning as
            # in _generate_from_ti1.
            self._generate_btn.setEnabled(False)
            self._layout_owned_by_build = True
            self.target_started.emit()

            # #130: remember which project we're in BEFORE the profile name is
            # applied. A build under the SAME profile name can honour the shared
            # bar's Profile-run selection (Overwrite runN / New run); a build under a
            # NEW name is its own new project (with its own run1), so the bar's
            # run selection — which refers to the previously loaded project — must
            # NOT drive it.
            _ctl = getattr(self, "_target_ctl", None)
            _proj_before = _ctl.project_or_none() if _ctl is not None else None

            params = self._collect_params()
            # Remembered for _stamp_chart_meta so the run's meta.json can carry the
            # full printtarg layout knobs (not just instrument/paper), letting the
            # TI2 editor restore a main-app chart exactly like an editor-saved one.
            self._last_params = params
            # The point of no return — see `_perform_pending_replace`.
            if not self._perform_pending_replace():
                self._generate_btn.setEnabled(True)
                self._layout_owned_by_build = False
                return
            if name:
                self._file_mgr.set_target_name(name)
            self._apply_gate_run_choice()
            base_name = self._file_mgr.get_target_name()

            # Calibration vs. normal run is now expressed by params.cal_target
            # alone — it routes chart_creator to cal/ (stem "calibration") vs the
            # current run folder (stem "chart"). The project folder is always
            # base_name; the file stem no longer carries a cal_ prefix.
            # WHERE THE BUILD GOES: cal/ or the run folder. Driven by the bar's Run
            # type (#137); the old "Create chart for calibration" checkbox is kept
            # only as a fallback for a window with no bar attached, so a build can
            # never silently lose its calibration routing.
            _ctl_cal = getattr(self, "_target_ctl", None)
            if _ctl_cal is not None:
                cal_target_active = bool(
                    getattr(_ctl_cal.target, "is_calibration", bool)())
            else:
                cal_target_active = (
                    hasattr(self, "_cal_target_check")
                    and self._cal_target_check.isChecked()
                    and self._cal_target_grp.isVisible()
                )
            params.cal_target = cal_target_active
            params.target_name = base_name
            self._last_target_name = base_name

            # "Use as pre-conditioning profile" → seed a fresh run from the parent
            # before generating the refined chart. new_run() copies the parent's
            # profile.icc / measurement.ti3 into the new run as preconditioning.*
            # and makes it current, so the chart generated below lands in the new
            # run and chart_creator's external-import becomes a no-op.
            if (not cal_target_active
                    and self._preconditioning_from_dialog
                    and self._precond_parent_run_id):
                proj = self._file_mgr.project()
                if proj.has_run(self._precond_parent_run_id):
                    parent = proj.run(self._precond_parent_run_id)
                    try:
                        new_run = proj.new_run(preconditioning_from=parent)
                        params.extra_targen_args = shlex.join(
                            ["-c", str(new_run.preconditioning_icc)]
                        )
                        params.neutral_axis_from_profile = True
                    except FileNotFoundError as exc:
                        log.warning("Could not seed pre-conditioning run: %s", exc)

            # #130 (Knut): for a normal build INTO the loaded project, point the
            # current run at the shared bar's Profile-run selection so the chart
            # lands where the bar shows — Overwrite runN → runs/runN/, New run → a
            # fresh runs/runN+1/ (Run type = Verification then files it under that
            # run's verifications/ in _on_generate_finished). Skipped for
            # calibration and refinement (they chose their run above) and for a
            # build under a new name (that's a different project with its own run1).
            _same_project = self._builds_into_project(_proj_before)
            if not cal_target_active and not self._preconditioning_from_dialog \
                    and _same_project:
                self._align_current_run_to_target()
            elif not _same_project:
                self._seed_new_project_text(cal_target_active)

            # #130 (Knut bug): a verification chart must live ONLY in the run's
            # verifications/ folder — the profiling chart at the run root must
            # survive. Generating the verify chart writes <stem>.ti1/.ti2/.tif into
            # the run root (overwriting the profiling chart) before it's moved into
            # verifications/, so snapshot the profiling chart now and restore it in
            # _on_generate_finished after the move.
            self._verify_profiling_backup = None
            if not cal_target_active:
                self._arm_verification_snapshot()

            self._log.clear()
            self._preview.clear()
            self._generate_btn.setEnabled(False)

            # Auto patch count (manual mode only): estimate now, then proceed.
            # Live re-estimation on every settings change blocks the UI for
            # custom layouts (binary search shells out to targen/printtarg
            # via subprocess.run), so we defer to the click.
            if (self._current_mode() == "manual"
                    # A CALIBRATION CHART'S SIZE COMES FROM THE RAMP, NOT THE PAGES.
                    # Belt and braces beside the UI state: the Auto boxes are
                    # already off and disabled while Run type = Calibration, and
                    # this guard keeps the built command right even if some future
                    # path reaches Generate with Auto still on. Without it the
                    # command preview (which reads the disabled -f widget and
                    # prints -f0) and the real build disagree in silence — which is
                    # exactly how #137 D7 went unnoticed.
                    and not cal_target_active
                    and self._manual_auto_patches_check is not None
                    and self._manual_auto_patches_check.isChecked()):
                self._log.appendPlainText("Calculating patch count…")
                self._log.ensureCursorVisible()
                from PyQt6.QtCore import QEventLoop
                from PyQt6.QtWidgets import QApplication

                # The binary-search path (custom layouts not in the patch DB)
                # shells out to targen/printtarg synchronously per step, blocking
                # this thread. Repaint the log after each progress line so the user
                # sees step-by-step progress instead of a frozen window / beach
                # ball. ExcludeUserInputEvents stops queued clicks/keys from
                # re-entering generation mid-search.
                def _estimate_progress(line: str) -> None:
                    self._on_log_line(line)
                    QApplication.processEvents(
                        QEventLoop.ProcessEventsFlag.ExcludeUserInputEvents
                    )

                QApplication.processEvents()
                try:
                    params.patches = self._creator.estimate_patches(
                        params, progress_cb=_estimate_progress
                    )
                except Exception as exc:
                    log.error("Auto patch estimation failed: %s", exc)
                    self._log.appendPlainText(f"Auto patch estimation failed: {exc}")
                    self._generate_btn.setEnabled(True)
                    # DROP THE SHIELD ON THE WAY OUT.
                    # `_layout_owned_by_build` tells the per-target loader that the rows
                    # on screen belong to the build, not to the target — and it is
                    # cleared only when a build FINISHES. Leaving it up on an early
                    # return means the next target the user selects never receives its
                    # own settings, and the next write files the previous run's values
                    # onto it (§4 S8; the F3 corruption the comment in
                    # `_apply_ui_state` warns about). Reproduced on screen: a refused
                    # Generate in a run with a 17 mm margin, one click to Calibration,
                    # and the calibration screen showed 17 mm.
                    self._layout_owned_by_build = False
                    return
                self._log.appendPlainText(f"Auto patch count: {params.patches}")
                # Now that the real patch count is known, recompute any Auto
                # -e/-B/-g from it (the preview used a cheap patch_db estimate).
                self._apply_auto_neutrals(params, use_estimate=True)

            # Pre-flight: targen exits with code 1 ("Must have some single or multi
            # dimensional RGB or CMY steps") if -f is 0 and no -g / -s / -c steps
            # provide patches either. Catch this before launching the subprocess so
            # the user sees an actionable message instead of a cryptic exit code.
            if (self._current_mode() == "manual"
                    and params.patches <= 0
                    and params.grey_steps <= 0
                    and params.single_channel_steps <= 0
                    and not _extra_args_have_patch_source(params.extra_targen_args)):
                self._log.appendPlainText(
                    "[ERROR] Nothing for targen to generate.\n"
                    "        Set a non-zero Total Patch Count (-f), enable the Auto checkbox,\n"
                    "        or set Grey Axis Steps (-g) / Single Channel Steps (-s) to a positive value."
                )
                self._log.ensureCursorVisible()
                self._generate_btn.setEnabled(True)
                # DROP THE SHIELD ON THE WAY OUT.
                # `_layout_owned_by_build` tells the per-target loader that the rows
                # on screen belong to the build, not to the target — and it is
                # cleared only when a build FINISHES. Leaving it up on an early
                # return means the next target the user selects never receives its
                # own settings, and the next write files the previous run's values
                # onto it (§4 S8; the F3 corruption the comment in
                # `_apply_ui_state` warns about). Reproduced on screen: a refused
                # Generate in a run with a 17 mm margin, one click to Calibration,
                # and the calibration screen showed 17 mm.
                self._layout_owned_by_build = False
                return

            # Arm the slow-chart watchdog: only this path runs targen (the tool
            # that can hit the OFPS hang). printtarg-only paths (load .ti1,
            # re-layout, prebuilt copy) are always fast and don't arm it.
            self._cancelled_by_user = False
            self._progress_line_active = False
            self._slow_watchdog.start(_SLOW_CHART_WATCHDOG_MS)
            self._creator.generate(
                params,
                on_line=self._on_log_line,
                on_finish=self._on_generate_finished,
            )

        # ------------------------------------------------------------------
        # Slow-chart watchdog (targen OFPS-cliff escape hatch)
        # ------------------------------------------------------------------
        finally:
            self._forget_gate_answer()
    def _on_slow_watchdog(self) -> None:
        """Fired when a chart generate has run past the watchdog threshold.

        Offers the user wait / rebuild-faster / cancel. The user must decide
        again on every slow generate — the choice is never remembered."""
        if not self._runner.is_running:
            return  # finished in the gap before the timer fired
        from ui.dialogs.slow_chart_dialog import SlowChartDialog

        dlg = SlowChartDialog(self.window())
        self._slow_dialog = dlg
        choice = dlg.exec()       # nested loop; targen keeps running behind it
        self._slow_dialog = None

        # targen may have finished (or been swapped out) while the dialog was
        # open — _on_generate_finished closes the dialog in that case, so bail.
        if not self._runner.is_running:
            return

        if choice == SlowChartDialog.FAST:
            self._log.appendPlainText(
                tr("Switching to the faster patch layout and rebuilding the chart…")
            )
            self._log.ensureCursorVisible()
            if not self._creator.restart_with_fast_sampler():
                self._cancel_generation()
        elif choice == SlowChartDialog.CANCEL:
            self._cancel_generation()
        else:
            # Keep waiting: re-arm so the user can change their mind later.
            self._slow_watchdog.start(_SLOW_CHART_WATCHDOG_MS)

    def eventFilter(self, obj, event):     # noqa: N802 — Qt's name
        """Keep Stop in step with the Generate button's own state."""
        try:
            from PyQt6.QtCore import QEvent
            if obj is getattr(self, "_generate_btn", None) \
                    and event.type() == QEvent.Type.EnabledChange:
                self._show_stop_button(self._chart_build_in_flight())
        except Exception:      # noqa: BLE001 — an event filter must never raise
            log.debug("could not refresh the Stop button", exc_info=True)
        return super().eventFilter(obj, event)

    def _on_stop_clicked(self) -> None:
        """The Stop button beside Generate Chart."""
        self._log.appendPlainText(tr(
            "Stopping. The chart that was here before is being put back, so "
            "nothing is lost."))
        self._log.ensureCursorVisible()
        self._cancel_generation()

    def _show_stop_button(self, running: bool) -> None:
        """Show Stop exactly while a chart build is in flight."""
        btn = getattr(self, "_stop_btn", None)
        if btn is not None:
            btn.setVisible(bool(running))
            btn.setEnabled(bool(running))

    def _cancel_generation(self) -> None:
        self._cancelled_by_user = True
        self._creator.cancel()

    def _ti1_load_destination(self, src: Path) -> "str | None":
        """Ask where a loaded patch set's chart should be built (#130).

        Returns ``"into"`` (lay it into the currently loaded profile project, so
        Create Chart writes it per the Profile-run bar), ``"into_replace"``,
        ``"into_new"``, ``"into_chart"`` (swap the chart only, #130), ``"new"``
        (start a new project named after the file), or ``None`` (Cancel). With no
        project loaded there is nothing to choose → ``"new"`` without a dialog."""
        from core.measurement_target import (RUN_TYPE_VERIFICATION)
        from ui.ti2_loader import _choice_dialog
        # Whether the patch set brought its layout settings along decides what
        # "replace only the chart" can promise, so the answer is worked out once
        # and stated in the option's own text.
        _has_sidecar = ti1_sidecar(src) is not None
        ctl = getattr(self, "_target_ctl", None)
        proj = ctl.project_or_none() if ctl is not None else None
        if proj is None:
            return "new"
        # Describe the bar so the user knows exactly where "into this project"
        # would put the chart.
        t = ctl.target
        run_id = t.profile_run
        if run_id and proj.has_run(run_id):
            where = tr("overwrite <b>{run}</b>").format(run=run_id)
        else:
            where = tr("a new run")
        rtype = (tr("Verification") if t.run_type == RUN_TYPE_VERIFICATION
                 else tr("Profiling"))
        pname = proj.root.name
        intro = tr(
            "You loaded the patch set <b>{file}</b>.<br><br>"
            "A profile project is open: <b>{project}</b>. Where should the chart "
            "these patches make be built?"
        ).format(file=src.name, project=pname)
        into_desc = tr(
            "Keep working in <b>{project}</b>. When you click <b>Create Chart</b>, "
            "the patches are laid out and saved into this project — following the "
            "Profile-run bar (Run type = <b>{rtype}</b>, {where}). Nothing is "
            "overwritten until you actually create the chart."
        ).format(project=pname, rtype=rtype, where=where)
        new_desc = tr(
            "Start a fresh profile project from these patches. You'll be asked "
            "for the project name (pre-filled as <b>{name}</b> — change it or "
            "keep it). The current project <b>{project}</b> is left untouched; "
            "the new project gets its own folder and its own run 1."
        ).format(name=self._file_mgr.strip_workfile_ext(src.stem), project=pname)
        # #130 §3 (Model B): building into a run that already holds work is a
        # Replace — say so, and offer a new run instead, before anything moves.
        if self._run_has_work_to_displace(proj, run_id):
            from ui.ti2_loader import _run_label
            # Friendly label ("run 1") in prose and on the button; the raw folder
            # id only inside the <code> paths, so both read naturally.
            label = _run_label(t)
            if t.run_type == RUN_TYPE_VERIFICATION:
                replace_desc = tr(
                    "Build the chart as <b>{label}</b>'s verification chart. The "
                    "verification chart that is there now moves to "
                    "<code>runs/{run}/verifications/old/</code> first — nothing "
                    "is deleted — and the new chart is saved in "
                    "<code>runs/{run}/verifications/</code>. Your dated "
                    "verification results are kept, and so are this run's own "
                    "chart, measurement and printer profile."
                ).format(label=label, run=run_id)
            else:
                replace_desc = tr(
                    "Build the chart into <b>{label}</b>. That run's current "
                    "chart, measurement and printer profile — together with "
                    "every folder inside it, including its reports and "
                    "verifications — move to <code>runs/{run}/old/</code> first, "
                    "and the new chart is saved in <code>runs/{run}/</code>. "
                    "Nothing is deleted. Everything moves because a new chart no "
                    "longer matches the measurement, profile or checks made from "
                    "the old one."
                ).format(label=label, run=run_id)
            new_run_desc = tr(
                "Build the chart in a brand-new run of <b>{project}</b> instead, "
                "so everything in <b>{run}</b> stays exactly as it is. The "
                "Profile-run bar moves to the new run."
            ).format(project=pname, run=label)
            # #130 (Knut, 2026-07-27): a fourth way — swap ONLY the chart and
            # leave everything else in the run standing. His reading (b): it is
            # a convenience that can also serve as a repair tool, and the user
            # must be warned about the consequence, because whether the incoming
            # patch set matches the measurement already in the run is a judgement
            # only a person can make.
            chart_only_desc = tr(
                "Swap the chart in <b>{label}</b> and leave everything else "
                "standing: the measurement, the profile, the reports and the "
                "verifications stay put, and nothing moves to <code>old/</code>. "
                "<b>ChromIQ cannot check that these patches are the ones your "
                "measurement was taken with</b> — only you can, and if they are "
                "not, the run keeps a measurement that no longer matches its "
                "chart. {sidecar}"
            ).format(label=label, sidecar=(
                tr("The chart's settings file was found beside it, so the sheet "
                   "is laid out exactly as it was.")
                if _has_sidecar else
                tr("No chart settings file was found beside it, so only the "
                   "patches are replaced and the settings now on screen decide "
                   "the layout.")))
            return _choice_dialog(
                self, tr("Where should this patch set's chart go?"), intro,
                [(tr("Replace {run}").format(run=label), replace_desc,
                  "into_replace"),
                 (tr("Build it as a new run instead"), new_run_desc, "into_new"),
                 (tr("Replace only the chart"), chart_only_desc, "into_chart"),
                 (tr("Start a new project"), new_desc, "new")],
            )
        return _choice_dialog(
            self, tr("Where should this patch set's chart go?"), intro,
            [(tr("Add to this project"), into_desc, "into"),
             (tr("Start a new project"), new_desc, "new")],
        )

    def _run_has_work_to_displace(self, proj, run_id: str) -> bool:
        """Whether building into *run_id* is an **Overwrite** of an existing run,
        and must therefore offer New-vs-Replace first (#130 §3).

        Knut's ruling of 2026-07-25 — "Always ask on an Overwrite run" — makes
        this a question about the run's existence, not its contents: any build
        into a run the user already has asks first, even when that run holds
        only a chart. Only "New run" proceeds without the question, because
        there is nothing there to displace.
        """
        return bool(run_id) and proj is not None and proj.has_run(run_id)

    def _on_load_ti1(self) -> None:
        path = open_file_dialog(
            self, "Load patch set",
            "Patch sets (*.ti1 *.pxf *.cgats *.txt)",
            extra_path=self._settings.get("custom_output_path", ""),
            declutter_settings=self._settings,
        )
        if not path:
            return
        src = Path(path)
        self._log.clear()
        from workflow.ti2_relayout import NO_RECIPE
        # THE SLOT DESCRIBES A DESIGN, AND THIS IS A DIFFERENT PATCH SET.
        # Whatever preset was selected before, its recipe does not describe the
        # file just loaded — and leaving it here stamps that preset's design
        # onto this chart as though it had built it (#164, Knut).
        self._pending_editor_recipe = NO_RECIPE

        # A native Argyll .ti1 already carries real colorimetry, so it's used
        # as-is. Anything else is treated as an i1Profiler RGB patch set
        # (.pxf / CGATS .txt) and converted to a .ti1 first — reconstructing
        # approximate XYZ so printtarg can lay it out (see
        # workflow/i1profiler_import). CMYK / parse errors raise ValueError.
        if src.suffix.lower() == ".ti1":
            ti1 = src
        else:
            try:
                # A LIST, not a single attribute. Each converted patch set
                # stays reachable through `_preset_ti1_path` until the user
                # loads something else or builds, so the folder must outlive
                # the NEXT load. Holding one holder meant the second load
                # dropped the first, its finalizer deleted the folder, and
                # `_preset_ti1_path` was left pointing at a file that no longer
                # existed — after which Generate logged one line and silently
                # built a fresh targen chart instead of the patch set the user
                # had loaded.
                #
                # THAT SYMPTOM HAS A SECOND, INDEPENDENT CAUSE, STILL OPEN.
                # `_preset_ti1_targen_sig` is snapshotted BEFORE
                # `_reset_override_checks()` / `_update_preset_locks()` change
                # what the targen widgets report (-e/-B go 0 -> 4), so
                # `_on_generate` sees `targen_changed` and drops the patch set
                # anyway — measured at HEAD and here alike: 2 patches in, 525
                # out, no dialog. Keeping the folder alive is necessary and not
                # sufficient; do not read this comment as saying the user-facing
                # fault is gone.
                if not hasattr(self, "_import_tmps"):
                    self._import_tmps = []
                holder = tempfile.TemporaryDirectory(prefix="chromiq_import_")
                self._import_tmps.append(holder)
                # BOUNDED. Append-only kept every converted patch set for the
                # life of the app, and main.py exits via os._exit() so the
                # finalizers never run at quit either. Two are enough: the one
                # `_preset_ti1_path` points into, and the one before it, which
                # a load that fails part-way may still be referencing.
                del self._import_tmps[:-2]
                tmp_dir = Path(holder.name)
                ti1, n = import_to_ti1(src, tmp_dir / f"{src.stem}.ti1")
            except ValueError as exc:
                InfoDialog(
                    "Couldn't read that patch set",
                    f"{exc}\n\nLoad an Argyll .ti1, or an i1Profiler RGB patch "
                    "set (a .pxf or a CGATS .txt). CMYK and extended-gamut "
                    "sets aren't supported.",
                    self, min_width=520,
                ).exec()
                return
            self._log.appendPlainText(
                f"Converted {src.name} to .ti1 ({n} patches)."
            )

        # A loaded patch set supplies its own fixed colorimetry, so it's built by
        # printtarg only — targen is skipped, exactly like a user preset that
        # bundled a .ti1. Point Generate at the loaded file and snapshot the
        # targen controls so the override box can still opt into a fresh targen
        # run; clear any other preset binding that was active.
        self._tc918_active = False
        self._tc918_targen_sig = None
        self._knut_active = False
        self._knut_targen_sig = None
        if self._prebuilt_active:
            self._leave_prebuilt()
        if self._applied_active:
            self._leave_applied()
        if self._reflected_active:
            self._leave_reflected()
        self._preset_ti1_path = ti1
        # THE SAME SHIELD THE OTHER TWO PRESET FAMILIES RAISE (#164).
        # Binding the patch set lands the Profile-run bar on a run, and on
        # "New run" that is a change of run — which resets every per-target row
        # to its factory value. targen's `-e`/`-B` go 0 → 4, this signature
        # stops matching, and Generate quietly rebuilds through targen instead
        # of laying out the patches the user loaded: measured, 2 patches in and
        # 525 out, with no dialog. `_apply_prebuilt_preset` and
        # `_apply_knut_preset` already raise this flag and say why; the load
        # path was the third family, and was missed.
        self._layout_owned_by_build = True
        self._preset_ti1_targen_sig = self._targen_signature()
        # Grey the targen panel (printtarg stays editable) so the loaded patch
        # set can't be silently overwritten by a stray targen run, and so
        # "Generate Chart" re-lays the same patches with the new printtarg knobs.
        self._reset_override_checks()
        self._update_preset_locks()
        # #130: where should the laid-out chart go? If a profile project is loaded,
        # ask — the patches can go INTO that project (Create Chart then writes them
        # per the Profile-run bar: Overwrite run N, or a new run), or start their
        # own new project named after the file. With no project loaded there's
        # nothing to disambiguate, so the file's own name seeds a new project.
        dest = self._ti1_load_destination(src)
        if dest is None:                       # Cancel — load nothing
            self._preset_ti1_path = None
            self._abandon_ti1_load()
            return
        if dest == "new":
            # Bug 4 (Knut): starting a new project from a patch set must let the
            # user confirm or change the name (pre-filled from the file, like
            # creating any new profile project), then actually LOAD it — show the
            # new name in the "Printer profile project name" field.
            from ui.ti2_loader import _ask_project_name
            # ASSIGN, TEST, THEN UNPACK — in that order. `_ask_project_name`
            # answers None when the person cancels, and unpacking that raises
            # `TypeError` before the guard below is ever reached. This is a Qt
            # slot, so the exception did not merely lose the load: PyQt hands it
            # to `sys.excepthook` and calls `qFatal()`, and ChromIQ ABORTED.
            # Measured through the real button, exit 134 (SIGABRT), on the
            # plainest journey there is — no project open, Load patch set, pick
            # a file, press Cancel. Shipped in every release since 2026-07-24.
            _picked = _ask_project_name(
                self, self._file_mgr.strip_workfile_ext(src.stem),
                self._file_mgr.root_dir())
            # Cancel answers None. The empty-name case cannot escape the
            # dialog either (`_accept` refuses it), but both are checked, so
            # neither shape can reach `start_new_project` with no name at all.
            if _picked is None or not (_picked[0] or "").strip():
                self._preset_ti1_path = None
                self._abandon_ti1_load()
                return
            name, _replace = _picked
            self._file_mgr.start_new_project(name)
            self._update_name_fields()
        else:
            # #130 (Knut K3): building INTO the open project must follow the
            # Profile-run bar — Overwrite run N → that run, New run → a fresh one
            # — instead of always using the project's current run, which quietly
            # built the chart into a different run than the bar showed.
            if dest == "into_new":
                # The user chose a fresh run over replacing the selected one.
                ctl = getattr(self, "_target_ctl", None)
                if ctl is not None:
                    ctl.set_profile_run("")            # "New run"
            self._align_current_run_to_target()
            # §4: loading a patch set into a run that already holds work is the
            # same replacement the Generate Chart button makes, so it asks the
            # same question. Knut, beta.125: *"Step 3 in test, but now loading a
            # ti1 file from button in Create Chart. Preview updates, but no
            # message comes. Bug again."* Both destinations that land on an
            # existing run are covered — "replace the run" and "replace only the
            # chart" — because either one leaves the measurement describing
            # patches that are no longer on the sheet.
            if dest in ("into_replace", "into_chart") \
                    and not self._confirm_displacing_results():
                self._preset_ti1_path = None
                self._abandon_ti1_load()
                return
            if dest == "into_replace":
                # #130 §5a/§5b: a Replace archives what it displaces — the same
                # rule, and the same helper, as a Print/Measure chart import.
                self._archive_run_for_replace()
        # "Replace only the chart" (#130, Knut 2026-07-27): the run keeps its
        # measurement and profile, and — when the patch set brought its settings
        # file along — the sheet is laid out exactly as that file describes,
        # seed included, so a chart put back this way is the chart it was.
        chart_only = dest == "into_chart"
        if chart_only:
            sidecar = ti1_sidecar(ti1) or ti1_sidecar(src)
            if sidecar is not None:
                self._apply_loaded_chart_settings(sidecar)
        # Run type = Verification lays the chart down at the run root before it
        # is filed under verifications/ — keep the run's profiling chart.
        self._arm_verification_snapshot()
        params = self._collect_params()
        self._preview.clear()
        self._generate_btn.setEnabled(False)
        self._creator.load_ti1_and_generate_preview(
            ti1, params,
            on_line=self._on_log_line,
            on_finish=self._on_generate_finished,
            keep_results=chart_only,
        )

    def _on_log_line(self, line: str) -> None:
        # Collapse targen's "Added N/M" seeding spam into one live percentage.
        matches = _TARGEN_ADDED_RE.findall(line)
        if matches:
            done, total = int(matches[-1][0]), int(matches[-1][1])
            pct = int(done * 100 / total) if total else 0
            self._set_progress_line(
                tr("Arranging colour patches: {pct}%").format(pct=pct)
            )
            return
        self._progress_line_active = False
        self._log.appendPlainText(line)
        self._log.ensureCursorVisible()

    def _set_progress_line(self, text: str) -> None:
        """Show ``text`` as the log's last line, replacing it in place if the
        previous line was already a progress line (so the percentage ticks up
        without scrolling hundreds of lines past)."""
        from PyQt6.QtGui import QTextCursor

        if self._progress_line_active:
            cur = self._log.textCursor()
            cur.movePosition(QTextCursor.MoveOperation.End)
            cur.select(QTextCursor.SelectionType.LineUnderCursor)
            cur.removeSelectedText()
            cur.insertText(text)
            self._log.setTextCursor(cur)
        else:
            self._log.appendPlainText(text)
            self._progress_line_active = True
        self._log.ensureCursorVisible()

    def _is_isis_selected(self) -> bool:
        """Read the instrument from the *active* mode's selector.

        i1iSis is intentionally absent from the Guided combo, so this only
        returns True from Manual mode in practice — but consulting the active
        selector keeps the check robust if that ever changes.
        """
        if self._current_mode() == "guided":
            code = (self._instr_combo.currentData() or "") if hasattr(self, "_instr_combo") else ""
        else:
            code = (self._manual_instr_pw.get_raw_value() or "") if self._manual_instr_pw else ""
        return code == "isis"

    def _update_isis_preview_banner(self) -> None:
        # The instrument signal can fire before _build_ui finishes constructing
        # the preview pane (during _make_manual_panel). Guard accordingly.
        if getattr(self, "_preview", None) is None:
            return
        if self._is_isis_selected():
            self._preview.set_banner(tr(
                "Layout preview only — i1Profiler will lay out the actual chart "
                "from the patch list when you load the .pxf, so the printed "
                "chart will look different from what's shown here."
            ))
        else:
            self._preview.set_banner(None)

    def _export_for_i1profiler_and_notify(
        self, work_dir: Path, stem: str, preview_available: bool
    ) -> bool:
        """Convert the TI1 to .txt + .pxf and show the i1Profiler hand-off popup.

        Returns True if the export succeeded (so the caller can suppress the
        generic "chart generation failed" path when printtarg crashed but the
        TI1 from targen is still usable).
        """
        ti1 = work_dir / f"{stem}.ti1"
        if not ti1.is_file():
            self._log.appendPlainText(
                f"[i1iSis] expected TI1 not found: {ti1}; skipping i1Profiler export."
            )
            return False
        try:
            target = parse_ti1(ti1)
            project = self._file_mgr.project()
            exports_dir = project.ensure_exports_dir()
            # Project-named export so the file is self-identifying when handed
            # to i1Profiler (e.g. printer-test-file-i1profiler.pxf).
            base_name = f"{project.current_run().stem}-i1profiler"
            txt_path, pxf_path = export_from_ti1(
                ti1, exports_dir, base_name=base_name,
                also_shuffled=self._settings.get("export_shuffled_pxf", False))
        except Exception as exc:  # noqa: BLE001
            log.exception("i1Profiler export failed")
            self._log.appendPlainText(f"[i1iSis] export failed: {exc}")
            InfoDialog(
                "i1Profiler export failed",
                f"ChromIQ could not write the i1Profiler patch-set files:\n\n{exc}",
                self,
                min_width=520,
            ).exec()
            return False

        if txt_path is not None:
            self._log.appendPlainText(f"[i1iSis] wrote {txt_path.name}")
        self._log.appendPlainText(f"[i1iSis] wrote {pxf_path.name}")
        if self._settings.get("export_shuffled_pxf", False):
            shuf = pxf_path.with_name(f"{pxf_path.stem}-shuffled.pxf")
            if shuf.is_file():
                self._log.appendPlainText(f"[i1iSis] wrote {shuf.name} (shuffled)")

        # Colorspace label for the popup. i1Profiler does not read the colour
        # space from the patch set — the user must select it in the workflow —
        # so spell out which one this chart is for.
        if target.kind == "RGB":
            cs_label = "RGB"
        elif target.kind == "CMYK":
            cs_label = "CMYK"
        else:
            cs_label = f"CMYK + {len(target.extras)}"

        files_lines = [
            f"  • {pxf_path.name}   (recommended — i1Profiler's native format)"
        ]
        if txt_path is not None:
            files_lines.append(f"  • {txt_path.name}   (CGATS text, as a fallback)")
        files_block = "\n".join(files_lines)

        steps = [
            "Connect your i1iSis and open i1Profiler.",
            "On the start screen, choose Advanced User Mode.",
            "In the menu on the left, under Printer, click Profiling.",
        ]
        if target.kind != "RGB":
            ink_note = ""
            if target.extras:
                inks = ", ".join(EXTRA_INK[c][0] for c in target.extras)
                ink_note = f", and define the {len(target.extras)} extra inks ({inks})"
            steps.append(
                f'Set the printer colour space to "{cs_label}" first — i1Profiler '
                f"does not read it from the file, so you must choose it here"
                f"{ink_note}."
            )
        steps.append(
            "In the Patch Set window, click Load and select the .pxf file above. "
            "Leave i1Profiler's Smart patch generator alone afterwards — changing "
            "its patch count or Scramble option replaces the loaded patches with "
            "freshly generated ones."
        )
        steps.append(
            "Continue through i1Profiler's wizard — it will lay out and print the "
            "chart, then ask you to scan it on the i1iSis and build the ICC profile."
        )
        steps_block = "\n".join(f"  {i}. {s}" for i, s in enumerate(steps, 1))

        preview_note = (
            "\n\nNote on the preview shown to the right: it is ChromIQ's own "
            "layout, meant only as a sanity check of the patches. The actual "
            "chart that gets printed will be laid out by i1Profiler and will "
            "look different."
            if preview_available else
            "\n\nNote: ChromIQ couldn't render a layout preview for this run, "
            "but the patch-set files above are still valid — i1Profiler builds "
            "its own layout from them, so the missing preview doesn't affect "
            "the workflow."
        )
        file_word = "file was" if txt_path is None else "files were"
        body = (
            f"Your {cs_label} chart is ready for i1Profiler. The following "
            f"{file_word} saved next to the chart:\n\n"
            f"{files_block}\n\n"
            f"Folder:  {work_dir}\n\n"
            f"Next steps in i1Profiler:\n"
            f"{steps_block}\n\n"
            f"ChromIQ's Print, Measure and Profile tabs are not used for this "
            f"instrument — the rest of the workflow happens entirely in i1Profiler."
            f"{preview_note}"
        )
        InfoDialog(
            "Next steps in i1Profiler",
            body,
            self,
            min_width=620,
        ).exec()
        return True

    def set_target_controller(self, controller) -> None:
        """Receive the shared Profile-run / Run-type controller (#130) so a
        Verification generation is filed as the run's verify chart, and so
        switching Run type / Profile run swaps the Create-Chart tab to that
        target's own chart (settings + preview)."""
        self._target_ctl = controller
        # Know whose settings are on screen from the start, or the FIRST target
        # change has no outgoing target and writes nothing.
        try:
            self._settings_store = self._target_settings_store()
            self._settings_key = self._target_settings_key()
        except Exception:      # noqa: BLE001 — a question must not break setup
            self._settings_store = self._settings_key = None
        # Let the bar's "Location being edited" line follow the name as it is
        # typed, so it is answerable before the first chart exists (#130).
        for _f in (getattr(self, "_target_name_edit", None),
                   getattr(self, "_manual_target_name_edit", None)):
            if _f is not None:
                _f.textChanged.connect(controller.set_pending_project_name)
                controller.set_pending_project_name(_f.text())
        # The actual chart (.ti2 path) the tab currently displays. Tracking the
        # real artefact — not a (run, type) key — keeps the swap correct even
        # after a generation or reload changed the chart out from under us
        # (Knut #130 beta-2 test: switching Run type showed the wrong chart).
        self._shown_chart_ti2: "Path | None" = None
        #: (path, .ti2 mtime) of the chart on screen — see _chart_stamp.
        self._shown_chart_stamp: "tuple | None" = None
        controller.changed.connect(self._on_target_changed)
        # …and label the two text rows for the selection the bar STARTS on.
        # They were built before the controller existed, so without this the
        # opening selection — "New run", Profiling — wore whatever labels the
        # constructor guessed at, and only became right after the first change.
        self._refresh_target_text()

    def clear_loaded_project(self) -> None:
        """Forget the project this tab is showing, leaving it as at launch.

        #130 (Knut, 2026-07-29): after "Delete the whole project" the name field
        still held the deleted project's name, so the next thing that touched it
        made the folder all over again — *"After deletion of the whole project I
        was working in, the user interface must return to the starting state of
        the app, empty and no loaded project. It must not create another project
        that I did not ask for."*

        Only the identity of the project is dropped. Every chart OPTION the user
        has set — instrument, paper, patch count, layout — is deliberately left
        alone, because those are their working preferences and re-typing them
        after a delete would be its own annoyance.
        """
        self._last_target_name = ""
        self._last_shown_project_name = None
        for f in (getattr(self, "_target_name_edit", None),
                  getattr(self, "_manual_target_name_edit", None)):
            if f is None:
                continue
            if isinstance(f, PrefixLockedLineEdit):
                f.set_prefix("")
            f.clear()
        # Nothing is on screen any more: no chart, no patch list, no preview.
        self._shown_chart_ti2 = None
        self._shown_chart_stamp = None
        self._current_ti1_path = None
        self._preview.clear()
        self._log.appendPlainText(tr(
            "The project was deleted, so ChromIQ is back where it starts: no "
            "project is open. Type a name into “Printer profile project name” "
            "and create a chart to begin a new one, or press “Open Project” at "
            "the top left of the window to open one you already have."))
        # Tell Print and Measure to let go of the chart as well.
        self.chart_finished.emit([], None, False)

    # ------------------------------------------------------------------
    # #130: the run's own description, and the chart's notes
    # ------------------------------------------------------------------
    #: Every label the description row can ever carry, so the label column can
    #: be sized once for the widest of them. The row's label CHANGES at runtime
    #: — the run number moves, and Calibration drops the number entirely — and
    #: a column measured for whichever label happened to be first would clip or
    #: jump the moment the user changed Run type.
    def _run_description_tooltip(self) -> str:
        """The help for "Run N Description" — Knut reviewed this wording in the
        specification (#130 §7a) before it was built."""
        return tr(
            "Optional, and empty unless you fill it in.\n\n"
            "A project usually holds several runs, and they are easy to confuse "
            "once there are a few. This is where you say what makes this one "
            "different: the paper, the finish, the chart size, or whatever you "
            "vary. It is only a description — it does not change any file "
            "name.\n\n"
            "Many people find it easiest to settle on a pattern and stick to "
            "it. For example, with the project named for the printer, paper "
            "make, size and instrument:\n\n"
            "    Printer profile project name:  Canon_Pro1000_Hahnemuehle_A4_i1Pro\n"
            "    Run 1 Description:  PhotoRagBaryta_Glossy_Large\n"
            "    Run 2 Description:  PhotoRagBaryta_Glossy_Small\n"
            "    Run 3 Description:  PhotoRagBaryta_Matte_Large\n\n"
            "Whatever you type here is added to the end of the profile's own "
            "description in the tab where you build the profile — that tab is "
            "called “4. Build Profile”, or “4. Calibration & Profiling” when "
            "calibration options are switched on in Preferences — so the "
            "finished .icc carries it too. Unless you have written your own "
            "description there, which is never overwritten.\n\n"
            "THIS STAYS WITH THE RUN. Restoring an earlier chart with "
            "“Restore Used Chart” does not change it, because it describes the "
            "run and not the sheet of paper.")

    def _target_text_label_candidates(self) -> "list[str]":
        return [
            tr("Run {n} Description:").format(n=88),
            tr("Run {n} Chart Notes:").format(n=88),
            tr("Verification Chart Notes:"),
            tr("Calibration Description:"),
            tr("Calibration Chart Notes:"),
        ]

    def _target_text_number(self) -> str:
        """The run number the labels name — including the one a New run will get.

        Knut, beta.144: *"when i look at 'Location being edited' that updates to
        /run N+1/ in the path, to signify the expected new run number. This could
        be done also for the labels."* So the number comes from the SAME place
        that line takes it from, ``Project._next_run_index()``, and the two can
        never disagree about which run is being described.

        Returns "" only when there is no project to count runs in — and then the
        answer is run 1, because that is what a Generate would create.
        """
        ctl = getattr(self, "_target_ctl", None)
        # "New run" is asked FIRST, and never of the store: `resolve_run` falls
        # back to the project's current run when the selection names none, so
        # asking it here labelled a New run with the number of the run that
        # already exists.
        new_run = ctl is not None and ctl.target.is_new_run()
        if not new_run:
            run = None
            try:
                run = self._target_text_store()
            except Exception:  # noqa: BLE001 — a label must never break the tab
                run = None
            # "run1" -> "1", the same derivation the bar's own dropdown uses
            # (MeasurementTargetBar._pretty_run) so the two can never disagree
            # about what a run is called.
            rid = getattr(run, "id", "") if run is not None else ""
            if isinstance(rid, str) and rid.startswith("run") and rid[3:]:
                return rid[3:]
        # The run that does not exist yet. Asked of project_or_none, never
        # project(), because a label must not conjure a project into being just
        # by being drawn.
        try:
            project = ctl.project_or_none() if ctl is not None else None
            if project is not None:
                return str(project._next_run_index())
        except Exception:      # noqa: BLE001
            pass
        return "1"

    def _target_text_labels(self) -> "tuple[str, str]":
        """``(description label, notes label)`` for what the bar points at.

        Knut set these out in full (#130, beta.144 report). Each of the three
        run types edits a DIFFERENT chart, so the notes label names the chart it
        belongs to, while the description belongs to the run or to the
        calibration:

        | Profile run | Run type | Description | Chart Notes |
        |---|---|---|---|
        | run N | Profiling | Run N Description: | Run N Chart Notes: |
        | New run | Profiling | Run N+1 Description: | Run N+1 Chart Notes: |
        | run N | Verification | Run N Description: | Verification Chart Notes: |
        | New run | Verification | Run N+1 Description: | Verification Chart Notes: |
        | — | Calibration | Calibration Description: | Calibration Chart Notes: |

        *"only one verification chart and we know it is for the run it belongs
        to"* — which is why the verification notes carry no run number, and why
        a New run says N+1 rather than "New run": the folder line above it
        already says ``/run N+1/``.
        """
        ctl = getattr(self, "_target_ctl", None)
        if ctl is not None and ctl.target.is_calibration():
            return tr("Calibration Description:"), tr("Calibration Chart Notes:")
        number = self._target_text_number()
        desc = tr("Run {n} Description:").format(n=number)
        if ctl is not None and ctl.target.is_verification():
            return desc, tr("Verification Chart Notes:")
        return desc, tr("Run {n} Chart Notes:").format(n=number)

    # ------------------------------------------------------------------
    # Per-target settings (#130 §2/§3) — the store, not the chart's record
    # ------------------------------------------------------------------
    def _target_own_snapshot(self) -> "tuple | None":
        """The parameters and UI state as the TARGET's own store just set them.

        Taken immediately after `load_target_settings`, before the chart
        sidecar has been anywhere near the screen.
        """
        try:
            from workflow.per_target_settings import snapshot
            return snapshot(self), self._collect_ui_state()
        except Exception:          # noqa: BLE001 — never lose a target change
            log.debug("could not snapshot the target's own settings",
                      exc_info=True)
            return None

    def _note_what_the_chart_imposed(self) -> None:
        """Record the values the chart sidecar changed, and what they replaced.

        Only the difference is kept, and only for a TARGET CHANGE. An explicit
        Restore Used Chart (§2 L5) is the case §10 blesses, and it does not
        come through here, so its values still reach the store as before.
        """
        was = getattr(self, "_own_values_before_chart", None)
        self._own_values_before_chart = None
        self._chart_imposed = {}
        self._release_imposed_connections()
        now = self._target_own_snapshot()
        if not was or not now:
            return
        (was_params, was_ui), (now_params, now_ui) = was, now
        moved = {k: (was_params.get(k), v) for k, v in now_params.items()
                 if k in was_params and was_params[k] != v}
        # PER FIELD, NOT PER BUCKET. `engine_recipe` is one key holding the
        # WHOLE layout recipe -- both indicator checkboxes, the margins, the
        # mode -- so shielding it as one lump means an unrelated edit releases
        # all of it. Measured after the first version of this: untick "show
        # strip indicators" on run 1, visit run 2, come back, nudge the top
        # margin by 1 mm, leave the tab, and the checkbox is back on in the
        # store. The margin and the checkbox are not the same decision, and
        # they must not share a fate.
        moved_ui = {}
        for k, v in now_ui.items():
            if k not in was_ui or was_ui[k] == v:
                continue
            before = was_ui[k]
            if isinstance(before, dict) and isinstance(v, dict):
                fields = {f: (before.get(f), nv) for f, nv in v.items()
                          if f in before and before[f] != nv}
                if fields:
                    moved_ui[k] = {"fields": fields}
            # A SCALAR UI VALUE IS NOT THE SIDECAR'S TO KEEP.
            #
            # `engine_recipe` is the chart's recipe and is what this shield is
            # for. The other UI keys -- `mode`, `stamp`, `engine_on` -- are
            # owned by controls OUTSIDE the layout panel, so no signal here can
            # tell that the user (or the app) has moved one, and the only
            # release left was "its value differs from what the chart put
            # there". `ui:mode` never differs, so it was shielded for ever:
            # opening a VERIFICATION target, where the app itself selects the
            # Gamut module, wrote `manual` back over that choice and the target
            # reopened in the wrong module. Measured A/B against the commit
            # before the shield existed. They are simply not shielded.
        if not (moved or moved_ui):
            return
        self._chart_imposed = {"params": moved, "ui": moved_ui}
        log.debug("the chart sidecar moved %d parameters and %d ui values "
                  "away from the target's own", len(moved), len(moved_ui))
        # AND FROM NOW ON, WHOEVER TOUCHES ONE OWNS IT.
        #
        # The first version of this decided at write time, by comparing the
        # widget with the value the sidecar had put there: equal meant
        # "untouched". That is the same mistake as a name box believing its
        # own prefill -- a user who deliberately picks the value the chart
        # suggested is indistinguishable from one who left it alone, and
        # their choice was silently replaced by the older stored value. The
        # acceptance driver caught it on two targets within a minute of the
        # disk verdict being restored.
        #
        # So provenance is taken from the signal instead: the moment a row
        # reports a change AFTER this point, it stops being the sidecar's and
        # is written normally.
        self._release_imposed_connections()
        from workflow.per_target_settings import params_for
        try:
            for param in params_for(self):
                if param.key not in moved:
                    continue
                for w in param.widgets:
                    sig = getattr(w, "value_changed", None)
                    if sig is None:
                        continue
                    slot = (lambda key=param.key:
                            self._chart_imposed.get("params", {}).pop(key, None))
                    sig.connect(slot)
                    self._imposed_connections.append((sig, slot))
            panel = getattr(self, "_manual_layout_panel", None)
            sig = getattr(panel, "changed", None) if panel is not None else None
            if sig is not None and moved_ui:
                # NOT `.clear()`. That released every UI value the chart had
                # imposed the moment ANY control on the panel moved -- which
                # is how one nudge of the top margin handed the strip-
                # indicator checkbox back to the sidecar.
                sig.connect(self._release_ui_values_that_moved)
                self._imposed_connections.append(
                    (sig, self._release_ui_values_that_moved))
        except Exception:          # noqa: BLE001 — a shield is never fatal
            log.debug("could not watch the imposed rows", exc_info=True)

    def _release_ui_values_that_moved(self) -> None:
        """Whatever the user just changed on the panel is theirs from now on.

        Only what MOVED: the panel emits one signal for every control it owns,
        so anything coarser hands back values nobody touched.
        """
        imposed = (getattr(self, "_chart_imposed", None) or {}).get("ui")
        if not imposed:
            return
        try:
            now = self._collect_ui_state() or {}
        except Exception:          # noqa: BLE001 — a shield is never fatal
            return
        for key, entry in list(imposed.items()):
            if isinstance(entry, dict) and "fields" in entry:
                have = now.get(key)
                if not isinstance(have, dict):
                    continue
                for field, (_own, from_chart) in list(entry["fields"].items()):
                    if field in have and have[field] != from_chart:
                        entry["fields"].pop(field, None)
                if not entry["fields"]:
                    imposed.pop(key, None)


    def _release_imposed_connections(self) -> None:
        """Drop the watchers from the previous target change."""
        for sig, slot in getattr(self, "_imposed_connections", []):
            try:
                sig.disconnect(slot)
            except (TypeError, RuntimeError):
                pass               # already gone with its widget
        self._imposed_connections = []

    def _keep_the_targets_own_values(self, wanted: dict, ui_state: dict) -> None:
        """Put back anything the chart sidecar imposed and the user left alone.

        A row that has reported a change since the chart imposed its value has
        already been struck off the list; anything left is checked against the
        value the sidecar put there as well, so a change nothing reported is
        still the user's.
        """
        imposed = getattr(self, "_chart_imposed", None)
        if not imposed:
            return
        # TWO CONDITIONS, AND BOTH MUST HOLD. A row is only still the
        # sidecar's if nothing has reported a change (the list below) AND it
        # still holds the value the sidecar put there.
        #
        # Neither test is sufficient alone. Equality alone believes its own
        # prefill: a user who deliberately picks the value the chart suggested
        # looks identical to one who left it alone, and the acceptance driver
        # caught exactly that on two targets. The signal alone misses anything
        # changed through a control this does not watch -- `ui:stamp` lives
        # outside the layout panel, was shielded after it had genuinely moved,
        # and the driver caught that one too, on the very next run.
        for key, (own, from_chart) in list(imposed.get("params", {}).items()):
            if key in wanted and wanted[key] == from_chart:
                wanted[key] = own
        for key, entry in list(imposed.get("ui", {}).items()):
            # Only the recipe's own fields; see `_note_what_the_chart_imposed`.
            if not (isinstance(entry, dict) and "fields" in entry):
                continue
            have = ui_state.get(key)
            if not isinstance(have, dict):
                continue
            for field, (own, from_chart) in entry["fields"].items():
                if field in have and have[field] == from_chart:
                    have[field] = own

    def save_target_settings(self, store=_NO_STORE_GIVEN,
                             key=_NO_STORE_GIVEN) -> bool:
        """Write this tab's settings into the selected target's ``meta.json``.

        Called on every event in §3 that belongs to Create Chart: Generate
        Chart, a preset/`.ti1`/`.ti2` being loaded, and **leaving the tab** —
        which includes a target change and app quit.

        Scoped to the one selected target (§2.0): it writes where
        ``_target_text_store()`` points and nowhere else, the same rule the two
        text fields already follow. Returns whether anything was written, so a
        caller can tell "nothing to write yet" from "written".
        """
        if getattr(self, "_loading_target_settings", False):
            return False
        # An explicit store is how a TARGET CHANGE writes the OUTGOING target.
        # By the time the bar reports the change, _target_text_store() already
        # points at the new one — so writing "the current target" there would
        # record the old target's edits onto the new one, which is precisely
        # the failure this whole feature exists to prevent (§2.1, test N1).
        if store is _NO_STORE_GIVEN:
            store = self._target_settings_store()
        if store is None:
            # A NEW RUN HAS NO FILE YET — HOLD IT, DO NOT DROP IT.
            #
            # Knut's rule is that values are written "when changing tabs or
            # 'Profile run' or 'Run type'", and a New run has nowhere to be
            # written until Generate Chart creates it. The tab already solves
            # this for the description fields the same way (`_new_run_text`,
            # his beta.147 report).
            #
            # Filed under the OUTGOING key: `_target_settings_key()` reads the
            # live selection, which by now is the incoming target.
            seed = self._new_run_seed_path()
            # A WRITE MUST NEVER BRING A DELETED PROJECT BACK.
            #
            # mkdir would recreate the whole tree, and "leaving a tab" and
            # "quitting" both fire right after a delete. Knut's beta.102
            # sequence caught this on the main write; the New-run block is a
            # second writer and needed the same guard.
            if seed is None or not seed.parent.parent.is_dir():
                return False
            from workflow.per_target_settings import snapshot
            try:
                import json as _json
                seed.parent.mkdir(parents=True, exist_ok=True)
                from core.file_manager import write_json_atomically
                write_json_atomically(seed, snapshot(self))
                return True
            except Exception:      # noqa: BLE001 — never lose the tab over it
                log.warning("Could not keep the New run's settings",
                            exc_info=True)
            return False
        # A WRITE MUST NEVER BRING A DELETED PROJECT BACK.
        #
        # save_meta() creates what it needs, so writing to a target whose
        # folder has gone recreates it — and "leaving a tab" and "quitting"
        # both fire right after a delete. Knut's beta.102 sequence (delete the
        # whole project, expect it gone) caught this the moment the events were
        # wired: the folder came straight back with a meta.json in it.
        # _target_text_store's own docstring warns about exactly this.
        try:
            if not Path(getattr(store, "dir", "")).is_dir():
                return False
        except (TypeError, ValueError):
            return False
        try:
            from workflow.per_target_settings import snapshot
            wanted = snapshot(self)
            if not wanted:
                return False
            # NOTHING CHANGED SINCE THE LAST WRITE → DO NOTHING AT ALL.
            #
            # Knut, #130 (2026-08-06): *"A write trigger should also have a
            # check if any settings have changed since last write, preventing
            # multiple writes in a row if user is going back and forth on the
            # profile run and run type input boxes."*
            #
            # The write trigger is the pulldown OPENING, so flicking between
            # the two boxes fires it repeatedly. Remembering the last snapshot
            # per target means a repeat costs nothing — not even the read of
            # meta.json that the disk comparison below needs.
            #
            # Safe because ChromIQ is the only writer of this key while the
            # project is open; the disk comparison stays as the backstop for
            # the first write after a load, when there is nothing remembered.
            # §4a N-1: SEED THE NEW-RUN BLOCK FROM THIS TARGET, ONCE.
            #
            # Done here because this runs on the pulldown-open trigger, while
            # the loaded target is still the selected one — the only moment its
            # settings are the ones on screen. Only when the block does not
            # already exist: re-seeding on every click would overwrite the
            # user's own New-run setup the moment they flicked to another run
            # and back, silently.
            self._seed_new_run_block(store, wanted)
            # The non-parameter controls travel in the same write (Knut's
            # beta.3 bug-test): module, Guided shared settings, engine
            # toggle + recipe, gamut options. Part of the dirty check, or a
            # ui-only change would never reach the file.
            ui_state = self._collect_ui_state()
            # THE CHART'S OWN VALUES ARE NOT THE TARGET'S (K3/K4). Whatever
            # the sidecar is allowed to SHOW, it may not be filed into the
            # store on the user's behalf; only a value they then changed is.
            #
            # Reached through `getattr` because `save_target_settings` is
            # deliberately liftable: the store tests run it on a stand-in that
            # implements only what the STORE needs, and a hard call turned
            # every one of them into "could not save" -- the broad except
            # below swallowed the AttributeError and returned False.
            keep = getattr(self, "_keep_the_targets_own_values", None)
            if keep is not None:
                keep(wanted, ui_state)
            fingerprint = str(getattr(store, "dir", store))
            if self._written_cache().get(fingerprint) == (wanted, ui_state):
                return False
            meta = store.load_meta()
            if (getattr(meta, "create_chart_settings", None) == wanted
                    and getattr(meta, "create_chart_ui", None) == ui_state):
                self._written_cache()[fingerprint] = (wanted, ui_state)
                return False       # nothing changed; don't churn the file
            meta.create_chart_settings = wanted
            if hasattr(meta, "create_chart_ui"):
                meta.create_chart_ui = ui_state
            store.save_meta(meta)
            self._written_cache()[fingerprint] = (wanted, ui_state)
            log.debug("create-chart settings written for %s (%d parameters "
                      "+ ui state)",
                      getattr(store, "id", store), len(wanted))
            return True
        except Exception:      # noqa: BLE001 — never lose the tab over a write
            log.warning("Could not save the target's Create Chart settings",
                        exc_info=True)
            return False

    def _open_this_target_on_its_defaults(self) -> None:
        """§4 S4-S7: a target with nothing stored opens on its OWN defaults.

        It used to be done in one of the two "nothing stored" branches and not
        the other. A run whose `meta.json` does not exist yet — which is every
        brand-new run — took the other branch and simply returned, so the
        previous run's layout stayed on screen and was then written into the
        new run's store as though the user had chosen it. §4 S4 is explicit:
        *"factory settings, or the saved defaults — never the last run's."*
        """
        ctl = getattr(self, "_target_ctl", None)
        on_calibration = bool(
            ctl is not None
            and getattr(ctl.target, "is_calibration", bool)())
        owned_by_calibration = (
            {(tool, flag) for tool, flag, _v in self._CAL_VALUES}
            if on_calibration else set())
        self._loading_target_settings = True
        try:
            from workflow.per_target_settings import params_for
            # NOT WHEN THE BUILD ON SCREEN OWNS THESE ROWS.
            #
            # Loading a built-in preset builds its own .ti1 and then lands
            # the bar on the new run — and on a FRESH project that is a
            # change of run, so this fires. It reset targen's rows to their
            # factory values, which for “Total Patch Count (-f)” is ZERO;
            # the preset's own signature no longer matched, so the next
            # Generate abandoned the preset's patch set, fell through to
            # targen and hit the pre-flight guard: "Nothing for targen to
            # generate" against an untouched “Edit patch recipe” checkbox
            # (Knut, #164). Worse on the prebuilt-file presets, where Auto
            # is on and it silently built a DIFFERENT chart — TC3.00's 300
            # patches came out as 504, with no warning at all.
            #
            # `_apply_ui_state` already refuses to overwrite build-owned
            # rows for the same reason (see `built_here` below).
            if getattr(self, "_layout_owned_by_build", False):
                raise _SkipReset
            for prm in params_for(self):
                if (prm.tool, prm.flag) in owned_by_calibration:
                    continue
                for w in prm.widgets:
                    w.reset_to_default()
        except _SkipReset:
            pass
        except Exception:      # noqa: BLE001
            log.warning("Could not reset the rows to their defaults",
                        exc_info=True)
        finally:
            self._loading_target_settings = False
        # A target with nothing stored must not inherit the previous
        # run's engine calibration from the screen either (Sebastian's
        # beta.5 check 3): an empty ui-state applies exactly the
        # engine-calibration neutral default and nothing else.
        self._loading_target_settings = True
        try:
            self._apply_ui_state({})
            # …NOR ITS LAYOUT RECIPE. `_apply_ui_state({})` resets the
            # engine-calibration block and the parameter rows above reset
            # themselves, but the layout panel held whatever the last run put
            # there — so a brand-new run opened on the previous run's
            # instrument, mode and indicator checkboxes and then STORED them,
            # permanently, as though the user had chosen them. Measured: run 1
            # holds a CR30 chart, select run 2 (fresh), and the panel and
            # run 2's `meta.json` both say CR30 (§4 S4: "factory settings, or
            # the saved defaults — never the last run's").
            #
            # `_init_manual_layout_panel` IS that rule: the "Save as Defaults"
            # recipe if there is one, otherwise the active preset for the
            # selection. It is what a first-ever chart opens on.
            #
            # NOT WHEN A BUILD ON SCREEN OWNS THE LAYOUT — §3 W2, NOT §4 S4.
            #
            # Applying a built-in preset seeds the layout panel with the
            # preset's own recipe and then builds it, which creates the run and
            # lands the bar on it — a target change, so this method runs while
            # that run's store is still empty. The parameter rows above already
            # skip for the flag, and `_apply_ui_state` raises the same shield
            # for the engine recipe and the Guided row; these two lines were the
            # one place that escaped it, and they re-seeded the panel from the
            # saved defaults. Measured on the ColorMunki 84-patch built-in:
            # paper A4R -> A4, margins 8/4 -> 6/11.1, minimum patch size
            # 4.0 -> 0.0, layout mode area_first -> patch_first. The chart on
            # disk was still the preset's; the panel was not, so W1's write at
            # the end of the build filed the RESET values as the run's own and
            # a second Generate laid the same patches out differently.
            #
            # §4 S4 is not what governs a preset-made target: §3 W2 says a
            # preset load writes that target's Create Chart settings, and §6.5
            # says a preset "still loads into the panels; W2 then records it for
            # the target". A target the preset just made has its settings — they
            # are on screen, on their way to the store. "Nothing stored" is true
            # of the file for a few hundred milliseconds and false of the
            # target. With the flag clear (every genuine fresh run) this is
            # unchanged, and `_on_target_changed` clears it right after the load.
            if (getattr(self, "_manual_layout_panel", None) is not None
                    and not getattr(self, "_layout_owned_by_build", False)):
                try:
                    # The panel's own instrument/paper/mode are the LAST run's
                    # too, and `_init_manual_layout_panel` reads them to pick
                    # which preset to seed from — so it has to be told the
                    # freshly-reset printtarg selection first, or it seeds the
                    # defaults for the wrong instrument.
                    self._sync_engine_panel_selection()
                    self._init_manual_layout_panel()
                except Exception:      # noqa: BLE001 — never block a load
                    log.warning("Could not open the layout panel on its "
                                "defaults", exc_info=True)
        finally:
            self._loading_target_settings = False

    def load_target_settings(self) -> bool:
        """Put the selected target's stored settings on screen (§2 L1).

        **Guarded against triggering a rebuild.** Filling the rows fires their
        ``changed`` signals, and with auto-update on that would redraw the chart
        — possibly over a measured one (§7 B). ``_loading_target_settings``
        holds the writers off for the duration, the way
        ``_loading_target_text`` already does for the two text fields.

        A target with nothing stored is left exactly as it is rather than being
        reset here: §4 says it opens on the saved defaults or the factory ones,
        and that is the panels' own job, not this one's.
        """
        store = self._target_settings_store()
        if store is None:
            seed = self._new_run_seed_path()
            held = None
            if seed is not None and seed.is_file():
                try:
                    import json as _json
                    held = _json.loads(read_text(seed))
                except Exception:      # noqa: BLE001 — a bad block is not fatal
                    log.warning("Could not read %s; the New run starts clean",
                                seed, exc_info=True)
            if not held:
                # NOT RESET HERE. `store is None` is "this target has no file
                # to read", which is also true of a target with no project at
                # all — and resetting there wipes values the person has just
                # typed with nowhere to have stored them (the calibration
                # run-type snapshot, `test_a_hand_set_value_comes_back`). The
                # leak §4 S4 is about comes in through the branch below, where
                # a store EXISTS and holds nothing.
                return False
            self._settings_store = None
            self._settings_key = self._target_settings_key()
            self._loading_target_settings = True
            try:
                from workflow.per_target_settings import apply
                apply(self, held)
                return True
            finally:
                self._loading_target_settings = False
        try:
            stored = getattr(store.load_meta(), "create_chart_settings", None)
        except Exception:      # noqa: BLE001
            log.warning("Could not read the target's Create Chart settings",
                        exc_info=True)
            return False
        if not stored:
            # §4 S4–S7: A TARGET WITH NOTHING STORED OPENS ON ITS DEFAULTS —
            # EXCEPT THE ROWS RUN TYPE = CALIBRATION ALREADY OWNS.
            #
            # Two people's rules meet here. Knut asked for "open on defaults"
            # (#130). Sebastian asked, on 2026-08-05, that Run type =
            # Calibration force its own values onto a handful of rows and
            # *"then also be reset to how it was before when the user sets
            # another runtype again"* — `_pre_cal_snapshot` and
            # `_apply_calibration_knobs`.
            #
            # They collide only on the six rows in `_CAL_VALUES` — and only
            # WHILE THE CALIBRATION IS THE SELECTED TARGET (F3, ruled
            # 2026-08-11: a setting's owner is the selected target). There the
            # knobs have just set the calibration's values and resetting them
            # would wipe them; on a run, skipping them was how the
            # calibration's patch count followed the user into the next run
            # they visited — a run with nothing stored opens on ALL its
            # defaults, six rows included (§4 S4/S5).
            self._settings_store = store
            self._settings_key = self._target_settings_key()
            self._open_this_target_on_its_defaults()
            return False
        # REMEMBER WHOSE SETTINGS ARE NOW ON SCREEN.
        #
        # Set here rather than only at the end of _on_target_changed, because
        # the FIRST target change would otherwise have no outgoing store to
        # write — and driving it on screen showed exactly that: the edit made
        # on run 1 was lost, and run 2 was written instead. §2.1/N1.
        self._settings_store = store
        self._loading_target_settings = True
        try:
            from workflow.per_target_settings import apply
            unknown = apply(self, stored)
            if unknown:
                # A chart made before a parameter was renamed or removed must
                # still open (§7 A) — say so in the log, never refuse to load.
                log.info("ignored %d unknown stored setting(s): %s",
                         len(unknown), ", ".join(sorted(unknown)[:8]))
            # The non-parameter controls follow in the same load (Knut's
            # beta.3 bug-test): module, Guided shared settings, engine
            # toggle + recipe, gamut options.
            try:
                ui_state = getattr(store.load_meta(), "create_chart_ui", None)
                # An EMPTY dict must still be applied: _apply_ui_state resets
                # the engine calibration to its neutral state for a target
                # that has never recorded one — skipping it left the previous
                # run's calibration on screen, and the next write filed it
                # (Sebastian's beta.5 check 3).
                if isinstance(ui_state, dict):
                    self._apply_ui_state(ui_state)
            except Exception:      # noqa: BLE001
                log.warning("Could not apply the target's Create Chart ui "
                            "state", exc_info=True)
            return True
        except Exception:      # noqa: BLE001
            log.warning("Could not apply the target's Create Chart settings",
                        exc_info=True)
            return False
        finally:
            self._loading_target_settings = False

    #: The last snapshot written for each target, so a repeated write trigger
    #: costs nothing. See save_target_settings.
    #:
    #: Reached through `_written_cache()`, never directly: as a bare class
    #: attribute every tab shared ONE dict, so a second tab (or a second test)
    #: inherited the first one's "already written" marks and had its writes
    #: silently skipped.
    _last_written: dict = {}

    def _written_cache(self) -> dict:
        """This tab's own record of what it last wrote."""
        if "_last_written" not in self.__dict__:
            self._last_written = {}
        return self._last_written

    #: Settings for targets with no file yet, keyed by (profile run, run type).
    #: Class-level default, replaced on first write, so a duck-typed caller
    #: never trips over a missing attribute.
    _pending_settings: dict = {}

    def _seed_new_run_block(self, store, snapshot_now: dict) -> None:
        """Copy this target's settings into the New-run block if it has none.

        §4a N-1 and N-2: seeded once, with the six rows Run type = Calibration
        owns stripped out, so a New run never starts from a calibration
        sheet's patch set.

        A CALIBRATION IS NOT A STARTING POINT FOR A RUN.

        Knut, 2026-08-08: the New-run seeding *"should only work for profiling
        and verification runs"*. Stripping the six ``_CALIBRATION_OWNED`` rows
        was not enough on its own — driven on screen, selecting Run type =
        Calibration still wrote a ``cal/cache/new_run.json`` carrying **34**
        other rows (paper, instrument, margins, the whole layout recipe), any
        of which a later New run would have started from.

        The block is written once and then left alone (N-1), so whether a
        particular value actually leaked depended on *when* the block happened
        to be written. That is why this is guarded structurally rather than by
        widening the strip list: a rule that holds only depending on timing is
        not a rule.
        """
        folder = getattr(store, "dir", None)
        if folder is None:
            return
        # ASK THE STORE, NOT THE SELECTION.
        #
        # This runs for the OUTGOING target while the bar already points at the
        # incoming one, so asking the controller answers about the wrong
        # target — the same trap that produced three separate faults in the
        # per-target settings work, and it made the first version of this guard
        # pass its unit test while still writing the file on screen. The store
        # IS the calibration or it is not, whatever the bar says.
        from core.file_manager import Calibration
        if isinstance(store, Calibration):
            return
        self._new_run_seed_dir = folder
        try:
            from workflow.per_target_settings import (NEW_RUN_FILENAME,
                                                      seed_for_new_run)
            seed = Path(folder) / "cache" / NEW_RUN_FILENAME
            if not Path(folder).is_dir():
                return                      # deleted; do not recreate it
            if seed.exists():
                return                      # it is the user's now (N-1)
            from core.file_manager import write_json_atomically
            write_json_atomically(seed, seed_for_new_run(snapshot_now))
        except Exception:      # noqa: BLE001 — a seed is never worth a crash
            log.warning("Could not seed the New run's settings", exc_info=True)

    def _adopt_new_run_settings(self, new_run) -> bool:
        """Give the freshly created run the settings chosen for "New run".

        §4a N-3. The block was the specification for this run; now the run
        exists, it becomes the run's own settings and the block is cleared.
        """
        seed = self._new_run_seed_path()
        if seed is None or not seed.is_file():
            return False
        try:
            import json as _json
            held = _json.loads(read_text(seed))
        except Exception:      # noqa: BLE001
            log.warning("Could not read %s when creating %s", seed,
                        getattr(new_run, "id", new_run), exc_info=True)
            self.clear_new_run_block()
            return False
        try:
            if held:
                meta = new_run.load_meta()
                meta.create_chart_settings = held
                new_run.save_meta(meta)
                log.info("New run %s adopted %d stored setting(s)",
                         getattr(new_run, "id", new_run), len(held))
        except Exception:      # noqa: BLE001 — never fail a build over this
            log.warning("Could not give %s its New-run settings",
                        getattr(new_run, "id", new_run), exc_info=True)
            return False
        finally:
            self.clear_new_run_block()
        return True

    def clear_new_run_block(self) -> bool:
        """Drop the New-run block once Generate Chart has consumed it (N-3).

        Without this the run *after* next starts from a stale copy instead of
        from the run actually loaded.
        """
        seed = self._new_run_seed_path()
        self._new_run_seed_dir = None
        if seed is None or not seed.is_file():
            return False
        try:
            seed.unlink()
            return True
        except OSError:
            log.warning("Could not remove %s", seed, exc_info=True)
            return False

    def _new_run_seed_path(self):
        """``<seed target>/cache/new_run.json``, or None if there is nowhere.

        Knut, #130 §4a N-4: the block lives in the ``cache/`` folder of the
        target it was seeded from. ``_new_run_seed_dir`` remembers which that
        was; after a restart it is forgotten and the block is simply orphaned,
        which costs nothing because ``cache/`` is always safe to delete.
        """
        folder = getattr(self, "_new_run_seed_dir", None)
        if folder is None:
            return None
        from workflow.per_target_settings import NEW_RUN_FILENAME
        return Path(folder) / "cache" / NEW_RUN_FILENAME

    def _target_settings_key(self) -> "tuple | None":
        """A stable name for the selected target, for the no-file-yet case."""
        ctl = getattr(self, "_target_ctl", None)
        if ctl is None:
            return None
        try:
            return (ctl.target.profile_run, ctl.target.run_type)
        except Exception:      # noqa: BLE001 — a question must not raise
            return None

    def per_target_widgets(self) -> "dict[str, list]":
        """The parameter rows that belong to the target, not the installation.

        Specification S1.1: the list is generated, never written out, so a
        parameter added to ``parameters.yaml`` cannot be left out of the store
        by omission. ``workflow.per_target_settings`` reads this, and so does
        the test harness — one answer, so the tests cannot cover a different
        set of parameters than the store does.

        Manual mode only: Guided is a way of *choosing* settings, and the rows
        it fills are the same manual rows underneath.
        """
        return {tool: list(widgets)
                for tool, widgets in getattr(self, "_manual_widgets", {}).items()}

    def _collect_ui_state(self) -> dict:
        """The Create Chart controls that are NOT parameter rows, for the
        target's ``create_chart_ui`` store (Knut's beta.3 bug-test: the
        module, Guided's shared settings, the engine toggle and recipe, and
        the gamut module's options followed the user from run to run).
        Best-effort per block: a control that cannot be read is left out
        rather than blocking the write."""
        out: dict = {"mode": self._mode_name()}
        try:
            out["stamp"] = bool(self._manual_stamp_cmd_check.isChecked())
        except Exception:      # noqa: BLE001
            pass
        try:
            out["guided"] = dict(self._shared_get("guided"))
        except Exception:      # noqa: BLE001
            pass
        try:
            out["engine_on"] = bool(
                self._settings.get("use_chromiq_layout_engine", False))
            rec = self._manual_layout_panel.get_recipe()
            if rec is not None:
                out["engine_recipe"] = rec.to_dict()
        except Exception:      # noqa: BLE001
            pass
        try:
            # The engine panel's Printer calibration controls are NOT part of
            # its recipe — without their own record they followed the user
            # from run to run (Sebastian's beta.5 check 3). Raw widget state,
            # so "Include" and "Off with a path still typed" stay distinct.
            panel = self._manual_layout_panel
            out["engine_cal"] = {
                "path": (panel.cal_path_edit.text().strip()
                         if panel.cal_path_edit is not None else ""),
                "mode": (panel.cal_mode.currentData()
                         if panel.cal_mode is not None else "off"),
            }
        except Exception:      # noqa: BLE001
            pass
        try:
            out["gamut"] = {
                "count": int(self._gamut_count_spin.value()),
                # WHETHER THE COUNT WAS CHOSEN, not merely what it was.
                #
                # This record is written for every target that is merely
                # visited, so the presence of "count" proves nothing — it is
                # usually the untouched global. Reading it as a choice left the
                # default in #162 disarmed on every target that already exists.
                "count_chosen": bool(getattr(self, "_gamut_count_user_set",
                                             False)),
                "auto": bool(self._gamut_auto_check.isChecked()),
                "margin": self._gamut_margin_combo.currentData(),
                "intent": self._gamut_intent_combo.currentData(),
            }
        except Exception:      # noqa: BLE001
            pass
        return out

    def _apply_ui_state(self, stored: dict) -> None:
        """Put a target's stored ``create_chart_ui`` on screen. Stale or
        unknown keys are ignored (§7 A); the run-type module rules
        (_refresh_gamut_visibility) still run afterwards and win over an
        illegal stored mode."""
        if not isinstance(stored, dict):
            return
        # IS THIS LOAD LANDING ON TOP OF A BUILD?
        #
        # Building a chart makes the run its own, and creating or re-aligning
        # that run fires the target-switch handler, which loads the run's
        # *stored* Create Chart state over the state the build just used. The
        # chart on disk is then right and the panel is wrong — and with "Update
        # the preview automatically" on, the panel wins two seconds later and
        # redraws the sheet from settings the user had left behind.
        #
        # `_chart_build_in_flight()` is deliberately NOT consulted. It reads the
        # Generate button, which on the real path is already re-enabled by the
        # time this runs (_on_generate_finished re-enables at the top, the load
        # comes 169 lines later), so it contributed nothing here — while it CAN
        # be true with no build anywhere: the gamut module with no profile
        # disables Generate indefinitely, and so does any Tools-menu Argyll job.
        # A load suppressed then is a target whose own settings never arrive,
        # which the next write files onto it — the F3 corruption, worse than the
        # fault being fixed.
        built_here = bool(getattr(self, "_layout_owned_by_build", False))
        # This target has not chosen a colour count until its record says so —
        # an empty record is applied deliberately for exactly this reason, so
        # nothing follows the user from the run they just left (#162).
        self._gamut_count_user_set = False
        # ABSENT MEANS NEUTRAL, FOR EVERY BUCKET IN THIS METHOD.
        #
        # `engine_cal` was given this treatment on its own (Sebastian's beta.5
        # check 3) and the others were not, so a record that predates a key —
        # or an empty record, which is how a target with nothing stored asks
        # for its defaults — left that control showing THE PREVIOUS RUN's
        # value, and the next write filed it as this run's own. Measured on a
        # second challenge round: Guided paper, the stamp checkbox and all four
        # gamut options each leaked from run 1 into a brand-new run 2, and the
        # Guided paper dragged the layout panel's paper with it.
        if not built_here:
            try:
                self._manual_stamp_cmd_check.setChecked(
                    bool(stored["stamp"]) if "stamp" in stored
                    else bool(self._settings.get("chart_stamp_commands", True)))
            except Exception:      # noqa: BLE001
                pass
        # The Guided row was outside the guard until 2026-08-22, when Basti hit
        # it from source, twice in a row: Guided, SpectroScan, 4x6, Generate —
        # "generated the chart but went to manual module on its own and i think
        # colormunki was still selected there". His run1 holds mode=manual,
        # guided={instrument: CM, paper: A4}, and that is what came back.
        guided = stored.get("guided")
        if isinstance(guided, dict) and built_here:
            log.debug("ui-state: kept the Guided row this build used "
                      "(the run's stored copy is the older one)")
        elif not isinstance(guided, dict) and not built_here:
            # ABSENT MEANS NEUTRAL. Its paper also drives the layout panel's
            # paper, so a run 1 set to US Letter made every later run Letter
            # too, stored as though it had been chosen.
            # EVERY FIELD THE BUCKET CARRIES, not the two that were noticed.
            # `pages`, `left_border` (-L), `no_strip_limit` (-P) and `precond`
            # leaked into a brand-new run and were written into its meta.json —
            # and a preconditioning `.ti3` path changes the targen command for
            # a run that never asked for one.
            guided = {"instrument": self._settings.get("chart_instrument", "i1"),
                      "paper": self._settings.get("chart_paper", "A4"),
                      # …from the saved defaults where there IS one, the same
                      # as instrument and paper above. Hard-coding these gave
                      # somebody with 3 pages saved a 1-page chart.
                      "pages": int(self._settings.get("chart_pages", 1) or 1),
                      "double_density": bool(
                          self._settings.get("chart_double_density", False)),
                      # No saved default exists for triple density (it is a
                      # ColorMunki-only layout, chosen per chart), so its
                      # neutral is off.
                      "triple_density": False,
                      "left_border": bool(
                          self._settings.get("chart_left_clip_info", False)),
                      "no_strip_limit": False,
                      "precond": ""}
            for fld, val in guided.items():
                try:
                    self._shared_set("guided", fld, val)
                except Exception:      # noqa: BLE001
                    log.debug("ui-state: guided %s not reset", fld)
        elif isinstance(guided, dict):
            for fld, val in guided.items():
                try:
                    self._shared_set("guided", fld, val)
                except Exception:      # noqa: BLE001
                    log.debug("ui-state: guided %s not applied", fld)
        if "engine_on" in stored and not built_here:
            try:
                on = bool(stored["engine_on"])
                self._settings.set("use_chromiq_layout_engine", on)
                self._set_engine_checked(on)
            except Exception:      # noqa: BLE001
                log.debug("ui-state: engine toggle not applied")
        rec_d = stored.get("engine_recipe")
        # NOT WHILE THAT LAYOUT IS BEING BUILT WITH. Building a chart makes the
        # run its own — creating or re-aligning it fires the target-switch
        # handler, which loads the run's *stored* Create Chart state right on top
        # of the layout the build is using. The chart on disk was then correct
        # and the panel was not, and with "Update the preview automatically" on,
        # the panel won two seconds later: Basti, 2026-08-16, picking the
        # 84-patch Hand Held preset — built at 7 columns with a 6 mm left margin,
        # replaced by a re-layout at 17 columns and 14 mm, so "same amount of
        # patches but less wide". His log named the path outright:
        #   chart build (user): chart.ti1, A4, 7x12 grid, margins … L6.0
        #   layout panel set_recipe [load_target_settings ← _apply_ui_state]  ×4
        #   chart build (live preview): …, 17x12 grid, margins … L14.0
        # A build in flight IS the newer state, so it wins here, and the next
        # write files it as the run's own. Every other stored value still loads —
        # only the layout being built with is protected.
        if isinstance(rec_d, dict) and built_here:
            log.debug("ui-state: kept the layout this build used "
                      "(the run's stored copy is the older one)")
        elif isinstance(rec_d, dict):
            try:
                import dataclasses as _dc

                from workflow.layout_engine.presets import LayoutRecipe
                names = {f.name for f in _dc.fields(LayoutRecipe)}
                rec = LayoutRecipe(
                    **{k: v for k, v in rec_d.items() if k in names})
                self._set_engine_recipe(rec)
            except Exception:      # noqa: BLE001
                log.debug("ui-state: engine recipe not applied", exc_info=True)
        elif not built_here:
            # ABSENT MEANS NEUTRAL here too, and this is the one that matters
            # most: `_adopt_new_run_settings` writes a record with
            # `create_chart_settings` present and `create_chart_ui` empty, and
            # ~40 shipped betas wrote that shape — so the panel was simply left
            # alone and the new run opened on, and stored, the previous run's
            # instrument, paper and layout mode.
            #
            # LAST of the three branches, deliberately: an `elif` earlier in
            # the chain swallows a recipe that IS present, and the panel is
            # then reset in the middle of a build that was using it.
            try:
                self._sync_engine_panel_selection()
                self._init_manual_layout_panel()
            except Exception:      # noqa: BLE001
                log.debug("ui-state: layout panel not reset", exc_info=True)
        ec = stored.get("engine_cal")
        if built_here:
            ec = None          # the build's calibration is the newer choice
        elif not isinstance(ec, dict):
            # A target stored before this key existed must not inherit the
            # previous run's calibration from the screen (Sebastian's beta.5
            # check 3: "when i chose a calibration file in run one it was the
            # same in run 2 automatically") — the panel's neutral state is
            # the honest answer for it.
            ec = {"path": "", "mode": "off"}
        # AFTER the recipe, which drives the rest of the panel — the
        # calibration controls are this target's own choice.
        if ec is not None:
            try:
                self._manual_layout_panel.set_cal(
                    str(ec.get("path") or ""), str(ec.get("mode") or "off"))
            except Exception:      # noqa: BLE001
                log.debug("ui-state: engine calibration not applied")
        gam = stored.get("gamut")
        if not isinstance(gam, dict) and not built_here:
            # …and the same for the gamut module's four options: the saved
            # defaults each control is BUILT with, so an absent record puts
            # them back exactly where a fresh tab has them.
            # NOT the count: `_gamut_count_user_set` is already cleared above,
            # and `_refresh_gamut_state` then DERIVES the count from the patch
            # count — which is a better answer than the stored default and the
            # one two tests assert. Writing 400 here overrode that derivation.
            gam = {
                "auto": bool(self._settings.get("gamut_target_auto", False)),
                "margin": str(self._settings.get("gamut_target_margin",
                                                 "safe")),
                "intent": str(self._settings.get("gamut_target_intent",
                                                 "absolute")),
            }
        if isinstance(gam, dict) and not built_here:
            try:
                if "count" in gam:
                    self._gamut_count_seeding = True
                    try:
                        self._gamut_count_spin.setValue(int(gam["count"]))
                    finally:
                        self._gamut_count_seeding = False
                # A record from before this flag existed carries a number
                # nobody chose, so it does not disarm the default (#162).
                self._gamut_count_user_set = bool(gam.get("count_chosen", False))
                if "auto" in gam:
                    self._gamut_auto_check.setChecked(bool(gam["auto"]))
                for key, combo in (("margin", self._gamut_margin_combo),
                                   ("intent", self._gamut_intent_combo)):
                    if key in gam:
                        i = combo.findData(gam[key])
                        if i >= 0:
                            combo.setCurrentIndex(i)
            except Exception:      # noqa: BLE001
                log.debug("ui-state: gamut options not applied")
        mode = stored.get("mode")
        # AND THE MODULE IS DELIBERATELY NOT RESET. A challenge round asked for
        # it — absent is applied everywhere else, so why not here — and it is
        # the one bucket where the answer is no: #162 says selecting another
        # run while a module is open leaves you in that module, and
        # `test_another_run_while_the_module_is_open_gets_its_own_default`
        # holds it. Resetting to the saved default moved the person out of the
        # gamut module mid-use, and the count then stopped deriving itself
        # because the seeding needs `_gamut_active`. A fresh run therefore
        # opens on the module you are standing in, with that module's own
        # values reset around you.
        if mode in ("guided", "manual", "gamut") and mode != self._mode_name():
            if built_here:
                # The module the chart was just built from is the newer state
                # too — moving the user out of Guided the moment his chart
                # appears is the most visible form of this fault.
                log.debug("ui-state: kept the module this build used "
                          "(stored %r is the older one)", mode)
            else:
                # A stored module IS the user's recorded choice for this target
                # — marked as such so the verification default cannot override
                # it.
                self._user_chose_module = True
                self._switch_mode(mode)

    def _target_settings_store(self):
        """Where this selection's SETTINGS are read from and written to.

        The shared resolver every storing tab uses — which, per Knut's F1
        ruling (2026-08-11), gives a Verification its own store in
        ``runs/runN/verifications/meta.json`` instead of sharing the run's.
        The two TEXT fields stay on :meth:`_target_text_store`: their spec
        (per-run description, §9 Q4) keys them by run type inside the run's
        own file, and that design is unchanged.
        """
        from workflow.per_target_settings import store_for_target
        return store_for_target(getattr(self, "_target_ctl", None))

    def _target_text_store(self):
        """Where this selection's two texts are read from and written to.

        Knut, #130 §9 Q4: **the Profile run picks the folder, the Run type picks
        the file, and exactly one file is written.** Returns the object with
        ``load_meta`` / ``save_meta``, or None when there is nowhere yet — a new
        run before it exists, or no project at all.

        **Never creates anything.** ``_target_run()`` reaches ``project()``,
        which INVENTS a project name when none is set — so asking it here would
        conjure a project back into existence the moment the user deleted one
        (Knut's beta.102 sequence). A question must not have side effects; this
        one asks ``project_or_none``.
        """
        ctl = getattr(self, "_target_ctl", None)
        if ctl is None:
            return None
        try:
            project = ctl.project_or_none()
            if project is None:
                return None
            if ctl.target.is_calibration():
                return project.calibration
            # "New run" HAS NO STORE YET, and must not borrow one.
            #
            # `resolve_run` falls back to the project's CURRENT run when the
            # selection names none, which is right for "where does a build go"
            # and wrong for "whose description is this": typing with New run
            # selected wrote silently into whichever run happened to be current,
            # and then Generate created the new run and re-read it — so the text
            # landed on the wrong run AND vanished from the screen. Knut,
            # beta.147: *"the Run Description and Run Chart Note … was cleared
            # in the newly created run 12."* Held in the fields instead, and
            # written by `_align_current_run_to_target` when the run appears.
            if ctl.target.is_new_run():
                return None
            from core.measurement_target import resolve_run
            return resolve_run(project, ctl.target)
        except Exception:      # noqa: BLE001
            return None

    def _refresh_target_text(self) -> None:
        """Re-label both rows and re-read their text for the current selection."""
        try:
            desc_label, notes_label = self._target_text_labels()
            for name in ("_manual_run_desc_lbl", "_guided_run_desc_lbl"):
                lbl = getattr(self, name, None)
                if lbl is not None:
                    lbl.setText(desc_label)
            lbl = getattr(self, "_manual_chart_notes_lbl", None)
            if lbl is not None:
                lbl.setText(notes_label)
            self._load_target_text()
        except Exception:      # noqa: BLE001 — never break the tab over a label
            log.warning("Could not refresh the run description fields",
                        exc_info=True)

    def _notes_attr(self) -> str:
        """Which of the meta's two notes fields this selection edits.

        A run has TWO charts — its own and its one verification chart — and they
        are different sheets of paper, so they keep their notes apart. The
        description is shared, because a verification belongs to the run it
        verifies (Knut, beta.150 and 2026-08-05 23:43).
        """
        ctl = getattr(self, "_target_ctl", None)
        if ctl is not None and ctl.target.is_verification():
            return "verify_chart_notes"
        return "chart_notes"

    def _load_target_text(self) -> None:
        """Fill both fields from whatever the bar points at.

        Called whenever the Profile run or the Run type changes, which is the
        whole of Knut's *"the chart notes must also be a field that is specific
        for each run"* — the storage was already per run, and nothing reloaded
        it when the selection moved.
        """
        store = self._target_text_store()
        if store is None:
            # A run that does not exist yet, or no project at all. There is
            # nothing on disk to read, so the text typed for it is held HERE —
            # and put back when the user returns to "New run". Leaving whatever
            # the last run put on screen was not enough: *"when I go back to
            # Profile run = New run the values I wrote down was NOT
            # remembered"* (Knut, beta.150).
            held = getattr(self, "_new_run_text", None)
            if held is not None:
                self._set_target_text_fields(*held)
            return
        description = notes = ""
        try:
            meta = store.load_meta()
            description = getattr(meta, "description", "") or ""
            notes = getattr(meta, self._notes_attr(), "") or ""
        except Exception:      # noqa: BLE001 — unreadable is empty, not fatal
            description = notes = ""
        self._set_target_text_fields(description, notes)

    def _set_target_text_fields(self, description: str, notes: str) -> None:
        """Put text into the fields without that looking like the user typing.

        The guard matters in both directions: the write-back is driven by the
        fields' own signals, so filling them from disk without it would save
        the value straight back into whichever run was selected next.
        """
        self._loading_target_text = True
        try:
            for edit in (getattr(self, "_manual_run_desc_edit", None),
                         getattr(self, "_guided_run_desc_edit", None)):
                if edit is not None and edit.text() != description:
                    edit.setText(description)
            edit = getattr(self, "_manual_chart_notes_edit", None)
            if edit is not None and edit.text() != notes:
                edit.setText(notes)
        finally:
            self._loading_target_text = False

    def _on_run_description_edited(self, text: str) -> None:
        """Keep the two description fields in step, and remember the text.

        Guided and Manual have separate Output frames, so the one value has two
        widgets. They are mirrored rather than left to diverge: a run has one
        description, and two boxes showing different text for it would be two
        truths for one run.
        """
        if getattr(self, "_loading_target_text", False):
            return
        self._set_target_text_fields(text, self._current_chart_notes())
        self._save_target_text()

    def _current_chart_notes(self) -> str:
        edit = getattr(self, "_manual_chart_notes_edit", None)
        return edit.text() if edit is not None else ""

    def _current_run_description(self) -> str:
        for name in ("_manual_run_desc_edit", "_guided_run_desc_edit"):
            edit = getattr(self, name, None)
            if edit is not None:
                return edit.text()
        return ""

    def _persist_restored_chart_notes(self, notes: str) -> None:
        """Make the restored chart's notes the working value for this target.

        Whichever of the three the bar points at — the run, the verification's
        run, or the calibration — writes to its own file and no other, the same
        rule every other write here follows.
        """
        store = self._target_text_store()
        if store is None:
            return
        try:
            attr = self._notes_attr()
            meta = store.load_meta()
            if getattr(meta, attr, "") == notes:
                return
            setattr(meta, attr, notes)
            store.save_meta(meta)
        except Exception:      # noqa: BLE001 — never lose the tab over a write
            log.warning("Could not save the restored chart notes", exc_info=True)

    def _seed_new_project_text(self, cal_target_active: bool) -> None:
        """Give the fields' text a home in the project a Generate just claimed.

        THE FIRST GENERATE OF A NEW PROJECT IS "NEW RUN" IN DISGUISE (Knut +
        Sebastian, 2026-08-13). The description and chart notes typed before
        this moment had nowhere to live — no project existed — so they were
        held in the fields (beta.147's rule). Creating the project here gives
        them their home, and the write must happen before anything re-reads
        the fields from the fresh, empty ``meta.json``: that re-read is
        exactly what wiped them. The bar still says "New run" at this point,
        so the store cannot be resolved through it — it is taken from the
        project directly: its first run for a profile build, ``cal/`` for a
        calibration build.
        """
        try:
            proj_new = self._file_mgr.project()        # creates on first call
            store = (proj_new.calibration if cal_target_active
                     else proj_new.current_run())
            self._write_target_text_into(store)
            # …and the SETTINGS the chart is being built from, for the same
            # reason: run1 is born with nothing stored, and §4's "nothing
            # stored opens on its defaults" would then reset the screen the
            # moment the post-generate load arrives — Sebastian watched the
            # Guided instrument flip ColorMunki → i1Pro exactly that way
            # (2026-08-13). Generate is a §3 save event for the selected
            # target; the fresh run simply did not exist as a destination
            # until this moment.
            from workflow.per_target_settings import snapshot
            meta = store.load_meta()
            meta.create_chart_settings = snapshot(self)
            store.save_meta(meta)
            log.info("create-chart settings seeded into the new project's %s",
                     getattr(store, "id", "calibration"))
        except Exception:      # noqa: BLE001 — never block a build over text
            log.warning("Could not seed the new project's description",
                        exc_info=True)

    def _write_target_text_into(self, store) -> None:
        """Put what is on screen into ``store``'s meta, whatever is selected.

        The one place that writes without asking where the selection points, so
        a run created mid-action can be given the text that was typed for it.
        """
        if store is None:
            return
        try:
            meta = store.load_meta()
            meta.description = self._current_run_description()
            setattr(meta, self._notes_attr(), self._current_chart_notes())
            store.save_meta(meta)
            self._new_run_text = None       # it has a home now
            log.info("run description + chart notes written to %s", store.id
                     if hasattr(store, "id") else store)
        except Exception:      # noqa: BLE001 — never lose the tab over a write
            log.warning("Could not save the run's description", exc_info=True)

    def _save_target_text(self) -> None:
        """Write both texts to the ONE file this selection points at.

        Knut, #130 §9 Q4: the Profile run picks the folder and the Run type
        picks the file — never both files, because two writable copies of the
        same text is how they come to disagree.

        Silently does nothing when there is nowhere to write yet (a new run
        before it exists, or no project at all). The text stays in the fields
        and is written when the run is created, so nothing the user typed is
        lost by typing it early.
        """
        if getattr(self, "_loading_target_text", False):
            return
        description = self._current_run_description()
        notes = self._current_chart_notes()
        store = self._target_text_store()
        if store is None:
            # Held in memory until the run exists — see _load_target_text.
            self._new_run_text = (description, notes)
            return
        attr = self._notes_attr()
        try:
            meta = store.load_meta()
            if (getattr(meta, "description", "") == description
                    and getattr(meta, attr, "") == notes):
                return                      # nothing changed; do not touch disk
            meta.description = description
            setattr(meta, attr, notes)
            store.save_meta(meta)
        except Exception:      # noqa: BLE001 — never lose the tab over a write
            log.warning("Could not save the run's description", exc_info=True)

    def _target_run(self):
        """The run the BAR points at, without creating anything.

        The §4 guard used ``project.current_run()``, which is the project's own
        idea of "current" and only follows the bar when a build aligns it. Knut,
        beta.132, on Demo-08: every run he selected raised the W4 window,
        because run 5 — the one with a verification history — was still the
        project's current run. And the other way round on Demo-06 step 6, where
        W4 was due and M-CHART-PROFILING came instead.

        ``resolve_run`` is the model's own resolution, and with ``create=False``
        it never makes a run the way ``_align_current_run_to_target`` does — a
        question must not have side effects.
        """
        ctl = getattr(self, "_target_ctl", None)
        proj = self._file_mgr.project()
        if ctl is None:
            return proj.current_run()
        from core.measurement_target import resolve_run
        return resolve_run(proj, ctl.target)

    def _confirm_displacing_results(self) -> bool:
        """Ask before a new chart displaces work made with the one it replaces.

        §4 of ``docs/design/unified_measurement_management.md``. A `.ti3`
        describes one chart and a profile describes one `.ti3`, so replacing a
        chart can break a chain three links deep — measurement, profile, and the
        dated verification measurements printed *through* that profile.

        Knut, #131 2026-07-28: he read one strip of a chart, went to Create
        Chart, changed the column count and re-generated. The measurement was
        archived to ``old/`` — correctly, and without a word — so back on the
        Measure tab the run simply had no measurement any more, and he spent a
        long time thinking the checkboxes were broken.

        Nothing is ever deleted; this only makes the move visible, and only when
        there is something to move. A run with no results yet — the ordinary case
        while you are still settling on chart options — never sees it.
        """
        # ASKING MUST NOT CREATE ANYTHING. The run lookup below goes through
        # `FileManager.project()`, which resolves the working folder with the
        # mutating `get_target_name()` — so with nothing open, merely asking
        # "is anything at risk?" invented a project and wrote its manifest.
        # Nothing can be displaced when no project is open, so the honest
        # answer is "yes, go ahead".
        if not _is_named(self._file_mgr, unknown=True):
            return True
        ctl = getattr(self, "_target_ctl", None)
        # Duck-typed: several tests (and any other host) supply a target double
        # that predates the calibration run type. Asking for the attribute
        # rather than assuming it keeps them all working, and a target that
        # cannot be a calibration answers "no" — which is the honest default.
        if ctl is not None and getattr(ctl.target, "is_calibration", bool)():
            # A CALIBRATION BUILD TOUCHES cal/, NOT THE RUN (#137 D2).
            # Asking assess_profiling_chart() about the run here warned the user
            # that their measurement and profile were about to move — while the
            # build left both exactly where they were, and said nothing about
            # the calibration it really was replacing. Wrong in both directions
            # at once.
            return self._confirm_replacing_calibration()
        if ctl is not None and not ctl.target.profile_run:
            # "New run" — the build makes a fresh, empty run, so nothing at all
            # is displaced. The results belong to whichever run happened to be
            # selected before, which is not the one being built (Knut, #130
            # 2026-07-28: "this is not at all relevant for a new run that is
            # being created, so this message should not happen").
            return True
        try:
            run = self._target_run()
        except Exception:      # noqa: BLE001 — no project yet: nothing at risk
            return True

        from workflow.chart_integrity import (assess_profiling_chart,
                                              assess_verification_chart)
        if self._is_verification_target():
            cost = assess_verification_chart(run)
            if not cost.warn:
                return True
            return self._ask_chart_question(*self._verify_chart_message(cost),
                                            tr("Generate the new chart"))

        cost = assess_profiling_chart(run)
        if not cost.warn:
            return True
        return self._ask_chart_question(*self._profiling_chart_message(run, cost),
                                        tr("Generate the new chart"))

    def _ask_chart_question(self, title: str, body: str, go_label: str) -> bool:
        """One window for both §4 messages: headline, explanation, two buttons."""
        from PyQt6.QtWidgets import QMessageBox
        from ui.widgets import fit_message_box_buttons

        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.NoIcon)
        # macOS paints no title on a message box, so a window the user can name
        # is one whose title is IN it (Knut, #131 2026-07-27). The headline goes
        # in setText, which is bold, and the explanation in setInformativeText
        # at normal weight — a whole screen of bold is a wall nobody reads.
        box.setWindowTitle(title)
        box.setText(title)
        box.setInformativeText(body)
        go = box.addButton(go_label, QMessageBox.ButtonRole.AcceptRole)
        box.addButton(tr("Cancel"), QMessageBox.ButtonRole.RejectRole)
        box.setDefaultButton(go)
        # Long labels clip once the font swap widens them, and polish does not
        # happen offscreen — so fit them here (Knut, #130).
        fit_message_box_buttons(box)
        box.exec()
        return box.clickedButton() is go

    def _pages_paragraph(self, cost) -> str:
        """M-CHART-NOPAGES — §4a rows 3 and 5, appended when it applies."""
        from workflow import measurement_messages as M

        if cost.can_redraw_pages:
            return ""
        if not cost.pages:
            pages = tr(M.M_CHART_NOPAGES_NONE)
        elif cost.pages == 1:
            pages = tr(M.M_CHART_NOPAGES_ONE)
        else:
            pages = tr(M.M_CHART_NOPAGES_SOME).format(n=cost.pages)
        _title, body = M.M_CHART_NOPAGES.render(pages=pages)
        return "\n\n" + tr(M.M_CHART_NOPAGES.title) + "\n" + body

    def _corrupt_measurement_note(self, cost) -> str:
        """M-CHART-CORRUPT — §4, when the run's measurement cannot be read.

        Knut, 2026-08-04: a corrupt or empty `.ti3` is not "a measurement of 0
        patches"; it is a file the user should look at before it is archived,
        and — when a profile is there too — the moment the chain from chart to
        profile stops being describable on disk.
        """
        from workflow import measurement_messages as M

        if not (cost.has_measurement and cost.readings == 0):
            return ""
        _title, body = M.M_CHART_CORRUPT.render()
        note = "\n\n" + tr(M.M_CHART_CORRUPT.title) + "\n" + body
        if cost.has_profile:
            note += tr(M.M_CHART_CORRUPT_WITH_PROFILE)
        return note

    def _duplicate_blocked_note(self, cost) -> str:
        """M-DUPLICATE-BLOCKED — appended to any message recommending Duplicate
        when this run cannot be duplicated (§4a, §6)."""
        from workflow import measurement_messages as M

        if cost.can_duplicate:
            return ""
        return tr(M.M_DUPLICATE_BLOCKED).format(
            missing=", ".join(cost.duplicate_blocked_by))

    def _profiling_chart_message(self, run, cost) -> "tuple[str, str]":
        """M-CHART-PROFILING, or M-CHART-W4 when the run has a history.

        The text is the reviewed catalogue's (§M); this only chooses the ID and
        fills the numbers.
        """
        from workflow import measurement_messages as M
        from workflow.chart_integrity import Blast

        if cost.blast is Blast.RUN_AND_HISTORY:
            title, body = M.M_CHART_W4.render(
                c=cost.readings, v=cost.verifications, folder=str(run.old_dir))
        elif cost.has_measurement and cost.readings == 0:
            # A CORRUPT OR EMPTY MEASUREMENT GETS ITS OWN WINDOW, NOT AN
            # APPENDED PARAGRAPH.
            #
            # Knut, beta.133: *"M-CHART-CORRUPT (ONLY THIS MESSAGE as defined
            # below, and in the unified measurement management model)."* The
            # first implementation followed the model's earlier note and hung it
            # under M-CHART-PROFILING, whose {items} list then had to describe a
            # file it cannot count. With the message standing on its own there
            # is no list to fill and nothing to contradict: it says what the
            # file is, and what happens to it.
            title, body = M.M_CHART_CORRUPT.render()
            if cost.has_profile:
                body += tr(M.M_CHART_CORRUPT_WITH_PROFILE)
            return title, body + self._pages_paragraph(cost) \
                + self._duplicate_blocked_note(cost)
        else:
            items = []
            if cost.readings == 1:
                items.append(tr(M.M_CHART_ITEM_MEASUREMENT_ONE))
            elif cost.readings:
                items.append(tr(M.M_CHART_ITEM_MEASUREMENT).format(
                    c=cost.readings))
            elif cost.has_measurement:
                # §M's {items} list has no entry for a measurement whose
                # readings cannot be counted, and "a measurement of 0 patches"
                # would be false. PROPOSED — on the issue for approval.
                items.append(tr(M.M_CHART_ITEM_MEASUREMENT_UNCOUNTABLE))
            if cost.has_profile:
                items.append(tr(M.M_CHART_ITEM_PROFILE))
            title, body = M.M_CHART_PROFILING.render(
                items="\n".join(items), folder=str(run.old_dir))
        return title, body + self._corrupt_measurement_note(cost) \
            + self._pages_paragraph(cost) + self._duplicate_blocked_note(cost)

    def _verify_chart_message(self, cost) -> "tuple[str, str]":
        """M-CHART-VERIFY — §4's W5."""
        from workflow import measurement_messages as M

        title, body = M.M_CHART_VERIFY.render(v=cost.verifications)
        return title, body + self._pages_paragraph(cost) \
            + self._duplicate_blocked_note(cost)

    def _is_verification_target(self) -> bool:
        ctl = getattr(self, "_target_ctl", None)
        return ctl is not None and ctl.target.is_verification()

    # ------------------------------------------------------------------
    # #133 feature B — FROM PROFILE GAMUT: a verification chart out of the
    # colours the run's own profile claims it can print.
    # ------------------------------------------------------------------

    def _embed_gamut_module(self) -> None:
        """Build the module's own controls and slot them into the MANUAL panel
        where the targen section sits. Switching to the module hides targen
        and shows this container — everything below (printtarg / the ChromIQ
        layout engine, with every option) is Manual's own widgets, live."""
        panel = QWidget(self)
        v = QVBoxLayout(panel)
        v.setContentsMargins(0, 0, 0, 0)
        v.setSpacing(8)

        self._gamut_grp = QGroupBox(tr("Colours from this profile's gamut"),
                                    panel)
        gl = QVBoxLayout(self._gamut_grp)
        gl.setSpacing(8)

        def row(label: str, control: QWidget, tip_title: str,
                tip_body: str) -> QWidget:
            r = QWidget(self._gamut_grp)
            lay = QHBoxLayout(r)
            lay.setContentsMargins(0, 0, 0, 0)
            lay.setSpacing(10)
            text = QLabel(label, r)
            text.setMinimumWidth(120)
            lay.addWidget(text)
            lay.addWidget(control, 1)
            lay.addWidget(TooltipButton(tip_title, tip_body, r))
            return r

        count_w = QWidget(self._gamut_grp)
        cw = QHBoxLayout(count_w)
        cw.setContentsMargins(0, 0, 0, 0)
        cw.setSpacing(8)
        self._gamut_count_spin = NoScrollSpinBox(count_w)
        # The engine options' compact height (22 px, via the shared
        # #compact_input QSS — popup sizing fix included), so this section
        # reads like the layout section living right below it (Basti).
        self._gamut_count_spin.setObjectName("compact_input")
        self._gamut_count_spin.setRange(50, 5000)
        self._gamut_count_spin.setSingleStep(50)
        self._gamut_count_spin.setValue(
            int(self._settings.get("gamut_target_count", 400)))
        cw.addWidget(self._gamut_count_spin, 1)
        # "+ 8" right beside the number, so nobody is surprised that the
        # chart holds more patches than they typed (Sebastian, 2026-08-11):
        # the eight cube corners are always added on top, whatever the count.
        _plus8 = QLabel(tr("+ 8"), count_w)
        set_ink(_plus8, "#909090", level="faint")
        _plus8.setToolTip(tr(
            "The 8 cube corners — paper white, black and the six primary and "
            "secondary ink corners — are always added on top of the number "
            "you choose here, so the chart's total is this number + 8."))
        cw.addWidget(_plus8)
        # Auto (Basti, 2026-08-09): fill the number of PAGES chosen in the
        # layout section below — the same idea as Manual's Auto patch count,
        # driven by the same pages spin, which is live on this page.
        self._gamut_auto_check = QCheckBox(tr("Auto — fill the pages"),
                                           count_w)
        self._gamut_auto_check.setChecked(
            bool(self._settings.get("gamut_target_auto", False)))
        cw.addWidget(self._gamut_auto_check)
        gl.addWidget(row(tr("Colours to test"), count_w,
                         tr(_GAMUT_SIZE_HELP_TITLE), tr(_GAMUT_SIZE_HELP_BODY)))

        self._gamut_margin_combo = NoScrollComboBox(self._gamut_grp)
        self._gamut_margin_combo.setObjectName("compact_input")
        # Short enough not to elide in the 580 px panel; the ⓘ carries the
        # full explanation (Basti's screenshot, 2026-08-09).
        self._gamut_margin_combo.addItem(
            tr("Stay safely inside (recommended)"), "safe")
        self._gamut_margin_combo.addItem(
            tr("Use the full printable range"), "full")
        if str(self._settings.get("gamut_target_margin", "safe")) == "full":
            self._gamut_margin_combo.setCurrentIndex(1)
        gl.addWidget(row(tr("Margin"), self._gamut_margin_combo,
                         tr(_GAMUT_MARGIN_HELP_TITLE),
                         tr(_GAMUT_MARGIN_HELP_BODY)))

        self._gamut_intent_combo = NoScrollComboBox(self._gamut_grp)
        self._gamut_intent_combo.setObjectName("compact_input")
        self._gamut_intent_combo.addItem(
            tr("Absolute colorimetric (recommended)"), "absolute")
        self._gamut_intent_combo.addItem(
            tr("Media-relative (relative colorimetric)"), "relative")
        if str(self._settings.get("gamut_target_intent", "absolute")) == "relative":
            self._gamut_intent_combo.setCurrentIndex(1)
        gl.addWidget(row(tr("Rendering intent"), self._gamut_intent_combo,
                         tr(_GAMUT_INTENT_HELP_TITLE),
                         tr(_GAMUT_INTENT_HELP_BODY)))

        v.addWidget(self._gamut_grp)

        # The live count line sits BELOW the group, not inside it: a
        # word-wrapped label nested in a group box clips its own last lines
        # (the same trap the Print tab's notice hit).
        self._gamut_count_lbl = QLabel("", panel)
        self._gamut_count_lbl.setWordWrap(True)
        self._gamut_count_lbl.setStyleSheet(
            "color: #9a9a9a; background: transparent;"
            " margin-left: 2px; padding: 2px 0;")
        v.addWidget(self._gamut_count_lbl)

        note_row = QWidget(panel)
        nl = QHBoxLayout(note_row)
        # Right margin matches the engine-toggle row's default layout margin,
        # so the two ⓘ buttons share one right edge (Basti, 2026-08-09); the
        # small left indent matches the count line above.
        nl.setContentsMargins(2, 0, 9, 0)
        nl.setSpacing(10)
        note = QLabel(tr(
            "The sheet itself is laid out with the MANUAL module's settings — "
            "printtarg or the ChromIQ layout engine, with every option you "
            "set there. This module only chooses the colours."), note_row)
        note.setWordWrap(True)
        note.setStyleSheet("color: #9a9a9a; background: transparent;")
        nl.addWidget(note, 1)
        nl.addWidget(TooltipButton(tr(_GAMUT_MODULE_HELP_TITLE),
                                   tr(_GAMUT_MODULE_HELP_BODY), note_row))
        self._gamut_layout_note = note_row
        v.addWidget(note_row)

        # The no-profile empty state REPLACES the options (#133 §10): the
        # profile's gamut is this module's input, so without one there is
        # nothing to ask. Text from the §M catalogue (M-GAMUT-NO-PROFILE).
        self._gamut_empty_lbl = QLabel("", panel)
        self._gamut_empty_lbl.setObjectName("info")
        self._gamut_empty_lbl.setWordWrap(True)
        self._gamut_empty_lbl.setVisible(False)
        v.addWidget(self._gamut_empty_lbl)

        self._gamut_count_spin.valueChanged.connect(
            lambda _v: self._update_gamut_count_line())
        self._gamut_count_user_set = False
        self._gamut_count_seeding = False
        self._gamut_count_spin.valueChanged.connect(self._on_gamut_count_edited)
        self._gamut_auto_check.toggled.connect(
            lambda _c: (self._sync_gamut_pages_enabled(),
                        self._update_gamut_count_line()))
        # Both of these change how many colours are in gamut, so both re-run
        # the default that is capped by it (#162).
        self._gamut_margin_combo.currentIndexChanged.connect(
            lambda _i: self._on_gamut_reach_changed())
        self._gamut_intent_combo.currentIndexChanged.connect(
            lambda _i: self._on_gamut_reach_changed())
        #: (profile path, mtime, margin, intent) → in-gamut total, so flicking
        #: between two settings is instant after the first query (#133 §10).
        self._gamut_coverage_cache: dict = {}
        self._pending_gamut_selection = None
        self._gamut_active = False

        # Slot the container into the Manual panel exactly where the targen
        # section sits — the module replaces targen ONLY (#133 §10/§11).
        self._gamut_container = panel
        panel.setVisible(False)
        idx = self._manual_inner_layout.indexOf(self._manual_targen_grp)
        self._manual_inner_layout.insertWidget(max(idx, 0), panel)

    def _gamut_profile(self) -> "Path | None":
        """The built profile of the run the bar points at, or None."""
        ctl = getattr(self, "_target_ctl", None)
        if ctl is None:
            return None
        try:
            project = ctl.project_or_none()
            if project is None:
                return None
            from core.measurement_target import resolve_run
            icc = resolve_run(project, ctl.target).built_profile_icc()
            return icc if icc.exists() else None
        except Exception:      # noqa: BLE001 — a question must never raise
            return None

    def _gamut_no_profile_message(self) -> "tuple[str, str]":
        """The module's empty state, rendered from the §M catalogue."""
        from workflow import measurement_messages as M
        ctl = getattr(self, "_target_ctl", None)
        run_id = (ctl.target.profile_run if ctl is not None else "") or ""
        run_name = tr("Run {n}").format(n=run_id.removeprefix("run")) \
            if run_id.startswith("run") else tr("This run")
        return M.M_GAMUT_NO_PROFILE.render(run=run_name)

    def _verify_noprofile_message(self) -> "tuple[str, str]":
        """The Guided/Manual info box, rendered from the §M catalogue."""
        from workflow import measurement_messages as M
        return M.M_VERIFY_CREATE_NO_PROFILE.render()

    def _refresh_gamut_visibility(self) -> None:
        """Show the module button only for a verification target, and keep the
        panel's profile-dependent state honest (#133 §10).

        With calibration options ON, Sebastian's matrix (2026-08-11) applies:
        a Verification run shows the mode row with MANUAL and FROM PROFILE
        GAMUT only (gamut as the default); Profiling and Calibration runs
        lock to MANUAL with the row hidden — never Guided, which used to be
        the landing place when a verification was left.
        """
        is_verif = self._is_verification_target()
        cal_on = getattr(self, "_cal_options_on", False)
        self._gamut_btn.setVisible(is_verif)
        if cal_on:
            self._mode_row_widget.setVisible(is_verif)
            self._guided_btn.setVisible(False)
            if not is_verif and self._mode_name() == "guided":
                self._switch_mode("manual")
        else:
            self._guided_btn.setVisible(True)
        if not is_verif and getattr(self, "_gamut_active", False):
            self._switch_mode("manual" if cal_on else "guided")
        profile = self._gamut_profile() if is_verif else None
        if is_verif:
            self._refresh_gamut_state()
            # A verification run that HAS a built profile opens on the FROM
            # PROFILE GAMUT module — the chart whose colours the profile can
            # actually print is the recommended check (Knut, 2026-08-10:
            # "the only correct thing"). Only ever as a default: the moment
            # the user picks a module by hand this session, their choice
            # wins and stays. GUIDED and MANUAL remain one click away.
            if (profile is not None
                    and not getattr(self, "_gamut_active", False)
                    and not getattr(self, "_user_chose_module", False)):
                self._switch_mode("gamut")
            # With calibration options on, Guided is not offered — a
            # verification that lands here on Guided (e.g. restored from an
            # earlier session) moves to the gamut module, or Manual when no
            # profile exists yet to feed it.
            if cal_on and self._mode_name() == "guided":
                self._switch_mode("gamut" if profile is not None else "manual")
        # LAST, after every module switch above has settled: whether the
        # Guided/Manual no-profile box shows depends on which module is
        # active NOW. Deciding it earlier left it standing next to the gamut
        # module's own empty state — two near-identical messages on one
        # screen (Sebastian, 2026-08-11).
        self._refresh_verify_noprofile_box()

    def _refresh_verify_noprofile_box(self) -> None:
        """The Guided/Manual info box (#133 Q11): shown while a verification
        target has no profile AND a module other than FROM PROFILE GAMUT is
        active — the gamut module explains the no-profile state itself, in
        its own words, and the two must never stand together."""
        lbl = getattr(self, "_verify_noprofile_lbl", None)
        if lbl is None:
            return
        is_verif = self._is_verification_target()
        profile = self._gamut_profile() if is_verif else None
        show = (is_verif and profile is None
                and not getattr(self, "_gamut_active", False))
        if show:
            title, body = self._verify_noprofile_message()
            lbl.setText(f"<b>{title}</b><br><br>"
                        + body.replace("\n\n", "<br><br>").replace("\n", "<br>"))
        lbl.setVisible(show)

    def _refresh_gamut_state(self) -> None:
        """Options vs the no-profile empty state, and the Generate button."""
        # Selecting another run does NOT re-enter the module — both automatic
        # routes into it are guarded by "only if the mode would change" — so
        # seeding from `_switch_mode` alone never fired for the run you switch
        # to while the module is already open (#162).
        self._seed_gamut_count_from_manual()
        profile = self._gamut_profile()
        has = profile is not None
        self._gamut_grp.setVisible(has)
        self._gamut_layout_note.setVisible(has)
        if not has:
            title, body = self._gamut_no_profile_message()
            self._gamut_empty_lbl.setText(
                f"<b>{title}</b><br><br>"
                + body.replace("\n\n", "<br><br>").replace("\n", "<br>"))
        self._gamut_empty_lbl.setVisible(not has)
        if getattr(self, "_gamut_active", False):
            self._generate_btn.setEnabled(has and not self._runner.is_running)
            if has:
                self._update_gamut_count_line()

    def _gamut_coverage(self, profile: "Path", margin: str,
                        intent: str) -> "int | None":
        """In-gamut total for the CURRENT settings, cached per profile file +
        modification time + margin + intent. ~0.2 s cold, instant warm."""
        try:
            key = (str(profile), profile.stat().st_mtime, margin, intent)
        except OSError:
            return None
        if key in self._gamut_coverage_cache:
            return self._gamut_coverage_cache[key]
        try:
            from workflow.gamut_target import select_gamut_targets
            sel = select_gamut_targets(
                profile, 1, margin, intent,
                bin_dir=self._settings.get("argyll_bin_path",
                                           "/Applications/Argyll/bin"))
        except Exception:      # noqa: BLE001 — the count line must never crash
            log.warning("gamut coverage query failed", exc_info=True)
            # Remember the FAILURE as well. It sat outside the cache, so every
            # refresh shelled out again — and a hung xicclu would freeze the
            # window for its whole timeout on every run you select.
            self._gamut_coverage_cache[key] = None
            return None
        self._gamut_coverage_cache[key] = sel.in_gamut_total
        self._gamut_master_total = sel.master_total
        return sel.in_gamut_total

    def _update_gamut_count_line(self) -> None:
        """The live figures of #133 §10: coverage (which needs the profile) and
        the sheet estimate (which needs only the layout)."""
        if not getattr(self, "_gamut_active", False):
            return
        profile = self._gamut_profile()
        if profile is None:
            self._gamut_count_lbl.setText("")
            return
        auto = self._gamut_auto_check.isChecked()
        count = self._gamut_effective_count()
        self._gamut_count_spin.setEnabled(not auto)
        if auto:
            # Show the computed fill in the greyed spin, without re-firing.
            self._gamut_count_spin.blockSignals(True)
            self._gamut_count_spin.setValue(
                min(max(count, self._gamut_count_spin.minimum()),
                    self._gamut_count_spin.maximum()))
            self._gamut_count_spin.blockSignals(False)
        margin = self._gamut_margin_combo.currentData() or "safe"
        intent = self._gamut_intent_combo.currentData() or "absolute"
        cover = self._gamut_coverage(profile, margin, intent)
        master = int(getattr(self, "_gamut_master_total", 0) or 0)
        parts = []
        if cover is not None and master:
            parts.append(tr(
                "{n} of the {total} reference colours ({pct} %) are "
                "printable with this profile.").format(
                    n=cover, total=master,
                    pct=round(100 * cover / master)))
            if cover < count:
                parts.append(tr(
                    "Only {n} can be tested, so the chart will hold {n} "
                    "colours plus the 8 cube corners.").format(n=cover))
            else:
                parts.append(tr(
                    "Your chart: {count} colours plus the 8 cube corners "
                    "= {total} patches.").format(count=count,
                                                 total=count + 8))
        else:
            parts.append(tr(
                "The in-gamut count could not be worked out yet — it runs "
                "the first time a profile is available."))
        patches = min(count, cover) + 8 if cover is not None else count + 8
        sheets = self._gamut_sheet_estimate(patches)
        if sheets:
            parts.append(sheets)
        self._gamut_count_lbl.setText(" ".join(parts))

    def _recipe_capacity(self) -> "int | None":
        """Patches per sheet under the LIVE Manual layout recipe.

        The recipe panel is the source of truth for the engine's layout, so
        anything that quotes a capacity in Manual mode has to read it rather
        than the printtarg widgets beside it.
        """
        panel = getattr(self, "_manual_layout_panel", None)
        if panel is None or not hasattr(panel, "get_recipe"):
            return None
        try:
            from workflow.layout_engine import geometry, instruments, papers
            rec = panel.get_recipe()
            geom = instruments.geom_from_build_kwargs(rec.build_kwargs())
            w_mm, h_mm = papers.dimensions_mm(rec.paper)
            n = int(geometry.patches_per_sheet(geom, w_mm, h_mm))
            return n if n > 0 else None
        except Exception:      # noqa: BLE001 — a hint may never block
            log.debug("recipe capacity unavailable", exc_info=True)
            return None

    def _gamut_per_sheet(self) -> "int | None":
        """Patches per sheet under the CURRENT Manual layout — engine-exact
        when the engine is on, the capacity database for printtarg, None when
        the combination cannot be resolved."""
        try:
            p = self._collect_manual()
            per = None
            if bool(self._settings.get("use_chromiq_layout_engine", False)):
                # FROM THE LIVE RECIPE, because in Manual mode that is what
                # lays the sheet out. Asking `_engine_capacity` with the
                # PRINTTARG fields ignored the recipe panel entirely — the
                # patch size, the margins, the clip border — and answered 550
                # for every layout, against a real 88 to 540. On a 20 mm-patch
                # chart it was out by 6.25x while its own docstring said
                # "engine-exact". Same family as the Guided estimate that
                # promised 368 patches on a 345-patch sheet.
                per = self._recipe_capacity()
                if not per:
                    per = self._engine_capacity(
                        p.instrument, p.paper, dd=p.double_density,
                        td=getattr(p, "triple_density", False),
                        eff_lb=p.disable_left_border,
                        nsl=p.no_strip_limit, pscale=float(p.patch_scale),
                        margin=float(p.margin_mm))
            if not per:
                from data.patch_db import query_patches
                per = query_patches(p.instrument, p.paper, p.double_density,
                                    True, int(p.margin_mm),
                                    float(p.patch_scale),
                                    False, p.no_strip_limit)
            return int(per) if per and per > 0 else None
        except Exception:      # noqa: BLE001
            return None

    def _gamut_manual_colour_count(self) -> "int | None":
        """What the Manual settings represent, as a count for THIS box (#162).

        soul-traveller: *"if I select a 484 patch preset, the default value
        should be 484 patches (including the 8 color extremes)"*. This box is
        the count BEFORE the corners are added — "+ 8" sits beside it — so a
        484-patch Manual chart seeds 476 and the chart totals 484.

        Note this is not what "Auto — fill the pages" computes: that fills the
        sheet to capacity, which for his preset is 550, not 484. Matching the
        chart and filling the paper are different numbers.
        """
        try:
            patches = int(self._collect_manual().patches)
        except Exception:      # noqa: BLE001
            return None
        if patches <= 0 and self._manual_auto_patches_check is not None \
                and self._manual_auto_patches_check.isChecked():
            # Manual is filling the pages itself and has not written a number
            # into targen -f. The chart it describes is then the sheet's
            # capacity — the same arithmetic Manual's own Auto uses.
            per = self._gamut_per_sheet()
            if per:
                patches = int(per) * max(1, int(self._gamut_pages()))
        if patches <= 0:
            return None
        want = patches - _GAMUT_CORNER_PATCHES
        # NEVER MORE THAN THE PROFILE CAN PRINT.
        #
        # The chart holds `min(count, in-gamut) + 8` whatever the box says, so a
        # default taken from the Manual chart alone can promise colours that do
        # not exist for this profile: a 3000-patch chart against a profile with
        # 2896 in-gamut colours put 2992 in the box while the line underneath
        # said "Only 2896 can be tested". A number the user types is still his
        # — the line explains it — but a DEFAULT the app cannot keep is the
        # app's own contradiction (#162, Sebastian).
        cover = self._gamut_in_gamut_total()
        if cover is not None:
            # `if cover:` read a reach of ZERO as "unknown", so the profile that
            # can print nothing got the largest default of all.
            want = min(want, int(cover))
        spin = self._gamut_count_spin
        return max(spin.minimum(), min(spin.maximum(), want))

    def _gamut_in_gamut_total(self) -> "int | None":
        """How many reference colours this profile can print, at the CURRENT
        margin and intent — cached, and None when it cannot be worked out."""
        profile = self._gamut_profile()
        if profile is None:
            return None
        return self._gamut_coverage(
            profile,
            self._gamut_margin_combo.currentData() or "safe",
            self._gamut_intent_combo.currentData() or "absolute")

    def _seed_gamut_count_from_manual(self) -> None:
        """Default the colour count to the Manual chart, on entering the module.

        A DEFAULT, not an override: it stands down as soon as the count is this
        target's own choice — typed here, or restored from the target's stored
        record. Seeding over a stored value would be the fault the per-target
        store exists to prevent, and the count is stored (`create_chart_ui`
        → `gamut.count`).
        """
        if not getattr(self, "_gamut_active", False):
            return                      # the reach query is not free
        if getattr(self, "_gamut_count_user_set", False):
            return
        want = self._gamut_manual_colour_count()
        if want is None or want == self._gamut_count_spin.value():
            return
        self._gamut_count_seeding = True
        try:
            self._gamut_count_spin.setValue(want)
        finally:
            self._gamut_count_seeding = False

    def _on_gamut_reach_changed(self) -> None:
        """Margin or intent changed — the in-gamut total moves with them.

        Not while a target's record is being applied: margin and intent arrive
        as two separate signals there, so a `full`/`relative` record asked the
        engine about `safe`/`absolute`, then about `full`/`absolute` — a pair
        nobody ever chose — before its own. Three queries, half a second of
        frozen window, and the box visibly stepping through the phantom's
        answer. The refresh that follows the record settles it once.
        """
        if getattr(self, "_loading_target_settings", False):
            return
        self._seed_gamut_count_from_manual()
        self._update_gamut_count_line()

    def _on_manual_patch_count_changed(self, *_a) -> None:
        """The Manual chart changed — re-default the module's count (#162)."""
        if getattr(self, "_gamut_active", False):
            self._seed_gamut_count_from_manual()

    def _on_gamut_count_edited(self, *_a) -> None:
        """Any value that is not our own seed is the user's choice, and sticks."""
        if not getattr(self, "_gamut_count_seeding", False):
            self._gamut_count_user_set = True

    def _gamut_effective_count(self) -> int:
        """The colour count a Generate would use right now: the spin's value,
        or — with Auto on — however many fill the pages set in the layout
        section below, minus the 8 corners that always ride along."""
        if getattr(self, "_gamut_auto_check", None) is not None \
                and self._gamut_auto_check.isChecked():
            per = self._gamut_per_sheet()
            pages = self._gamut_pages()
            if per:
                fill = per * max(1, int(pages)) - _GAMUT_CORNER_PATCHES
                # Filling the pages cannot conjure colours the profile does not
                # have either — and this is the number the user CANNOT correct,
                # because Auto greys the box. It was the one left uncapped.
                cover = self._gamut_in_gamut_total()
                if cover is not None:
                    fill = min(fill, int(cover))
                return max(50, fill)
        return int(self._gamut_count_spin.value())

    def _gamut_pages(self) -> int:
        """The page count the build will actually use: the engine panel's own
        Pages control when the engine is on, printtarg's spin otherwise."""
        if bool(self._settings.get("use_chromiq_layout_engine", False)) \
                and getattr(self, "_manual_layout_panel", None) is not None:
            return int(self._manual_layout_panel.get_pages())
        return int(self._manual_pages_spin.value()
                   if self._manual_pages_spin is not None else 1)

    def _sync_gamut_pages_enabled(self) -> None:
        """Pages follows #93's rule — greyed while an exact count fixes it —
        but in the gamut module the AUTO checkbox is the thing that makes
        pages the input, so it must unlock them (Basti, 2026-08-09). Leaving
        the module restores Manual's own Auto-patch-count state."""
        if getattr(self, "_gamut_active", False):
            on = self._gamut_auto_check.isChecked()
        else:
            on = (self._manual_auto_patches_check.isChecked()
                  if self._manual_auto_patches_check is not None else True)
        if self._manual_pages_spin is not None:
            self._manual_pages_spin.setEnabled(on)
        if getattr(self, "_manual_pages_lbl", None) is not None:
            self._manual_pages_lbl.setEnabled(on)
        if getattr(self, "_manual_layout_panel", None) is not None:
            self._manual_layout_panel.set_pages_enabled(on)

    def _gamut_sheet_estimate(self, patches: int) -> str:
        """'≈ N sheets' from the Manual layout — EXACT with the ChromIQ layout
        engine (the same geometry that will build the sheet, asked in
        advance), the empirical capacity database for printtarg, and honest
        silence when the combination cannot be resolved (#133 §10)."""
        per = self._gamut_per_sheet()
        if per:
            import math as _math
            n = _math.ceil(patches / per)
            return (tr("That is about one sheet with your current layout.")
                    if n == 1 else
                    tr("That is about {n} sheets with your current "
                       "layout.").format(n=n))
        return ""

    def _on_generate_gamut(self) -> None:
        """Generate for the FROM PROFILE GAMUT module: select the colours from
        the master set through this run's profile, write the patch list, and
        hand it to the ordinary from-.ti1 build (Manual's layout settings)."""
        profile = self._gamut_profile()
        if profile is None:
            self._refresh_gamut_state()
            return
        count = self._gamut_effective_count()
        margin = self._gamut_margin_combo.currentData() or "safe"
        intent = self._gamut_intent_combo.currentData() or "absolute"
        from PyQt6.QtWidgets import QApplication
        from workflow.gamut_target import (GamutTargetError,
                                           select_gamut_targets,
                                           write_gamut_ti1)
        QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
        try:
            selection = select_gamut_targets(
                profile, count, margin, intent,
                bin_dir=self._settings.get("argyll_bin_path",
                                           "/Applications/Argyll/bin"))
            ctl = getattr(self, "_target_ctl", None)
            project = ctl.project_or_none() if ctl is not None else None
            if project is None:
                return
            from core.measurement_target import resolve_run
            run = resolve_run(project, ctl.target)
            ti1 = run.ensure_cache_dir() / "gamut-target.ti1"
            write_gamut_ti1(selection, ti1)
            # A cached copy of the reference lives beside the cached patch
            # list: an auto-preview re-layout rebuilds from this .ti1 with no
            # fresh selection, and the adoption step clears the verify files —
            # reference included — so it is restored from this copy.
            from workflow.gamut_target import write_colorimetric_reference
            write_colorimetric_reference(
                selection, run.cache_dir / "gamut-target-reference.ti3")
        except GamutTargetError as exc:
            InfoDialog(
                tr("The colours could not be chosen"),
                tr("ChromIQ asked your profile which of the reference colours "
                   "it can print, and that did not finish.\n\n"
                   "Details: {reason}\n\n"
                   "The most common reason is that the ArgyllCMS folder in "
                   "Preferences is not the one you installed, or the profile "
                   "file is damaged. Nothing has been changed."
                   ).format(reason=str(exc)),
                self, min_width=520,
            ).exec()
            return
        finally:
            QApplication.restoreOverrideCursor()
        if selection.achieved < count:
            self._log.appendPlainText(tr(
                "Only {n} of the requested {count} colours are printable "
                "with this profile, so the chart holds {n} colours plus the "
                "8 cube corners.").format(n=selection.achieved, count=count))
        self._settings.set("gamut_target_count", count)
        self._settings.set("gamut_target_margin", margin)
        self._settings.set("gamut_target_intent", intent)
        self._settings.set("gamut_target_auto",
                           self._gamut_auto_check.isChecked())
        self._pending_gamut_selection = selection
        self._generate_from_ti1(ti1)

    def _write_gamut_reference_after_adopt(self, new_ti2: "Path | None") -> None:
        """After a gamut chart was adopted as the run's verify chart, store the
        colorimetric reference beside it — the report's yardstick, the Print
        tab's force-Raw marker, and the §5.4 record, in one file."""
        selection = getattr(self, "_pending_gamut_selection", None)
        self._pending_gamut_selection = None
        if new_ti2 is None:
            return
        if selection is None:
            # A re-layout (the auto-update preview, or Generate pressed again
            # with the module's cached patch list): the colours are unchanged,
            # but the adoption step cleared the verify files — the reference
            # among them — so put the cached copy back. Only while the module
            # is the active mode; a targen chart replacing a gamut chart must
            # NOT inherit colorimetric targets that describe other colours.
            if not getattr(self, "_gamut_active", False):
                return
            try:
                from core.file_manager import Run
                run = Run.for_dir(Path(new_ti2).parents[1])
                cached = run.cache_dir / "gamut-target-reference.ti3"
                if cached.is_file():
                    from workflow.gamut_target import mark_chart_as_colorimetric
                    from workflow.verification_print import \
                        colorimetric_reference_for
                    ref = colorimetric_reference_for(new_ti2)
                    shutil.copyfile(cached, ref)
                    mark_chart_as_colorimetric(new_ti2, ref)
                    self._log.appendPlainText(tr(
                        "The chart's colorimetric reference was restored "
                        "beside the new layout — same colours, same "
                        "targets."))
            except Exception:      # noqa: BLE001 — never break a finished build
                log.warning("could not restore the colorimetric reference",
                            exc_info=True)
            return
        try:
            from workflow.gamut_target import (mark_chart_as_colorimetric,
                                               write_colorimetric_reference)
            from workflow.verification_print import colorimetric_reference_for
            ref = write_colorimetric_reference(
                selection, colorimetric_reference_for(new_ti2))
            mark_chart_as_colorimetric(new_ti2, ref)
            self._log.appendPlainText(tr(
                "The colorimetric reference was stored beside the chart "
                "({name}). This chart already has your profile applied — "
                "print it exactly as it is; the Print Chart tab selects "
                "“Raw” for it automatically.").format(name=ref.name))
        except Exception:      # noqa: BLE001 — never break a finished build
            log.warning("could not write the colorimetric reference",
                        exc_info=True)
            self._log.appendPlainText(tr(
                "The colorimetric reference could not be written — without "
                "it the measurement report cannot judge this chart. Please "
                "generate the chart again."))

    def _snapshot_profiling_chart(self) -> "Path | None":
        """Copy the current run's PROFILING work aside before a verification
        chart is built into the same run root, so building the verify chart
        (which overwrites the run root before the files are moved into
        verifications/) never disturbs it (#130, Knut). Returns the temp folder,
        or None when the run has nothing to protect.

        Covers the chart files **and the run's measurement (.ti3) and printer
        profile (.icc/.icm)**: the build starts with ``reset_chart_artefacts()``,
        which archives those to ``old/`` — so without this the run appeared to
        have lost its finished profile the moment a verification chart was made.
        """
        try:
            run = self._file_mgr.project().current_run()
        except Exception:      # noqa: BLE001
            return None
        stem = run.stem
        srcs = [run.dir / f"{stem}{ext}" for ext in
                (".ti1", ".ti2", ".cht", ".channels.json", ".strips.json",
                 ".tif", ".ti3", ".icc", ".icm")]
        srcs += run.stem_files(stem, "_*.tif")
        present = [p for p in srcs if p.is_file()]
        if not present:
            return None
        import tempfile
        tmp = Path(tempfile.mkdtemp(prefix="chromiq_prof_chart_"))
        for p in present:
            try:
                shutil.copy2(p, tmp / p.name)
            except OSError:
                pass
        return tmp

    def _restore_profiling_chart(self) -> None:
        """Move the snapshotted profiling chart back to the run root after a
        verification chart was generated + filed into verifications/ (#130)."""
        bak = getattr(self, "_verify_profiling_backup", None)
        self._verify_profiling_backup = None
        if not bak:
            return
        try:
            run = self._file_mgr.project().current_run()
            for p in Path(bak).iterdir():
                shutil.move(str(p), str(run.dir / p.name))
        except Exception:      # noqa: BLE001 — never break a finished generation
            log.warning("Could not restore the profiling chart after verify "
                        "generation", exc_info=True)
        finally:
            shutil.rmtree(bak, ignore_errors=True)

    def _abandon_ti1_load(self) -> None:
        """Cancel a patch-set load and leave the tab exactly as it was.

        Every one of these exits used to clear the preview, which is wrong for
        a cancel: nothing was replaced, so the chart that was on screen is still
        the chart in the run. Knut, beta.128, after cancelling the §4 window on
        a "Replace only the Chart": *"Now my chart for
        'Demo-03-Complete-And-Profiled' is gone from the preview. The ti1 file
        is still in the run folder, and if I go to Print Chart Tab the chart is
        showing in preview, but not in Create Chart tab. I am able to refresh
        the preview by changing the Profile run parameter to New run and back to
        run 1."*

        That workaround is the fix: re-resolve the selected target and draw its
        chart. The remembered stamp has to go first, or the redraw is skipped as
        "already showing this exact chart" — which is precisely why the preview
        stayed blank until the selection changed.
        """
        self._generate_btn.setEnabled(True)
        self._shown_chart_ti2 = None
        self._shown_chart_stamp = None
        try:
            self._on_target_changed()
        except Exception:      # noqa: BLE001 — a cancel must never raise
            log.warning("could not put the chart back after a cancelled load",
                        exc_info=True)
            self._preview.clear()

    def _calibration_replace_message(self, proj, measured: bool):
        """M-CAL-REPLACE-CHART / M-CAL-REPLACE-MEASURED, from the catalogue.

        Returns ``(window title, bold first line, body)``. Three strings rather
        than the usual two because these two windows carry a window title AND a
        bold opening line, which is one more than :class:`Message` holds; the
        opening line is a module constant beside its message, so every sentence
        either window can show is still written down in one reviewable place.

        WHICH WINDOW IS DECIDED BY ``Calibration.exists()`` — a ``.ti3`` or a
        ``.cal`` — and that is narrower than what the CODE keeps
        (``Calibration.result_files()``, which also counts an ``.icc`` and a
        ``.ti3.engine-partial``). The direction is deliberate and is the only
        safe one: this window can say "not kept" over a calibration that is in
        fact kept, and can never say "kept" over one that is dropped. Proved
        exhaustively in
        ``tests/test_calibration_keeps_only_measured.py::test_the_window_can_only_ever_promise_less_than_the_code_keeps``.
        """
        from workflow import measurement_messages as M

        if measured:
            runs = [self._pretty_run_name(r)
                    for r in self._runs_built_on_calibration(proj)]
            title, body = M.M_CAL_REPLACE_MEASURED.render(
                runs_line=M.calibration_runs_phrase(runs))
            return title, tr(M.M_CAL_MEASURED_HEADLINE), body
        title, body = M.M_CAL_REPLACE_CHART.render()
        return title, tr(M.M_CAL_CHART_HEADLINE), body

    def _confirm_replacing_calibration(self) -> bool:
        """Ask before a new calibration chart replaces the one in ``cal/``.

        Two windows, and which one appears decides what the app is about to do
        with the chart.

        **A finished calibration is kept, whole.** It is a printed and measured
        sheet's worth of work and it is what ``printcal``'s Re-calibrate and
        Verify modes read back, so losing it silently costs the user the round
        trip AND those two modes. Everything moves to ``cal/old/<date>/``.

        **A chart nobody measured is an experiment and is not kept.** The owner
        ruled that on 2026-09-02 (option 3 of
        ``RULING-calibration-old-charts.txt``), and it is what a profile run has
        done since ``93ba45ee``: iterating on a layout ten times must not leave
        ten dated folders holding charts their owner had already decided
        against. It is set aside for the length of the build, so a build that
        fails, is stopped or is killed still puts it back, and dropped once a
        replacement really exists.

        **THIS WINDOW SAID THE OPPOSITE FOR ONE COMMIT AND THAT WAS THE POINT
        OF THE WHOLE EXERCISE.** The wording moved through §M and was approved
        by Basti on 2026-09-02; until it was, two strict xfails in
        ``tests/test_calibration_keeps_only_measured.py`` held the branch shut
        rather than let a false promise reach anybody. The pair is still checked
        against each other there, which is what stops it drifting again.
        """
        from PyQt6.QtWidgets import QMessageBox
        from ui.widgets import fit_message_box_buttons

        try:
            proj = self._file_mgr.project()
            cal = proj.calibration
        except Exception:      # noqa: BLE001 — no project yet: nothing at risk
            return True
        if not cal.live_files():
            return True                     # nothing there to replace

        measured = cal.ti3.exists() or cal.cal_path.exists()
        title, headline, body = self._calibration_replace_message(proj, measured)
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.NoIcon)
        box.setWindowTitle(title)
        box.setText(headline)
        box.setInformativeText(body)
        go = tr("Replace the calibration") if measured else tr("Replace the chart")
        ok = box.addButton(go, QMessageBox.ButtonRole.AcceptRole)
        cancel = box.addButton(tr("Cancel"), QMessageBox.ButtonRole.RejectRole)
        # RETURN MUST NEVER BE A REPLACE. This is the app's own rule, written
        # in as many words at three other doors (`ti2_loader.py:1025` and
        # `:1560`, `txt_loader.py:430`) and followed at every destructive
        # window in the app - Close project, File it in a new run, Make a new
        # run, Restore chart files anyway. This one was the exception, and
        # since the owner's 2026-09-02 ruling the accept button on the
        # unmeasured branch DISCARDS a chart that is not kept anywhere, so a
        # stray Return was the cheapest possible way to lose it.
        box.setDefaultButton(cancel)
        fit_message_box_buttons(box)
        box.exec()
        return box.clickedButton() is ok

    @staticmethod
    def _pretty_run_name(run_id: str) -> str:
        n = run_id[3:] if run_id.startswith("run") else run_id
        return tr("Run {n}").format(n=n)

    def _runs_built_on_calibration(self, proj) -> "list[str]":
        """Runs whose profile was built with the calibration now in ``cal/``.

        Absent means unknown — every run built before ChromIQ recorded this
        simply does not say, and guessing would be worse than staying quiet.
        """
        out: list[str] = []
        try:
            stem = proj.calibration.stem
            for run in proj.all_runs():
                if getattr(run.meta, "calibration_used", "") == stem:
                    out.append(run.id)
        except Exception:      # noqa: BLE001 — never block a build on this
            log.debug("could not list runs built on the calibration",
                      exc_info=True)
        return out

    def _resolve_target_chart(self) -> "tuple[Path, list[Path], Path] | None":
        """``(ti2, tiffs, ti1)`` for the current Profile-run / Run-type target's
        EXISTING chart — the verification chart for Run type = Verification, the
        run's profiling chart for Profiling — or ``None`` when that chart hasn't
        been generated yet. Never creates anything (#130)."""
        ctl = getattr(self, "_target_ctl", None)
        if ctl is None:
            return None
        try:
            proj = ctl.project_or_none()
            if proj is None:
                return None
            t = ctl.target
            if getattr(t, "is_calibration", bool)():
                # THE CALIBRATION CHART IS A CHART LIKE ANY OTHER (#137 D3).
                # Resolving it here means the preview, Print Chart and Measure
                # all follow with no change of their own — and it is what makes
                # a calibration chart reloadable at all, which it was not.
                cal = proj.calibration
                tiffs = cal.chart_tiffs()
                if cal.ti2.is_file() and tiffs:
                    return cal.ti2, list(tiffs), cal.ti1
                return None
            run_id = t.profile_run
            if not run_id or not proj.has_run(run_id):
                return None                      # "New run" / no such run yet
            run = proj.run(run_id)
            if t.is_verification():
                ti2, ti1 = run.verify_chart_ti2, run.verify_chart_ti1
                tiffs = run.verify_chart_tiffs()
            else:
                ti2, ti1 = run.chart_ti2, run.chart_ti1
                tiffs = run.stem_files(run.stem, "_*.tif")
                if not tiffs and (run.dir / f"{run.stem}.tif").is_file():
                    tiffs = [run.dir / f"{run.stem}.tif"]
            if ti2.is_file() and tiffs:
                return ti2, list(tiffs), ti1
        except Exception as exc:  # noqa: BLE001 — never break the tab on this
            log.warning("Run-type switch: could not resolve target chart: %s", exc)
        return None

    def _default_bar_to_current_run(self) -> None:
        """Point the shared bar at the loaded project's current run (#130), so the
        bar reads "Overwrite run N" rather than its empty "New run" default — and
        a plain Generate overwrites that run instead of creating a spurious new
        one. A no-op without a project or controller; the user can still pick
        "New run" explicitly afterwards."""
        ctl = getattr(self, "_target_ctl", None)
        if ctl is None:
            return
        try:
            proj = ctl.project_or_none()
            if proj is None:
                return
            rid = proj.current_run().id
            if ctl.target.profile_run != rid:
                ctl.set_profile_run(rid)
        except Exception as exc:  # noqa: BLE001
            log.warning("Could not default the target bar to the current run: %s", exc)

    def _reset_run_type_for_loaded_project(self) -> None:
        """Put Run type back to Profiling when a project is OPENED.

        Knut asked for this (#130, 2026-07-29): *"When using the load profile
        button in create chart, and then loading a stored project.json file:
        Reset Run type to Profiling, so that all newly loaded charts start at
        its profiling data."* Run type is working state rather than a property
        of the project, and it was simply whatever the previous project had been
        left on.

        **Only on a project load.** It lived in _default_bar_to_current_run at
        first, which every successful generation also calls — including the
        redraw that follows Restore Used Chart. So restoring a verification's
        chart threw the user back to Profiling mid-task, and he could no longer
        tell whether the chart had been replaced at all: *"This should NOT
        happen. Going back to run type profiling automatically shall only happen
        when loading a profile.json file from the load ti1 button in create
        chart tab."*
        """
        ctl = getattr(self, "_target_ctl", None)
        if ctl is None:
            return
        try:
            if ctl.target.is_verification():
                ctl.set_run_type("profiling")
                ctl.set_verification_id("")
        except Exception as exc:      # noqa: BLE001 — never block a load
            log.warning("Could not reset the run type on project load: %s", exc)

    def _builds_into_project(self, proj_before) -> bool:
        """Whether the build about to run targets the project that was loaded
        *before* the name was applied — i.e. an in-project build that must honour
        the Profile-run bar, rather than a build under a new name (its own,
        brand-new project).

        Compares the actual folders, not just their names (#130, Knut): a project
        opened from a SUB-folder of the ChromIQ folder has the same name as the
        ``<ChromIQ>/<name>`` path a fresh project would use, so a name-only check
        called a different folder "the same project".
        """
        # A PROJECT ADOPTED THROUGH THE §S4.7 WINDOW COUNTS AS "in project".
        # The user was just shown that project by name and picked the run they
        # want inside it, so the bar must be honoured — otherwise the build
        # silently takes the manifest's own current run and the bar goes on
        # saying something else. Measured before this: the bar said run1 and the
        # chart landed in run3. One-shot: consumed here, so it can never leak
        # into the next build.
        if getattr(self, "_adopted_via_gate", False):
            self._adopted_via_gate = False
            return True
        # (Reset at every gate entry as well, so a route that never reaches
        # this consumer cannot leave it armed for an unrelated build.)
        if proj_before is None:
            return False
        try:
            return (Path(proj_before.root).resolve()
                    == Path(self._file_mgr.working_dir()).resolve())
        except OSError:                     # unreadable path — assume different
            return False

    def _archive_run_for_replace(self) -> None:
        """Move everything a Replace displaces in the current run to
        ``runs/runN/old/<timestamp>/`` (#130 §5a/§5b) — the run's chart,
        measurement, printer profile, reports and verifications for a Profiling
        build; the verification chart and all dated verifications for a
        Verification build. Never deletes; shares the helper the Print/Measure
        chart import uses, so both Replace paths behave identically."""
        from workflow.chart_import import archive_run_for_replace
        try:
            run = self._file_mgr.project().current_run()
            archive_run_for_replace(
                run, verification=self._is_verification_target())
        except Exception:      # noqa: BLE001 — never block a build on this
            log.warning("Could not archive the run before a Replace build",
                        exc_info=True)

    def rebuild_verification_pages(self) -> bool:
        """Redraw the printable pages of the chart that was just restored, for
        **any of the three targets** — a profile run, a verification, or the
        calibration (#130, Knut).

        Called after **Restore Used Chart** has put an older chart back: the
        snapshot deliberately holds no page images when the chart carries a
        layout recipe, so the pages are rebuilt here rather than copied. The
        chart's own saved settings are applied first — including the seed it was
        actually shuffled with — so the rebuilt sheet is the sheet that was
        measured: same patch order, patch size, margins and spacers, not
        whatever the panels happen to show.

        Profiling runs kept their own copy only from beta.42 on, and until now
        nothing redrew their pages afterwards: the restore left the chart files
        right but the Create Chart preview empty, which is what Knut saw
        (2026-07-27). All three targets now take the same route; only *which*
        chart files are read differs. The calibration was the one left out, and
        leaving it out meant a calibration restore silently redrew the selected
        run's chart instead — see the note in the body.

        Returns True when a rebuild was started. Best-effort: a chart that can't
        be rebuilt leaves the restored files in place and says so via the caller.
        """
        ctl = getattr(self, "_target_ctl", None)
        if ctl is None:
            return False
        verification = ctl.target.is_verification()
        calibration = ctl.target.is_calibration()
        try:
            proj = ctl.project_or_none()
            if proj is None:
                return False
            # A CALIBRATION IS A THIRD TARGET, AND THIS KNEW ONLY TWO.
            #
            # This asked "verification, or else the selected RUN?" — written
            # when there were two run types. With Calibration selected it
            # rebuilt the pages of whatever profile run the bar happened to
            # point at, and pinned THAT chart's patch count on screen. Knut,
            # beta.159: a 60-patch calibration chart came back as *"750 and the
            # resulting chart was 10 pager long … totally different from
            # originally stored"*, and his log names the file it actually
            # rebuilt — `runs/run8/Test-Profiling-P.ti2`, the run's chart.
            #
            # `restore_slot` had already put the right files back. It was this
            # redraw that then laid the wrong chart over them.
            run_id = None
            if calibration:
                cal = proj.calibration
                ti1, ti2 = cal.ti1, cal.ti2
            else:
                run_id = ctl.target.profile_run
                if not run_id or not proj.has_run(run_id):
                    return False
                run = proj.run(run_id)
                ti1, ti2 = ((run.verify_chart_ti1, run.verify_chart_ti2)
                            if verification else (run.chart_ti1, run.chart_ti2))
            if not ti1.is_file():
                return False
            # Build the restored chart exactly as it was made: its own recipe
            # first, then the normal build, which lays the pages at the run root
            # — and, for a verification, files them back under verifications/.
            restored_recipe = False
            if ti2.is_file():
                restored_recipe = self._restore_chart_settings(ti2)
                self._forget_what_the_chart_imposed()
            # …and BUILD IN THE MODE THAT RECIPE LANDED IN.
            #
            # Knut, #130 2026-07-29, on Demo-Verify-History: he restored a
            # verification's chart and *"it was clear that the restored chart
            # was very different from the one that was in the verifications
            # folder"*. He was right, and it was not the demo data.
            # _restore_chart_settings fills the MANUAL panels — the engine
            # toggle, the layout recipe, the pinned patch count — but
            # _collect_params() reads whichever mode is on screen, and the app
            # opens in Guided. So every one of those restored settings was
            # discarded and the rebuild laid out a brand-new chart: shuffled
            # where the original was in fixed order, with a fresh seed, 15
            # patches per pass instead of 16 and 60 sets instead of 64.
            if restored_recipe and self._current_mode() != "manual":
                self._switch_mode("manual")
            # SAY SO WHEN THE OPTIONS COULD NOT COME BACK.
            #
            # Knut, #130 2026-07-29: *"after restore of the chart the options in
            # the Create Chart is not changed back to what they were before."*
            # A chart whose stored copy carries its settings sidecar restores
            # them completely — that is checked by test. But a copy taken before
            # the sidecar was included, or a chart made without one, has nothing
            # recording those settings, so the options on screen are simply left
            # alone. That was happening in silence, which is indistinguishable
            # from the restore having failed. Now it is said plainly, together
            # with what IS guaranteed: the chart files themselves are the ones
            # that were measured.
            if not restored_recipe:
                self._log.appendPlainText(tr(
                    "The chart files have been put back exactly as they were "
                    "measured, but this stored chart carries no record of the "
                    "Create Chart options it was made with — so the options on "
                    "screen have been left as they are. Only its patch count "
                    "could be recovered. Charts created from now on always save "
                    "their settings with them, so a later restore will bring "
                    "those back too."))
            # Only a run has a "current run" to move; a calibration does not
            # live under runs/ at all.
            if run_id is not None and proj.current_run().id != run_id:
                proj.set_current_run(run_id)
            self._arm_verification_snapshot()
            params = self._collect_params()
            params.target_name = self._file_mgr.get_target_name()
            self._pin_restored_recipe(params)
            # THE CHART ITSELF MUST SURVIVE THE REDRAW.
            #
            # Redrawing pages is a rendering job; it is not licence to lay the
            # chart out again. If the rebuild writes a different .ti2 the run's
            # measurement no longer describes the sheet beside it, and nothing
            # warns anybody — the files simply stop agreeing. So the chart is
            # kept and put back if the redraw changes it (Knut, #130
            # 2026-07-29).
            self._rebuild_guard = _ChartRebuildGuard(ti2)
            self._preview.clear()
            self._generate_btn.setEnabled(False)
            self._creator.load_ti1_and_generate_preview(
                ti1, params,
                on_line=self._on_log_line,
                on_finish=self._on_generate_finished,
                # This IS the chart the run's measurement was taken with, so
                # redrawing its pages must not move that measurement aside
                # (Knut, #130 2026-07-27).
                keep_results=True,
            )
            return True
        except Exception:      # noqa: BLE001 — never break a restore
            log.warning("Could not rebuild the restored chart pages",
                        exc_info=True)
            return False

    def _arm_verification_snapshot(self) -> None:
        """Protect the run's PROFILING chart before a verification chart is built
        into the same run root (#130, Knut K3).

        Every build — Generate, a prebuilt preset, a .ti1 preset, a loaded patch
        set — lays its chart down at the run root first; for Run type =
        Verification, ``_on_generate_finished`` then moves it into
        ``verifications/``. Without a snapshot the run's own profiling chart is
        overwritten (and ``reset_chart_artefacts`` clears what's left), so it was
        simply gone once the user switched Run type back to Profiling. Taking the
        snapshot here — the one place every build path passes through before
        starting — is what ``_restore_profiling_chart`` puts back afterwards.
        """
        self._verify_profiling_backup = None
        if self._is_verification_target():
            self._verify_profiling_backup = self._snapshot_profiling_chart()

    def _align_current_run_to_target(self) -> None:
        """Point the loaded project's current run at the shared bar's Profile-run
        selection before a normal build, so the chart is written where the bar
        shows (#130, Knut): **Overwrite run N** → that run's folder; **New run**
        → a fresh ``runs/runN+1/``. Only called for an in-project build (same
        profile name); never for calibration, refinement or a new-name project.

        For "New run" the bar is advanced to the freshly created run so the next
        action targets it too (and so the run stops reading as "New run")."""
        ctl = getattr(self, "_target_ctl", None)
        if ctl is None:
            return
        proj = ctl.project_or_none()
        if proj is None:
            return
        run_id = ctl.target.profile_run
        if run_id and proj.has_run(run_id):
            if proj.current_run().id != run_id:
                proj.set_current_run(run_id)
                log.info("Create Chart: build target run → %s (overwrite)", run_id)
        elif not run_id:                     # "New run"
            new_run = proj.new_run()
            log.info("Create Chart: build target run → %s (new run)", new_run.id)
            # THE TEXT TYPED FOR THIS RUN GOES IN BEFORE ANYONE READS IT BACK.
            # With "New run" selected there was nowhere to save the description
            # and the chart notes, so they were held in the fields; this is the
            # moment they have a home. It must happen before `set_profile_run`,
            # which fires `changed` and re-reads both fields from the run —
            # finding them empty is exactly what wiped them (Knut, beta.147).
            self._write_target_text_into(new_run)
            # …and the same for the SETTINGS the user chose for this run while
            # it did not exist. §4a N-3: copied into the run, then the block is
            # dropped — otherwise the run after next would start from a stale
            # copy instead of the run actually loaded. Before `set_profile_run`
            # for the same reason the text is: that fires `changed`, which
            # re-reads everything from the run.
            self._adopt_new_run_settings(new_run)
            ctl.set_profile_run(new_run.id)

    @staticmethod
    def _count_with_accent(number: str, mark: str = "!") -> str:
        """The patch count with its closing mark in the tab's accent colour.

        Not a translated string: the whole thing is a numeral and one piece of
        punctuation, so there is nothing to translate and no twelve-catalogue
        migration to pay for. The sibling headlines are `tr()`ed because they
        contain WORDS — "Feed the beast!", "Keep calm!" — and each language
        needs its own sentence around the mark.

        `number` is escaped even though it is built from `int` today, because a
        label that renders markup must never be handed unescaped text: the day
        someone puts a user-supplied string in here, "<b>" would become bold
        rather than visible.
        """
        import html as _html

        # ONE ACCENT UNDER NEUTRAL. The mark is the tab's own hue in the two
        # coloured appearances and ACTION in the third — the same value the
        # numeral itself is set in there, so the headline reads as one word.
        return (f'{_html.escape(number)}<span style="color: '
                f'{accent_for(SPEC_MAGENTA)}; '
                f'font-style: italic;">{mark}</span>')

    def _no_chart_guidance(self) -> str:
        """Friendly text for the empty preview when the selected Profile-run /
        Run-type has no chart yet (#130, Knut beta-6): explain that nothing is
        wrong and how to make the chart, tailored to Profiling vs Verification."""
        ctl = getattr(self, "_target_ctl", None)
        if ctl is not None and ctl.target.is_verification():
            return tr(
                "No verification chart for this run yet.\n\n"
                "To make one, keep “Run type” set to “Verification”, choose your "
                "chart options above and click “Generate Chart”. Then print that "
                "chart on the Print Chart tab with “Colour” set to “Through the "
                "profile”, and measure it on the Measure tab.")
        return tr(
            "No chart for this profile run yet.\n\n"
            "Choose your chart options above and click “Generate Chart” to make "
            "it. (If you had a chart here before, its files may have been moved "
            "or deleted — just create it again.)")

    def _on_target_changed(self) -> None:
        """Switch the tab to another run's chart, and leave the live preview
        exactly where it found it.

        SELECTING A RUN IS NOT A LAYOUT EDIT. Loading a target's settings fills
        twenty widgets, each of which fires a `changed` signal, and with
        auto-update on the debounce timer armed and re-laid out that run's chart
        — rewriting it to disk. No Generate, no knob, no mode switch: merely
        picking a different run in the bar.

        `docs/design/per_target_settings.md` §7 B forbids exactly this —
        *"Loading settings must not trigger a rebuild … This is the one that
        would actually hurt, so it gets its own test"* — and the test plan's N3
        says nothing ships until it is green. §7 B used to prescribe a flag
        raised for the duration of the fill; that paragraph now carries the
        correction, because the flag cannot work here: this handler seeds the
        panel twice, once through `load_target_settings` and again through
        `_display_run_chart` -> `_restore_chart_settings`, and the second seeder
        runs after the flag is down. Guarding the first merely
        moved which line armed the timer.

        So the episode, not the flag, is the unit: whatever the load did to the
        fingerprint, re-baseline it here and drop anything already queued. A real
        edit made AFTER the switch still arms the timer normally.
        """
        self._cancel_pending_auto_preview()
        try:
            """React to a Profile-run / Run-type change: show THAT target's chart —
            its own Create-Chart settings + preview — and hand it to Print / Measure,
            so the chart that prints and is measured always matches the selected
            Profile run and Run type (#130, Knut beta-2 tests).

            When the selected target has no chart yet (a fresh run, or a verification
            chart not made yet), the previous chart is CLEARED from the preview and
            from Print / Measure so a stale chart can never linger there; the
            Create-Chart editing settings are left as-is so the new chart can be made."""
            ctl = getattr(self, "_target_ctl", None)
            if ctl is None:
                return
            # #130: the two text fields belong to whatever the bar now points at.
            # This IS the half of Knut's request that was a missing refresh rather
            # than new storage — chart notes have always been stored per run, in
            # the run's own .channels.json, and simply were not re-read when the
            # Profile run changed, which is what made them look project-wide.
            # §2.1 / N1: WRITE THE OUTGOING TARGET FIRST, then load the incoming
            # one. The order is the whole point — see save_target_settings.
            # Passed even when None: that means "the outgoing target has no file
            # yet", which is a New run — the case that most needs its values kept,
            # and exactly the one an `is not None` guard skips.
            self.save_target_settings(
                getattr(self, "_settings_store", _NO_STORE_GIVEN),
                getattr(self, "_settings_key", _NO_STORE_GIVEN))
            self._refresh_target_text()
            # RUN TYPE = CALIBRATION SETS THE CHART UP (#137) — BEFORE the load,
            # so the incoming target's own values always have the last word (F3,
            # Knut/Sebastian 2026-08-11: a setting's owner is the SELECTED
            # target). Entering Calibration this snapshots the outgoing screen
            # and sets the calibration values; leaving it restores that snapshot
            # — and then the load below lays the incoming run's own stored six
            # rows over it. With the old order (knobs AFTER load) the restore
            # clobbered the freshly loaded values, and the next write filed the
            # calibration's rows into the first run visited. Idempotent (R1).
            self._apply_calibration_knobs(
                bool(getattr(ctl.target, "is_calibration", bool)()))
            self.load_target_settings()
            # WHAT THE TARGET ITSELF SAYS, BEFORE THE CHART GETS A WORD IN.
            #
            # `_display_run_chart` -> `_restore_chart_settings` runs a few
            # lines below and lays the chart sidecar's own recipe (instrument,
            # paper, layout mode, both indicator checkboxes) over what was just
            # loaded here. Whether it should is §10's question and is not
            # settled -- but the NEXT write must not file the chart's values
            # into the target's store as though the user had chosen them.
            # Measured: pick CR30 on run 1, visit run 2, come back, leave the
            # tab, and run 1's stored `printtarg-i` has gone from CR30 back to
            # CM. Visiting a run destroyed a setting nobody touched.
            self._own_values_before_chart = self._target_own_snapshot()
            # ONE protected load, then back to normal. The flag is set when a build
            # starts and shields the layout that build used from the run's older
            # stored copy — see _apply_ui_state. It is cleared here rather than when
            # the build ends, because the build's own run does not resolve until
            # this handler has run once: the write that files the new layout can
            # only succeed on the NEXT pass, and until then the screen is the only
            # place the truth exists. Clearing unconditionally means it can never
            # latch on and freeze a run's stored layout out.
            self._layout_owned_by_build = False
            self._settings_store = self._target_settings_store()
            self._settings_key = self._target_settings_key()
            # #130 Bug C (Knut): if the loaded PROJECT changed (e.g. a Print/Measure
            # load copied a new project into the working folder), reflect its name in
            # the "Printer profile project name" field so it's visibly loaded. Gated
            # on the name actually changing, so run/type toggles within one project
            # never overwrite a name the user is typing.
            # Read the name WITHOUT get_target_name(): that invents and stores a
            # "Printer_Paper_Type_Instr_<timestamp>" name whenever none is set, and
            # the line below would then stamp that invented name straight over what
            # the user had typed — on nothing more than a Run-type toggle. Only a
            # name that genuinely belongs to a loaded project should be reflected.
            cur_name = getattr(self._file_mgr, "_target_name", "")
            # …and never while the Guided↔Manual name mirror is writing: the
            # mirror's setText re-enters here via set_pending_project_name, and
            # reflecting the stored project name mid-keystroke would overwrite
            # the very text being typed (found by the mirror's own test,
            # 2026-08-13). A mirror write is not a project change.
            if (cur_name and not getattr(self, "_syncing_target_name", False)
                    and cur_name != getattr(self, "_last_shown_project_name", None)):
                self._last_shown_project_name = cur_name
                self._update_name_fields()
            # #133: the FROM PROFILE GAMUT module exists only for a verification
            # target, and its panel state follows the run's profile.
            self._refresh_gamut_visibility()
            resolved = self._resolve_target_chart()
            if resolved is None:
                if self._shown_chart_ti2 is not None:
                    self._shown_chart_ti2 = None
                    self._shown_chart_stamp = None
                    self._preview.clear()
                    self._current_ti1_path = None
                    # Empty payload → main window drops the chart from Print / Measure.
                    self.chart_finished.emit([], None, False)
                # #130 (Knut beta-6): the empty preview must tell the user WHY it's
                # empty and how to fill it — this run/type simply has no chart yet.
                self._preview.set_notice(self._no_chart_guidance())
                return
            ti2, tiffs, ti1 = resolved
            stamp = self._chart_stamp(ti2)
            if stamp is not None and stamp == self._shown_chart_stamp:
                return                               # already showing this exact chart
            self._shown_chart_ti2 = ti2              # set first so the dedup is robust
            self._shown_chart_stamp = stamp
            kind = (tr("verification chart") if ctl.target.is_verification()
                    else tr("profiling chart"))
            self._log.appendPlainText(
                tr("Switched to this run's {kind}.").format(kind=kind))
            self._display_run_chart(ti2, tiffs, ti1)
        finally:
            # Note exactly which values the chart moved, so the write can tell
            # "the sidecar put this here" from "the user did". In `finally`
            # because this handler returns early down several paths -- a run
            # with no chart among them -- and a snapshot left lying around
            # would be compared against the NEXT target's screen.
            self._note_what_the_chart_imposed()
            self._settle_live_preview()

    @staticmethod
    def _chart_stamp(ti2) -> "tuple | None":
        """What makes a chart *this* chart on screen: its path AND when its
        ``.ti2`` was last written.

        The path alone is not enough. Restore Used Chart puts different bytes at
        the SAME path — same run, same stem — so a dedup that compares paths
        decides the chart is already showing and skips the reload. Knut, #130
        2026-07-29: *"pressing Restore Used Chart, I get a warning message
        (good), but the preview is not updated. I have to click NEXT and PREV
        buttons to get the screen to redraw preview."* Regenerating a chart into
        the same run has the same shape, and the overlay had exactly this bug in
        beta.75.
        """
        if ti2 is None:
            return None
        try:
            return (str(ti2), Path(ti2).stat().st_mtime_ns)
        except OSError:
            return (str(ti2), None)

    def _release_rebuild_guard(self) -> None:
        """Put the chart back if redrawing its pages changed it, and say so.

        Called AFTER the verification chart has been filed into
        ``verifications/`` — the build lays its files at the run root and
        ``adopt_run_chart_as_verify`` moves them across, so releasing the guard
        any earlier restores the bytes and then watches the move overwrite them
        again. That is exactly what happened on the first attempt at this fix.
        """
        guard, self._rebuild_guard = getattr(self, "_rebuild_guard", None), None
        if guard is None:
            return
        changed = guard.put_back()
        if not changed:
            return
        try:
            self._log.appendPlainText(tr(
                "Redrawing the pages would have changed the chart itself, so "
                "the restored chart has been put back exactly as it was. Your "
                "measurement still matches the chart file beside it. The pages "
                "shown here were drawn from a different layout — create the "
                "chart again in this tab if you need printable pages."))
        except Exception:      # noqa: BLE001 — never break a finished build
            log.warning("could not report the rebuild guard", exc_info=True)

    def _show_restored_chart_after_a_stop(self) -> None:
        """Put the run's own chart back on screen after a build was stopped.

        Best-effort and silent: the files are what matter, and a preview that
        cannot be redrawn is a cosmetic problem, not a reason to raise out of a
        finish handler.
        """
        try:
            run = self._file_mgr.project().current_run()
            tiffs = sorted(run.chart_tiffs())
            if tiffs:
                self._preview.load_tiff(list(tiffs))
                self._set_margin_chart(list(tiffs),
                                       run.chart_ti2 if run.chart_ti2.exists()
                                       else None)
            else:
                self._preview.clear()
                self._set_margin_chart([], None)
        except Exception:      # noqa: BLE001 — never break the finish handler
            log.debug("could not put the chart back on screen after a stop",
                      exc_info=True)

    def _on_generate_finished(self, tiffs: list[Path]) -> None:
        # Disarm the slow-chart watchdog and dismiss its dialog if it's still
        # open (targen finished/was swapped while the user was deciding).
        self._slow_watchdog.stop()
        if self._slow_dialog is not None:
            from ui.dialogs.slow_chart_dialog import SlowChartDialog
            self._slow_dialog.done(SlowChartDialog.WAIT)
        self._generate_btn.setEnabled(True)
        # One-shot flag: consumed by this run, don't carry over to the next.
        self._preconditioning_from_dialog = False
        self._precond_parent_run_id = None

        # Deliberate user cancel via the watchdog: report it plainly and skip
        # the generic "generation failed" error path below.
        if not tiffs and self._cancelled_by_user:
            self._cancelled_by_user = False
            self._log.appendPlainText(tr("Chart generation cancelled."))
            self._log.ensureCursorVisible()
            # A cancelled build owns nothing — see the note in `_on_generate`.
            self._layout_owned_by_build = False
            # …AND THE PREVIEW HAS TO CATCH UP WITH THE FILES. The chart that
            # was here has been put back on disk by now, but the preview was
            # cleared when the build started, so the panel said "NO PREVIEW"
            # over a run that has its chart — under a log line promising that
            # nothing was lost. Measured on screen; a tab round trip did not
            # fix it either.
            self._show_restored_chart_after_a_stop()
            return
        is_isis = self._is_isis_selected()
        # File stem is fixed by the folder layout ("chart" / "calibration").
        # Derive it from the actual page bitmaps so it's correct regardless of
        # which flow produced them; fall back to "chart" when none exist.
        if tiffs:
            m = re.match(r"(.+?)_\d+$", tiffs[0].stem)
            stem = m.group(1) if m else tiffs[0].stem
        else:
            stem = "chart"

        # #130: when the user chose Run type = Verification, move the just-
        # generated chart into the run's verifications/ folder as its shared
        # verify chart, then continue with the moved files (preview, meta,
        # sidecars and the chart_finished signal all use the verify paths).
        # Guarded — profiling generation is completely untouched.
        if tiffs and self._is_verification_target():
            try:
                run = self._file_mgr.project().current_run()
                new_ti2 = run.adopt_run_chart_as_verify()
                if new_ti2 is not None:
                    tiffs = run.verify_chart_tiffs()
                    stem = run.verify_stem
                    if getattr(self, "_pending_gamut_selection", None) is not None:
                        # A gamut chart already carries the profile — telling
                        # the user to print it through the profile would cause
                        # the one mistake nothing downstream can detect.
                        self._log.appendPlainText(tr(
                            "This chart was saved as the run's verification "
                            "chart (in the “verifications” folder). It already "
                            "has your profile applied — print it exactly as it "
                            "is, then measure it with the run type set to "
                            "Verification."))
                    else:
                        self._log.appendPlainText(tr(
                            "This chart was saved as the run's verification chart "
                            "(in the “verifications” folder). Print it through your "
                            "finished profile, then measure it with the run type set "
                            "to Verification."))
                    # #133: store the colorimetric reference beside the adopted
                    # chart (no-op unless this build came from the gamut module).
                    self._write_gamut_reference_after_adopt(new_ti2)
            except Exception:  # noqa: BLE001 — never break a finished generation
                log.warning("verify-chart adopt failed", exc_info=True)
            # A pending gamut selection is consumed by the adopt above; if the
            # adopt failed it must not leak into the NEXT build's reference.
            self._pending_gamut_selection = None
            # Put the profiling chart back at the run root — the verify chart now
            # lives only in verifications/, and the two must coexist (#130, Knut).
            self._restore_profiling_chart()
        else:
            # ONLY when the build produced no chart: it failed or was cancelled,
            # so the release further down (after the auto-tag) is never reached
            # and nothing else would free the guard.
            #
            # A SUCCESSFUL profiling build must not release it here. This branch
            # was written when a profiling build could never arm the guard, but
            # since beta.42 a profiling run keeps its own chart copy and the
            # redraw that follows Restore Used Chart arms the guard for it. This
            # point is BEFORE `_maybe_autotag_randomised`, which upgrades a
            # well-mixed fixed-order chart from CHART_ID to RANDOM_START — so
            # releasing here put the restored bytes back and then re-tagged them
            # a line later, and the restored chart came out marked as shuffled
            # when it had been laid out in fixed order. chartread reads those two
            # differently, so the run's measurement described a sheet that no
            # longer existed, silently. Exactly the beta.97 fault, on the
            # profiling path (#130, found while reproducing Knut's beta.98
            # report).
            if not tiffs:
                self._release_rebuild_guard()
            # A failed or non-verification build never writes a reference.
            self._pending_gamut_selection = None
            # The run root has already been cleared when a verification build
            # failed, so put the snapshot back rather than dropping it — a failed
            # verification chart must not cost the run its profiling work.
            self._restore_profiling_chart()

        # For i1iSis the load-bearing artifact is the TI1 from targen, not the
        # printtarg TIFF. Run the export off the TI1 so users still get their
        # patch-set files even if printtarg fails for an unrelated reason
        # (e.g. paper-size validation crash). work_dir is wherever the TI1 lives
        # — derive from tiffs when present, else from the current run folder.
        isis_export_ok = False
        if is_isis:
            work_dir = tiffs[0].parent if tiffs else self._file_mgr.project().current_run().dir
            isis_export_ok = self._export_for_i1profiler_and_notify(
                work_dir, stem, preview_available=bool(tiffs),
            )

        if tiffs:
            self._preview.set_notice(None)   # chart just made — drop any guidance
            self._preview.load_tiff(tiffs)
            log.info("Preview loaded: %d TIFF(s)", len(tiffs))
            ti2 = tiffs[0].parent / f"{stem}.ti2"
            # #130 Bug 1 (Knut): save this chart's printtarg fields with it, so
            # switching Run type later shows THIS chart's printtarg settings
            # (not the last preset's). Engine charts restore from their recipe
            # instead; this is the printtarg-chart counterpart.
            self._store_printtarg_fields_in_sidecar(ti2)
            # Record the chart's instrument + paper in the run's meta.json,
            # mirroring what the TI2 layout editor writes (see
            # workflow.ti2_relayout.save_editor_meta). The .ti2 carries these
            # too, but stamping them in meta.json keeps the run folder
            # self-describing. Read straight from the just-written .ti2 so it's
            # correct for every creation path (normal / prebuilt / from-.ti1).
            self._stamp_chart_meta(ti2)
            # Always leave the hand-off sidecars with the chart — the colour
            # list and the i1Profiler pair — so every generated chart is
            # self-contained for users who profile elsewhere, not only the i1iSis
            # flow (Knut). They go into the exports/ sub-folder (#127); works
            # for run folders and cal/ alike since the folder is derived from
            # wherever the chart was generated. The .cht comes from the build
            # itself (engine emit_cht / printtarg). Best-effort; the colour
            # list skips CMYK charts.
            try:
                from core.file_manager import exports_subdir
                from workflow.chart_exports import write_sidecars
                extras = write_sidecars(
                    ti2.with_suffix(".ti1"), exports_subdir(ti2.parent), stem,
                    also_shuffled=self._settings.get("export_shuffled_pxf", False))
                for e in extras:
                    self._log.appendPlainText(f"wrote {e.name}")
            except Exception:  # noqa: BLE001 — never block on the sidecars
                log.warning("chart sidecar export failed", exc_info=True)
            # If this chart was laid out in fixed order (-r "Preserve Patch
            # Order", e.g. a pre-shuffled generate-colour-sets / editor-recipe
            # layout) but its colours are actually well mixed, upgrade the tag so
            # chartread can read it bidirectionally — the same auto-tag the TI2
            # layout editor does on save. No-op for the common case (printtarg
            # randomises by default → already RANDOM_START).
            self._maybe_autotag_randomised(ti2)
            # AFTER the auto-tag, which is the last thing that writes to the
            # chart. Releasing the guard before it meant the bytes were put back
            # and then re-tagged a line later — the restored chart came out
            # marked RANDOM_START when it had been laid out in fixed order, and
            # chartread reads those two differently.
            self._release_rebuild_guard()
            # If the patch set leaves a notably under-filled last page (or spilled
            # onto a near-empty extra page), offer to edit the patch set (#93, Knut).
            self._maybe_warn_partial_last_page(ti2)
            # Remember the .ti1 backing this chart so the Save Preset dialog can
            # offer to attach it.
            ti1 = tiffs[0].parent / f"{stem}.ti1"
            self._current_ti1_path = ti1 if ti1.is_file() else None
            # Baseline the auto-preview signature to what we just rendered, so the
            # refresh this generation triggers doesn't immediately re-render.
            self._last_auto_sig = self._layout_signature()
            self._set_margin_chart(tiffs, ti2)
            # #79: arm the one-shot Guided→Manual transfer when this chart was
            # built in Guided mode, so opening Manual seeds the recipe used.
            self._guided_transfer_pending = (self._current_mode() == "guided")
            # Track the just-built chart so a later Run-type switch back to it
            # doesn't needlessly reload (#130).
            self._shown_chart_ti2 = ti2
            self._shown_chart_stamp = self._chart_stamp(ti2)
            # #130: default the shared bar to the run we just built into, so a
            # plain re-Generate OVERWRITES it instead of spuriously creating a new
            # run (the bar's empty default reads as "New run").
            self._default_bar_to_current_run()
            self.chart_finished.emit(tiffs, ti2, is_isis)
        else:
            self._set_margin_chart([], None)
            self._log.appendPlainText("[ERROR] Chart generation failed.")
            self._log.ensureCursorVisible()
            # When the i1iSis hand-off already succeeded the user doesn't need
            # a second failure dialog telling them printtarg crashed — the
            # popup we already showed explained that the preview is optional
            # and the workflow continues in i1Profiler.
            if not isis_export_ok:
                failure = self._creator.primary_failure()
                if failure is not None:
                    tool, _key, friendly = failure
                    title = (
                        "Chart Generation Failed (targen)"
                        if tool == "targen"
                        else "Chart Layout Failed (printtarg)"
                    )
                    InfoDialog(title, friendly, self, min_width=520).exec()
                elif self._creator.unmatched_failure() is not None:
                    # No pattern recognised the message — but the tool DID report
                    # one, and the user is still owed a word rather than an empty
                    # preview (Knut, #130 2026-07-30: printtarg refused his chart
                    # with "Input file doesn't contain two or three tables", which
                    # nothing here knew, so no window ever appeared).
                    #
                    # Gated on the tool having said something: a build that ends
                    # with no output at all — a cancel, or a caller driving this
                    # handler directly — has nothing to report, and a window
                    # saying "no further detail" would be noise. It also kept a
                    # test waiting forever on a modal nobody could dismiss.
                    raw = self._creator.unmatched_failure()
                    said = raw[1]
                    InfoDialog(
                        tr("The chart could not be built"),
                        tr("ChromIQ could not build this chart, so the preview "
                           "is empty. Your chart files and any measurement in "
                           "this run are untouched.\n\n"
                           "This is what the tool reported:\n\n{said}\n\n"
                           "If this happened just after “Restore Used Chart”, the "
                           "chart itself is safely back — only its printable "
                           "pages could not be redrawn, and you can create the "
                           "chart again in this tab when you need to print it."
                           ).format(said=said),
                        self, min_width=560).exec()
        # THE CHART THAT WAS JUST BUILT IS NOW THIS RUN'S OWN SETTINGS.
        #
        # §3 lists Generate Chart as a write event, and save_target_settings'
        # own docstring says so — but the target-change handler was its only
        # caller, so a build never told the store what it had used. The run kept
        # whatever layout was filed against it BEFORE, and the next target
        # change — which a build itself causes, by creating or re-aligning the
        # run — loaded that older layout straight back over the screen.
        #
        # Basti, 2026-08-16, opening the app, turning "Show helper markers" off
        # and picking the 84-patch Hand Held preset. Traced on his own settings
        # and project:
        #     7.475  build starts   7 columns, 6 mm left margin   (the preset)
        #     7.605  build finished
        #     7.9-8.6 the run's stored settings load, four times, putting
        #             17 columns and 14 mm back on screen
        #     9.358  the live preview rebuilds the chart from THAT
        # — "same amount of patches but less wide". The chart on disk was right
        # the whole time; the screen, and then the sheet, were rebuilt from a
        # layout the user had left behind.
        #
        # Writing here, before those loads run, makes them re-apply the values
        # that just built the chart instead of contradicting them. It is also
        # simply the truth: this run's chart was made with this layout.
        try:
            self.save_target_settings()
        except Exception:      # noqa: BLE001 — a failed write must not lose the chart
            log.warning("could not file the built chart's settings against its "
                        "run", exc_info=True)
        # RE-BASELINE LAST. The earlier baseline is taken part-way through this
        # handler, and everything after it — restoring the chart's own settings,
        # the margin inspector, the helper-marker controls — can still nudge the
        # layout signature. Any nudge made the live preview think the layout had
        # changed and re-render the chart that had just been drawn: the same
        # sheet twice, which is the "it loaded and immediately reloaded" Basti
        # saw even when the second chart looked right. Taking the fingerprint
        # once more, when the screen has actually settled, costs nothing and
        # leaves a real later edit still triggering a refresh.
        try:
            self._last_auto_sig = self._layout_signature()
        except Exception:      # noqa: BLE001
            pass
        # THE SHIELD LASTS EXACTLY AS LONG AS THE BUILD — AND NO LONGER.
        #
        # It is also cleared in _on_target_changed, but only AFTER that
        # handler's load, so a build that causes no target change (a plain
        # re-Generate, with the bar already on the run being built into) never
        # consumed it and left it armed. The next GENUINE run switch then
        # skipped the incoming run's module and Guided row, and the write that
        # followed filed the previous run's values onto it — §10 F3,
        # "ownership follows the selected target".
        #
        # Here, at the end of the handler, both branches arrive: a FAILED build
        # left it armed too, and a failure is exactly when the screen has no
        # claim to be the newer state.
        self._layout_owned_by_build = False

    # ------------------------------------------------------------------
    # Margin inspector
    # ------------------------------------------------------------------
    def _set_margin_chart(self, tiffs: "list[Path]", ti2: "Path | None") -> None:
        """Record the chart now in the preview and refresh the margin inspector."""
        self._margin_tiffs = list(tiffs or [])
        self._margin_ti2 = ti2 if (ti2 and Path(ti2).is_file()) else None
        self._update_margin_inspector()
        self._update_layout_info()

    def _onscreen_patch_total(self) -> "int | None":
        """Patch count of the chart currently in the preview (its .ti2
        NUMBER_OF_SETS), or None when nothing is generated. Lets the estimate lay
        out the SAME patches the on-screen chart has under the current settings,
        instead of a capacity-fill (#93, Knut beta-13: estimate pages were wrong
        for a loaded chart)."""
        ti2 = getattr(self, "_margin_ti2", None)
        if not ti2 or not getattr(self, "_margin_tiffs", None):
            return None
        try:
            import re
            m = re.search(r"NUMBER_OF_SETS\s+(\d+)",
                          read_text(Path(ti2), lenient=True))
            return int(m.group(1)) if m else None
        except Exception:
            return None

    def _predict_layout_info(self, geom, paper: str, pages_req: int,
                             npat: "int | None" = None) -> None:
        """Fill the Chart-layout-information panel with the engine's predicted
        grid (#93). With *npat* (the on-screen chart's patch count) the SAME
        patches are laid out under the current settings; otherwise a capacity-
        filled layout of *pages_req* pages is shown (the auto-count prediction)."""
        panel = getattr(self, "_layout_info_panel", None)
        if panel is None:
            return
        try:
            from workflow.layout_engine import geometry, papers
            w_mm, h_mm = papers.dimensions_mm(paper)
            per_sheet = geometry.patches_per_sheet(geom, w_mm, h_mm)
            if not per_sheet:
                panel.show_placeholder()
                return
            total = npat if npat else per_sheet * max(1, pages_req)
            lay = geometry.compute(geom, w_mm, h_mm, total)
            rows = lay.steps_in_pass
            n0 = min(lay.total_patches, lay.patches_per_page)
            cols = (n0 + rows - 1) // rows if rows else 0
            panel.set_estimate(total=lay.total_patches, rows=rows, cols=cols,
                               pages=lay.pages, patch_w=geom.pwid, patch_h=geom.plen,
                               page_patches=n0,
                               fillup=getattr(lay, "padding", None))
        except Exception:
            panel.clear_estimate()

    def _update_layout_info(self) -> None:
        """Fill the on-screen column of the Chart-layout-information panel from
        the previewed chart's .ti2 (patch count, strip grid) + page TIFFs (#93).
        The estimate column is driven separately by the live predictors."""
        panel = getattr(self, "_layout_info_panel", None)
        if panel is None:
            return
        show = bool(self._settings.get("layout_info_show", True))
        panel.setVisible(show)
        if not show:
            return
        tiffs = getattr(self, "_margin_tiffs", None)
        ti2 = getattr(self, "_margin_ti2", None)
        if not tiffs or not ti2:
            panel.clear_actual()
            return
        try:
            import re
            from core.strip_utils import parse_passes_per_page
            txt = read_text(Path(ti2), lenient=True)
            total = int(re.search(r"NUMBER_OF_SETS\s+(\d+)", txt).group(1))
            _m = re.search(r'STEPS_IN_PASS\s+"?(\d+)"?', txt)
            rows = int(_m.group(1)) if _m else 0
            passes = parse_passes_per_page(ti2) or []
            idx = self._preview.current_page()
            if not (0 <= idx < len(passes)):
                idx = 0
            cols = passes[idx] if passes else 0
            pw, ph = self._chart_patch_size_mm(ti2)
            # Patches on the SHOWN page: full passes are `rows` tall; the chart's
            # last pass may be partial, so cap by the remaining count (#93, Knut).
            before = rows * sum(passes[:idx]) if passes else 0
            page_patches = (min(rows * cols, total - before)
                            if rows and cols else None)
            # Fill-up count = laid-out total minus the designed patch count (the
            # .ti1 next to the .ti2): a partial last strip is topped up with
            # paper-white patches, and this row is where Knut read the grown
            # total without an explanation (#124 follow-up).
            designed = _number_of_sets(Path(ti2).with_suffix(".ti1"))
            fillup = (total - designed
                      if designed is not None and 0 <= total - designed else None)
            panel.set_actual(total=total, rows=rows, cols=cols, pages=len(tiffs),
                             patch_w=pw, patch_h=ph, page_patches=page_patches,
                             fillup=fillup)
        except Exception:
            panel.clear_actual()

    @staticmethod
    def _chart_patch_size_mm(ti2: "Path") -> "tuple[float, float]":
        """Patch (width, height) in mm of the previewed chart, from its engine
        ``channels.json`` patch rects (px → mm). (0, 0) for printtarg charts /
        when unavailable (#93)."""
        try:
            import json
            sidecar = Path(ti2).with_suffix(".channels.json")
            if not sidecar.is_file():
                return (0.0, 0.0)
            doc = json.loads(read_text(sidecar))
            layout = doc.get("layout") or {}
            rects = layout.get("patches") or []
            recipe = layout.get("recipe") or {}
            # The rects are in the pixel space `layout["dpi"]` describes, so
            # that is the only dpi that converts them. `recipe["dpi"]` is the
            # requested render dpi and a derived layout has no recipe at all;
            # NEVER guess 300 — an unknown dpi means an unknown size, and the
            # panel already renders that honestly as "—".
            dpi = float(layout.get("dpi") or recipe.get("dpi") or 0)
            if not rects or dpi <= 0:
                return (0.0, 0.0)
            r0 = rects[0]
            return (r0["w"] * 25.4 / dpi, r0["h"] * 25.4 / dpi)
        except Exception:
            return (0.0, 0.0)

    def _chart_is_hexagonal(self) -> bool:
        """True for a SpectroScan chart drawn with six-sided patches.

        **Read from the live selectors, not from a stored setting.** Knut,
        beta.5 (#152): *"When instrument is SpectroScan and Patch shape is
        Hexagonal, the checkbox for 'Show helper markers' with its spinboxes and
        belonging labels are not greyed with explanation tool-tip, as
        specified."* The reason was that this asked ``chart_instrument`` in
        Preferences, which describes the last chart that was *built* — pick
        SpectroScan and Hexagonal in the Create Chart selectors and that stored
        value still says i1, so the controls stayed live on a chart that cannot
        have markers. The combos on screen are the only honest answer to "what
        is selected", and they are what ``_warn_if_hexagonal_selected`` already
        uses, so the two now agree.
        """
        try:
            panel = getattr(self, "_manual_layout_panel", None)
            if panel is None:
                return False
            # Any hex-CAPABLE instrument, asked of the geometry rather than
            # matched against a list of names: #152's rule (a honeycomb has no
            # rows to line a ruler against, so the markers are suppressed)
            # follows the SHAPE, not the device. The CR30 is simply the first
            # instrument after the SpectroScan to build one (#159).
            from workflow.layout_engine.instruments import hex_capable
            if panel.instr is not None and panel.mode is not None:
                return (hex_capable(panel.instr.currentData() or "")
                        and panel.mode.currentData() == "hex")
            # No selectors on this panel (the editor's cut-down variant) — fall
            # back to the recipe, where hflag is the hex/flat switch.
            rec = panel.get_recipe()
            return (hex_capable(str(getattr(rec, "instrument", "")))
                    and bool(getattr(rec, "hflag", False)))
        except Exception:      # noqa: BLE001
            return False

    def _update_margin_inspector(self) -> None:
        panel = getattr(self, "_margin_panel", None)
        if panel is None:
            return
        tiffs = getattr(self, "_margin_tiffs", None)
        show = bool(self._settings.get("margin_inspector_show", True))
        panel.setVisible(show)
        # #152: a hexagonal SpectroScan chart has no straight rows or columns
        # for a ruler, so the marker controls grey out with the reason showing
        # in both the hover tooltip and the ⓘ, rather than silently doing
        # nothing (Knut: "greyed out with explanation in tool-tip and in help
        # icon").
        self._refresh_helper_marker_support()
        # The ruler dashes follow whatever chart and page are on screen, so they
        # are refreshed here as well as on the checkbox (#152).
        self._refresh_helper_marker_overlay()
        if not show or not tiffs:
            panel.show_placeholder()
            self._preview.set_margin_guides(None)
            self._preview.set_measured_guides(None)
            return

        from workflow.margin_inspector import measure_margins, check_violations
        from core.settings import margin_combo_key

        # ChromIQ always renders with printtarg -M (the margin is kept inside the
        # TIFF), so the page TIFF already spans the full sheet — the TIFF's own
        # size is the page. Do NOT pass a paper size here: the Create Chart paper
        # combo can be stale relative to the chart actually in the preview (e.g.
        # after loading a preset), and a wrong paper size would inflate every
        # measured margin by the bogus (paper − tiff)/2 offset (#83).
        dpi = float(self._settings.get("printtarg_dpi", 300) or 300)
        # Measure the page CURRENTLY SHOWN in the preview, so the numbers, the
        # threshold guides and the visible patches all describe the same page.
        # Multi-page charts have different per-page margins, so measuring a
        # different page than the one on screen made the guides land away from
        # the patches (#83). Re-runs when the user pages through (page_changed).
        idx = self._preview.current_page()
        if not (0 <= idx < len(self._margin_tiffs)):
            idx = 0
        # Engine charts: report EXACT margins/patch size from the recorded
        # geometry (channels.json) instead of detecting them from the image —
        # the image detector mis-reads the patch width as the strip pitch and a
        # large Strip gap corrupts the detected margins (#93, Knut). Falls back to
        # image measurement for printtarg charts.
        self._ruler_over_mm = None
        _geom_ruler = None
        report = None
        if self._margin_ti2 is not None:
            from workflow.margin_inspector import measure_from_engine
            ch = Path(self._margin_ti2).with_suffix(".channels.json")
            eng = measure_from_engine(ch, idx) if ch.is_file() else None
            if eng is not None:
                report, _geom_ruler = eng
        if report is None:
            report = measure_margins(self._margin_tiffs[idx], dpi=dpi,
                                     ti2_path=self._margin_ti2)
        if report is None:
            panel.show_placeholder()
            self._preview.set_margin_guides(None)
            self._preview.set_measured_guides(None)
            return

        # An engine chart records the instrument it was actually laid out for.
        # Trust that over the printtarg -i widget, which is hidden and stale
        # while the layout engine is on — reading it there fell back to "i1" and
        # judged a ColorMunki chart against i1Pro's margins (Knut, #130
        # 2026-07-27).
        instr_flag = self._chart_instrument_flag() or self._active_instrument_flag()
        instr_label = _MARGIN_INSTR_LABEL.get(instr_flag, "i1Pro")
        paper_name = _canonical_paper_name(report.page_w_mm, report.page_h_mm)
        orient = "Landscape" if report.page_w_mm > report.page_h_mm else "Portrait"
        # Which minimums this chart is judged against (Knut, #130 2026-07-27).
        # With "Use instrument margins" ON: the per-instrument minimums from
        # Preferences. With it OFF: the margins the chart was actually laid out
        # to — the user still wants to know when a printed margin came out
        # under what they asked for; they only declined the instrument's
        # guideline, not the check itself.
        thresholds = self._chart_own_margins()
        if thresholds is None and paper_name:
            key = margin_combo_key(instr_label, paper_name, orient)
            thresholds = self._settings.get_margin_thresholds().get(key)

        # Strip-length (ruler) limit: the per-combo value configured in
        # Preferences → Instrument Limits wins; else the instrument's built-in ruler
        # reported by the engine geometry (#93, Knut). Warn when the strip is over.
        _eff_ruler = _geom_ruler
        try:
            _cfg = float((thresholds or {}).get("ruler") or 0.0)
            if _cfg > 0:
                _eff_ruler = _cfg
        except (TypeError, ValueError):
            pass
        if (_eff_ruler and report.strip_length_mm is not None
                and report.strip_length_mm > _eff_ruler + 0.5):
            self._ruler_over_mm = _eff_ruler

        violations = check_violations(report, thresholds)
        warns = self._engine_text_overflow_warnings()
        if getattr(self, "_ruler_over_mm", None):
            warns = list(warns) + [tr(
                "⚠ Strip length {len:.0f} mm exceeds the {ruler:.0f} mm "
                "instrument ruler — the strip may not fit your jig").format(
                    len=report.strip_length_mm or 0.0, ruler=self._ruler_over_mm)]
        panel.update_report(
            report, violations,
            thresholds_defined=bool(thresholds),
            notify=bool(self._settings.get("margin_violation_notify", True)),
            thresholds=thresholds,
            text_warnings=warns,
        )
        self._refresh_margin_guides(report, thresholds, violations)
        self._refresh_measured_guides(report)

    def _refresh_measured_guides(self, report) -> None:
        """Push long purple/blue lines at the measured margins (patch-area edges)
        to the preview, when the second checkbox is on (#89)."""
        panel = getattr(self, "_margin_panel", None)
        if panel is None or not panel.measured_guides_enabled() or report is None:
            self._preview.set_measured_guides(None)
            return
        pw, ph = report.page_w_mm, report.page_h_mm
        guides: list[tuple[str, float]] = []
        if pw > 0:
            guides.append(("v", report.left_mm / pw))
            guides.append(("v", 1.0 - report.right_mm / pw))
        if ph > 0:
            guides.append(("h", report.top_mm / ph))
            guides.append(("h", 1.0 - report.bottom_mm / ph))
        self._preview.set_measured_guides(guides or None)

    def _engine_text_overflow_warnings(self) -> "list[str]":
        """Warnings for when a page margin is too small to hold the text band that
        side carries (margins are the law, so the text overflows toward the page
        edge — flag it below the preview, by the margin violations) (#93, Knut).
        Engine-Manual only; empty otherwise."""
        warns: list[str] = []
        try:
            manual = (self._manual_btn is not None and self._manual_btn.isChecked())
            if not (manual and getattr(self, "_manual_layout_panel", None) is not None
                    and bool(self._settings.get("use_chromiq_layout_engine", False))):
                return warns
            r = self._current_layout_recipe()
            from workflow.layout_engine import instruments
            geom = instruments.geom_from_build_kwargs(r.build_kwargs())
            # THE MARGIN WE MOVED, SAID OUT LOUD — and it is said in BOTH
            # layout modes, because the raise happens in both.
            #
            # `raster.apply_row_label_geometry` raises the left margin to
            # `floor + band + 1 mm` so the row labels have somewhere to live
            # (§R1.5). Measured on beta 6: a typed 26 mm resolved to 33.03, a
            # typed 10 mm to 33.64, 6 to 14.38, 4 to 8.95 — and NOTHING on
            # screen said so. The design document even claimed "the panel says
            # so", which was simply untrue. A silently moved margin is the
            # user's own setting being overruled, so it is reported here, with
            # the two numbers the raise is made of, next to the margins it
            # changed.
            _asked_l = float(getattr(r, "margin_left", 0.0) or 0.0)
            _got_l = float(getattr(geom, "margin_l", 0.0) or 0.0)
            _floor_l = float(getattr(geom, "row_label_floor", 0.0) or 0.0)
            _raised_l = bool(geom.rlwi > 0 and _got_l > _asked_l + 0.05)
            if _raised_l:
                warns.append(tr(
                    "⚠ The left margin was widened from {asked:.1f} mm to "
                    "{got:.1f} mm to fit the row indicators. The labels start "
                    "{floor:.1f} mm in from the page edge (the larger of "
                    "“Clip” under “Text distance from edge” and the width of "
                    "the clip border) and their text needs {band:.1f} mm. To "
                    "get that paper back, switch “Show row indicators” off, "
                    "use a smaller label size, or reduce “Clip”.").format(
                        asked=_asked_l, got=_got_l, floor=_floor_l,
                        band=geom.rlwi))
            # The text-overflow warning only applies in "margins are law" mode,
            # which is now AREA-FIRST (Knut #93): there the label/text lives inside
            # the margin, so a too-small margin overflows toward the page edge. In
            # patch-first the band is reserved above/below the patches — no overflow.
            if r.layout_mode != "area_first":
                return warns
            lab = geom.label_band_mm if geom.label_band_mm >= 0 else geom.txhisl
            if r.show_strip_indicators and lab > 0 and \
                    r.margin_top + 0.05 < r.text_edge_top_mm + lab:
                warns.append(tr("⚠ Top margin is too small for the strip labels — "
                                "they overflow toward the page edge."))
            # …AND THE ROW NUMBERS DOWN THE LEFT, the same rule one edge over.
            # Area-first no longer reserves their 7.5 mm band outside the margin
            # (that was the fault Basti reported: a 1 mm margin put the first
            # patch at 8.5 mm), so with a small left margin the numbers slide
            # into the margin and clamp at the paper edge -- where they can end
            # up under the patches. The patches are where he asked for them;
            # this says what it cost.
            # TWO BANDS, BECAUSE THE OUTCOMES DIFFER. Keying this on the full
            # 7.5 mm band cried wolf: measured on a real CR30 hex chart, the
            # row numbers are perfect from 2 mm, keep about 80 % of each digit
            # at 1 mm, and are gone entirely at 0. A warning that fires at 5 mm
            # where nothing is wrong teaches the user to ignore it, and one
            # that says "may sit under the patches" at 0 mm understates a
            # number that is not there at all.
            # …AND NOT WHEN THE MARGIN WAS RAISED, which is every chart that
            # asked for less than the labels need. Measured on beta 6: with a
            # typed left margin of 1 mm the geometry resolves to 8.95 / 14.38 /
            # 33.03 mm on Knut's three presets and the labels print perfectly
            # — while this warning said "the patches will cover part of each
            # one" on a page where nothing of the sort happens. A warning that
            # fires while the user is looking at the thing working is how
            # people learn to ignore warnings. The raise itself is reported
            # above; these two describe what happens when there is no raise.
            if geom.rlwi > 0 and not _raised_l and r.margin_left < 0.5:
                warns.append(tr(
                    "⚠ There is no room for the row indicators down the left, "
                    "so they will not be printed. Give the left margin about "
                    "2 mm to get them back."))
            elif geom.rlwi > 0 and not _raised_l and r.margin_left + 0.05 < 2.0:
                warns.append(tr(
                    "⚠ The left margin is tight for the row indicators, so the "
                    "patches will cover part of each one. About 2 mm prints "
                    "them cleanly."))
            # THE NUMBERS AND THE CLIP BAND WANT THE SAME PAPER.
            #
            # "Fill the page" deliberately stops reserving the 7.5 mm band
            # (geometry.py: `_rlwi = 0.0 if g.fill_beyond_ruler`), because the
            # margin is the law for the PATCHES there. The numbers are then
            # drawn growing LEFT from the first patch — straight into the clip
            # border or the notes band when the chart has one on that edge, so
            # the digits print on top of whatever is written there. Nothing is
            # lost and no patch moves, so this is a warning and not a refusal;
            # switching to "Prioritise patch size" reserves the band again.
            # …AND ONLY WHEN SOMETHING IS ACTUALLY PRINTED THERE. With the clip
            # content switched off the strip is empty, nothing is pasted over
            # the digits and they come out perfectly — measured, 96,313 dark
            # pixels in the left 20 mm against 0 with notes on. Warning there
            # tells the user a feature is broken while they are looking at it
            # working, which is the fastest way to teach them to ignore
            # warnings.
            # …AND ONLY WHEN THE LABELS REALLY ARE UNDER THE BORDER. The band's
            # floor is now the WIDTH of the clip border on this edge, and the
            # left margin is raised to hold the band beside it, so on these
            # charts the numbers print clear of the border and this warning is
            # simply untrue. Measured on Knut's own
            # `i1Pro-A4-162p-1page-Portrait-w7.5mm` (fill-the-page, a 26 mm
            # left border, notes on): the labels print at 27.3 to 32.8 mm, and
            # the panel said they would not appear at all. Asking whether the
            # floor actually clears the border keeps the message for the day it
            # is true again instead of deleting a guard.
            _border_w = (float(getattr(r, "clip_border_width_mm", 0.0) or 0.0)
                         if getattr(r, "clip_border", False) else 0.0)
            if geom.rlwi > 0 and geom.fill_beyond_ruler and geom.lbord > 0 \
                    and _floor_l + 0.05 < _border_w \
                    and r.clip_content_mode != "off" \
                    and (getattr(geom, "clip_side", "left") or "left") == "left":
                warns.append(tr(
                    "⚠ The row indicators will not appear on this chart. "
                    "“Prioritise chart area, then fit patches to it” gives "
                    "their space to the patches, so they are drawn where the "
                    "clip border is and the clip border is printed over them. "
                    "Switch to “Prioritise patch size, then fit to page” to "
                    "get them back, or put the clip border on the right."))
            nlines = (1 if r.chart_text else 0) + (1 if r.stamp_command else 0)
            if nlines and r.margin_bottom + 0.05 < r.text_edge_mm + 4.2 * nlines:
                warns.append(tr("⚠ Bottom margin is too small for the sheet text — "
                                "it overflows toward the page edge."))
        except Exception:  # noqa: BLE001 — never block the inspector on this
            pass
        return warns

    def _refresh_margin_guides(self, report, thresholds, violations) -> None:
        """Push dotted threshold guide lines to the preview (or clear them)."""
        panel = getattr(self, "_margin_panel", None)
        if panel is None or not panel.guides_enabled() or not thresholds:
            self._preview.set_margin_guides(None)
            return
        violated = {v.edge for v in violations}
        guides: list[tuple[str, float, bool]] = []
        # (key, edge, axis, page-extent, measured-from-start)
        specs = (
            ("L", "Left", "v", report.page_w_mm, True),
            ("R", "Right", "v", report.page_w_mm, False),
            ("T", "Top", "h", report.page_h_mm, True),
            ("B", "Bottom", "h", report.page_h_mm, False),
        )
        for key, edge, axis, extent, from_start in specs:
            raw = thresholds.get(key)
            if raw in (None, "") or not extent:
                continue
            try:
                thr = float(raw)
            except (TypeError, ValueError):
                continue
            frac = (thr / extent) if from_start else (1.0 - thr / extent)
            guides.append((axis, frac, edge in violated))
        self._preview.set_margin_guides(guides or None)

    def _on_margin_guides_toggled(self, on: bool) -> None:
        self._settings.set("margin_guides_show", bool(on))
        self._update_margin_inspector()

    def _on_margin_measured_guides_toggled(self, on: bool) -> None:
        self._settings.set("margin_measured_guides_show", bool(on))
        self._update_margin_inspector()

    def _remember_helper_markers(self) -> None:
        """Keep the ruler-marker choice as the default for the next chart, and
        redraw the preview overlay with it (#152, moved by #158).

        The controls are ordinary layout controls now, so the values reach the
        renderer through the recipe like everything else — this only persists
        them and updates the overlay, which is what lets the two distances be
        judged while they are being nudged rather than after a rebuild.
        """
        panel = getattr(self, "_manual_layout_panel", None)
        if panel is None or not hasattr(panel, "helper_markers_cb"):
            return
        try:
            self._settings.set("helper_markers_show",
                               bool(panel.helper_markers_cb.isChecked()))
            self._settings.set("helper_marker_edge_mm",
                               float(panel.helper_marker_edge.value()))
            self._settings.set("helper_marker_len_mm",
                               float(panel.helper_marker_len.value()))
            self._settings.set("helper_marker_per_patch",
                               int(panel.helper_marker_per_patch.value()))
            self._settings.set("helper_markers_top_bottom",
                               bool(panel.helper_markers_top_bottom.isChecked()))
            self._settings.set("helper_markers_sides",
                               bool(panel.helper_markers_sides.isChecked()))
            self._refresh_helper_marker_overlay()
        except Exception:      # noqa: BLE001 — never break the tab on a toggle
            log.warning("could not remember the helper-marker choice",
                        exc_info=True)

    def _seed_helper_markers_from_prefs(self) -> None:
        """Start a session on the ruler-marker values the last chart used."""
        panel = getattr(self, "_manual_layout_panel", None)
        if panel is None or not hasattr(panel, "helper_markers_cb"):
            return
        try:
            for w, v in (
                (panel.helper_markers_cb,
                 bool(self._settings.get("helper_markers_show", False))),
                (panel.helper_marker_edge,
                 float(self._settings.get("helper_marker_edge_mm", 2.0) or 2.0)),
                (panel.helper_marker_len,
                 float(self._settings.get("helper_marker_len_mm", 2.0) or 2.0)),
                (panel.helper_marker_per_patch,
                 int(self._settings.get("helper_marker_per_patch", 3) or 3)),
                (panel.helper_markers_top_bottom,
                 bool(self._settings.get("helper_markers_top_bottom", True))),
                (panel.helper_markers_sides,
                 bool(self._settings.get("helper_markers_sides", True))),
            ):
                w.blockSignals(True)
                if hasattr(w, "setChecked"):
                    w.setChecked(v)
                else:
                    w.setValue(v)
                w.blockSignals(False)
        except Exception:      # noqa: BLE001
            log.debug("could not seed the helper-marker controls", exc_info=True)

    def _set_engine_recipe(self, recipe) -> None:
        """Apply *recipe* to the Manual layout panel **and to the controls that
        show part of it elsewhere on screen**.

        The ruler helper markers are a layout setting like any other, but their
        on-screen controls do not live in the layout panel — the tick box and the
        two distances sit under the preview, in "Measured from Preview", because
        that is where a ruler is judged. So ``set_recipe`` alone leaves them
        showing the previous chart's values: Basti, 2026-08-16, on Knut's
        ColorMunki presets — *"loading knuts presets with the helper markers
        turned on did not set the show helper markers option there."* The chart
        was built with markers; only the tick box disagreed.

        Every path that loads a recipe — a built-in preset, a user preset, a
        chart loaded from disk, a carry-back from the patch-set editor, the
        restored session — goes through here, so none of them can drift again.
        """
        panel = getattr(self, "_manual_layout_panel", None)
        if panel is None:
            return
        panel.set_recipe(recipe)


    def _refresh_helper_marker_support(self, *_a) -> None:
        """Grey (or restore) the ruler-marker controls for the current selection.

        Runs on every layout change as well as on a chart/page change, so
        choosing SpectroScan + Hexagonal explains itself at the moment it is
        chosen (#152).
        """
        panel = getattr(self, "_manual_layout_panel", None)
        if panel is None or not hasattr(panel, "set_helper_markers_supported"):
            return
        try:
            panel.set_helper_markers_supported(not self._chart_is_hexagonal())
        except Exception:      # noqa: BLE001 — never block the inspector
            log.debug("could not set helper-marker availability", exc_info=True)

    def _refresh_helper_marker_overlay(self) -> None:
        """Draw (or clear) the ruler dashes over the chart now in the preview.

        The geometry comes from the chart's OWN recorded layout
        (``channels.json``) whenever there is one, not from the Create Chart
        controls — those can describe a chart the user is about to build rather
        than the one on screen, and dashes that do not line up with the visible
        patches would defeat the point of showing them. A printtarg chart has no
        recorded layout, so it gets no overlay.
        """
        prev = getattr(self, "_preview", None)
        if prev is None:
            return
        try:
            got = self._helper_marker_lines_frac()
            lines, pending = got if got is not None else (None, False)
        except Exception:      # noqa: BLE001 — an overlay is never fatal
            # WARNING, not DEBUG: this handler once hid a real fault (the #158
            # move left this reading a control that no longer existed, and the
            # dashes silently stopped appearing — the exact symptom Knut
            # reported for #152). A swallowed error that changes what is on
            # screen has to leave a trace somebody will actually see.
            log.warning("helper-marker overlay skipped", exc_info=True)
            lines, pending = None, False
        prev.set_helper_markers(lines, pending=pending)

    #: The marker settings that decide whether the overlay matches the sheet.
    _HM_KEYS = ("helper_markers", "helper_marker_edge_mm", "helper_marker_len_mm",
                "helper_marker_per_patch", "helper_markers_top_bottom",
                "helper_markers_sides")

    def _helper_marker_lines_frac(
        self,
    ) -> "tuple[list[tuple[float, float, float, float]], bool] | None":
        """The marker segments for the page on screen, as page fractions, plus
        whether they are still only a PROPOSAL.

        THE SHEET ALREADY HAS DASHES ON IT, AND THEY DO NOT MOVE WHEN A SPIN BOX
        DOES. That is what made Knut count dashes that the geometry cannot
        produce (#164, 2026-08-23): *"When 4, then there are actually 5, and the
        three within the patch area are not distributed evenly … When 6, then
        there are 7."* A sheet generated at 3 markers per patch carries the
        3-comb in its ink for ever; raising the spin box to 4 drew the 4-comb
        over the top of it, and the sheet on screen then showed the UNION of the
        two — 5 dashes per patch for 4, 7 for 6, unevenly spaced, and exactly
        even at 5 because the 3-comb is a subset of the 5-comb. Every number he
        reported falls out of that arithmetic.

        So the overlay still follows the controls — that is the whole point of
        it, and this docstring's predecessor was right that a rebuild after
        every nudge is no way to judge a distance. What was missing is that it
        must SAY when it is showing something the sheet does not have yet. The
        second return value is True exactly then, and the preview draws those
        dashes in the accent colour with a caption instead of in printed black.
        """
        # The controls moved into the Manual layout panel in #158, so in MANUAL
        # the values come from there. They are read off the CONTROLS rather than
        # the chart's recorded layout on purpose: the overlay is what lets the
        # two distances be judged while they are being nudged, before anything
        # is rebuilt.
        panel = getattr(self, "_manual_layout_panel", None)
        if panel is None or not hasattr(panel, "helper_markers_cb"):
            return None
        if not getattr(self, "_margin_tiffs", None) or self._margin_ti2 is None:
            return None
        if self._chart_is_hexagonal():
            return None
        from workflow.layout_engine.presets import LayoutRecipe
        from workflow.layout_engine import instruments, geometry, papers
        ch = Path(self._margin_ti2).with_suffix(".channels.json")
        rec = LayoutRecipe.from_channels_json(ch)
        if rec is None:
            return None                      # printtarg chart — no engine layout

        # GUIDED HAS NO MARKER CONTROLS, SO IT HAS NOTHING TO PROPOSE.
        #
        # The six values below live only in the Manual layout panel, but the
        # SETTING behind them (`helper_markers_show`) is global and is written
        # from exactly one place — that same panel. Guided read it anyway and
        # compared it against the sheet, so a Guided chart drew the accent-colour
        # overlay with the caption "Markers not on this sheet yet — press
        # Generate Chart", naming a control the user cannot reach in that mode.
        #
        # Worse, the caption could not be obeyed: `_engine_build_kwargs` never
        # asks for markers, so every Guided recipe records `helper_markers:
        # false` and pressing Generate Chart rebuilt the same markerless sheet.
        # The pending state was therefore permanent (Sebastian, 2026-08-26;
        # present since be85d7e5, 2026-06-30 — it was merely invisible while
        # `chart_left_clip_info` dropped Guided onto printtarg, which records no
        # layout and so drew no overlay at all).
        #
        # In Guided the sheet is the only truth: show what it actually carries,
        # and never claim a proposal. Keyed on the MODE, not on
        # `panel.isVisible()` — that is False whenever Create Chart is not the
        # current tab, which would flip the data source with the visible tab.
        # `_current_mode()`, NOT `_manual_btn.isChecked()`. The FROM PROFILE
        # GAMUT module is the Manual PAGE with the targen group swapped out
        # (`_switch_mode`), so its layout panel — marker controls included — is
        # on screen and enabled, and `_on_generate_gamut` hands the build to
        # `_generate_from_ti1` with Manual's layout settings. A proposal made
        # there IS obeyable. But that module leaves the mode BUTTON unchecked,
        # so keying on the button froze the overlay on the previous sheet's
        # markers: unticking "Print helper markers" or raising markers-per-patch
        # changed nothing on screen. `_current_mode()` asks which PAGE is
        # showing, which is the real question; `_mode_name()` is the one that
        # distinguishes the module and is deliberately not used here.
        manual = self._current_mode() == "manual"
        if manual:
            on = bool(panel.helper_markers_cb.isChecked())
            edge_mm = float(panel.helper_marker_edge.value())
            len_mm = float(panel.helper_marker_len.value())
            per_patch = int(panel.helper_marker_per_patch.value())
            top_bottom = bool(panel.helper_markers_top_bottom.isChecked())
            sides = bool(panel.helper_markers_sides.isChecked())
        else:
            on = bool(getattr(rec, "helper_markers", False))
            edge_mm = float(getattr(rec, "helper_marker_edge_mm", 0.0) or 0.0)
            len_mm = float(getattr(rec, "helper_marker_len_mm", 0.0) or 0.0)
            per_patch = int(getattr(rec, "helper_marker_per_patch", 0) or 0)
            top_bottom = bool(getattr(rec, "helper_markers_top_bottom", False))
            sides = bool(getattr(rec, "helper_markers_sides", False))
        if not on:
            return None
        m = re.search(r"NUMBER_OF_SETS\s+(\d+)",
                      read_text(Path(self._margin_ti2), lenient=True))
        if not m:
            return None
        # THE SAME KWARGS THE RENDERER USED, INCLUDING THE PATCH COUNT.
        #
        # `build_kwargs()` does not carry `area_target_count` — `chart.build_chart`
        # injects it from the .ti1 it is building (chart.py:230), and area-first
        # sizes the patches to FILL the page with exactly that many. Every
        # default recipe is area-first, so without it this rebuilt a geometry
        # that could be nothing like the one on paper: measured on a 480-patch
        # ColorMunki sheet, 19 dashes at a 15.8 mm pitch here against 285 at
        # 1.0 mm there. That was survivable while the overlay only ever offered
        # itself as a guide; it is not survivable now that a matching overlay
        # positively claims to BE the ink on the sheet. The count is the one the
        # .ti2 in front of us declares.
        kwargs = rec.build_kwargs()
        kwargs["area_target_count"] = int(m.group(1))
        geom = instruments.geom_from_build_kwargs(kwargs)
        w_mm, h_mm = papers.dimensions_mm(rec.paper)
        if w_mm <= 0 or h_mm <= 0:
            return None
        lay = geometry.compute(geom, w_mm, h_mm, int(m.group(1)))
        lines = geometry.helper_marker_lines_mm(
            geom, w_mm, h_mm, lay, edge_mm=edge_mm, length_mm=len_mm,
            per_patch=per_patch, top_bottom=top_bottom, sides=sides)
        wanted = (True, edge_mm, len_mm, per_patch, top_bottom, sides)
        printed = tuple(getattr(rec, k) for k in self._HM_KEYS)
        # Floats come from spin boxes on both sides, so compare them as the user
        # sees them (0.1 mm) rather than bit for bit.
        pending = manual and not (bool(printed[0]) == wanted[0]
                                  and abs(float(printed[1]) - edge_mm) < 0.05
                                  and abs(float(printed[2]) - len_mm) < 0.05
                                  and int(printed[3]) == per_patch
                                  and bool(printed[4]) == top_bottom
                                  and bool(printed[5]) == sides)
        # `manual and …` is belt AND braces. In Guided the six values above were
        # read straight off `rec`, so this comparison already collapses to False
        # — but it compares floats, and a caption that tells the user to press a
        # button which cannot change anything must not be one rounding away from
        # coming back. Guided has no proposal to make, so it never has one.
        return ([(x0 / w_mm, y0 / h_mm, x1 / w_mm, y1 / h_mm)
                 for x0, y0, x1, y1 in lines], pending)

    def _on_margin_coords_toggled(self, on: bool) -> None:
        self._settings.set("margin_coords_show", bool(on))
        self._preview.set_coord_readout(
            bool(on), float(self._settings.get("printtarg_dpi", 300) or 300))

    def _chart_own_margins(self) -> "dict | None":
        """The margins this chart was laid out to, when it declined the
        instrument's minimums — otherwise None, so the caller falls back to
        Preferences (Knut, #130 2026-07-27).

        Returned in the same shape as a Preferences threshold row, so the panel
        compares and reports it identically.
        """
        try:
            import json
            if self._margin_ti2 is None:
                return None
            ch = Path(self._margin_ti2).with_suffix(".channels.json")
            if not ch.is_file():
                return None
            layout = json.loads(read_text(ch)).get("layout") or {}
            recipe = layout.get("recipe")
            if not isinstance(recipe, dict):
                return None
            # NOBODY CHOSE A GUIDED CHART'S MARGINS, and the 6/6/6/6 in its
            # recipe is not what the sheet was laid out to — it is the
            # LayoutRecipe dataclass default. The engine is handed the
            # instrument's own border (10 mm for the i1Pro), and the realised
            # margins are an output of the layout (i1Pro/A4: 10/10/41.58/24.57).
            # `use_instrument_margins: false` beside those numbers is a default
            # too, not a user declining the guideline — Guided has no such
            # control. Reading it as a decision silenced the jig check on 112 of
            # 384 Guided combinations. See `ChartCreator._embed_layout_geometry`.
            # `is False`, not falsy: only a chart that positively declares the
            # provenance is re-judged, so charts written by earlier versions
            # keep the behaviour they were built with.
            if layout.get("margins_chosen_by_user") is False:
                return None            # judged against the instrument instead
            if recipe.get("use_instrument_margins", True):
                return None            # judged against the instrument instead
            return {
                "L": float(recipe.get("margin_left", 0.0)),
                "R": float(recipe.get("margin_right", 0.0)),
                "T": float(recipe.get("margin_top", 0.0)),
                "B": float(recipe.get("margin_bottom", 0.0)),
                "desc": tr("the margins this chart was laid out to"),
                # STRUCTURAL, NEVER TRANSLATED. The panel used to work out which
                # of its two messages to show by testing whether `desc` ends with
                # "laid out to" — and `desc` is `tr()`ed, so the test could only
                # ever match in English. Confirmed on screen 2026-08-26: the same
                # chart, own margin 20 mm, reads "below the 20 mm minimum set for
                # this chart" in English and "liegt unter dem Messgeräte-Minimum
                # von 20 mm" in German, where no instrument row says 20. That is
                # Knut's own #130 complaint, still live in eleven languages, and
                # CI could not see it because CI runs in English.
                "source": "chart",
            }
        except Exception:      # noqa: BLE001 — the inspector must never crash
            return None

    def _chart_instrument_flag(self) -> str:
        """The instrument recorded in the chart's own layout recipe, or "".

        Only a ChromIQ-engine chart has one. It is the truth about the chart in
        the preview, whereas the printtarg widget describes what the panel would
        build next — and with the engine on, that widget is not even shown.
        """
        try:
            import json
            if self._margin_ti2 is None:
                return ""
            ch = Path(self._margin_ti2).with_suffix(".channels.json")
            if not ch.is_file():
                return ""
            doc = json.loads(read_text(ch))
            recipe = (doc.get("layout") or {}).get("recipe") or {}
            return str(recipe.get("instrument") or "")
        except Exception:      # noqa: BLE001 — the inspector must never crash
            return ""

    def _active_instrument_flag(self) -> str:
        """The instrument the chart in the preview was built with. In Manual mode
        that is the manual -i widget; otherwise the Guided instrument combo. Used
        so the margin combo follows the chart, not a stale mode's control (#81)."""
        if self._manual_btn is not None and self._manual_btn.isChecked():
            for pw in self._manual_widgets.get("printtarg", []):
                if pw.flag == "-i":
                    return str(pw.get_raw_value() or "i1")
        combo = getattr(self, "_instr_combo", None)
        return (combo.currentData() if combo is not None else "i1") or "i1"

    def _active_paper_code(self) -> str:
        """The paper code currently selected (manual -p in Manual mode, else the
        Guided paper combo)."""
        if self._manual_btn is not None and self._manual_btn.isChecked():
            for pw in self._manual_widgets.get("printtarg", []):
                if pw.flag == "-p":
                    return str(pw.get_raw_value() or "A4")
        combo = getattr(self, "_paper_combo", None)
        return (combo.currentData() if combo is not None else "A4") or "A4"

    def current_margin_combo(self) -> "tuple[str, str, str] | None":
        """The (instrument label, paper name, orientation) the Margin Thresholds
        tab should preselect (#80/#81). Always follows the active mode's current
        instrument + paper *selection* — what the user is looking at in the
        dropdowns — so Preferences opens on it immediately, even before a chart
        is generated and regardless of any chart still in the preview."""
        instr_label = _MARGIN_INSTR_LABEL.get(self._active_instrument_flag())
        code = self._active_paper_code()
        if not instr_label or not code:
            return None
        dims = _PAPER_MM.get(code)
        if dims is None and "x" in str(code):
            try:
                w, h = str(code).split("x", 1)
                dims = (float(w), float(h))
            except ValueError:
                dims = None
        if dims is None:
            return None
        paper_name = _canonical_paper_name(dims[0], dims[1])
        if not paper_name:
            return None
        orient = "Landscape" if dims[0] > dims[1] else "Portrait"
        return (instr_label, paper_name, orient)

    def current_layout_combo(self) -> "tuple[str, str, str] | None":
        """The (engine instrument, paper code, layout mode) the Chart Layout tab
        should preselect (#93), mirroring :meth:`current_margin_combo`. Follows
        the live engine recipe in Manual when present, else the active
        instrument + paper selection — so Preferences opens on what the user is
        editing, instead of always resetting to i1/A4 (which made a preset saved
        under any other combination look lost)."""
        try:
            if (self._manual_btn is not None and self._manual_btn.isChecked()
                    and getattr(self, "_manual_layout_panel", None) is not None):
                r = self._current_layout_recipe()
                return (r.instrument, r.paper, r.mode())
        except Exception:
            pass
        instr = {"3p": "p3"}.get(self._active_instrument_flag(),
                                 self._active_instrument_flag())
        if instr not in ("i1", "p3", "CM", "SS", "CR30"):
            instr = "i1"
        paper = self._active_paper_code() or "A4"
        try:
            from workflow.layout_engine.presets import default_recipe
            mode = default_recipe(instr, paper).mode()
        except Exception:
            mode = "clip" if instr in ("i1", "p3") else (
                "freehand" if instr == "CM" else "flat")
        return (instr, paper, mode)

    def refresh_margin_inspector_settings(self) -> None:
        """Re-read the Create-Chart preview-panel settings after the Preferences
        dialog closes (margin-inspector visibility, notify, thresholds, and the
        Chart-layout-information panel's visibility may have changed)."""
        panel = getattr(self, "_margin_panel", None)
        if panel is not None:
            panel.set_guides_checked(
                bool(self._settings.get("margin_guides_show", False)))
            panel.set_measured_guides_checked(
                bool(self._settings.get("margin_measured_guides_show", False)))
        self._update_margin_inspector()
        self._update_layout_info()

    @staticmethod
    def _recipe_rebuilds_its_own_sheet(ti2: Path) -> bool:
        """True when re-deriving the page geometry from this chart's stored
        recipe gives back the sheet the user is actually looking at.

        FOR A GUIDED CHART IT DOES NOT. Guided writes no layout recipe of its
        own, so the sidecar carries the LayoutRecipe dataclass defaults — 6 mm
        on all four sides — while the sheet was laid out at the instrument's
        default border (10 mm for the i1Pro, whose shipping preset is
        `m10_a0.95`). Re-deriving from those defaults produces a ROOMIER page
        than the real one: measured, 506 patches for a real 484-patch i1Pro A4
        sheet.

        Everything downstream of that mistake is confidently wrong. The
        partial-last-page hint told the owner of a completely full sheet that
        there was room for 22 more patches, and the capacity beside it — added
        in #130 precisely so a wrong N could be told from a right one — was
        computed the same wrong way, so it agreed. Suppressing only the
        capacity made it worse, not better: the hint still fired and now read
        "space for about 22 more patches (the page holds about 0 in total)",
        which is a sentence that contradicts itself in the same breath.

        So the whole hint goes, not one number in it. `margins_chosen_by_user`
        is the honest marker — written False by
        `ChartCreator._embed_layout_geometry` for a chart whose margins nobody
        chose, absent on charts built before it existed and on charts the user
        laid out by hand. Absent is read as "rebuildable", which is what every
        Manual chart is.
        """
        try:
            import json as _json
            ch = Path(ti2).with_suffix(".channels.json")
            layout = (_json.loads(read_text(ch)).get("layout") or {})
            return layout.get("margins_chosen_by_user") is not False
        except Exception:      # noqa: BLE001 — unreadable sidecar: assume the
            return True        # recipe is honest, as it was before this existed

    def _last_page_capacity(self, ti2: Path) -> int:
        """How many patches a sheet of this chart's layout holds, or 0.

        Reported beside the free-slot count so the number in the window can be
        checked against the patch count already on screen.
        """
        try:
            from workflow.layout_engine.presets import LayoutRecipe
            from workflow.layout_engine import instruments, geometry, papers
            ch = Path(ti2).with_suffix(".channels.json")
            if not self._recipe_rebuilds_its_own_sheet(ti2):
                return 0               # not known — see the helper's docstring
            rec = LayoutRecipe.from_channels_json(ch)
            if rec is None:
                return 0
            geom = instruments.geom_from_build_kwargs(rec.build_kwargs())
            w_mm, h_mm = papers.dimensions_mm(rec.paper)
            return max(0, int(geometry.patches_per_sheet(geom, w_mm, h_mm)))
        except Exception as exc:  # noqa: BLE001 — never block a hint
            log.debug("last-page capacity unavailable: %s", exc)
            return 0

    #: How full the last page must be before "it doesn't quite fill" is a fair
    #: description of it. Below this the chart is not *almost* full, it is
    #: mostly empty, and the hint is noise (see _partial_last_page_blank).
    _PARTIAL_PAGE_MIN_FILL = 0.5

    def _partial_last_page_blank(self, ti2: Path) -> "int | None":
        """Engine charts only: the number of unused patch slots on the last page
        when that page is nearly — but not quite — full, else None. Pure so it's
        unit-testable (#93).

        The gap used to be "at least one empty strip", which is true of an
        almost-full page and equally true of an almost-empty one. Knut, #130
        2026-08-01, on a 12-patch chart:

            *"I get message 'Your patch set doesn't quite fill the last page -
            there's space for about 670 more patches'. Simultaneously the total
            patches count below the preview says 12 patches … The number in the
            message is wrong."*

        The arithmetic was right — the sheet really did have room for 670 more —
        but nothing else about it was. A 12-patch chart has not *almost* filled
        its page, and "add a few more patches to fill the gap" is not advice
        anybody can act on when the gap is fifty times the chart. So the hint
        now only appears once the page is at least half full, which is what
        "doesn't quite fill" means to a reader.
        """
        try:
            from workflow.layout_engine.presets import LayoutRecipe
            from workflow.layout_engine import instruments, geometry, papers
            ch = Path(ti2).with_suffix(".channels.json")
            if not self._recipe_rebuilds_its_own_sheet(ti2):
                return None    # the recipe describes a roomier page than the
                               # real sheet, so every number below would be
                               # wrong — say nothing at all
            rec = LayoutRecipe.from_channels_json(ch)
            if rec is None:
                return None                  # printtarg chart — no engine layout
            m = re.search(r"NUMBER_OF_SETS\s+(\d+)",
                          read_text(Path(ti2), lenient=True))
            if not m:
                return None
            total = int(m.group(1))
            geom = instruments.geom_from_build_kwargs(rec.build_kwargs())
            w_mm, h_mm = papers.dimensions_mm(rec.paper)
            per = geometry.patches_per_sheet(geom, w_mm, h_mm)
            if per <= 0 or total <= 0:
                return None
            lay = geometry.compute(geom, w_mm, h_mm, total)
            steps = lay.steps_in_pass or 1
            on_last = total - (lay.pages - 1) * per
            blank = per - on_last
            if blank < steps:
                return None            # full enough; nothing worth saying
            if on_last < per * self._PARTIAL_PAGE_MIN_FILL:
                return None            # mostly empty — not an almost-full page
            return blank
        except Exception as exc:  # noqa: BLE001
            log.debug("partial-last-page check skipped: %s", exc)
            return None

    # ------------------------------------------------------------------
    # Auto-update preview (Knut): live-refresh on layout changes
    # ------------------------------------------------------------------
    def _on_auto_preview_toggled(self, on: bool) -> None:
        """Persist the auto-update-preview choice; confirm with the user the first
        time they turn it on so they know what it does (Knut)."""
        self._settings.set("auto_update_preview", bool(on))
        # Knut's rule: the "preview is not being re-drawn" window comes once per
        # switch-on, so switching on re-arms it (see _say_preview_is_paused).
        self._said_auto_update_paused = False
        if on:
            InfoDialog(
                tr("Auto-update preview is on"),
                tr("From now on, the chart preview will refresh automatically "
                   "whenever you change a layout setting — margins, patch size, "
                   "columns, spacers, the clip border, and so on — once you've "
                   "generated or loaded a chart.\n\n"
                   "To keep it quick, ChromIQ re-lays-out the patches already in "
                   "your chart; it does not pick new colours or re-run the patch "
                   "generator. While this is on, the “there's a little room left "
                   "on the last page” reminder is hidden so it doesn't interrupt "
                   "you — you can still open the patch-set editor whenever you "
                   "like to add or remove patches.\n\n"
                   "Turn the option off any time to go back to refreshing the "
                   "preview only when you click Generate Chart."),
                self, min_width=560,
            ).exec()
        else:
            self._auto_preview_timer.stop()

    def _layout_signature(self) -> "str | None":
        """A cheap fingerprint of the current layout settings, so the auto-preview
        only re-renders when something actually changed (and the post-render
        refresh doesn't loop)."""
        try:
            if (bool(self._settings.get("use_chromiq_layout_engine", False))
                    and getattr(self, "_manual_layout_panel", None) is not None):
                # Via _current_layout_recipe so a Settings styling change also
                # counts as a layout change and re-triggers the auto-preview.
                return repr(self._current_layout_recipe().to_dict())
            return repr(self._printtarg_signature())
        except Exception:  # noqa: BLE001
            return None

    def _log_chart_build(self, trigger: str, ti1_path) -> None:
        """One line per chart build, saying what started it and what it will lay
        out — on the SUCCESS path, not only when something goes wrong.

        A chart that is built and then immediately replaced is impossible to
        diagnose from the outside: both builds look like "a chart appeared".
        With this line a log says which patch set each build used and whether the
        user or the live preview asked for it, which is the whole question.
        """
        try:
            rec = self._manual_layout_panel.get_recipe().to_dict() \
                if getattr(self, "_manual_layout_panel", None) is not None else {}
            # SAY WHICH MODULE IS SPEAKING, AND LOG THE OTHER ONE TOO.
            #
            # This line reads the MANUAL panel whatever built the chart, so a
            # Guided build was logged with Manual's numbers. Basti's log of
            # 2026-08-26 says "A4" for a sheet Guided had just built as A4R —
            # and I diagnosed the wrong field from it, because the line looked
            # like a description of the chart and was a description of the
            # other module's widgets.
            #
            # The mismatch is the interesting part, not noise to tidy away: it
            # is exactly the "the panel disagrees with the sheet" condition that
            # produced the bug. So log both, labelled, and let a reader see the
            # gap.
            mode = self._current_mode()
            log.info("chart build (%s) in %s: patch set %s | manual panel: %s, "
                     "%sx%s grid, margins T%s R%s B%s L%s",
                     trigger, mode, getattr(ti1_path, "name", ti1_path),
                     rec.get("paper"), rec.get("area_cols"), rec.get("area_rows"),
                     rec.get("margin_top"), rec.get("margin_right"),
                     rec.get("margin_bottom"), rec.get("margin_left"))
            if mode != "manual":
                # What the module that is actually building will hand the
                # engine — the numbers that describe the sheet.
                try:
                    kw = self._creator._engine_build_kwargs(
                        self._collect_guided()) if mode == "guided" else {}
                    log.info("chart build (%s) in %s: engine kwargs %s",
                             trigger, mode,
                             {k: kw.get(k) for k in
                              ("instrument", "paper", "border", "patch_w_mm")
                              if k in kw})
                except Exception:      # noqa: BLE001
                    log.debug("could not log the building module's geometry",
                              exc_info=True)
        except Exception:      # noqa: BLE001 — a log line must never break a build
            pass

    def _chart_build_in_flight(self) -> bool:
        """True while a chart is being built and has not come back yet.

        ``_runner.is_running`` only knows about ArgyllCMS processes. A chart laid
        out by the **ChromIQ layout engine** runs no external tool, so that guard
        sees nothing and the live preview happily started a second, competing
        build over the top of the first (Basti, 2026-08-16). The Generate button
        is the honest marker: every build path disables it on the way in and
        re-enables it in ``_on_generate_finished`` — including the failure paths,
        so this cannot latch on and silence the preview for good.
        """
        if self._runner.is_running:
            return True
        btn = getattr(self, "_generate_btn", None)
        return btn is not None and not btn.isEnabled()

    def _settle_live_preview(self) -> None:
        """End an operation that filled the layout widgets on the user's behalf,
        leaving the live preview exactly where it found it.

        SEEDING A WIDGET IS NOT AN EDIT. Loading a preset, resetting to one,
        opening a .ti2 or selecting another run fills the panel programmatically,
        every field fires a `changed` signal, and `_maybe_schedule_auto_preview`
        cannot tell that from a user's hand on a knob — so the debounce timer
        arms and 450 ms later the chart is re-laid out and REWRITTEN TO DISK.
        Basti, 2026-08-26, on the mode-switch case: the sheet he had just
        generated was silently replaced.

        Two lines, and both are needed. Cancelling alone leaves a stale
        fingerprint that arms on the next unrelated signal; re-baselining alone
        does not stop a timer that is already running.

        THE EPISODE IS THE UNIT, NOT A FLAG. `_loading_target_settings` was
        built to guard this and cannot: an operation that seeds the panel twice
        runs its second seeder after the flag is down, so declining while the
        flag is up only moves which line arms the timer. Call this at the END of
        the whole operation, on every exit path, and it holds however many
        seeders the operation grows.

        A real edit made AFTER the operation still arms the timer normally.
        """
        try:
            self._cancel_pending_auto_preview()
            self._last_auto_sig = self._layout_signature()
        except Exception:      # noqa: BLE001 — never break the caller
            log.debug("could not settle the live preview", exc_info=True)

    def _cancel_pending_auto_preview(self) -> None:
        """Drop a queued live re-render because a real chart build is starting.

        The live preview re-lays out **the chart currently on screen**
        (``_current_ti1_path``). Choosing a built-in preset changes the layout
        options first — which queues a re-render of the OLD chart — and only then
        builds the preset's own patch set. If the queued timer fired before that
        build finished, the preset the user had just picked was replaced by the
        previous chart's patches re-flowed into the preset's layout: a chart that
        looked wrong and belonged to nothing (Basti, 2026-08-16, first preset
        picked in a session).

        Whatever a queued re-render was going to show, the build starting now
        supersedes it, and ``_on_generate_finished`` re-baselines the layout
        signature — so cancelling here loses nothing.

        BOTH TIMERS, NOT ONE. The command preview is debounced too, and it is
        what ARMS the render timer (`_maybe_schedule_auto_preview`). Cancelling
        only the render left the 150 ms scheduler pending, so a Generate click
        within 150 ms of the last change re-armed the render from inside the
        §S4.7 window — and the user pressed Cancel on a window that says "stops
        here and changes nothing" while their chart file had already been
        rewritten and their Build Profile and Check tabs cleared. Driven,
        against the shipped build as a control.
        """
        for name in ("_auto_preview_timer", "_cmd_preview_timer"):
            timer = getattr(self, name, None)
            if timer is not None and timer.isActive():
                timer.stop()

    def _maybe_schedule_auto_preview(self) -> None:
        """Start the debounce timer to re-render the preview, if auto-update is on,
        a chart already exists, nothing is running, and the layout actually
        changed since the last render."""
        if not bool(self._settings.get("auto_update_preview", False)):
            return
        # Manual mode only — ignored in Guided even if the option is on (Knut).
        if self._current_mode() != "manual":
            return
        # A build already under way will finish by re-baselining the signature,
        # so queueing a re-render here would only race it — with the chart from
        # BEFORE that build, which is still what _current_ti1_path points at.
        if self._chart_build_in_flight():
            return
        ti1 = getattr(self, "_current_ti1_path", None)
        if not (ti1 is not None and ti1.is_file()):
            return
        if self._layout_signature() == self._last_auto_sig:
            return
        self._auto_preview_timer.start(450)

    def _auto_regenerate_preview(self) -> None:
        """Re-lay-out the current chart's patch set with the current layout, to
        refresh the preview live (Knut). Fast: no targen, same patches."""
        if (self._chart_build_in_flight()
                or self._current_mode() != "manual"
                or not bool(self._settings.get("auto_update_preview", False))):
            return
        # THE TIMER IS ARMED FOR A LAYOUT, NOT FOR A MOMENT. Re-check the
        # fingerprint it was armed for, because whoever re-baselined it in the
        # meantime decided this render was not wanted.
        #
        # Without this, re-baselining `_last_auto_sig` does not stop anything:
        # the timer is already running by then and this method used to check the
        # mode, the build guard, the .ti1 and §4 — everything except the one
        # question it was started to answer. Every caller that re-baselines then
        # has to remember to stop the timer as well, and the next seeding path
        # added to this file quietly defeats the fix by forgetting. Asking here
        # makes a re-baseline sufficient on its own, wherever it happens.
        if self._layout_signature() == self._last_auto_sig:
            return
        ti1 = getattr(self, "_current_ti1_path", None)
        if not (ti1 is not None and ti1.is_file()):
            return
        # A LIVE PREVIEW MUST NOT CREATE A PROJECT either. `_current_ti1_path`
        # can point at a chart opened with "Open Chart File (.ti2)" that lives
        # outside any project, so this is reachable with nothing named, and
        # `_target_run()` below is the mutating getter's road again.
        if not _is_named(self._file_mgr):
            return
        # Record the signature we're about to render so the post-render refresh
        # (same layout) doesn't immediately re-schedule another render.
        # §4: the auto-update preview re-lays out the chart in the run, which
        # would leave the measurement describing patch positions that are no
        # longer on the sheet. A window here would open on every turn of a
        # layout knob, so this path declines instead and says so once — the
        # Generate Chart button still offers the full choice.
        from workflow.chart_integrity import assess_profiling_chart
        try:
            _run = self._target_run()          # the bar's run, not the project's
        except Exception:      # noqa: BLE001
            _run = None
        # Assess the chart the re-layout actually touches. For a verification
        # target that is the VERIFY chart, and the stake is narrower still:
        # only a measured dated verification that DESCRIBES THE LIVE CHART is
        # stranded by a re-layout — a date whose stored snapshot differs
        # already describes an earlier chart (Restore Used Chart brings it
        # back). Asking about the profiling chart here paused the preview
        # forever once the run had its profiling measurement; asking about
        # every measured date would pause it forever once ANY verification
        # existed, even straight after Generate had knowingly replaced the
        # chart (Basti, 2026-08-10: "after hitting generate a working live
        # update would be nice").
        if self._is_verification_target():
            warn = self._verify_live_chart_has_measured_dates(_run)
        else:
            warn = assess_profiling_chart(_run).warn
        if warn:
            self._say_preview_is_paused()
            return
        self._last_auto_sig = self._layout_signature()
        self._generate_from_ti1(ti1, ask=False, preview=True)

    @staticmethod
    def _verify_live_chart_has_measured_dates(run) -> bool:
        """True when a measured dated verification was made with the verify
        chart currently on disk — the real §4 stake for re-laying it.

        A date whose stored chart snapshot DIFFERS from the live chart
        describes an earlier chart; replacing the live one again strands
        nothing of it. A measured date with no snapshot has unknown
        provenance, so it stays protected."""
        from workflow.verify_chart_snapshot import (has_snapshot,
                                                    live_differs_from_snapshot)
        if run is None:
            return False
        try:
            if not run.has_verify_chart():
                return False
            for v in run.verifications():
                if not v.exists():
                    continue          # no measurement — nothing at stake
                if not has_snapshot(v) or not live_differs_from_snapshot(v):
                    return True
        except Exception:      # noqa: BLE001 — unreadable state: stay safe
            log.warning("could not judge the verification dates", exc_info=True)
            return True
        return False

    #: Message text — the same sentences on screen and in the log, so a user
    #: comparing the two never wonders whether they mean different things.
    PREVIEW_PAUSED_TITLE = "The live preview is not being re-drawn"

    def _preview_paused_body(self) -> str:
        return tr(
            "This run already holds work made with the chart the preview would "
            "replace, so the preview is left as it is rather than re-drawn "
            "over it.\n\n"
            "Press “Generate Chart” when you want the new layout. You will be "
            "told exactly what moves to the run's “old” folder first, and "
            "nothing is deleted.\n\n"
            "This window appears once each time you switch “Auto-update "
            "preview” on. While it stays on, the same note goes to the log "
            "instead, so your layout work is not interrupted.")

    def _say_preview_is_paused(self) -> None:
        """§4, auto-update — Knut's ruling in beta.125.

        He accepted that a window on every turn of a knob would be unusable,
        and set the rule: *"the popup window saying 'The live preview is not
        being re-drawn...' should come once only, then again the next time
        'auto-update preview ...' is enabled. At the same time it can come in
        the log window until 'auto-update preview ...' is disabled."*

        So: the log line every time, the window only on the first refusal after
        the option was switched on. :meth:`_on_auto_preview_toggled` re-arms it.
        """
        self._log.appendPlainText(
            tr(self.PREVIEW_PAUSED_TITLE) + " — " + self._preview_paused_body()
            .replace("\n\n", " "))
        if getattr(self, "_said_auto_update_paused", False):
            return
        self._said_auto_update_paused = True
        from PyQt6.QtWidgets import QMessageBox

        from ui.widgets import fit_message_box_buttons
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.NoIcon)
        title = tr(self.PREVIEW_PAUSED_TITLE)
        box.setWindowTitle(title)
        box.setText(title)
        box.setInformativeText(self._preview_paused_body())
        box.addButton(tr("OK"), QMessageBox.ButtonRole.AcceptRole)
        fit_message_box_buttons(box)
        box.exec()

    def _maybe_warn_partial_last_page(self, ti2: Path) -> None:
        """If the patch set leaves a notably under-filled last page (or spilled
        onto a near-empty extra page), show a friendly heads-up with a button to
        open the patch-set editor so the user can fill or trim the set (Knut #93).
        We don't auto-fill or guess — over/under-fill can equally mean patches
        should be removed.

        Only in Manual mode with a FIXED patch count: in Guided (and Manual with
        "Auto patch count" on) the count is auto-filled to the page, so any small
        gap is just estimate rounding, not the user's choice — and Guided has no
        patch-set editor to point them at (Knut)."""
        # While auto-update-preview is on, this reminder would interrupt every
        # live layout tweak — suppress it (the user can still open the editor).
        if bool(self._settings.get("auto_update_preview", False)):
            return
        manual = (getattr(self, "_manual_btn", None) is not None
                  and self._manual_btn.isChecked())
        auto_count = (getattr(self, "_manual_auto_patches_check", None) is not None
                      and self._manual_auto_patches_check.isChecked())
        if not manual or auto_count:
            return
        # A fixed-patch-set preset (a bundled .ti1: TC9.18, Knut, a vendor family
        # like Red River, or a user preset with an attached .ti1) owns its patch
        # count — the set is locked and targen is greyed, so "add/remove a few
        # patches" is exactly the wrong advice. Suppress the heads-up for those.
        if self._ti1_preset_active():
            return
        blank = self._partial_last_page_blank(ti2)
        if not blank:
            return
        # A bare "space for about N more" is unverifiable from the screen, and
        # an N that looks wrong is indistinguishable from one that is wrong
        # (Knut, #130 2026-08-01). Saying how many the page holds lets anyone
        # check the arithmetic against the patch count already on display.
        capacity = self._last_page_capacity(ti2)
        try:
            from PyQt6.QtWidgets import QMessageBox
            box = QMessageBox(self)
            box.setIcon(QMessageBox.Icon.Information)
            box.setWindowTitle(tr("There's a little room left on the last page"))
            box.setText(tr(
                "Your patch set doesn't quite fill the last page — there's space "
                "for about {n} more patches on it (the page holds about {cap} "
                "in total).\n\n"
                "That's perfectly fine to print as it is; the empty area is just "
                "blank paper. If you'd rather have a tidy, completely full page, "
                "you have two easy options in the patch-set editor:\n\n"
                "• Add a few more patches to fill the gap, or\n"
                "• Remove a few so the set ends neatly on the previous page.\n\n"
                "The page layout itself — instrument, paper, margins and patch "
                "size — stays exactly as you've set it here in Create Chart; only "
                "the colours in the set change. Click “Edit patch set…” to open "
                "the editor now, or “OK” to keep the chart as it is."
            ).format(n=blank, cap=capacity))
            edit_btn = box.addButton(tr("Edit patch set…"),
                                     QMessageBox.ButtonRole.ActionRole)
            box.addButton(QMessageBox.StandardButton.Ok)
            box.exec()
            if box.clickedButton() is edit_btn:
                self.edit_patch_set_requested.emit()
        except Exception as exc:  # noqa: BLE001 — never block on this hint
            log.debug("partial-last-page check skipped: %s", exc)

    def _maybe_autotag_randomised(self, ti2: Path) -> None:
        """Upgrade a fixed-order (CHART_ID) chart to RANDOM_START when its layout
        is well mixed, so chartread gets auto strip-ID + bidirectional reading.

        Mirrors the TI2 layout editor's auto-tag-on-save
        (:meth:`TI2RelayoutDialog._maybe_tag_randomised`): a one-directional,
        gate-checked upgrade that can only ever help. printtarg randomises by
        default (already RANDOM_START → skipped here); a chart carries CHART_ID
        only when "Preserve Patch Order" (-r) is in effect — e.g. when a
        pre-shuffled generate-colour-sets / editor-recipe layout is generated.
        A structured chart (a deliberate ramp, a calibration ramp) fails the
        gate and is left untouched. Best-effort: never blocks chart creation.
        """
        try:
            if not ti2.is_file():
                return
            # Cheap guard: only fixed-order charts need upgrading. The default
            # printtarg output is already RANDOM_START, so skip the heavier
            # analysis for it.
            text = ti2.read_text(encoding="utf-8", errors="ignore")
            if "CHART_ID" not in text or "RANDOM_START" in text:
                return
            from workflow.ti2_relayout import (
                analyze_randomisation, tag_ti2_randomised,
            )
            if analyze_randomisation(ti2).safe and tag_ti2_randomised(ti2):
                log.info("Auto-tagged %s as randomised (layout is well mixed).",
                         ti2.name)
        except Exception as exc:  # noqa: BLE001
            log.warning("auto-tag randomised check failed for %s: %s",
                        ti2.name, exc)

    def _stamp_chart_meta(self, ti2: Path) -> None:
        """Record instrument / paper AND the printtarg layout knobs in the run's
        meta.json, so a main-app chart opened in the TI2 layout editor restores
        exactly like an editor-saved one.

        Reuses :func:`workflow.ti2_relayout.save_editor_meta` (the same writer
        the editor uses), feeding it a LayoutOptions built from the params this
        chart was generated with. The chart's instrument/paper come from the
        just-written .ti2 (authoritative for every creation path). Only runs for
        charts in a ``runs/runN/`` folder — calibration targets live in ``cal/``
        and aren't RunMeta-backed. Best-effort: never block chart creation.
        """
        try:
            run_dir = ti2.parent
            if run_dir.parent.name != "runs":   # cal/ or some other folder
                return
            from core.file_manager import Run
            from workflow.ti2_relayout import ChartSpec, save_editor_meta
            spec = ChartSpec.from_ti2(ti2)
            run = Run.for_dir(run_dir)
            # Build the editor's LayoutOptions from the params this chart was
            # generated with (stored at generate time). Without params we can
            # still stamp instrument/paper but not the layout knobs.
            params = getattr(self, "_last_params", None)
            if params is not None:
                opts = _layout_options_from_params(params)
                # Pass the active preset's recipe (Set B) so a preset-generated
                # chart carries it into meta.json; None preserves any existing
                # recipe and never invents one for plain targen charts (#70).
                # save_editor_meta reconciles the recipe's layout to these opts,
                # so Set A and Set B never disagree on what was built (#92) —
                # except for engine-built charts, whose real layout is the
                # engine recipe in channels.json, not these printtarg-derived
                # opts: their creation recipe stays as created (#100).
                from workflow.layout_engine.presets import LayoutRecipe
                is_engine = LayoutRecipe.from_channels_json(
                    ti2.with_suffix(".channels.json")) is not None
                save_editor_meta(ti2, spec, opts, run.stem,
                                 recipe=self._pending_editor_recipe,
                                 sync_layout=not is_engine)
            else:
                # NO PARAMS MEANS NO TARGEN RUN — a bundled .ti1 went straight
                # onto the sheet. That is still a chart this run did not design,
                # so its record must be cleared rather than left describing
                # whatever was there before (#164). This branch used never to
                # touch `editor_recipe` at all, which is how the nine
                # prebuilt-file presets inherited the previous chart's design.
                meta = run.load_meta()
                meta.instrument = spec.instrument_flag
                meta.paper = spec.paper_flag
                if not self._pending_editor_recipe:
                    meta.editor_recipe = None
                run.save_meta(meta)
        except Exception:  # noqa: BLE001 — metadata is non-essential
            log.exception("could not stamp chart meta.json")

    def _on_save_defaults(self) -> None:
        params = self._collect_params()
        s = self._settings
        # The project NAME is deliberately not saved (Sebastian, 2026-08-13):
        # every other row here is a preference, but the name is the project's
        # identity — a saved name would seed every future fresh start with an
        # old project's name, one Generate away from building into it. The
        # stored key is reset so a name saved by an older version stops
        # leaking into new sessions too. It resets to EMPTY, not to a factory
        # name (Basti, #164 Q15) — see _restore_defaults.
        s.set("chart_target_name",         "")
        s.set("chart_stamp_commands",      bool(params.stamp_commands))
        s.set("chart_left_clip_info",      bool(params.left_clip_info))
        s.set("chart_instrument",          params.instrument)
        s.set("chart_paper",               params.paper)
        s.set("chart_pages",               params.pages)
        s.set("chart_double_density",      params.double_density)
        s.set("chart_triple_density",      params.triple_density)
        # If Triple density is on, the lb_check shows TD's forced True;
        # save the stashed pre-TD value so the user's preference round-trips.
        guided_lb_save = params.disable_left_border
        if (params.triple_density
                and getattr(self, "_td_saved_lb_check", None) is not None):
            guided_lb_save = bool(self._td_saved_lb_check)
        s.set("chart_disable_left_border", guided_lb_save)
        # Triple density forces -P internally; persist the user's standalone
        # -P preference rather than the TD-derived True.
        guided_nsl_save = (False if params.triple_density
                           else bool(self._nsl_check.isChecked()
                                     and (params.instrument in {"i1", "p3"})))
        s.set("chart_no_strip_limit", guided_nsl_save)
        s.set("targen_device_type",        params.device_type)
        s.set("targen_good_mode",          params.good_mode)
        s.set("printtarg_dpi",             params.tiff_dpi)
        # Save all manual widget values individually. When Triple density is
        # active the four widgets it owns (-a / -m / -P / -L) currently show
        # the i1Pro-emulation overrides; persisting those would clobber the
        # user's pre-TD preferences and trap the next session in TD-shaped
        # values that no longer round-trip through the stash. Save the
        # stashed pre-TD values instead for those four flags.
        td_stash = (self._td_saved_layout
                    if (self._manual_td_check is not None
                        and self._manual_td_check.isChecked()
                        and self._td_saved_layout)
                    else None)
        for tool, widgets in self._manual_widgets.items():
            for pw in widgets:
                if pw in self._d_cascade_widgets:
                    continue
                if td_stash is not None and tool == "printtarg" and pw.flag in td_stash:
                    v = td_stash[pw.flag]
                else:
                    v = pw.get_raw_value()
                key = _pw_settings_key(tool, pw.flag)
                if v is not None:
                    s.set(key, v)
                # Expert non-boolean rows carry their enable-checkbox state
                # separately from the value; persist it so the flag is re-armed
                # on restore (otherwise build_args drops it).
                if pw.has_separate_enable:
                    s.set(f"{key}_enabled", pw.is_enabled_by_user)
        for idx, pw in enumerate(self._d_cascade_widgets):
            s.set(f"manual_targen_-D_{idx}", pw.get_raw_value())
            s.set(f"manual_targen_-D_{idx}_enabled", pw.is_enabled_by_user)
        if self._bit16_radio is not None:
            s.set("manual_printtarg_tiff_16bit", self._bit16_radio.isChecked())
        if self._manual_auto_patches_check is not None:
            s.set("manual_auto_patches", self._manual_auto_patches_check.isChecked())
        if self._manual_auto_grey_check is not None:
            s.set("manual_auto_grey", self._manual_auto_grey_check.isChecked())
        if self._manual_auto_white_check is not None:
            s.set("manual_auto_white", self._manual_auto_white_check.isChecked())
        if self._manual_auto_black_check is not None:
            s.set("manual_auto_black", self._manual_auto_black_check.isChecked())
        if self._manual_pages_spin is not None:
            s.set("manual_pages", int(self._manual_pages_spin.value()))
        if self._manual_td_check is not None:
            s.set("manual_printtarg__triple_density",
                  self._manual_td_check.isChecked())
        # Persist the full ChromIQ layout-engine recipe so every engine option
        # (paper, margins, indicators, strip gap, label offset, …) survives a
        # restart — _init_manual_layout_panel restores it. Without this, only the
        # printtarg widgets above were saved and the engine panel reset (#93).
        if getattr(self, "_manual_layout_panel", None) is not None:
            try:
                s.set("manual_engine_recipe",
                      self._current_layout_recipe().to_dict())
            except Exception as exc:  # noqa: BLE001 — don't fail the whole save
                log.warning("save engine layout defaults failed: %s", exc)
        log.info("Chart defaults saved")
        self._log.appendPlainText("Current settings saved as defaults.")
        self._log.ensureCursorVisible()

    # ------------------------------------------------------------------
    # Param collection
    # ------------------------------------------------------------------

    def _collect_params(self) -> ChartParams:
        p = (self._collect_guided() if self._current_mode() == "guided"
             else self._collect_manual())
        # The full registry travels with the chart (K2, Knut's beta.4:
        # "Targen parameters are not loaded with charts json file") — the
        # sidecar then restores the exact settings that made the sheet.
        try:
            from workflow.per_target_settings import snapshot
            p.settings_snapshot = snapshot(self)
        except Exception:      # noqa: BLE001 — a snapshot must never block
            pass
        return p

    def _collect_guided(self) -> ChartParams:
        pages   = self._pages_spin.value()
        instr   = self._instr_combo.currentData() or "i1"
        paper   = self._paper_combo.currentData() or "A4"
        dd      = self._dd_check.isChecked()
        td      = self._td_check.isChecked() and instr == "CM"
        has_lb  = self._lb_check.isChecked()
        nsl_ui  = (self._nsl_check.isChecked()
                   and instr in {"i1", "p3"}
                   and not td)
        if td:
            # Triple-density forces i1Pro layout params; the arg builder also
            # applies these, but we set them on ChartParams so patch-count
            # lookup, command preview and TIFF metadata stay consistent.
            margin = 5
            patch_scale = 1.3
            no_strip_limit = True
            dd = False  # mutual exclusion (UI also enforces)
        elif instr == "i1":
            preset_key = str(self._settings.get(
                "i1pro_default_preset", I1PRO_DEFAULT_PRESET_KEY
            ))
            margin, patch_scale = i1_defaults_from_preset(preset_key)
            no_strip_limit = nsl_ui
        else:
            margin = INSTRUMENT_DEFAULT_MARGIN.get(instr, 6)
            patch_scale = 1.0
            no_strip_limit = nsl_ui
        # ChromIQ-style and triple-density both force -L; mirror the chart's
        # effective suppress_lb state so guided_neutrals sees what targen/
        # printtarg will actually run.
        # Guided is always the ChromIQ engine, and the engine ignores the
        # printtarg-era ChromIQ clip style, so it must not force -L here (#170).
        eff_lb = has_lb or td
        grey_steps, white_patches, black_patches = guided_neutrals(
            instr, paper, pages, GUIDED_NEUTRAL_BASE, GUIDED_NEUTRAL_BASE, eff_lb,
            double_density=dd, triple_density=td,
            no_strip_limit=no_strip_limit,
            ref_budget=int(self._settings.get("grey_ramp_reference", REF_BUDGET)),
        )

        precond_path = self._guided_precond_path.text().strip()
        precond_active = self._guided_precond_check.isChecked() and bool(precond_path)
        extra_targen = shlex.join(["-c", precond_path]) if precond_active else ""

        return ChartParams(
            instrument           = instr,
            paper                = paper,
            pages                = pages,
            double_density       = dd,
            triple_density       = td,
            disable_left_border  = has_lb,
            device_type          = self._settings.get("targen_device_type", "2"),
            patches              = 0,
            white_patches        = white_patches,
            black_patches        = black_patches,
            good_mode            = bool(self._settings.get("targen_good_mode", True)),
            grey_steps           = grey_steps,
            # When a refinement profile is supplied, the corrected neutral axis
            # is known, so sample it with targen -n instead of device-grey -g.
            neutral_axis_from_profile = precond_active,
            extra_targen_args    = extra_targen,
            tiff_dpi             = int(self._settings.get("printtarg_dpi", 300)),
            patch_scale          = patch_scale,
            margin_mm            = margin,
            no_strip_limit       = no_strip_limit,
            left_clip_info       = bool(self._settings.get("chart_left_clip_info", False)),
            chromiq_clip_style   = bool(self._settings.get("i1pro_chromiq_clip_style", False)),
        )

    def _collect_manual(self) -> ChartParams:
        p = ChartParams()

        if self._manual_pages_spin is not None:
            p.pages = int(self._manual_pages_spin.value())

        def _get(tool: str, flag: str, default: Any) -> Any:
            for pw in self._manual_widgets.get(tool, []):
                if pw.flag == flag:
                    v = pw.get_raw_value()
                    return v if v is not None else default
            return default

        p.device_type          = str(_get("targen",    "-d",  "2"))
        p.patches              = int(_get("targen",    "-f",  0))
        # -e / -B / -g read the raw widget value; Auto-checked rows return
        # 0 from the spinbox (specialValueText "Auto"), and we substitute
        # the manual_neutrals() value at the end of _collect_manual once
        # the rest of ChartParams is populated.
        p.white_patches        = int(_get("targen",    "-e",  4))
        p.black_patches        = int(_get("targen",    "-B",  4))
        p.good_mode            = bool(_get("targen",   "-G",  True))
        p.grey_steps           = int(_get("targen",    "-g",  0))
        p.single_channel_steps = int(_get("targen",    "-s",  0))

        # Emit extras in an explicit order rather than widget order so -n
        # (Neutral Axis Steps) reads ahead of -c (pre-conditioning profile)
        # in the command. targen parses options order-independently and the
        # -c path-staging/rewrite logic scans for the "-c" token wherever it
        # sits, so the order is purely cosmetic.
        # ``__targen_distribution__`` is the pseudo-id for the mutex
        # distribution-selector row (flag_choice); its value is the actual
        # token (-r, -t, …) and is emitted by ParameterWidget.build_args.
        extra = []
        for flag in (
            "-n", "-c", "-A", "-C", "-N", "-V", "-D",
            "-l", "-m", "-M", "-b", "__targen_distribution__",
        ):
            for pw in self._manual_widgets.get("targen", []):
                if pw.flag == flag:
                    extra.extend(pw.build_args())
        if extra:
            p.extra_targen_args = shlex.join(extra)

        p.instrument           = str(_get("printtarg", "-i",  "i1"))
        p.paper                = str(_get("printtarg", "-p",  "A4"))
        p.tiff_dpi             = int(_get("printtarg", "-t",  300))
        p.tiff_16bit           = self._bit16_radio is not None and self._bit16_radio.isChecked()
        p.double_density       = bool(_get("printtarg", "-h", False))
        p.disable_left_border  = bool(_get("printtarg", "-L", True))
        p.patch_scale          = float(_get("printtarg", "-a", 1.0))
        # -A (spacer scale) and -n (no spacers) reach printtarg via the manual
        # widget build_args path; captured here for metadata (the editor's
        # LayoutOptions) only — see ChartParams.spacer_scale / no_spacers.
        p.spacer_scale         = float(_get("printtarg", "-A", 1.0) or 1.0)
        p.no_spacers           = bool(_get("printtarg", "-n",  False))
        p.margin_mm            = int(_get("printtarg",  "-m",  6))
        p.no_randomise         = bool(_get("printtarg", "-r",  False))
        p.bw_spacers           = bool(_get("printtarg", "-b",  False))
        p.no_strip_limit       = bool(_get("printtarg", "-P",  False))
        # Triple density is a ChromIQ-internal flag (no Argyll mapping); the
        # arg builder substitutes -i / -a / -m / -P at command time. UI also
        # already stashes the prior layout values, so reading the widget
        # state here is enough.
        p.triple_density = (
            self._manual_td_check is not None
            and self._manual_td_check.isChecked()
            and p.instrument == "CM"
        )

        # All remaining printtarg params (e.g. -N, -K, -I, -C, -D, -U, -R, -Q, -A, -n, -c)
        # are collected here and passed through extra_printtarg_args, which
        # _build_printtarg_args() already appends verbatim before the target name.
        _pt_mapped = {"-i", "-p", "-t", "-h", "-L", "-a", "-m", "-r", "-b", "-P"}
        extra_pt: list[str] = []
        for pw in self._manual_widgets.get("printtarg", []):
            if pw.flag not in _pt_mapped:
                extra_pt.extend(pw.build_args())
        if extra_pt:
            p.extra_printtarg_args = shlex.join(extra_pt)

        p.chart_notes          = self._manual_chart_notes_edit.text().strip()
        # #130: carried into the chart so {rundescription} can stamp it and the
        # sidecar can record it. Taken from the field rather than from disk, so
        # what is stamped is what is on screen at the moment Generate is pressed.
        p.run_description      = self._current_run_description().strip()
        p.stamp_commands       = self._manual_stamp_cmd_check.isChecked()
        p.left_clip_info       = self._manual_left_clip_check.isChecked()
        p.chromiq_clip_style   = bool(self._settings.get("i1pro_chromiq_clip_style", False))
        p.is_manual            = True

        # ChromIQ layout engine on: the layout panel is the source of truth for
        # the chart layout. Take instrument/paper + the full recipe + calibration
        # from it (the printtarg layout widgets are hidden), so every panel option
        # takes effect.
        if (getattr(self, "_manual_layout_panel", None) is not None
                and bool(self._settings.get("use_chromiq_layout_engine", False))):
            recipe = self._current_layout_recipe()
            p.instrument = recipe.instrument
            p.paper = recipe.paper
            p.tiff_dpi = recipe.dpi
            p.pages = self._manual_layout_panel.get_pages()
            p.layout_recipe = recipe
            cal_path, apply_cal = self._manual_layout_panel.cal_settings()
            p.engine_cal_path = cal_path
            p.engine_apply_cal = apply_cal

        # Auto -e / -B / -g substitution. For the live preview we use a
        # cheap patch_db estimate when -f itself is auto; the real
        # estimate_patches() value is re-applied in _on_generate.
        self._apply_auto_neutrals(p, use_estimate=False)
        return p

    def _resolve_total_patches(self, p: ChartParams, use_estimate: bool) -> int:
        """Return the total patch count to feed manual_neutrals().

        When -f is set manually, use it. When -f is on Auto, fall back to
        a cheap patch_db lookup for the live preview (use_estimate=False)
        or the real targen-driven estimate at Generate-click
        (use_estimate=True; caller is responsible for having already
        called estimate_patches and updated p.patches).
        """
        if not (self._manual_auto_patches_check is not None
                and self._manual_auto_patches_check.isChecked()):
            return int(p.patches)
        if use_estimate:
            return int(p.patches)
        # Cheap preview path: patch_db lookup × pages. Returns 0 when the
        # combination isn't in the lookup tables (custom patch_scale/margin,
        # or layout-affecting extras like -A / -n) — _apply_auto_neutrals
        # then falls back to default neutrals for the live preview; the
        # real estimate at Generate-click reruns this via estimate_patches
        # which routes such cases to a binary search.
        from workflow.chart_creator import _chromiq_clip_active
        triple = p.triple_density and p.instrument == "CM"
        force_l = _chromiq_clip_active(p) or triple
        eff_lb = p.disable_left_border or force_l
        nominal = query_patches(p.instrument, p.paper,
                                double_density=p.double_density,
                                suppress_lb=eff_lb,
                                margin_mm=p.margin_mm,
                                patch_scale=p.patch_scale,
                                triple_density=triple,
                                no_strip_limit=p.no_strip_limit)
        if nominal is None:
            return 0
        return int(nominal * max(1, p.pages))

    def _apply_auto_neutrals(self, p: ChartParams, use_estimate: bool) -> None:
        """Overwrite -e / -B / -g on `p` for any Auto checkbox that's on."""
        from workflow.chart_creator import manual_neutrals
        if not any((
            self._manual_auto_grey_check  is not None and self._manual_auto_grey_check.isChecked(),
            self._manual_auto_white_check is not None and self._manual_auto_white_check.isChecked(),
            self._manual_auto_black_check is not None and self._manual_auto_black_check.isChecked(),
        )):
            return
        total = self._resolve_total_patches(p, use_estimate=use_estimate)
        # Pull bases from any user-set values (so an Auto checkbox respects
        # a non-default starting base if the user typed one before checking
        # Auto). Falls back to 4 / 4 — same as targen's default.
        base_w = p.white_patches if p.white_patches > 0 else 4
        base_b = p.black_patches if p.black_patches > 0 else 4
        g, w, b = manual_neutrals(
            total, base_w, base_b,
            ref_budget=int(self._settings.get("grey_ramp_reference", REF_BUDGET)),
        )
        if self._manual_auto_grey_check is not None and self._manual_auto_grey_check.isChecked():
            p.grey_steps    = g
        if self._manual_auto_white_check is not None and self._manual_auto_white_check.isChecked():
            p.white_patches = w
        if self._manual_auto_black_check is not None and self._manual_auto_black_check.isChecked():
            p.black_patches = b

    # ------------------------------------------------------------------
    # Restore saved defaults
    # ------------------------------------------------------------------

    def _restore_defaults(self) -> None:
        s = self._settings

        # Strip any stray extension a pre-fix session may have persisted, so a
        # contaminated default (e.g. "…_target.icm") doesn't reappear on launch.
        # EMPTY on a fresh start (Basti, #164 Q15). It used to default to
        # "ChromIQ Test Chart", which put "Location being edited:
        # …/ChromIQ-Test-Chart/runs/run1/" on screen with no project open —
        # a path into a project that does not exist, right under the sentence
        # telling you to open one. An older install's copy of that string is
        # dropped by AppSettings._migrate_factory_project_name.
        default_name = self._file_mgr.strip_workfile_ext(
            s.get("chart_target_name", "")
        )
        self._target_name_edit.setText(default_name)
        self._manual_target_name_edit.setText(default_name)

        # Chart notes are per-chart, not a session default — always start empty.
        # Also evict any stale value that an older session may have persisted
        # under the now-unused "chart_notes" key.
        try:
            if s._qs.contains("chart_notes"):
                s._qs.remove("chart_notes")
        except AttributeError:
            pass
        if hasattr(self, "_manual_chart_notes_edit"):
            self._manual_chart_notes_edit.setText("")
        if hasattr(self, "_manual_stamp_cmd_check"):
            self._manual_stamp_cmd_check.setChecked(bool(s.get("chart_stamp_commands", True)))
        if hasattr(self, "_manual_left_clip_check"):
            self._manual_left_clip_check.setChecked(bool(s.get("chart_left_clip_info", False)))

        instr = s.get("chart_instrument", "i1")
        idx = self._instr_combo.findData(instr)
        if idx >= 0:
            self._instr_combo.setCurrentIndex(idx)
        self._rebuild_paper_combo()  # populate/filter even if instrument index didn't change

        paper = s.get("chart_paper", "A4")
        idx = self._paper_combo.findData(paper)
        if idx >= 0:
            self._paper_combo.setCurrentIndex(idx)

        self._pages_spin.setValue(int(s.get("chart_pages", 1)))
        self._dd_check.setChecked(bool(s.get("chart_double_density", False)))
        self._td_check.setChecked(bool(s.get("chart_triple_density", False)))
        self._lb_check.setChecked(bool(s.get("chart_disable_left_border", True)))
        self._nsl_check.setChecked(bool(s.get("chart_no_strip_limit", False)))
        self._update_dd_visibility()
        self._update_patch_count()

        # Restore manual widget values. Prefer the case-disambiguated key;
        # fall through to the legacy bare key for backward compatibility, then
        # evict the bare key so it can't keep colliding with its case-twin in
        # the Windows registry (HKCU is case-insensitive). Legacy values that
        # don't type-coerce to the widget's expected type are discarded
        # silently — they are leftover bytes from a clobbering case-twin.
        for tool, widgets in self._manual_widgets.items():
            for pw in widgets:
                if pw in self._d_cascade_widgets:
                    continue
                new_key = _pw_settings_key(tool, pw.flag)
                v = s.get(new_key)
                if v is None:
                    legacy_key = f"manual_{tool}_{pw.flag}"
                    if legacy_key != new_key:
                        v = s.get(legacy_key)
                        try:
                            if s._qs.contains(legacy_key):
                                s._qs.remove(legacy_key)
                        except AttributeError:
                            pass
                        if v is not None and not _value_compatible_with_pw(v, pw):
                            v = None
                if v is not None:
                    pw.set_value(v)
                # Re-arm the enable-checkbox for expert non-boolean rows; without
                # this the value is restored but the flag stays off (and is
                # dropped by build_args). Only act when the key was persisted, so
                # presets/defaults from before this fix don't force rows off.
                if pw.has_separate_enable:
                    en = s.get(f"{new_key}_enabled")
                    if en is not None:
                        pw.set_user_enabled(bool(en))
        for idx, pw in enumerate(self._d_cascade_widgets):
            v = s.get(f"manual_targen_-D_{idx}")
            if v is not None:
                pw.set_value(v)
            pw.set_user_enabled(bool(s.get(f"manual_targen_-D_{idx}_enabled", False)))
        self._rebuild_d_cascade_visibility()
        if self._bit8_radio is not None and self._bit16_radio is not None:
            is_16bit = bool(s.get("manual_printtarg_tiff_16bit", False))
            self._bit16_radio.setChecked(is_16bit)
            self._bit8_radio.setChecked(not is_16bit)
        if self._manual_pages_spin is not None:
            self._manual_pages_spin.setValue(int(s.get("manual_pages", 1)))
        if self._manual_auto_patches_check is not None:
            # All four targen-basic Auto options default ON (Knut): the patch
            # count and neutral counts auto-fill unless the user opts out.
            auto_on = bool(s.get("manual_auto_patches", True))
            self._manual_auto_patches_check.setChecked(auto_on)
            self._on_auto_patches_toggled(auto_on)
        self._load_auto_neutral_states(
            grey  = bool(s.get("manual_auto_grey",  True)),
            white = bool(s.get("manual_auto_white", True)),
            black = bool(s.get("manual_auto_black", True)),
        )
        # Restore manual triple-density. The toggle handler stashes the
        # current -a / -m / -P / -L widget values, so they need to reflect
        # the user's pre-TD preferences at this point — not the TD overrides
        # themselves. Older builds (and the very first 3.7.9 build, before
        # the save-time fix) persisted the override values directly when
        # defaults were saved while TD was on; heal that on the way in by
        # detecting the TD-override fingerprint and substituting sane
        # defaults for the stash.
        td_saved = bool(s.get("manual_printtarg__triple_density", False))
        if td_saved and self._manual_td_check is not None:
            def _approx(a, b, eps=0.01) -> bool:
                try:
                    return abs(float(a) - float(b)) <= eps
                except (TypeError, ValueError):
                    return False
            looks_overridden = (
                self._manual_a_pw is not None and _approx(self._manual_a_pw.get_raw_value(), 1.3)
                and self._manual_m_pw is not None and int(self._manual_m_pw.get_raw_value() or 0) == 5
                and self._manual_P_pw is not None and bool(self._manual_P_pw.get_raw_value())
                and self._manual_lb_pw is not None and bool(self._manual_lb_pw.get_raw_value())
            )
            if looks_overridden:
                # Pretend the user had Argyll defaults pre-TD. Anything more
                # specific is unrecoverable — the override values clobbered
                # the original on save.
                self._manual_a_pw.set_value(1.0)
                self._manual_m_pw.set_value(6)
                self._manual_P_pw.set_value(False)
                self._manual_lb_pw.set_value(True)
        if self._manual_td_check is not None:
            self._manual_td_check.setChecked(td_saved)
        self._update_manual_lb_visibility()
        self._apply_instrument_default_margin()
        self._update_isis_preview_banner()

        presets = self._load_presets_from_settings()
        self._populate_preset_combo(presets)

        mode = s.get("chart_mode", "guided")
        self._switch_mode(mode)
